 */
export interface PromptBuilderDependencies {
  memoryEngine: {
    getUserProfile?: () => {
      getBasicInfo: () => { name: string };
      getDevelopmentHabits: () => {
        preferredLanguages?: string[];
        preferredFrameworks?: string[];
