/**
 * JiabaixingCore 核心引擎
 * 
 * V5.0 统一架构：
 * - 完全委托给 AgentHarness 处理
 * - 保留必要的集成组件（记忆、调度、进化）
 * - 移除旧的 FC 循环、DirectExecutor 等残留
 */
export class JiabaixingCore {
  private initialized = false;
  private personaCore: PersonaCore;
  private personaGuard: PersonaRules;
  private llm: LLMProvider;
  private memoryEngine: IMemoryEngine | null = null;
  private performanceMonitor: PerformanceMonitor;
  private securityAuditor: SecurityAuditor;
  private evolutionEngine: IEvolutionEngine | null = null;
  private traeOptimizationIntegrator: ITRAEOptimizationIntegrator | null = null;
  private optimizationSchedulerManager!: OptimizationScheduler;
  private scenarioScheduler: ScenarioAwareScheduler | null = null;

  public orchestrator: EvolutionOrchestrator;

  // V5.0: 核心组件
  private harness: import('../harness/AgentHarness').AgentHarness | null = null;
  private constitutionPromptBuilder: ConstitutionPromptBuilder;
  private memoryAssistant!: MemoryAssistant;
  private conversationHistoryManager: ConversationHistoryManager;

  constructor() {
    this.personaCore = new PersonaCore();
    this.personaGuard = new PersonaRules(this.personaCore);
    this.llm = new LLMProvider(process.env.LLM_MODEL || 'qwen2.5-vl');
    this.performanceMonitor = PerformanceMonitor.getInstance();
    this.securityAuditor = new SecurityAuditor({
      logFilePath: path.join(
        process.cwd(),
        'data',
        'logs',
        'security-audit.log'
      ),
    });

    // 初始化宪法 prompt 构建器
    this.constitutionPromptBuilder = new ConstitutionPromptBuilder({
      memoryEngine: this
        .memoryEngine as unknown as PromptBuilderDependencies['memoryEngine'],
      evolutionEngine: this.evolutionEngine,
    });

    // 初始化进化编排器
    this.orchestrator = EvolutionOrchestrator.getInstance();

    // 初始化对话历史管理器
    this.conversationHistoryManager = new ConversationHistoryManager();
  }

  public getLLM(): LLMProvider {
    return this.llm;
  }

  public getPersonaCore(): PersonaCore {
    return this.personaCore;
  }

  async initialize(): Promise<void> {
    if (this.initialized) {
      Logger.info('JiabaixingCore 已初始化，跳过', 'JiabaixingCore');
      return;
    }

    Logger.info('🧠 初始化 JiabaixingCore (V5.0 统一架构)', 'JiabaixingCore');

    Logger.info('✅ 步骤5：SkillRegistry 核心技能由 AgentHarness 双写兼容注册', 'JiabaixingCore');

    // 模型初始化 + 健康检查
    try {
      await this.llm.initialize();
      const healthCheckResult = await this.llm.healthCheck();
      if (!healthCheckResult.available) {
        Logger.warn(
          `⚠️ LLM服务暂时不可用: ${healthCheckResult.message}，将以降级模式运行`,
          'JiabaixingCore'
        );
        this.llm.markLocalUnavailable(healthCheckResult.message);
      } else {
        Logger.info(
          `✅ 步骤6：LLM健康检查通过: ${healthCheckResult.message}`,
          'JiabaixingCore'
        );
        Logger.info(
          `   LLM模型: ${process.env.MODEL_NAME || 'qwen2.5:3b'}`,
          'JiabaixingCore'
        );
      }
    } catch (llmError) {
      Logger.warn(
        `⚠️ LLM初始化失败: ${(llmError as Error).message}，将以降级模式运行`,
        'JiabaixingCore'
      );
      this.llm.markLocalUnavailable((llmError as Error).message);
    }

    // 异步加载对话历史
    await this.conversationHistoryManager.init();

    // 初始化优化调度器
    this.optimizationSchedulerManager = new OptimizationScheduler({
      memoryEngine: this
        .memoryEngine as OptimizationDependencies['memoryEngine'],
    });

    this.memoryAssistant = new MemoryAssistant({
      memoryEngine: this.memoryEngine,
    });

    if (process.env.ENABLE_AUTO_OPTIMIZE !== 'false') {
      await this.optimizationSchedulerManager.applyOptimizationsFromReport();
      this.optimizationSchedulerManager.startOptimizationScheduler();
      Logger.info(
        '🧬 步骤9：自动优化调度已启动（每24小时执行一次）',
        'JiabaixingCore'
      );
    } else {
      Logger.info(
        '⏸️ 步骤9：自动优化调度已禁用（ENABLE_AUTO_OPTIMIZE=false）',
        'JiabaixingCore'
      );
    }

    this.optimizationSchedulerManager.setupUserCorrectionHandler();
    this.optimizationSchedulerManager.watchAnalysisReport();

    this.performanceMonitor.startMonitoring();

    this.initialized = true;
    Logger.info('✅ JiabaixingCore 初始化完成 (V5.0)', 'JiabaixingCore');
  }

  /**
   * 注入记忆引擎
   */
  setMemoryEngine(memoryEngine: IMemoryEngine): void {
    this.memoryEngine = memoryEngine;
    this.constitutionPromptBuilder = new ConstitutionPromptBuilder({
      memoryEngine: this
        .memoryEngine as unknown as PromptBuilderDependencies['memoryEngine'],
      evolutionEngine: this.evolutionEngine,
    });
  }

  /**
   * 设置进化引擎
   */
  setEvolutionEngine(engine: IEvolutionEngine): void {
    this.evolutionEngine = engine;
  }

  /**
   * 设置场景感知调度器
   */
  setScenarioScheduler(scheduler: ScenarioAwareScheduler): void {
    this.scenarioScheduler = scheduler;
  }

  /**
   * 获取场景感知调度器
   */
  getScenarioScheduler(): ScenarioAwareScheduler | null {
    return this.scenarioScheduler;
  }

  /**
   * 获取性能监控器
   */
  getPerformanceMonitor(): PerformanceMonitor {
    return this.performanceMonitor;
  }

  /**
   * 设置TRAE优化系统集成器
   */
  setTRAEOptimizationIntegrator(integrator: ITRAEOptimizationIntegrator): void {
    this.traeOptimizationIntegrator = integrator;
    Logger.info('✅ TRAE优化系统集成器已注入', 'JiabaixingCore');
  }

  /**
   * 获取TRAE优化系统集成器
   */
  getTRAEOptimizationIntegrator(): ITRAEOptimizationIntegrator | null {
    return this.traeOptimizationIntegrator;
  }

  /**
   * 注入 Agent Harness（V5.0 统一架构）
   */
  setHarness(harness: import('../harness/AgentHarness').AgentHarness): void {
    this.harness = harness;
    Logger.info('✅ Agent Harness 已注入 (V5.0)', 'JiabaixingCore');
  }

  /**
   * 获取 Agent Harness
   */
  getHarness(): import('../harness/AgentHarness').AgentHarness | null {
    return this.harness;
  }

  /**
   * 获取记忆引擎实例
   */
  public getMemoryEngine(): IMemoryEngine | null {
    return this.memoryEngine;
  }

  async getLLMHealth(): Promise<{ available: boolean; message: string }> {
    return this.llm.healthCheck();
  }

  /**
   * V5.0 统一 processInput
   * 
   * 完全委托给 AgentHarness 处理，保留降级路径
   */
  async processInput(
    input: string,
    userId?: string,
    traceId?: string
  ): Promise<ProcessInputResult> {
    if (!this.initialized) {
      await this.initialize();
    }

    const finalTraceId = traceId || Logger.generateTraceId();
    Logger.setTraceId(finalTraceId);
    Logger.info(
      `🚀 开始处理用户输入: ${input.substring(0, 50)}${input.length > 50 ? '...' : ''}`,
      'JiabaixingCore'
    );

    const startTime = Date.now();

    // 更新用户活跃状态
    if (this.scenarioScheduler) {
      this.scenarioScheduler.updateUserActivity();
    }

    this.securityAuditor.logAuditEntry({
      level: 'info',
      category: 'user_action',
      userId: userId || 'anonymous',
      action: 'process_input',
      details: { inputLength: input.length, traceId: finalTraceId },
      severity: 'low',
    });

    try {
      // ═══════════════════════════════════════════════════════════════
      // V5.0: Harness Agent Framework (统一架构)
      // ═══════════════════════════════════════════════════════════════
      if (this.harness && this.harness.getConfig().useHarnessLoop) {
        Logger.info(
          '🏗️ V5.0 Harness 统一处理',
          'JiabaixingCore'
        );

        const harnessResult = await this.harness.processInput({
          text: input,
          userId,
          traceId: finalTraceId,
        });

        const safeResponse = harnessResult.response;
        const qualityScore = harnessResult.quality.overall;

        Logger.info(
          `🏗️ Harness 处理完成 (质量:${qualityScore.toFixed(2)}, 轮次:${harnessResult.metadata.loopRounds}, 工具:${harnessResult.trace.totalToolCalls})`,
          'JiabaixingCore'
        );

        // 更新对话历史
        this.conversationHistoryManager.addUserMessage(input);
        this.conversationHistoryManager.addAssistantMessage(safeResponse);

        // 自动知识提取
        setImmediate(() => {
          this.memoryAssistant
            .autoExtractKnowledge(input, safeResponse, userId)
            .catch(() => {});
        });

        // 进化记录
        setImmediate(() => {
          try {
            const orchestrator = EvolutionOrchestrator.getInstance();
            orchestrator.recordInteraction({
              traceId: finalTraceId,
              input,
              response: safeResponse,
              success: qualityScore >= 0.5,
              qualityScore,
              executionDuration: harnessResult.trace.totalDuration,
              toolCalls: [],
              scene: 'general',
              userId: userId || 'default',
            });
          } catch (error) {
            Logger.debug(
              `进化编排器记录失败（非关键）: ${(error as Error).message}`,
              'JiabaixingCore'
            );
          }
        });

        void EventBus.emit('response_ready', {
          response: safeResponse,
          traceId: finalTraceId,
          success: true,
        });
        Logger.info(
          `✅ response_ready已发射: traceId=${finalTraceId}, 响应长度=${safeResponse.length}, 质量=${qualityScore.toFixed(2)}`,
          'JiabaixingCore'
        );

        return {
          response: safeResponse,
          traceId: finalTraceId,
          intent: 'harness_orchestrated',
        };
      }

      // ═══════════════════════════════════════════════════════════════
      // 降级：如果 Harness 不可用
      // ═══════════════════════════════════════════════════════════════
      Logger.warn(
        '⚠️ Harness 不可用，使用简单回复',
        'JiabaixingCore'
      );
      const fallbackResponse = `抱歉，当前系统配置不完整，请检查环境变量设置。`;

      this.conversationHistoryManager.addUserMessage(input);
      this.conversationHistoryManager.addAssistantMessage(fallbackResponse);

      void EventBus.emit('response_ready', {
        response: fallbackResponse,
        traceId: finalTraceId,
        success: false,
      });
      Logger.warn(
        `⚠️ response_ready已发射(降级): traceId=${finalTraceId}`,
        'JiabaixingCore'
      );

      return {
        response: fallbackResponse,
        traceId: finalTraceId,
        intent: 'fallback_simple',
      };
    } catch (error) {
      Logger.error('❌ 处理用户输入失败', error as Error, 'JiabaixingCore');
      const fallbackResponse = `抱歉，处理过程中出现了问题：${(error as Error).message}`;

      void EventBus.emit('response_ready', {
        response: fallbackResponse,
        traceId: finalTraceId,
        success: false,
      });
      Logger.error(
        `❌ response_ready已发射(错误): traceId=${finalTraceId}, error=${(error as Error).message}`,
        error as Error,
        'JiabaixingCore'
      );

      return {
        response: fallbackResponse,
        traceId: finalTraceId,
        intent: 'error_fallback',
      };
    } finally {
      const duration = Date.now() - startTime;
      this.performanceMonitor.recordRequest(duration, true);
      Logger.clearTraceId();
    }
  }

  async processInputWithTracking(
    input: string,
    userId?: string,
    traceId?: string
  ): Promise<TrackedProcessResult> {
    const finalTraceId = traceId || Logger.generateTraceId();
    const startTime = Date.now();

    EventBus.startTrace(finalTraceId, 'core_process_input', {
      input: input.substring(0, 50),
      userId,
    });

    void EventBus.emit('agent_execution_update', {
      traceId: finalTraceId,
      phase: 'processing_start',
      status: 'started',
      timestamp: new Date().toISOString(),
    });

    try {
      const result = await this.processInput(input, userId, finalTraceId);

      EventBus.completeTrace(finalTraceId, true);

      return {
        success: true,
        response: result.response,
        intent: result.intent,
        duration: Date.now() - startTime,
        traceId: finalTraceId,
      };
    } catch (error) {
      EventBus.failTrace(finalTraceId, (error as Error).message);

      void EventBus.emit('agent_execution_update', {
        traceId: finalTraceId,
        phase: 'processing_error',
        status: 'failed',
        result: { error: (error as Error).message },
        timestamp: new Date().toISOString(),
      });

      return {
        success: false,
        error: (error as Error).message,
        duration: Date.now() - startTime,
        traceId: finalTraceId,
      };
    }
  }

  // 兼容层：保留原有属性，委托给 ConversationHistoryManager
  private get recentConversationHistory(): Array<{
    role: string;
    content: string;
    timestamp: Date;
  }> {
    return this.conversationHistoryManager.getAll();
  }

  private set recentConversationHistory(
    value: Array<{ role: string; content: string; timestamp: Date }>
  ) {
    this.conversationHistoryManager.setHistory(value as ConversationEntry[]);
  }

  private readonly MAX_CONVERSATION_HISTORY = 20;

  /**
   * 生成主动消息（已简化，不再依赖 ProactiveMessageGenerator）
   */
  public async generateProactiveMessage(context: {
    reason: string;
    context: string;
    scene: string;
    isEmotionBased: boolean;
  }): Promise<string> {
    return `提醒：${context.reason}`;
  }

  public getLastToolResults(): Array<{
    toolCall: { id: string; type: string; function: { name: string; arguments: string } };
    validated: { valid: boolean; sanitizedOutput: string; warning?: string };
    duration: number;
  }> {
    return [];
  }
}

import { IMemoryEngine } from './JiabaixingCore';
import { UserProfileSummary } from '../persona/DialogueGenerator';
import { Logger } from '../utils/Logger';

/**
 * MemoryAssistant 依赖接口
 */
export interface MemoryAssistantDeps {
  memoryEngine: IMemoryEngine | null;
}

/**
 * 记忆辅助方法
 * 从 JiabaixingCore 中提取的记忆相关实例方法
 */
export class MemoryAssistant {
  private memoryEngine: IMemoryEngine | null;

  constructor(deps: MemoryAssistantDeps) {
    this.memoryEngine = deps.memoryEngine;
  }

  /**
   * 构建用户画像摘要
   */
  async buildUserProfileSummary(
    userId?: string
  ): Promise<UserProfileSummary | undefined> {
    if (this.memoryEngine?.getUserProfileSummary && userId) {
      try {
        const profile = await this.memoryEngine.getUserProfileSummary(userId);
        return {
          name: profile.name,
          preferredLanguage: profile.preferredLanguage,
          preferredFrameworks: profile.preferredFrameworks,
          recentTopics: profile.recentTopics,
        };
      } catch {
        // 忽略画像获取失败
      }
    }

    return undefined;
  }

  /**
   * v3: 自动记忆检索——在 FC 循环前自动注入相关记忆，不依赖 LLM 主动调用 memory_recall
   * P2增强：添加记忆去重，避免相似记忆重复注入
   */
  async autoRetrieveMemories(
    input: string,
    _userId?: string
  ): Promise<string[]> {
    if (!this.memoryEngine?.retrieveRelevant) {
      return [];
    }
    try {
      const memories = await this.memoryEngine.retrieveRelevant({
        query: input,
        limit: 10,
      });

      if (!memories || memories.length === 0) return [];

      const formatted = (
        memories as Array<{
          content: string;
          type?: string;
          timestamp?: Date;
          relevance?: number;
        }>
      ).map(
        (m) =>
          `[${m.type || '记忆'}] ${m.content}${m.timestamp ? `（${new Date(m.timestamp).toLocaleDateString('zh-CN')}）` : ''}`
      );

      // P2增强：基于Jaccard相似度的记忆去重
      const deduped = this.deduplicateMemoryStrings(formatted);

      // 只返回前5条去重后的记忆
      return deduped.slice(0, 5);
    } catch {
      return [];
    }
  }

  /**
   * P2: 基于Jaccard相似度的记忆去重
   */
  deduplicateMemoryStrings(memories: string[]): string[] {
    if (memories.length <= 1) return memories;

    const result: string[] = [];
    const seen = new Set<string>();

    for (const memory of memories) {
      if (seen.has(memory)) continue;

      let isDuplicate = false;
      const memTokens = this.tokenizeForDedup(memory);

      for (const existing of result) {
        const exTokensArray = this.tokenizeForDedup(existing);
        const exTokenSet = new Set(exTokensArray);
        const intersection = memTokens.filter((t) => exTokenSet.has(t));
        const union = new Set([...memTokens, ...exTokensArray]);
        const similarity =
          union.size === 0 ? 0 : intersection.length / union.size;

        if (similarity > 0.7) {
          isDuplicate = true;
          break;
        }
      }

      if (!isDuplicate) {
        seen.add(memory);
        result.push(memory);
      }
    }

    return result;
  }

  private tokenizeForDedup(text: string): string[] {
    const tokens: string[] = [];
    const cleaned = text.replace(/[\[\]（）()，。！？、：；""''【】-]/g, ' ');

    for (const word of cleaned.split(/\s+/)) {
      const trimmed = word.trim();
      if (trimmed.length >= 2) {
        tokens.push(trimmed.toLowerCase());
      }
    }

    return tokens;
  }

  /**
   * v3: 自动知识提取——对话结束后异步提取关键信息存入记忆
   * 不依赖 LLM 主动调用 memory_store
   */
  async autoExtractKnowledge(
    input: string,
    response: string,
    _userId?: string
  ): Promise<void> {
    if (!this.memoryEngine?.storeShortTermMemory) return;

    const extracted: Array<{ content: string; category: string }> = [];

    // 1. 提取用户偏好
    const preferencePatterns = [
      {
        pattern: /我(?:喜欢|爱|偏好|习惯|常用|一般|通常)\s*([^。，！？]+)/,
        category: 'preference',
      },
      {
        pattern: /我(?:不喜欢|讨厌|反感|不用|从不)\s*([^。，！？]+)/,
        category: 'preference',
      },
      {
        pattern: /我(?:是|在|做|从事)\s*([^。，！？]{3,30})/,
        category: 'fact',
      },
      {
        pattern:
          /我(?:明天|下周|后天|过几天|待会|稍后)\s*(?:要|需要|准备|打算)\s*([^。，！？]+)/,
        category: 'task',
      },
    ];

    for (const { pattern, category } of preferencePatterns) {
      const match = input.match(pattern);
      if (match && match[1].trim().length > 2) {
        extracted.push({ content: match[1].trim(), category });
      }
    }

    // 2. 提取确认的任务
    if (
      response.includes('已') &&
      (response.includes('设置') ||
        response.includes('添加') ||
        response.includes('保存'))
    ) {
      const taskMatch = input.match(
        /(?:设置|添加|创建|安排|提醒)\s*([^。，！？]+)/
      );
      if (taskMatch) {
        extracted.push({
          content: `任务/提醒: ${taskMatch[1].trim()}`,
          category: 'task',
        });
      }
    }

    // 3. 存储
    for (const item of extracted) {
      try {
        await this.memoryEngine.storeShortTermMemory(item.content, item.category);
        Logger.info(
          `🧠 自动提取知识: [${item.category}] ${item.content}`,
          'MemoryAssistant'
        );
      } catch (error) {
        Logger.debug(
          `知识存储失败（非关键）: ${(error as Error).message}`,
          'MemoryAssistant'
        );
      }
    }
  }
}

import * as fs from 'fs';
import path from 'path';
import { EventBus } from '../shared/EventBus';
import { HeuristicSuggestion } from '../interfaces';
import { Logger } from '../utils/Logger';

interface OptimizationReport {
  timestamp?: string;
  generatedAt?: string;
  analysisWindow: { start: string; end: string } | string;
  toolWeightAdjustments?: unknown[];
  heuristicSuggestions?: HeuristicSuggestion[];
}

interface IMemoryEngine {
  storeFeedbackSignal?: (signal: {
    traceId?: string;
    toolName: string;
    feedbackType: string;
    rating: number;
    message: string;
  }) => Promise<void>;
}

export interface OptimizationDependencies {
  memoryEngine: IMemoryEngine | null;
}

export class OptimizationScheduler {
  private optimizationScheduler: NodeJS.Timeout | null = null;

  constructor(private deps: OptimizationDependencies) {}

  async applyOptimizationsFromReport(): Promise<void> {
    const traceId = Logger.generateTraceId();
    Logger.setTraceId(traceId);

    const reportPath = path.join(
      process.cwd(),
      'data',
      'feedback',
      'feedback_analysis_report.json'
    );

    Logger.info('🤖 自动优化调度：开始扫描优化报告...', 'OptimizationScheduler');

    if (!fs.existsSync(reportPath)) {
      Logger.info(
        `⏭️ 自动优化调度：未找到报告文件 (${reportPath})，跳过`,
        'OptimizationScheduler'
      );
      Logger.clearTraceId();
      return;
    }

    try {
      const reportContent = await fs.promises.readFile(reportPath, 'utf-8');
      const report: OptimizationReport = JSON.parse(reportContent);

      const reportTimestamp = report.timestamp || report.generatedAt || '未知';
      const analysisWindowStr =
        typeof report.analysisWindow === 'string'
          ? report.analysisWindow
          : `${report.analysisWindow.start} ~ ${report.analysisWindow.end}`;

      Logger.info(
        `📊 自动优化调度：加载报告 [${reportTimestamp}]，分析窗口: ${analysisWindowStr}`,
        'OptimizationScheduler'
      );

      if (
        report.heuristicSuggestions &&
        report.heuristicSuggestions.length > 0
      ) {
        Logger.info(
          `启发式建议: ${report.heuristicSuggestions.length} 项（由 LLM FC 循环自动处理）`,
          'OptimizationScheduler'
        );
      }

      Logger.info(
        `✅ 自动优化调度：处理完成（工具权重调整由 LLM FC 循环驱动）`,
        'OptimizationScheduler'
      );
    } catch (error) {
      Logger.error(
        '❌ 自动优化调度：处理报告失败',
        error as Error,
        'OptimizationScheduler'
      );
    }

    Logger.clearTraceId();
  }

  watchAnalysisReport(): void {
    const reportPath = path.join(
      process.cwd(),
      'data',
      'feedback',
      'feedback_analysis_report.json'
    );

    fs.watchFile(reportPath, { interval: 10000 }, async (curr, prev) => {
      if (curr.mtimeMs !== prev.mtimeMs) {
        Logger.info('📡 检测到优化报告更新，正在热加载...', 'OptimizationScheduler');
        await this.applyOptimizationsFromReport();
        Logger.info('✅ 优化报告已热加载', 'OptimizationScheduler');
      }
    });

    Logger.info('🔍 已启动优化报告热监视', 'OptimizationScheduler');
  }

  startOptimizationScheduler(): void {
    const INTERVAL_24H = 24 * 60 * 60 * 1000;

    this.optimizationScheduler = setInterval(async () => {
      Logger.info('⏰ 定时调度触发：开始执行自动优化...', 'OptimizationScheduler');
      await this.applyOptimizationsFromReport();
    }, INTERVAL_24H);

    Logger.info(`⏰ 自动优化定时调度已启动，间隔: 24小时`, 'OptimizationScheduler');
  }

  setupUserCorrectionHandler(): void {
    EventBus.on('user_correction', async (data: unknown) => {
      try {
        const payload = data as Record<string, unknown>;
        const toolId = (payload.toolId || payload.tool_name) as
          | string
          | undefined;
        const correctionType = (payload.correctionType ||
          payload.type) as string;
        const reason = (payload.reason || payload.message) as string;
        const severity = Number(payload.severity) || 1;
        const traceId = (payload.traceId || payload.trace_id) as
          | string
          | undefined;

        if (!toolId) {
          Logger.warn('⚠️ user_correction事件缺少toolId', 'OptimizationScheduler');
          return;
        }

        const mem = this.deps.memoryEngine as IMemoryEngine | undefined;
        if (mem?.storeFeedbackSignal) {
          await mem.storeFeedbackSignal({
            traceId,
            toolName: toolId,
            feedbackType: 'correction',
            rating: severity > 0 ? 1 : 4,
            message: `[${correctionType}] ${reason || '未提供原因'}`,
          });
        }

        Logger.info(
          `🎯 用户纠错已记录: [${toolId}] ${correctionType}, 原因: ${reason}`,
          'OptimizationScheduler'
        );
      } catch (error) {
        Logger.warn(
          '⚠️ 处理user_correction事件失败: ' + (error as Error).message,
          'OptimizationScheduler'
        );
      }
    });
    Logger.info('✅ user_correction事件监听器已注册', 'OptimizationScheduler');
  }

  shutdown(): void {
    if (this.optimizationScheduler) {
      clearInterval(this.optimizationScheduler);
      this.optimizationScheduler = null;
    }
  }
}

