/**
 * 场景感知调度器 v2 - 简化版
 * 核心功能：
 * 1. 基于时间的任务调度
 * 2. 与记忆引擎集成
 * 3. 简化的主动关怀
 */

import { MemoryEngine } from '../memory/MemoryEngine';
import { EventBus } from '../shared/EventBus';
import { Logger } from '../utils/Logger';

type JiabaixingCore = import('./JiabaixingCore').JiabaixingCore;

// ── 类型定义 ──
export interface ScheduledTask {
  id: string;
  name: string;
  description: string;
  schedule: string;
  priority: number;
  lastRun?: Date;
  nextRun?: Date;
  enabled: boolean;
  executionCount: number;
  successCount: number;
  averageExecutionTime: number;
}

// ── 调度器主类 ──
export class ScenarioAwareScheduler {
  private tasks: Map<string, ScheduledTask> = new Map();
  private isRunning: boolean = false;
  private checkInterval: ReturnType<typeof setInterval> | null = null;
  private readonly CHECK_INTERVAL_MS = 30000;
  private memoryEngine: MemoryEngine | null = null;
  private llmCore: JiabaixingCore | null = null;

  constructor() {
    this.initializeDefaultTasks();
  }

  /** 注入记忆引擎 */
  public setMemoryEngine(engine: MemoryEngine): void {
    this.memoryEngine = engine;
    Logger.info('✅ 记忆引擎已注入到调度器', 'ScenarioAwareScheduler');
  }

  /** 注入LLM核心 */
  public setLLMCore(core: JiabaixingCore): void {
    this.llmCore = core;
    Logger.info('✅ LLM核心已注入到调度器', 'ScenarioAwareScheduler');
  }

  /** 更新用户活跃状态 */
  public updateUserActivity(): void {
    // 简单实现：记录最后活跃时间
  }

  // ── 初始化 ──
  private initializeDefaultTasks(): void {
    const defaultTasks: ScheduledTask[] = [
      {
        id: 'morning_briefing',
        name: '早安问候',
        description: '每天早晨提供问候和天气提醒',
        schedule: '0 9 * * *',
        priority: 1,
        enabled: true,
        executionCount: 0,
        successCount: 0,
        averageExecutionTime: 0,
      },
    ];
    defaultTasks.forEach((task) => {
      this.tasks.set(task.id, task);
    });
  }

  // ── 核心调度循环 ──
  public start(): void {
    if (this.isRunning) {
      Logger.warn('调度器已在运行中', 'ScenarioAwareScheduler');
      return;
    }
    this.isRunning = true;
    Logger.info('🚀 场景感知调度器已启动', 'ScenarioAwareScheduler');
    void this.checkAndExecuteTasks();
    this.checkInterval = setInterval(() => {
      void this.checkAndExecuteTasks();
    }, this.CHECK_INTERVAL_MS);
    void EventBus.emit('scheduler_started', {
      timestamp: new Date().toISOString(),
    });
  }

  public stop(): void {
    if (!this.isRunning) return;

    this.isRunning = false;
    if (this.checkInterval) {
      clearInterval(this.checkInterval);
      this.checkInterval = null;
    }

    Logger.info('⏹ 场景感知调度器已停止', 'ScenarioAwareScheduler');
    void EventBus.emit('scheduler_stopped', {
      timestamp: new Date().toISOString(),
    });
  }

  public isActive(): boolean {
    return this.isRunning;
  }

  // ── 任务检查与执行 ──
  private async checkAndExecuteTasks(): Promise<void> {
    const now = new Date();
    // 1. 检查基于时间的任务
    for (const task of this.tasks.values()) {
      if (!task.enabled) continue;
      if (this.shouldExecuteTask(task, now)) {
        await this.executeTask(task);
      }
    }
  }

  private shouldExecuteTask(task: ScheduledTask, now: Date): boolean {
    // 简化的调度检查：每小时检查一次
    if (!task.nextRun) {
      task.nextRun = new Date(now.getTime() + 60 * 60 * 1000); // 1小时后
      return false;
    }

    if (now >= task.nextRun) {
      return true;
    }

    return false;
  }

  private async executeTask(task: ScheduledTask): Promise<void> {
    const startTime = Date.now();

    Logger.info(`📋 执行任务: ${task.name}`, 'ScenarioAwareScheduler');

    try {
      switch (task.id) {
        case 'morning_briefing':
          await this.executeMorningBriefing();
          break;
      }

      task.lastRun = new Date();
      task.nextRun = new Date(Date.now() + 60 * 60 * 1000); // 1小时后
      task.executionCount++;
      task.successCount++;
      task.averageExecutionTime =
        (task.averageExecutionTime * (task.executionCount - 1) +
          (Date.now() - startTime)) /
        task.executionCount;

      Logger.info(
        `✅ 任务完成: ${task.name} (${Date.now() - startTime}ms)`,
        'ScenarioAwareScheduler'
      );
    } catch (error) {
      Logger.warn(
        `❌ 任务执行失败: ${task.name} - ${(error as Error).message}`,
        'ScenarioAwareScheduler'
      );
    }
  }

  private async executeMorningBriefing(): Promise<void> {
    Logger.info('☀️ 执行早安问候任务', 'ScenarioAwareScheduler');
    // 简化实现：不执行实际操作
  }

  // ── 公开 API ──
  public getTasks(): ScheduledTask[] {
    return Array.from(this.tasks.values());
  }

  public getTask(taskId: string): ScheduledTask | undefined {
    return this.tasks.get(taskId);
  }

  public updateTask(taskId: string, updates: Partial<ScheduledTask>): void {
    const task = this.tasks.get(taskId);
    if (task) {
      Object.assign(task, updates);
    }
  }

  public addTask(task: ScheduledTask): string {
    this.tasks.set(task.id, task);
    Logger.info(`➕ 任务已添加: ${task.name}`, 'ScenarioAwareScheduler');
    return task.id;
  }

  public toggleTask(taskId: string, enabled?: boolean): void {
    const task = this.tasks.get(taskId);
    if (task) {
      task.enabled = enabled ?? !task.enabled;
      Logger.info(`${task.enabled ? '启用' : '禁用'} 任务: ${task.name}`, 'ScenarioAwareScheduler');
    }
  }

  public async executeTaskById(taskId: string): Promise<void> {
    const task = this.tasks.get(taskId);
    if (task) {
      await this.executeTask(task);
    } else {
      throw new Error(`任务不存在: ${taskId}`);
    }
  }

  public getProactiveTriggers(): Array<{ type: string; reason: string; priority: number }> {
    return [];
  }

  public getUserBehaviorPattern(): {
    activeHours: string[];
    frequentTopics: string[];
    taskCompletionRate: number;
    averageSessionDuration: number;
  } {
    return {
      activeHours: [],
      frequentTopics: [],
      taskCompletionRate: 0,
      averageSessionDuration: 0,
    };
  }
}

/**
 * Harness Layer 0: Daemon Manager — 后台常驻服务管理
 *
 * 无外部依赖的进程守护：
 *   daemon start   — 以后台进程启动后端服务
 *   daemon stop    — 停止后台服务
 *   daemon status  — 查看运行状态
 *   daemon restart — 重启后台服务
 *   daemon logs    — 查看最近日志
 *
 * 通过 PID 文件 (daemon.json) 追踪进程生命周期。
 * 支持 Windows / Linux / macOS。
 */

import * as path from 'path';
import * as fs from 'fs';
import * as os from 'os';
import { spawn, execSync } from 'child_process';

// ============ 类型 ============

interface DaemonState {
  pid: number;
  port: number;
  startTime: string;
  logFile: string;
  devMode: boolean;
}

interface DaemonStatus {
  running: boolean;
  state: DaemonState | null;
  uptime: number | null; // seconds
  memoryUsage: string | null;
}

// ============ 常量 ============

const PROJECT_ROOT = path.resolve(process.cwd());
const DAEMON_DIR = path.join(PROJECT_ROOT, '.jiabaixing');
const DAEMON_FILE = path.join(DAEMON_DIR, 'daemon.json');
const DEFAULT_LOG_FILE = path.join(DAEMON_DIR, 'daemon.log');
const DEFAULT_PORT = parseInt(process.env.API_PORT || process.env.PORT || '3111', 10);

// ============ DaemonManager ============

export class DaemonManager {
  private port: number;

  constructor(port?: number) {
    this.port = port || DEFAULT_PORT;
  }

  // ============ 公共 API ============

  async start(): Promise<{ success: boolean; message: string; pid?: number }> {
    const status = await this.status();
    if (status.running) {
      return {
        success: false,
        message: `后端服务已在运行中 (PID: ${status.state!.pid}, 已运行 ${this.formatUptime(status.uptime!)})`,
      };
    }

    const devMode = !this.isProductionBuild();
    const entryPoint = this.resolveEntryPoint(devMode);

    if (!fs.existsSync(entryPoint)) {
      return {
        success: false,
        message: `入口文件不存在: ${entryPoint}。${devMode ? '请确保 src/main.ts 存在。' : '请先执行 npm run build 构建项目。'}`,
      };
    }

    try {
      const pid = await this.spawnProcess(entryPoint, devMode);
      const state: DaemonState = {
        pid,
        port: this.port,
        startTime: new Date().toISOString(),
        logFile: DEFAULT_LOG_FILE,
        devMode,
      };

      this.ensureDaemonDir();
      fs.writeFileSync(DAEMON_FILE, JSON.stringify(state, null, 2), 'utf-8');

      // 等待 2 秒确认进程没有立即崩溃
      await this.sleep(2000);
      const confirmed = this.isProcessAlive(pid);

      if (!confirmed) {
        // 进程可能立即崩溃了，尝试读取日志
        const logTail = this.readLogTail(10);
        return {
          success: false,
          message: `进程启动后立即退出 (PID: ${pid})。\n最近日志:\n${logTail}`,
        };
      }

      return {
        success: true,
        message: `后端服务已启动 (PID: ${pid}, 端口: ${this.port}, 模式: ${devMode ? '开发' : '生产'})`,
        pid,
      };
    } catch (err) {
      return {
        success: false,
        message: `启动失败: ${(err as Error).message}`,
      };
    }
  }

  async stop(): Promise<{ success: boolean; message: string }> {
    const state = this.readState();
    if (!state) {
      return { success: false, message: '未找到运行中的守护进程（daemon.json 不存在）' };
    }

    const alive = this.isProcessAlive(state.pid);
    if (!alive) {
      // PID 文件存在但进程已死 — 清理
      this.cleanup();
      return { success: true, message: `守护进程记录已清理 (PID ${state.pid} 已不存在)` };
    }

    try {
      // 先尝试 SIGTERM（优雅退出）
      this.killProcess(state.pid, 'SIGTERM');

      // 等待最多 5 秒
      let waited = 0;
      while (this.isProcessAlive(state.pid) && waited < 5000) {
        await this.sleep(500);
        waited += 500;
      }

      // 如果还没死，用 SIGKILL
      if (this.isProcessAlive(state.pid)) {
        this.killProcess(state.pid, 'SIGKILL');
        await this.sleep(500);
      }

      const finalCheck = this.isProcessAlive(state.pid);
      this.cleanup();

      if (finalCheck) {
        return { success: false, message: `无法终止进程 PID: ${state.pid}` };
      }

      return {
        success: true,
        message: `后端服务已停止 (PID: ${state.pid}, 运行时长: ${this.formatUptime(this.calculateUptime(state))})`,
      };
    } catch (err) {
      return { success: false, message: `停止失败: ${(err as Error).message}` };
    }
  }

  async status(): Promise<DaemonStatus> {
    const state = this.readState();
    if (!state) {
      return { running: false, state: null, uptime: null, memoryUsage: null };
    }

    const alive = this.isProcessAlive(state.pid);
    if (!alive) {
      return { running: false, state: null, uptime: null, memoryUsage: null };
    }

    const uptime = this.calculateUptime(state);
    const memoryUsage = this.getMemoryUsage(state.pid);

    return { running: true, state, uptime, memoryUsage };
  }

  async restart(): Promise<{ success: boolean; message: string }> {
    const stopResult = await this.stop();
    // stop 成功或进程本来就不在运行都可以继续
    if (!stopResult.success && stopResult.message.includes('无法终止进程')) {
      return stopResult;
    }

    await this.sleep(1000);
    return this.start();
  }

  async logs(lines: number = 30): Promise<string> {
    const logFile = DEFAULT_LOG_FILE;
    if (!fs.existsSync(logFile)) {
      const state = this.readState();
      const file = state?.logFile;
      if (!file || !fs.existsSync(file)) {
        return '(暂无日志文件)';
      }
      return this.readLogTail(lines, file);
    }
    return this.readLogTail(lines, logFile);
  }

  logFilePath(): string {
    const state = this.readState();
    return state?.logFile || DEFAULT_LOG_FILE;
  }

  // ============ 内部方法 ============

  private readState(): DaemonState | null {
    try {
      if (!fs.existsSync(DAEMON_FILE)) return null;
      const raw = fs.readFileSync(DAEMON_FILE, 'utf-8');
      return JSON.parse(raw) as DaemonState;
    } catch {
      return null;
    }
  }

  private ensureDaemonDir(): void {
    if (!fs.existsSync(DAEMON_DIR)) {
      fs.mkdirSync(DAEMON_DIR, { recursive: true });
    }
  }

  private cleanup(): void {
    try {
      if (fs.existsSync(DAEMON_FILE)) {
        fs.unlinkSync(DAEMON_FILE);
      }
    } catch {
      // 忽略清理错误
    }
  }

  private isProductionBuild(): boolean {
    const distMain = path.join(PROJECT_ROOT, 'dist', 'src', 'main.js');
    return fs.existsSync(distMain);
  }

  private resolveEntryPoint(devMode: boolean): string {
    if (devMode) {
      return path.join(PROJECT_ROOT, 'src', 'main.ts');
    }
    return path.join(PROJECT_ROOT, 'dist', 'src', 'main.js');
  }

  private spawnProcess(entryPoint: string, devMode: boolean): Promise<number> {
    return new Promise((resolve, reject) => {
      this.ensureDaemonDir();

      const logFd = fs.openSync(DEFAULT_LOG_FILE, 'a');

      let child;
      if (devMode) {
        // ts-node 开发模式
        const tsNodePath = path.join(PROJECT_ROOT, 'node_modules', '.bin', 'ts-node');
        child = spawn(
          'node',
          [tsNodePath, '--transpileOnly', entryPoint],
          {
            cwd: PROJECT_ROOT,
            detached: true,
            stdio: ['ignore', logFd, logFd],
            env: {
              ...process.env,
              API_PORT: String(this.port),
              CONSOLE_LOG_LEVEL: 'warn',
            },
            shell: true,
          }
        );
      } else {
        // 编译后的 JS 生产模式
        child = spawn(
          'node',
          [entryPoint],
          {
            cwd: PROJECT_ROOT,
            detached: true,
            stdio: ['ignore', logFd, logFd],
            env: {
              ...process.env,
              API_PORT: String(this.port),
              NODE_ENV: 'production',
            },
            shell: true,
          }
        );
      }

      fs.closeSync(logFd);

      child.on('error', (err) => {
        reject(new Error(`无法启动进程: ${err.message}`));
      });

      child.on('spawn', () => {
        if (child.pid) {
          child.unref();
          resolve(child.pid);
        } else {
          reject(new Error('进程 PID 为空'));
        }
      });

      // 超时保护
      setTimeout(() => {
        if (!child.pid) {
          reject(new Error('进程启动超时'));
        }
      }, 10000);
    });
  }

  private isProcessAlive(pid: number): boolean {
    try {
      // 发送信号 0 不会杀死进程，仅检查是否存在
      process.kill(pid, 0);
      return true;
    } catch {
      return false;
    }
  }

  private killProcess(pid: number, signal: NodeJS.Signals): void {
    try {
      if (os.platform() === 'win32' && signal === 'SIGKILL') {
        // Windows 不支持 SIGKILL，用 taskkill
        execSync(`taskkill /PID ${pid} /F /T 2>nul`, { stdio: 'ignore' });
      } else if (os.platform() === 'win32' && signal === 'SIGTERM') {
        // Windows 用不带 /F 的 taskkill
        execSync(`taskkill /PID ${pid} /T 2>nul`, { stdio: 'ignore' });
      } else {
        process.kill(pid, signal);
      }
    } catch {
      // 进程可能已经退出
    }
  }

  private calculateUptime(state: DaemonState): number {
    const start = new Date(state.startTime).getTime();
    const now = Date.now();
    return Math.max(0, Math.floor((now - start) / 1000));
  }

  private getMemoryUsage(pid: number): string | null {
    try {
      if (os.platform() === 'win32') {
        const output = execSync(
          `tasklist /FI "PID eq ${pid}" /FO CSV /NH 2>nul`,
          { encoding: 'utf-8', timeout: 3000 }
        );
        const match = output.match(/"([^"]+)","([^"]+)","([^"]+)"/);
        if (match) {
          const memKB = parseInt(match[3].replace(/[^0-9]/g, ''), 10);
          return memKB >= 1024 ? `${(memKB / 1024).toFixed(1)} MB` : `${memKB} KB`;
        }
      } else {
        const output = execSync(
          `ps -o rss= -p ${pid} 2>/dev/null`,
          { encoding: 'utf-8', timeout: 3000 }
        ).trim();
        const memKB = parseInt(output, 10);
        if (memKB > 0) {
          return memKB >= 1024 ? `${(memKB / 1024).toFixed(1)} MB` : `${memKB} KB`;
        }
      }
    } catch {
      // 无法获取内存信息
    }
    return null;
  }

  private readLogTail(lines: number, logFile?: string): string {
    const file = logFile || DEFAULT_LOG_FILE;
    try {
      if (!fs.existsSync(file)) return '(日志文件不存在)';
      const content = fs.readFileSync(file, 'utf-8');
      const allLines = content.split('\n').filter((l) => l.trim());
      const tail = allLines.slice(-lines);
      return tail.length > 0 ? tail.join('\n') : '(日志为空)';
    } catch {
      return '(无法读取日志)';
    }
  }

  formatUptime(seconds: number): string {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const s = seconds % 60;
    const parts: string[] = [];
    if (h > 0) parts.push(`${h}h`);
    if (m > 0) parts.push(`${m}m`);
    parts.push(`${s}s`);
    return parts.join(' ');
  }

  private sleep(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}

export default DaemonManager;

import { execSync } from 'child_process';
import * as fs from 'fs';
import * as path from 'path';
import { Logger } from '../utils/Logger';
import { UIElementParser } from './ui/UIElementParser';
import {
  UIAControlType,
  UIElement,
  UIElementNode,
  ElementQueryResult,
  UIInspectorConfig,
} from './ui/types';

export { UIAControlType, UIElement, UIElementNode, ElementQueryResult, UIInspectorConfig } from './ui/types';

export class DesktopUIInspector {
  private static instance: DesktopUIInspector | null = null;
  private initialized: boolean = false;
  private config: UIInspectorConfig;
  private parser: UIElementParser;

  private constructor(config?: UIInspectorConfig) {
    this.config = {
      maxDepth: config?.maxDepth ?? 8,
      includeInvisible: config?.includeInvisible ?? false,
      minSize: config?.minSize ?? 4,
      timeoutMs: config?.timeoutMs ?? 15000,
    };
    this.parser = UIElementParser.getInstance();
  }

  public static getInstance(config?: UIInspectorConfig): DesktopUIInspector {
    if (!DesktopUIInspector.instance) {
      DesktopUIInspector.instance = new DesktopUIInspector(config);
    }
    return DesktopUIInspector.instance;
  }

  public async initialize(): Promise<void> {
    if (this.initialized) return;
    Logger.info('🔍 DesktopUIInspector 初始化', 'DesktopUIInspector');
    this.initialized = true;
  }

  public getInteractiveElements(): UIElement[] {
    return this.inspectDesktop();
  }

  public getWindowElements(windowTitle: string): UIElement[] {
    return this.inspectWindow(windowTitle);
  }

  public findElement(description: string): ElementQueryResult {
    const allElements = this.getInteractiveElements();
    return this.parser.findElement(description, allElements);
  }

  public getControlTree(): UIElementNode[] {
    try {
      const json = this.runUIAScript(this.buildTreeScript());
      return this.parser.parseTreeNodes(json);
    } catch (error) {
      Logger.error('❌ 获取控件树失败', error as Error, 'DesktopUIInspector');
      return [];
    }
  }

  public getFocusedElement(): UIElement | null {
    try {
      const json = this.runUIAScript(this.buildFocusedElementScript());
      const elements = this.parser.parseElements(json);
      return elements.length > 0 ? elements[0] : null;
    } catch (error) {
      Logger.error('❌ 获取焦点控件失败', error as Error, 'DesktopUIInspector');
      return null;
    }
  }

  public getElementAtCursor(): UIElement | null {
    try {
      const json = this.runUIAScript(this.buildCursorElementScript());
      const elements = this.parser.parseElements(json);
      return elements.length > 0 ? elements[0] : null;
    } catch (error) {
      Logger.error(
        '❌ 获取光标下控件失败',
        error as Error,
        'DesktopUIInspector'
      );
      return null;
    }
  }

  public generateElementReport(elements?: UIElement[]): string {
    const elems = elements || this.getInteractiveElements();
    return this.parser.generateElementReport(elems);
  }

  private inspectDesktop(): UIElement[] {
    try {
      const json = this.runUIAScript(this.buildDesktopScript());
      return this.parser.parseElements(json);
    } catch (error) {
      Logger.error('❌ 桌面检查失败', error as Error, 'DesktopUIInspector');
      return [];
    }
  }

  private inspectWindow(windowTitle: string): UIElement[] {
    try {
      const json = this.runUIAScript(this.buildWindowScript(windowTitle));
      return this.parser.parseElements(json);
    } catch (error) {
      Logger.error(
        `❌ 窗口检查失败: ${windowTitle}`,
        error as Error,
        'DesktopUIInspector'
      );
      return [];
    }
  }

  private runUIAScript(script: string): string {
    const tmpDir = path.join(process.cwd(), 'tmp');
    if (!fs.existsSync(tmpDir)) fs.mkdirSync(tmpDir, { recursive: true });
    const tmpFile = path.join(tmpDir, `uia_inspect_${Date.now()}.ps1`);

    fs.writeFileSync(tmpFile, script, 'utf8');

    try {
      const result = execSync(
        `powershell -NoProfile -ExecutionPolicy Bypass -File "${tmpFile}"`,
        {
          encoding: 'utf-8',
          timeout: this.config.timeoutMs,
          maxBuffer: 50 * 1024 * 1024,
        }
      );
      return result;
    } finally {
      try {
        fs.unlinkSync(tmpFile);
      } catch {
        // ignore cleanup error
      }
    }
  }

  private buildDesktopScript(): string {
    return `
Add-Type -AssemblyName UIAutomationClient
$automation = [System.Windows.Automation.AutomationElement]::RootElement

function Get-ElementInfo {
  param($element, $depth = 0, $path = "")
  if ($depth -gt ${this.config.maxDepth}) { return @() }

  $rect = $element.Current.BoundingRectangle
  $width = $rect.Right - $rect.Left
  $height = $rect.Bottom - $rect.Top

  if ($width -lt ${this.config.minSize} -or $height -lt ${this.config.minSize}) { return @() }

  $isVisible = $element.Current.IsOffscreen -eq $false
  if (-not $isVisible -and -not $${this.config.includeInvisible}) { return @() }

  $pattern = $null
  $isClickable = [System.Windows.Automation.PatternIdentifiers]::InvokePattern -and
    $element.TryGetCurrentPattern([System.Windows.Automation.PatternIdentifiers]::InvokePattern, [ref]$pattern)

  $valuePattern = $null
  $isEditable = $element.TryGetCurrentPattern([System.Windows.Automation.PatternIdentifiers]::ValuePattern, [ref]$valuePattern)

  $name = $element.Current.Name
  $controlType = [int]$element.Current.ControlType.ProgrammaticName.Split(".")[-1]

  # 只收集有名称或可交互的控件
  if (-not $name -and -not $isClickable -and -not $isEditable) {
    # 继续遍历子元素
  }

  $info = @{
    name = $name
    automationId = $element.Current.AutomationId
    controlType = $controlType
    className = $element.Current.ClassName
    processName = $element.Current.ProcessId
    windowTitle = $automation.Current.Name
    x = $rect.Left
    y = $rect.Top
    width = $width
    height = $height
    isClickable = [bool]$isClickable
    isEditable = [bool]$isEditable
    isVisible = $isVisible
    isEnabled = $element.Current.IsEnabled
    hasKeyboardFocus = $element.Current.HasKeyboardFocus
    helpText = $element.Current.HelpText
    depth = $depth
    path = $path
    childCount = $element.FindAll([System.Windows.Automation.TreeScope]::Children, [System.Windows.Automation.Condition]::TrueCondition).Count
  }

  $results = @($info)

  $children = $element.FindAll([System.Windows.Automation.TreeScope]::Children, [System.Windows.Automation.Condition]::TrueCondition)
  for ($i = 0; $i -lt $children.Count; $i++) {
    $childPath = if ($path) { "$path > $($name)[$i]" } else { "$($name)[$i]" }
    $results += Get-ElementInfo -element $children[$i] -depth ($depth + 1) -path $childPath
  }

  return $results
}

$allElements = Get-ElementInfo -element $automation -depth 0 -path "Desktop"
$allElements | ConvertTo-Json -Compress -Depth 10
`;
  }

