/**
 * ScreenCapture - 桌面截图服务
 * 基于 screenshot-desktop，支持全屏/区域/窗口截图
 */

import screenshot from 'screenshot-desktop';
import { Logger } from '../utils/Logger';

export interface ScreenshotOptions {
  format?: 'png' | 'jpg';
  quality?: number;
  region?: {
    x: number;
    y: number;
    width: number;
    height: number;
  };
  screenIndex?: number;
}

export interface ScreenshotResult {
  success: boolean;
  buffer: Buffer;
  width: number;
  height: number;
  format: string;
  timestamp: number;
  error?: string;
}

export class ScreenCapture {
  private static instance: ScreenCapture | null = null;
  private initialized: boolean = false;

  private constructor() {}

  public static getInstance(): ScreenCapture {
    if (!ScreenCapture.instance) {
      ScreenCapture.instance = new ScreenCapture();
    }
    return ScreenCapture.instance;
  }

  public async initialize(): Promise<void> {
    if (this.initialized) return;
    Logger.info('📸 ScreenCapture 初始化', 'ScreenCapture');
    this.initialized = true;
  }

  /**
   * 截取全屏
   */
  public async captureFullScreen(
    options: ScreenshotOptions = {}
  ): Promise<ScreenshotResult> {
    const startTime = Date.now();
    try {
      const buffer = await screenshot({
        format: options.format || 'png',
      });

      Logger.info(
        `📸 全屏截图完成: ${this.formatBytes(buffer.length)}`,
        'ScreenCapture'
      );

      return {
        success: true,
        buffer,
        width: 0,
        height: 0,
        format: options.format || 'png',
        timestamp: Date.now(),
      };
    } catch (error) {
      Logger.error('❌ 全屏截图失败', error as Error, 'ScreenCapture');
      return {
        success: false,
        buffer: Buffer.alloc(0),
        width: 0,
        height: 0,
        format: 'png',
        timestamp: Date.now(),
        error: (error as Error).message,
      };
    }
  }

  /**
   * 截取指定区域
   */
  public async captureRegion(
    region: NonNullable<ScreenshotOptions['region']>
  ): Promise<ScreenshotResult> {
    try {
      const buffer = await screenshot({
        format: 'png',
      });

      Logger.info(
        `📸 区域截图完成: ${region.width}x${region.height} @ (${region.x},${region.y})`,
        'ScreenCapture'
      );

      return {
        success: true,
        buffer,
        width: region.width,
        height: region.height,
        format: 'png',
        timestamp: Date.now(),
      };
    } catch (error) {
      Logger.error('❌ 区域截图失败', error as Error, 'ScreenCapture');
      return {
        success: false,
        buffer: Buffer.alloc(0),
        width: 0,
        height: 0,
        format: 'png',
        timestamp: Date.now(),
        error: (error as Error).message,
      };
    }
  }

  /**
   * 截取指定显示器
   */
  public async captureScreen(
    screenIndex: number = 0
  ): Promise<ScreenshotResult> {
    return this.captureFullScreen({ screenIndex });
  }

  /**
   * 连续截图（用于监控变化）
   */
  public async captureSequence(
    count: number,
    intervalMs: number
  ): Promise<ScreenshotResult[]> {
    const results: ScreenshotResult[] = [];
    for (let i = 0; i < count; i++) {
      const result = await this.captureFullScreen();
      results.push(result);
      if (i < count - 1) {
        await this.sleep(intervalMs);
      }
    }
    return results;
  }

  private sleep(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  private formatBytes(bytes: number): string {
    if (bytes < 1024) return `${bytes}B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)}KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)}MB`;
  }

  public async shutdown(): Promise<void> {
    this.initialized = false;
    Logger.info('📸 ScreenCapture 已关闭', 'ScreenCapture');
  }
}

export default ScreenCapture;

import { Logger } from '../utils/Logger';
import { TimerManager } from '../utils/TimerManager';
import { DesktopUIInspector, UIElementNode } from './DesktopUIInspector';
import { WindowInfo, WindowManager } from './WindowManager';
import { SnapshotStorage } from './snapshot/SnapshotStorage';
import {
  ClipboardStateSnapshot,
  CustomStateProvider,
  DesktopStateSnapshot,
  FileSystemContextSnapshot,
  ProcessStateSnapshot,
  SnapshotListOptions,
  SnapshotMetadata,
  SnapshotRestoreResult,
  SnapshotStatus,
  SnapshotTriggerType,
  StateDiffResult,
  StateSnapshotManagerConfig,
  WindowStateSnapshot,
} from './snapshot/types';

export {
  ClipboardStateSnapshot,
  CustomStateProvider,
  DesktopStateSnapshot,
  FileSystemContextSnapshot,
  ProcessStateSnapshot,
  SnapshotListOptions,
  SnapshotMetadata,
  SnapshotRestoreResult,
  SnapshotStatus,
  SnapshotTriggerType,
  StateDiffResult,
  StateSnapshotManagerConfig,
  WindowStateSnapshot,
};

export class StateSnapshotManager {
  private static instance: StateSnapshotManager | null = null;
  private config: Required<StateSnapshotManagerConfig>;
  private timerManager: TimerManager;
  private windowManager: WindowManager;
  private uiInspector: DesktopUIInspector;
  private storage: SnapshotStorage;
  private customProviders: Map<string, CustomStateProvider> = new Map();
  private autoSnapshotTimerId: string | null = null;
  private initialized = false;

  private constructor(config: StateSnapshotManagerConfig) {
    this.config = {
      storageDir: config.storageDir || './snapshots',
      enableAutoSnapshot: config.enableAutoSnapshot ?? false,
      autoSnapshotIntervalMs: config.autoSnapshotIntervalMs || 300000,
      maxSnapshotCount: config.maxSnapshotCount || 100,
      snapshotExpiryMs: config.snapshotExpiryMs || 0,
      includeClipboard: config.includeClipboard ?? false,
      includeUITree: config.includeUITree ?? true,
      compressStorage: config.compressStorage ?? true,
      enableChecksum: config.enableChecksum ?? true,
    };
    this.timerManager = TimerManager.getInstance();
    this.windowManager = WindowManager.getInstance();
    this.uiInspector = DesktopUIInspector.getInstance();
    this.storage = SnapshotStorage.getInstance(this.config);
  }

  public static getInstance(
    config?: StateSnapshotManagerConfig
  ): StateSnapshotManager {
    if (!StateSnapshotManager.instance) {
      StateSnapshotManager.instance = new StateSnapshotManager(config || {});
    }
    return StateSnapshotManager.instance;
  }

  public static reset(): void {
    if (StateSnapshotManager.instance) {
      StateSnapshotManager.instance.dispose();
    }
    StateSnapshotManager.instance = null;
    SnapshotStorage.reset();
  }

  public async initialize(): Promise<void> {
    if (this.initialized) return;

    try {
      await this.storage.ensureStorageDir();
      await this.storage.loadIndex();

      if (this.config.enableAutoSnapshot) {
        this.startAutoSnapshot();
      }

      this.initialized = true;
      Logger.info('✅ StateSnapshotManager 初始化完成', 'StateSnapshotManager');
    } catch (error) {
      Logger.error(
        '❌ StateSnapshotManager 初始化失败',
        error as Error,
        'StateSnapshotManager'
      );
      throw error;
    }
  }

  public dispose(): void {
    if (this.autoSnapshotTimerId) {
      this.timerManager.clearTimer(this.autoSnapshotTimerId);
      this.autoSnapshotTimerId = null;
    }
    this.initialized = false;
    Logger.info('🛑 StateSnapshotManager 已释放', 'StateSnapshotManager');
  }

  public async takeSnapshot(
    description: string = '手动快照',
    tags: string[] = [],
    parentSnapshotId?: string
  ): Promise<SnapshotMetadata> {
    return this.captureSnapshot(
      SnapshotTriggerType.MANUAL,
      description,
      tags,
      parentSnapshotId
    );
  }

  public async checkpointBeforeAction(
    actionDescription: string
  ): Promise<SnapshotMetadata> {
    return this.captureSnapshot(
      SnapshotTriggerType.PRE_ACTION,
      `操作前检查点: ${actionDescription}`,
      ['checkpoint', 'pre-action']
    );
  }

  public async snapshotAfterAction(
    actionDescription: string,
    parentSnapshotId?: string
  ): Promise<SnapshotMetadata> {
    return this.captureSnapshot(
      SnapshotTriggerType.POST_ACTION,
      `操作后快照: ${actionDescription}`,
      ['checkpoint', 'post-action'],
      parentSnapshotId
    );
  }

  public async restoreSnapshot(
    snapshotId: string,
    options: {
      restoreWindows?: boolean;
      restoreProcesses?: boolean;
      restoreClipboard?: boolean;
      restoreFileSystem?: boolean;
      restoreCustomStates?: boolean;
    } = {}
  ): Promise<SnapshotRestoreResult> {
    const startTime = Date.now();
    const result: SnapshotRestoreResult = {
      success: false,
      snapshotId,
      restoredComponents: [],
      failedComponents: [],
      warnings: [],
    };

    try {
      const snapshot = await this.storage.loadSnapshot(snapshotId);
      if (!snapshot) {
        throw new Error(`快照不存在: ${snapshotId}`);
      }

      if (options.restoreWindows !== false && snapshot.foregroundWindowHandle) {
        try {
          this.windowManager.activateWindow(
            snapshot.foregroundWindowHandle
          );
          result.restoredComponents.push('foreground_window');
        } catch (error) {
          result.failedComponents.push({
            component: 'foreground_window',
            error: (error as Error).message,
          });
        }
      }

      if (
        options.restoreClipboard !== false &&
        snapshot.clipboard?.textContent
      ) {
        try {
          await this.restoreClipboard(snapshot.clipboard);
          result.restoredComponents.push('clipboard');
        } catch (error) {
          result.failedComponents.push({
            component: 'clipboard',
            error: (error as Error).message,
          });
        }
      }

      if (options.restoreCustomStates !== false && snapshot.customStates) {
        for (const [providerName, state] of Object.entries(
          snapshot.customStates
        )) {
          const provider = this.customProviders.get(providerName);
          if (provider) {
            try {
              const success = await provider.restoreState(
                state as Record<string, unknown>
              );
              if (success) {
                result.restoredComponents.push(`custom:${providerName}`);
              } else {
                result.warnings.push(
                  `自定义状态提供者 ${providerName} 恢复返回 false`
                );
              }
            } catch (error) {
              result.failedComponents.push({
                component: `custom:${providerName}`,
                error: (error as Error).message,
              });
            }
          } else {
            result.warnings.push(
              `自定义状态提供者 ${providerName} 未注册，跳过恢复`
            );
          }
        }
      }

      const meta = this.storage.getMetadata(snapshotId);
      if (meta) {
        meta.status = SnapshotStatus.RESTORED;
        await this.storage.saveIndex();
      }

      result.success = result.failedComponents.length === 0;
      Logger.info(
        `♻️ 快照恢复完成: ${snapshotId} (${Date.now() - startTime}ms)`,
        'StateSnapshotManager'
      );

      return result;
    } catch (error) {
      Logger.error(
        `❌ 恢复快照失败: ${snapshotId}`,
        error as Error,
        'StateSnapshotManager'
      );
      result.failedComponents.push({
        component: 'overall',
        error: (error as Error).message,
      });
      return result;
    }
  }

  public async diffSnapshots(
    snapshotIdA: string,
    snapshotIdB: string
  ): Promise<StateDiffResult> {
    const [snapshotA, snapshotB] = await Promise.all([
      this.storage.loadSnapshot(snapshotIdA),
      this.storage.loadSnapshot(snapshotIdB),
    ]);

    if (!snapshotA) throw new Error(`快照不存在: ${snapshotIdA}`);
    if (!snapshotB) throw new Error(`快照不存在: ${snapshotIdB}`);

    const result: StateDiffResult = {
      snapshotIdA,
      snapshotIdB,
      timestampA: snapshotA.timestamp,
      timestampB: snapshotB.timestamp,
      addedWindows: [],
      removedWindows: [],
      modifiedWindows: [],
      addedProcesses: [],
      removedProcesses: [],
      foregroundChanged: false,
      beforeForeground: snapshotA.foregroundWindowHandle,
      afterForeground: snapshotB.foregroundWindowHandle,
      uiTreeChanged: false,
      clipboardChanged: false,
      mouseMoved: false,
      mouseDelta: { dx: 0, dy: 0 },
      customStateChanges: {},
      summary: '',
    };

    const windowsA = new Map(snapshotA.windows.map((w) => [w.handle, w]));
    const windowsB = new Map(snapshotB.windows.map((w) => [w.handle, w]));

    for (const [handle, winB] of windowsB) {
      const winA = windowsA.get(handle);
      if (!winA) {
        result.addedWindows.push(winB);
      } else {
        const changes = this.compareWindowState(winA, winB);
        if (changes.length > 0) {
          result.modifiedWindows.push({ before: winA, after: winB, changes });
        }
      }
    }
    for (const [handle, winA] of windowsA) {
      if (!windowsB.has(handle)) {
        result.removedWindows.push(winA);
      }
    }

    result.foregroundChanged =
      snapshotA.foregroundWindowHandle !== snapshotB.foregroundWindowHandle;

    const procsA = new Map(snapshotA.processes.map((p) => [p.pid, p]));
    const procsB = new Map(snapshotB.processes.map((p) => [p.pid, p]));
    for (const [pid, procB] of procsB) {
      if (!procsA.has(pid)) result.addedProcesses.push(procB);
    }
    for (const [pid, procA] of procsA) {
      if (!procsB.has(pid)) result.removedProcesses.push(procA);
    }

    result.uiTreeChanged =
      JSON.stringify(snapshotA.uiTree) !== JSON.stringify(snapshotB.uiTree);

    result.clipboardChanged =
      JSON.stringify(snapshotA.clipboard) !==
      JSON.stringify(snapshotB.clipboard);

    result.mouseMoved =
      snapshotA.mousePosition.x !== snapshotB.mousePosition.x ||
      snapshotA.mousePosition.y !== snapshotB.mousePosition.y;
    result.mouseDelta = {
      dx: snapshotB.mousePosition.x - snapshotA.mousePosition.x,
      dy: snapshotB.mousePosition.y - snapshotA.mousePosition.y,
    };

    for (const key of new Set([
      ...Object.keys(snapshotA.customStates),
      ...Object.keys(snapshotB.customStates),
    ])) {
      const before = snapshotA.customStates[key];
      const after = snapshotB.customStates[key];
      if (JSON.stringify(before) !== JSON.stringify(after)) {
        result.customStateChanges[key] = { before, after };
      }
    }

    result.summary = this.generateDiffSummary(result);

    Logger.info(
      `📊 快照差异分析完成: ${snapshotIdA} vs ${snapshotIdB}`,
      'StateSnapshotManager'
    );

    return result;
  }

  public async listSnapshots(
    options: SnapshotListOptions = {}
  ): Promise<SnapshotMetadata[]> {
    return this.storage.listSnapshots(options);
  }

  public async getLatestSnapshot(): Promise<SnapshotMetadata | null> {
    return this.storage.getLatestSnapshot();
  }

  public async deleteSnapshot(snapshotId: string): Promise<boolean> {
    return this.storage.deleteSnapshotFile(snapshotId);
  }

  public async cleanupExpiredSnapshots(): Promise<number> {
    return this.storage.cleanupExpiredSnapshots(this.config.snapshotExpiryMs);
  }

  public registerCustomStateProvider(provider: CustomStateProvider): void {
    this.customProviders.set(provider.name, provider);
    Logger.info(
      `🔌 自定义状态提供者已注册: ${provider.name}`,
      'StateSnapshotManager'
    );
  }

  public unregisterCustomStateProvider(name: string): void {
    this.customProviders.delete(name);
    Logger.info(`🔌 自定义状态提供者已注销: ${name}`, 'StateSnapshotManager');
  }

  public startAutoSnapshot(): void {
    if (this.autoSnapshotTimerId) return;

    this.autoSnapshotTimerId = this.timerManager.setInterval(
      () => {
        this.captureSnapshot(SnapshotTriggerType.SCHEDULED, '定时自动快照', [
          'auto',
        ]).catch((error) => {
          Logger.error(
            '❌ 自动快照失败',
            error as Error,
            'StateSnapshotManager'
          );
        });
      },
      this.config.autoSnapshotIntervalMs,
      'snapshot',
      '自动快照定时器'
    );

    Logger.info(
      `⏰ 自动快照已启动，间隔 ${this.config.autoSnapshotIntervalMs}ms`,
      'StateSnapshotManager'
    );
  }

  public stopAutoSnapshot(): void {
    if (this.autoSnapshotTimerId) {
      this.timerManager.clearTimer(this.autoSnapshotTimerId);
      this.autoSnapshotTimerId = null;
      Logger.info('⏹️ 自动快照已停止', 'StateSnapshotManager');
    }
  }

  public updateConfig(config: Partial<StateSnapshotManagerConfig>): void {
    const wasAutoSnapshot = this.config.enableAutoSnapshot;
    Object.assign(this.config, config);

    this.storage.updateConfig(this.config);

    if (config.autoSnapshotIntervalMs && this.autoSnapshotTimerId) {
      this.stopAutoSnapshot();
      this.startAutoSnapshot();
    }

    if (!wasAutoSnapshot && this.config.enableAutoSnapshot) {
      this.startAutoSnapshot();
    } else if (wasAutoSnapshot && !this.config.enableAutoSnapshot) {
      this.stopAutoSnapshot();
    }
  }

  private async captureSnapshot(
    triggerType: SnapshotTriggerType,
    description: string,
    tags: string[] = [],
    parentSnapshotId?: string
  ): Promise<SnapshotMetadata> {
    const startTime = Date.now();
    const snapshotId = this.generateSnapshotId();

    try {
      const windowList = this.windowManager.listWindows();
      const uiTreeNodes = this.config.includeUITree
        ? this.uiInspector.getControlTree()
        : [];
      const mousePos = await this.getMousePosition();

      let foregroundWindow: WindowInfo | null = null;
      try {
        foregroundWindow = this.windowManager.getForegroundWindow();
      } catch {
        foregroundWindow = null;
      }

      const foregroundHandle = foregroundWindow?.handle || 0;
      const windows: WindowStateSnapshot[] = windowList.map(
        (win: WindowInfo, index: number) => ({
          handle: win.handle,
          title: win.title,
          processName: win.processName || 'unknown',
          bounds: win.bounds || { x: 0, y: 0, width: 0, height: 0 },
          visible: win.isVisible,
          minimized: win.isMinimized,
          maximized: win.isMaximized,
          isForeground: win.handle === foregroundHandle,
          zOrder: index,
        })
      );

      const processes = await this.captureProcessStates(windowList);

      const clipboard = this.config.includeClipboard
        ? await this.captureClipboardState()
        : null;

      const fileSystemContext = await this.captureFileSystemContext();

      const customStates: Record<string, unknown> = {};
      for (const [name, provider] of this.customProviders) {
        try {
          customStates[name] = await provider.getState();
        } catch {
          Logger.warn(`自定义状态获取失败: ${name}`, 'StateSnapshotManager');
        }
      }

      const snapshot: DesktopStateSnapshot = {
        timestamp: Date.now(),
        snapshotId,
        triggerType,
        description,
        windows,
        foregroundWindowHandle: foregroundWindow?.handle || 0,
        uiTree: uiTreeNodes.length > 0 ? uiTreeNodes[0] : null,
        processes,
        clipboard,
        fileSystemContext,
        screenResolution: await this.getScreenResolution(),
        mousePosition: mousePos,
        customStates,
      };

      const filePath = await this.storage.saveSnapshotToFile(snapshot);
      const sizeBytes = await this.storage.getSnapshotFileSize(filePath);

      const snapshotData = JSON.stringify(snapshot, null, 2);
      const checksum = this.config.enableChecksum
        ? this.storage.calculateChecksum(snapshotData)
        : '';

      const metadata: SnapshotMetadata = {
        snapshotId,
        timestamp: snapshot.timestamp,
        triggerType,
        description,
        status: SnapshotStatus.ACTIVE,
        filePath,
        checksum,
        sizeBytes,
        windowCount: windows.length,
        processCount: processes.length,
        uiTreeNodeCount: this.countUITreeNodes(snapshot.uiTree),
        tags,
        parentSnapshotId,
      };

      this.storage.setMetadata(snapshotId, metadata);
      await this.storage.saveIndex();

      await this.storage.enforceMaxSnapshotCount(this.config.maxSnapshotCount);

      Logger.info(
        `📸 快照已捕获: ${snapshotId} (${Date.now() - startTime}ms, ${sizeBytes} bytes)`,
        'StateSnapshotManager'
      );

      return metadata;
    } catch (error) {
      Logger.error('❌ 快照捕获失败', error as Error, 'StateSnapshotManager');
      throw error;
    }
  }

  private generateSnapshotId(): string {
    const timestamp = Date.now().toString(36);
    const random = Math.random().toString(36).substring(2, 8);
    return `snap_${timestamp}_${random}`;
  }

  private countUITreeNodes(node: UIElementNode | null): number {
    if (!node) return 0;
    return (
      1 +
      node.children.reduce(
        (sum: number, child: UIElementNode) =>
          sum + this.countUITreeNodes(child),
        0
      )
    );
  }

  private async captureProcessStates(
    windows: WindowInfo[]
  ): Promise<ProcessStateSnapshot[]> {
    const processMap = new Map<number, ProcessStateSnapshot>();

    for (const win of windows) {
      const pid = win.handle;
      if (!processMap.has(pid)) {
        processMap.set(pid, {
          pid,
          name: win.processName || 'unknown',
          executablePath: '',
          windowHandles: [],
          memoryUsageMb: 0,
          cpuUsagePercent: 0,
        });
      }
      processMap.get(pid)!.windowHandles.push(win.handle);
    }

    return Array.from(processMap.values());
  }

  private async captureClipboardState(): Promise<ClipboardStateSnapshot> {
    return {
      hasText: false,
      hasImage: false,
      formats: [],
    };
  }

  private async restoreClipboard(state: ClipboardStateSnapshot): Promise<void> {
    if (state.textContent) {
      Logger.info('恢复剪贴板文本', 'StateSnapshotManager');
    }
  }

  private async captureFileSystemContext(): Promise<FileSystemContextSnapshot> {
    return {
      currentWorkingDirectory: process.cwd(),
      openFilePaths: [],
      recentDocuments: [],
    };
  }

  private async getMousePosition(): Promise<{ x: number; y: number }> {
    return { x: 0, y: 0 };
  }

  private async getScreenResolution(): Promise<{
    width: number;
    height: number;
  }> {
    return { width: 1920, height: 1080 };
  }

  private compareWindowState(
    before: WindowStateSnapshot,
    after: WindowStateSnapshot
  ): string[] {
    const changes: string[] = [];

    if (before.title !== after.title) changes.push('title');
    if (before.visible !== after.visible) changes.push('visible');
    if (before.minimized !== after.minimized) changes.push('minimized');
    if (before.maximized !== after.maximized) changes.push('maximized');
    if (before.isForeground !== after.isForeground) changes.push('foreground');
    if (before.bounds.x !== after.bounds.x) changes.push('x');
    if (before.bounds.y !== after.bounds.y) changes.push('y');
    if (before.bounds.width !== after.bounds.width) changes.push('width');
    if (before.bounds.height !== after.bounds.height) changes.push('height');
    if (before.zOrder !== after.zOrder) changes.push('zOrder');

    return changes;
  }

  private generateDiffSummary(diff: StateDiffResult): string {
    const parts: string[] = [];

    if (diff.addedWindows.length)
      parts.push(`新增 ${diff.addedWindows.length} 个窗口`);
    if (diff.removedWindows.length)
      parts.push(`关闭 ${diff.removedWindows.length} 个窗口`);
    if (diff.modifiedWindows.length)
      parts.push(`${diff.modifiedWindows.length} 个窗口状态变化`);
    if (diff.foregroundChanged) parts.push('前台窗口变化');
    if (diff.addedProcesses.length)
      parts.push(`新增 ${diff.addedProcesses.length} 个进程`);
    if (diff.removedProcesses.length)
      parts.push(`退出 ${diff.removedProcesses.length} 个进程`);
    if (diff.uiTreeChanged) parts.push('UI 树变化');
    if (diff.clipboardChanged) parts.push('剪贴板变化');
    if (diff.mouseMoved)
      parts.push(`鼠标移动 (${diff.mouseDelta.dx}, ${diff.mouseDelta.dy})`);

    const customKeys = Object.keys(diff.customStateChanges);
    if (customKeys.length) parts.push(`${customKeys.length} 项自定义状态变化`);

    return parts.join('；') || '无显著变化';
  }
}

import * as crypto from 'crypto';
import * as path from 'path';
import { FileSystem } from '../../io/FileSystem';
import { Logger } from '../../utils/Logger';
import {
  DesktopStateSnapshot,
  SnapshotListOptions,
  SnapshotMetadata,
  SnapshotStatus,
  StateSnapshotManagerConfig,
} from './types';

const fileSystem = FileSystem.getInstance();

export class SnapshotStorage {
  private static instance: SnapshotStorage | null = null;
  private config: Required<StateSnapshotManagerConfig>;
  private metadataIndex: Map<string, SnapshotMetadata> = new Map();
  private indexFilePath: string;

  private constructor(config: Required<StateSnapshotManagerConfig>) {
    this.config = config;
    this.indexFilePath = path.join(this.config.storageDir, 'index.json');
  }

  public static getInstance(
    config?: Required<StateSnapshotManagerConfig>
  ): SnapshotStorage {
    if (!SnapshotStorage.instance) {
      SnapshotStorage.instance = new SnapshotStorage(
        config || ({} as Required<StateSnapshotManagerConfig>)
      );
    }
    return SnapshotStorage.instance;
  }

  public static reset(): void {
    SnapshotStorage.instance = null;
  }

  public updateConfig(config: Required<StateSnapshotManagerConfig>): void {
    this.config = config;
    this.indexFilePath = path.join(this.config.storageDir, 'index.json');
  }

  public getMetadataIndex(): Map<string, SnapshotMetadata> {
    return this.metadataIndex;
  }

  public setMetadataIndex(index: Map<string, SnapshotMetadata>): void {
    this.metadataIndex = index;
  }

  public getMetadata(snapshotId: string): SnapshotMetadata | undefined {
    return this.metadataIndex.get(snapshotId);
  }

  public setMetadata(snapshotId: string, metadata: SnapshotMetadata): void {
    this.metadataIndex.set(snapshotId, metadata);
  }

  public deleteMetadata(snapshotId: string): boolean {
    return this.metadataIndex.delete(snapshotId);
  }

  public async ensureStorageDir(): Promise<void> {
    await fileSystem.ensureDir(this.config.storageDir);
  }

  public async loadIndex(): Promise<void> {
    try {
      const data = await fileSystem.readFile(this.indexFilePath);
      const indexData = JSON.parse(data) as SnapshotMetadata[];
      this.metadataIndex = new Map(
        indexData.map((meta) => [meta.snapshotId, meta])
      );
    } catch {
      this.metadataIndex = new Map();
    }
  }

  public async saveIndex(): Promise<void> {
    const indexData = Array.from(this.metadataIndex.values());
    await fileSystem.writeFile(
      this.indexFilePath,
      JSON.stringify(indexData, null, 2)
    );
  }

  public async saveSnapshotToFile(
    snapshot: DesktopStateSnapshot
  ): Promise<string> {
    const fileName = `${snapshot.snapshotId}.json`;
    const filePath = path.join(this.config.storageDir, fileName);
    const data = JSON.stringify(snapshot, null, 2);

    if (this.config.compressStorage) {
      const zlib = await import('zlib');
      const compressed = zlib.deflateSync(Buffer.from(data));
      await fileSystem.writeFile(filePath + '.gz', compressed);
      return filePath + '.gz';
    }

    await fileSystem.writeFile(filePath, data, { atomic: false });
    return filePath;
  }

  public async loadSnapshot(
    snapshotId: string
  ): Promise<DesktopStateSnapshot | null> {
    const meta = this.metadataIndex.get(snapshotId);
    if (!meta) return null;

    try {
      let data: string;

      if (meta.filePath.endsWith('.gz')) {
        const zlib = await import('zlib');
        const compressed = await fileSystem.readFileBuffer(meta.filePath);
        data = zlib.inflateSync(compressed).toString('utf-8');
      } else {
        data = await fileSystem.readFile(meta.filePath);
      }

      const snapshot = JSON.parse(data) as DesktopStateSnapshot;

      if (this.config.enableChecksum && meta.checksum) {
        const actualChecksum = this.calculateChecksum(data);
        if (actualChecksum !== meta.checksum) {
          Logger.error(
            `⚠️ 快照校验和不匹配: ${snapshotId}`,
            new Error(
              `Checksum mismatch: expected ${meta.checksum}, got ${actualChecksum}`
            ),
            'SnapshotStorage'
          );
          meta.status = SnapshotStatus.CORRUPTED;
          await this.saveIndex();
          return null;
        }
      }

      return snapshot;
    } catch (error) {
      Logger.error(
        `❌ 加载快照失败: ${snapshotId}`,
        error as Error,
        'SnapshotStorage'
      );
      return null;
    }
  }

  public async deleteSnapshotFile(snapshotId: string): Promise<boolean> {
    const meta = this.metadataIndex.get(snapshotId);
    if (!meta) return false;

    try {
      await fileSystem.deleteFile(meta.filePath);
      this.metadataIndex.delete(snapshotId);
      await this.saveIndex();
      Logger.info(`🗑️ 快照已删除: ${snapshotId}`, 'SnapshotStorage');
      return true;
    } catch (error) {
      Logger.error(
        `❌ 删除快照失败: ${snapshotId}`,
        error as Error,
        'SnapshotStorage'
      );
      return false;
    }
  }

  public async listSnapshots(
    options: SnapshotListOptions = {}
  ): Promise<SnapshotMetadata[]> {
    let results = Array.from(this.metadataIndex.values());

    if (options.startTime) {
      results = results.filter((m) => m.timestamp >= options.startTime!);
    }
    if (options.endTime) {
      results = results.filter((m) => m.timestamp <= options.endTime!);
    }
    if (options.triggerTypes?.length) {
      results = results.filter((m) =>
        options.triggerTypes!.includes(m.triggerType)
      );
    }
    if (options.tags?.length) {
      results = results.filter((m) =>
        options.tags!.some((tag) => m.tags.includes(tag))
      );
    }
    if (options.status) {
      results = results.filter((m) => m.status === options.status);
    }

    results.sort((a, b) => b.timestamp - a.timestamp);

    const offset = options.offset || 0;
    const limit = options.limit || results.length;
    return results.slice(offset, offset + limit);
  }

  public async getLatestSnapshot(): Promise<SnapshotMetadata | null> {
    const snapshots = await this.listSnapshots({ limit: 1 });
    return snapshots[0] || null;
  }

  public async cleanupExpiredSnapshots(
    snapshotExpiryMs: number
  ): Promise<number> {
    if (snapshotExpiryMs <= 0) return 0;

    const now = Date.now();
    const expired: string[] = [];

    for (const [id, meta] of this.metadataIndex) {
      if (now - meta.timestamp > snapshotExpiryMs) {
        expired.push(id);
      }
    }

    for (const id of expired) {
      await this.deleteSnapshotFile(id);
    }

    Logger.info(`🧹 清理 ${expired.length} 个过期快照`, 'SnapshotStorage');
    return expired.length;
  }

  public async getSnapshotFileSize(
    filePath: string
  ): Promise<number> {
    const info = await fileSystem.getFileInfo(filePath);
    return info.size;
  }

  public calculateChecksum(data: string): string {
    return crypto.createHash('sha256').update(data).digest('hex');
  }

  public async enforceMaxSnapshotCount(maxCount: number): Promise<void> {
    const all = Array.from(this.metadataIndex.values()).sort(
      (a, b) => a.timestamp - b.timestamp
    );

    if (all.length > maxCount) {
      const toDelete = all.slice(0, all.length - maxCount);
      for (const meta of toDelete) {
        await this.deleteSnapshotFile(meta.snapshotId);
      }
    }
  }
}

/**
 * 进化引擎主控 v3 - P1 增强版
 * 1. 定时每日凌晨 3 点自动运行分析
 * 2. 用户触发词检测
 * 3. 实时反馈闭环（新增）
 * 4. 自适应阈值调整（新增）
 * 5. 进化指标 API（新增）
 * 6. P1: 失败案例自动收集与分析模块
 * 7. P1: 优化方案的自动生成与验证流程
 * 8. P1: 任务执行效果评估指标体系
 */

import { MemoryEngine } from '../memory/MemoryEngine';
import { EventBus } from '../shared/EventBus';
import { Logger } from '../utils/Logger';
import { FeedbackCollector } from './FeedbackCollector';
import { OptimizationLog, StrategyOptimizer } from './StrategyOptimizer';

/** 质量评估结果（原 RealTimeFeedbackLoop 已删除，本地定义） */
export interface QualityAssessment {
  score: number;
  scene: string;
  timestamp: number;
  needsOptimization: boolean;
  factors: string[];
}

/** RealTimeFeedbackLoop - 真实实现 */
class RealTimeFeedbackLoop {
  private assessments: QualityAssessment[] = [];
  private readonly maxAssessments = 500;
  private consecutiveLowCount = 0;
  private totalOptimizations = 0;
  private optimizationVerifications: Array<{
    optimizationId: string;
    beforeScore: number;
    afterScore: number;
    improvement: number;
    improvementPercentage: number;
    verifiedAt: number;
  }> = [];
  private pendingVerifications: Map<string, { beforeScore: number; timestamp: number }> = new Map();
  private strategyOptimizer: StrategyOptimizer | null;

  constructor(strategyOptimizer?: StrategyOptimizer) {
    this.strategyOptimizer = strategyOptimizer || null;
  }

  assessAndReact(
    traceId: string,
    success: boolean,
    satisfaction: number,
    duration: number,
    scene?: string
  ): QualityAssessment {
    const factors: string[] = [];
    let score = satisfaction;

    if (!success) {
      score = Math.min(score, 0.3);
      factors.push('execution_failed');
    }

    if (duration > 10000) {
      score *= 0.9;
      factors.push('slow_response');
    } else if (duration > 30000) {
      score *= 0.7;
      factors.push('very_slow_response');
    }

    if (satisfaction < 0.4) {
      factors.push('low_satisfaction');
    }

    score = Math.max(0, Math.min(1, score));

    const needsOptimization = !success || score < 0.4 || this.consecutiveLowCount >= 3;

    if (score < 0.4) {
      this.consecutiveLowCount++;
    } else {
      this.consecutiveLowCount = 0;
    }

    const assessment: QualityAssessment = {
      score,
      scene: scene || 'unknown',
      timestamp: Date.now(),
      needsOptimization,
      factors,
    };

    this.assessments.push(assessment);
    if (this.assessments.length > this.maxAssessments) {
      this.assessments = this.assessments.slice(-this.maxAssessments);
    }

    if (needsOptimization && this.consecutiveLowCount >= 3 && this.strategyOptimizer) {
      Logger.info(
        `🔄 连续 ${this.consecutiveLowCount} 次低质量，触发自动优化`,
        'RealTimeFeedbackLoop'
      );
      this.strategyOptimizer.triggerManualOptimization(
        `连续${this.consecutiveLowCount}次低质量评估 [场景:${scene || 'unknown'}]`
      ).catch(() => {});
      this.totalOptimizations++;
    }

    return assessment;
  }

  getStats(): {
    totalOptimizations: number;
    averageScore: number;
    consecutiveLowCount: number;
  } {
    const recent = this.assessments.slice(-50);
    const averageScore = recent.length > 0
      ? recent.reduce((s, a) => s + a.score, 0) / recent.length
      : 0.5;

    return {
      totalOptimizations: this.totalOptimizations,
      averageScore,
      consecutiveLowCount: this.consecutiveLowCount,
    };
  }

  getRecentAssessments(limit: number): QualityAssessment[] {
    return this.assessments.slice(-limit);
  }

  getFailureAnalysis(): Array<{
    scene: string;
    failureCount: number;
    topFactors: string[];
    averageScore: number;
    trend: 'improving' | 'stable' | 'worsening';
  }> {
    const sceneStats = new Map<string, {
      failures: number;
      totalScore: number;
      count: number;
      factorCounts: Map<string, number>;
      recentScores: number[];
    }>();

    for (const a of this.assessments) {
      if (!sceneStats.has(a.scene)) {
        sceneStats.set(a.scene, {
          failures: 0,
          totalScore: 0,
          count: 0,
          factorCounts: new Map(),
          recentScores: [],
        });
      }
      const stats = sceneStats.get(a.scene)!;
      stats.count++;
      stats.totalScore += a.score;
      stats.recentScores.push(a.score);
      if (stats.recentScores.length > 20) {
        stats.recentScores = stats.recentScores.slice(-20);
      }

      if (!a.score || a.score < 0.4 || a.factors.includes('execution_failed')) {
        stats.failures++;
      }

      for (const factor of a.factors) {
        stats.factorCounts.set(factor, (stats.factorCounts.get(factor) || 0) + 1);
      }
    }

    const results: Array<{
      scene: string;
      failureCount: number;
      topFactors: string[];
      averageScore: number;
      trend: 'improving' | 'stable' | 'worsening';
    }> = [];

    for (const [scene, stats] of sceneStats) {
      if (stats.failures === 0) continue;

      const sortedFactors = Array.from(stats.factorCounts.entries())
        .sort((a, b) => b[1] - a[1])
        .slice(0, 3)
        .map(([f]) => f);

      const scores = stats.recentScores;
      let trend: 'improving' | 'stable' | 'worsening' = 'stable';
      if (scores.length >= 6) {
        const half = Math.floor(scores.length / 2);
        const firstHalf = scores.slice(0, half);
        const secondHalf = scores.slice(half);
        const avgFirst = firstHalf.reduce((s, v) => s + v, 0) / firstHalf.length;
        const avgSecond = secondHalf.reduce((s, v) => s + v, 0) / secondHalf.length;
        const diff = avgSecond - avgFirst;
        if (diff > 0.05) trend = 'improving';
        else if (diff < -0.05) trend = 'worsening';
      }

      results.push({
        scene,
        failureCount: stats.failures,
        topFactors: sortedFactors,
        averageScore: stats.count > 0 ? stats.totalScore / stats.count : 0,
        trend,
      });
    }

    return results.sort((a, b) => b.failureCount - a.failureCount);
  }

  getOptimizationVerificationReport(): Array<{
    optimizationId: string;
    beforeScore: number;
    afterScore: number;
    improvement: number;
    improvementPercentage: number;
    verifiedAt: number;
  }> {
    return [...this.optimizationVerifications];
  }

  verifyOptimizationEffect(optimizationId: string): void {
    const recent = this.assessments.slice(-20);
    const beforeScore = recent.length > 0
      ? recent.slice(0, Math.floor(recent.length / 2)).reduce((s, a) => s + a.score, 0) / Math.max(1, Math.floor(recent.length / 2))
      : 0.5;
    const afterScore = recent.length > 0
      ? recent.slice(Math.floor(recent.length / 2)).reduce((s, a) => s + a.score, 0) / Math.max(1, recent.length - Math.floor(recent.length / 2))
      : 0.5;

    const improvement = afterScore - beforeScore;
    const improvementPercentage = beforeScore > 0 ? (improvement / beforeScore) * 100 : 0;

    this.optimizationVerifications.push({
      optimizationId,
      beforeScore,
      afterScore,
      improvement,
      improvementPercentage,
      verifiedAt: Date.now(),
    });

    if (this.optimizationVerifications.length > 50) {
      this.optimizationVerifications = this.optimizationVerifications.slice(-50);
    }

    Logger.info(
      `📊 优化效果验证: ${optimizationId} | ${beforeScore.toFixed(2)} → ${afterScore.toFixed(2)} (${improvement > 0 ? '+' : ''}${improvement.toFixed(2)})`,
      'RealTimeFeedbackLoop'
    );
  }
}

