}

export interface SkillRegistryDeps {
  registerInfrastructureTool(tool: {
    name: string;
    description: string;
    parameters: Array<{
      name: string;
      type: string;
      required: boolean;
      description: string;
    }>;
    execute: (args: Record<string, unknown>, context?: unknown) => Promise<{
      success: boolean;
      output: unknown;
      error?: string;
      metadata?: Record<string, unknown>;
