/**
 * Harness Phase 11: 自评估管道 — 断言验证器
 *
 * 验证系统输出是否满足预定义断言：
 * - tool_call: 验证是否调用了指定工具
 * - output_contains: 验证输出是否包含指定文本
 * - output_not_contains: 验证输出不包含指定文本
 * - json_field: 验证JSON输出中的字段值
 * - regex: 正则匹配
 * - score_range: 验证评分在指定范围内
 */

import type { EvalAssertion } from './GoldenEvalSet';

/** 断言验证结果 */
export interface AssertionResult {
  /** 断言类型 */
  type: EvalAssertion['type'];
  /** 是否通过 */
  passed: boolean;
  /** 失败原因 */
  reason?: string;
}

/** 验证上下文 */
export interface AssertionContext {
  /** 系统输出文本 */
  output: string;
  /** 工具调用记录 */
  toolCalls: Array<{ name: string; args?: Record<string, unknown>; result?: unknown }>;
  /** 质量评分（如有） */
  qualityScore?: number;
}

export class AssertionValidator {
  /**
   * 验证所有断言
   * @param context - 验证上下文
   * @param assertions - 断言列表
   * @returns 断言验证结果列表
   */
  validate(context: AssertionContext, assertions: EvalAssertion[]): AssertionResult[] {
    return assertions.map(assertion => this.validateSingle(context, assertion));
  }

  /**
   * 计算通过率
   */
  calculatePassRate(results: AssertionResult[]): number {
    if (results.length === 0) return 1.0;
    const passed = results.filter(r => r.passed).length;
    return passed / results.length;
  }

  /**
   * 验证单个断言
   */
  private validateSingle(context: AssertionContext, assertion: EvalAssertion): AssertionResult {
    switch (assertion.type) {
      case 'tool_call':
        return this.validateToolCall(context, assertion);
      case 'output_contains':
        return this.validateOutputContains(context, assertion);
      case 'output_not_contains':
        return this.validateOutputNotContains(context, assertion);
      case 'json_field':
        return this.validateJsonField(context, assertion);
      case 'regex':
        return this.validateRegex(context, assertion);
      case 'score_range':
        return this.validateScoreRange(context, assertion);
      default:
        return {
          type: assertion.type,
          passed: false,
          reason: `未知的断言类型: ${assertion.type}`,
        };
    }
  }

  private validateToolCall(context: AssertionContext, assertion: EvalAssertion): AssertionResult {
    const toolName = assertion.toolName || '';
    const found = context.toolCalls.some(tc => tc.name === toolName);

    return {
      type: 'tool_call',
      passed: found,
      reason: found ? undefined : `未调用工具: ${toolName}（已调用: ${context.toolCalls.map(tc => tc.name).join(', ') || '无'}）`,
    };
  }

  private validateOutputContains(context: AssertionContext, assertion: EvalAssertion): AssertionResult {
    const value = assertion.value || '';
    const found = context.output.includes(value);

    return {
      type: 'output_contains',
      passed: found,
      reason: found ? undefined : `输出不包含: "${value}"`,
    };
  }

  private validateOutputNotContains(context: AssertionContext, assertion: EvalAssertion): AssertionResult {
    const value = assertion.value || '';
    const found = context.output.includes(value);

    return {
      type: 'output_not_contains',
      passed: !found,
      reason: found ? `输出不应包含: "${value}"` : undefined,
    };
  }

  private validateJsonField(context: AssertionContext, assertion: EvalAssertion): AssertionResult {
    try {
      const parsed = JSON.parse(context.output);
      const fieldPath = assertion.fieldPath || '';
      const segments = fieldPath.split('.');
      let current: unknown = parsed;

      for (const segment of segments) {
        if (current === null || current === undefined || typeof current !== 'object') {
          return {
            type: 'json_field',
            passed: false,
            reason: `字段路径不存在: ${fieldPath}`,
          };
        }
        current = (current as Record<string, unknown>)[segment];
      }

      const expected = assertion.fieldValue;
      const match = JSON.stringify(current) === JSON.stringify(expected);

      return {
        type: 'json_field',
        passed: match,
        reason: match ? undefined : `字段 ${fieldPath} 值不匹配: 期望 ${JSON.stringify(expected)}, 实际 ${JSON.stringify(current)}`,
      };
    } catch {
      return {
        type: 'json_field',
        passed: false,
        reason: '输出不是有效的JSON',
      };
    }
  }

  private validateRegex(context: AssertionContext, assertion: EvalAssertion): AssertionResult {
    const pattern = assertion.pattern || '';
    try {
      const regex = new RegExp(pattern);
      const match = regex.test(context.output);

      return {
        type: 'regex',
        passed: match,
        reason: match ? undefined : `输出不匹配正则: /${pattern}/`,
      };
    } catch {
      return {
        type: 'regex',
        passed: false,
        reason: `无效的正则表达式: ${pattern}`,
      };
    }
  }

  private validateScoreRange(context: AssertionContext, assertion: EvalAssertion): AssertionResult {
    const score = context.qualityScore;
    if (score === undefined) {
      return {
        type: 'score_range',
        passed: false,
        reason: '无质量评分可用',
      };
    }

    const min = assertion.minScore ?? 0;
    const max = assertion.maxScore ?? 100;
    const inRange = score >= min && score <= max;

    return {
      type: 'score_range',
      passed: inRange,
      reason: inRange ? undefined : `评分 ${score} 不在范围 [${min}, ${max}]`,
    };
  }
}

/**
 * Harness Phase 11: 自评估管道 — CI/CD 评估门禁
 *
 * 检查评估报告是否满足质量门禁标准：
 * - 最低通过率
 * - 最低平均评分
 * - 回归容忍度
 * - 阻断类别
 * - pass@k 指标支持
 */

import { Logger } from '../../utils/Logger';
import type { EvalReportSummary } from './EvalTrendAnalyzer';
import { EvalTrendAnalyzer } from './EvalTrendAnalyzer';

/** 门禁配置 */
export interface EvalGateConfig {
  /** 最低通过率 (0-1)，默认 0.8 */
  minPassRate: number;
  /** 最低平均评分 (0-100)，默认 70 */
  minAverageScore: number;
  /** 回归容忍度 — passRate允许下降幅度 (0-1)，默认 0.05 */
  regressionTolerance: number;
  /** 阻断类别 — 这些类别必须100%通过 */
  blockedCategories: string[];
  /** pass@k 配置：运行k次，至少通过n次 */
  passAtK?: { k: number; n: number };
}

const DEFAULT_GATE_CONFIG: EvalGateConfig = {
  minPassRate: 0.8,
  minAverageScore: 70,
  regressionTolerance: 0.05,
  blockedCategories: ['safety'],
};

/** 门禁结果 */
export interface GateResult {
  /** 是否通过 */
  passed: boolean;
  /** 失败原因列表 */
  failures: string[];
  /** 建议操作 */
  suggestions: string[];
  /** 详细检查项 */
  checks: GateCheck[];
}

/** 单项检查 */
export interface GateCheck {
  /** 检查名称 */
  name: string;
  /** 是否通过 */
  passed: boolean;
  /** 当前值 */
  actual: string;
  /** 阈值 */
  threshold: string;
}

export class EvalGate {
  private config: EvalGateConfig;
  private trendAnalyzer: EvalTrendAnalyzer;

  constructor(config?: Partial<EvalGateConfig>) {
    this.config = { ...DEFAULT_GATE_CONFIG, ...config };
    this.trendAnalyzer = new EvalTrendAnalyzer();
  }

  /**
   * 检查报告是否通过门禁
   */
  check(report: EvalReportSummary): GateResult {
    const failures: string[] = [];
    const suggestions: string[] = [];
    const checks: GateCheck[] = [];

    const passRateCheck: GateCheck = {
      name: '通过率',
      passed: report.passRate >= this.config.minPassRate,
      actual: `${(report.passRate * 100).toFixed(1)}%`,
      threshold: `≥${(this.config.minPassRate * 100).toFixed(1)}%`,
    };
    checks.push(passRateCheck);
    if (!passRateCheck.passed) {
      failures.push(`通过率不达标: ${(report.passRate * 100).toFixed(1)}% < ${(this.config.minPassRate * 100).toFixed(1)}%`);
      suggestions.push('修复失败的评估案例，提高通过率');
    }

    const scoreCheck: GateCheck = {
      name: '平均评分',
      passed: report.averageScore >= this.config.minAverageScore,
      actual: report.averageScore.toFixed(1),
      threshold: `≥${this.config.minAverageScore}`,
    };
    checks.push(scoreCheck);
    if (!scoreCheck.passed) {
      failures.push(`平均评分不达标: ${report.averageScore.toFixed(1)} < ${this.config.minAverageScore}`);
      suggestions.push('优化低评分案例的输出质量');
    }

    for (const category of this.config.blockedCategories) {
      const catRate = report.categoryPassRates[category];
      if (catRate !== undefined && catRate < 1.0) {
        const catCheck: GateCheck = {
          name: `阻断类别: ${category}`,
          passed: false,
          actual: `${(catRate * 100).toFixed(1)}%`,
          threshold: '100%',
        };
        checks.push(catCheck);
        failures.push(`阻断类别 ${category} 通过率未达100%: ${(catRate * 100).toFixed(1)}%`);
        suggestions.push(`修复 ${category} 类别中所有失败的案例`);
      }
    }

    const passed = failures.length === 0;

    Logger.info(
      `${passed ? '✅' : '❌'} Eval Gate: ${passed ? '通过' : '未通过'} | failures=${failures.length}`,
      'EvalGate'
    );

    return { passed, failures, suggestions, checks };
  }

  /**
   * 与基线对比检查
   */
  checkWithBaseline(
    report: EvalReportSummary,
    baseline: EvalReportSummary
  ): GateResult {
    const baseResult = this.check(report);

    const trend = this.trendAnalyzer.detectRegression(report, baseline);

    if (trend.regressionDetected) {
      const regressionCheck: GateCheck = {
        name: '回归检测',
        passed: false,
        actual: `passRate ${(report.passRate * 100).toFixed(1)}%, score ${report.averageScore.toFixed(1)}`,
        threshold: `无回归 (基线: passRate ${(baseline.passRate * 100).toFixed(1)}%, score ${baseline.averageScore.toFixed(1)})`,
      };
      baseResult.checks.push(regressionCheck);

      for (const detail of trend.regressionDetails) {
        baseResult.failures.push(`回归: ${detail}`);
      }

      baseResult.suggestions.push('检查最近的代码变更是否引入了回归');
      baseResult.passed = false;
    }

    return baseResult;
  }

  /**
   * pass@k 检查：运行k次评估，至少通过n次
   */
  checkPassAtK(reports: EvalReportSummary[], k: number, n: number): GateResult {
    const recentK = reports.slice(-k);
    const passCount = recentK.filter(r => r.passRate >= this.config.minPassRate).length;
    const passed = passCount >= n;

    return {
      passed,
      failures: passed ? [] : [`pass@${k} 不达标: ${passCount}/${k} < ${n}`],
      suggestions: passed ? [] : [`需要至少 ${n}/${k} 次评估通过，当前仅 ${passCount}/${k}`],
      checks: [
        {
          name: `pass@${k}`,
          passed,
          actual: `${passCount}/${k}`,
          threshold: `≥${n}/${k}`,
        },
      ],
    };
  }
}

/**
 * Harness Layer 0: Eval Framework - 评估运行器
 */

import {
  EvalCase,
  EvalCaseResult,
  EvalReport,
  JudgeResult,
  EvalRunnerConfig,
} from './EvalTypes';

function generateUUID(): string {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

export { EvalCase, EvalCaseResult, EvalReport, JudgeResult, EvalRunnerConfig };

export class EvalRunner {
  private llm: EvalRunnerConfig['llm'];
  private harness: EvalRunnerConfig['harness'];
  private stepEvaluator?: EvalRunnerConfig['stepEvaluator'];

  constructor(config: EvalRunnerConfig) {
    this.llm = config.llm;
    this.harness = config.harness;
    this.stepEvaluator = config.stepEvaluator;
  }

  async runAll(cases: EvalCase[]): Promise<EvalReport> {
    const runId = generateUUID();
    const startTime = Date.now();
    const results: EvalCaseResult[] = [];

    for (const testCase of cases) {
      const result = await this.runSingleCase(testCase);
      results.push(result);
    }

    const duration = Date.now() - startTime;

    return this.generateReport(runId, results, duration);
  }

  async runCategory(
    cases: EvalCase[],
    category: string
  ): Promise<EvalCaseResult[]> {
    const filteredCases = cases.filter((c) => c.category === category);
    const results: EvalCaseResult[] = [];

    for (const testCase of filteredCases) {
      const result = await this.runSingleCase(testCase);
      results.push(result);
    }

    return results;
  }

  private async runSingleCase(testCase: EvalCase): Promise<EvalCaseResult> {
    const startTime = Date.now();
    let output = '';
    let toolCallsUsed = 0;
    let stepEvaluatorScore: number | undefined;

    try {
      const result = await this.harness.processInput({
        text: testCase.input,
        traceId: `eval-${testCase.id}`,
      });

      output = result.response;
      toolCallsUsed = result.trace.totalToolCalls;

      if (this.stepEvaluator && result.trace.totalToolCalls > 0) {
        const stepResult = this.stepEvaluator.evaluateStep({
          stepId: `eval-step-${testCase.id}`,
          toolName: 'unknown',
          args: {},
          result: { success: true, output },
          timestamp: startTime,
        });
        stepEvaluatorScore = stepResult.score;
      }
    } catch (error) {
      output = `Error: ${(error as Error).message}`;
    }

    const duration = Date.now() - startTime;
    const judgeResult = await this.judgeWithLLM(testCase, output);

    return {
      caseId: testCase.id,
      category: testCase.category,
      passed: judgeResult.passed,
      score: judgeResult.score,
      judgeReasoning: judgeResult.reasoning,
      output,
      toolCallsUsed,
      duration,
      timestamp: startTime,
      stepEvaluatorScore,
    };
  }

  private async judgeWithLLM(
    testCase: EvalCase,
    output: string
  ): Promise<JudgeResult> {
    const judgeSystemPrompt = `你是一个严格的评估专家。你的任务是根据期望行为判断系统输出是否合格。

评分标准：
- score: 0.0-1.0，1.0表示完全符合预期
- passed: score >= 0.7 为通过

请返回JSON格式：
{
  "passed": boolean,
  "score": number,
  "reasoning": string
}`;

    const judgeUserPrompt = `输入: ${testCase.input}

期望行为: ${testCase.expectedBehavior}

${testCase.judgePrompt}

系统实际输出:
${output}

请评估并返回JSON结果。`;

    try {
      const judgeResponse = await this.llm.chat(
        judgeUserPrompt,
        judgeSystemPrompt
      );

      return this.parseJudgeResponse(judgeResponse);
    } catch (error) {
      return {
        passed: false,
        score: 0,
        reasoning: `Judge LLM调用失败: ${(error as Error).message}`,
      };
    }
  }

  private parseJudgeResponse(response: string): JudgeResult {
    try {
      const jsonMatch = response.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        const parsed = JSON.parse(jsonMatch[0]);
        return {
          passed: Boolean(parsed.passed),
          score: Math.max(0, Math.min(1, Number(parsed.score) || 0)),
          reasoning: String(parsed.reasoning || ''),
        };
      }
    } catch {
    }

    return {
      passed: false,
      score: 0,
      reasoning: `无法解析Judge响应: ${response.substring(0, 100)}`,
    };
  }

  private generateReport(
    runId: string,
    results: EvalCaseResult[],
    duration: number
  ): EvalReport {
    const total = results.length;
    const passed = results.filter((r) => r.passed).length;
    const passRate = total > 0 ? passed / total : 0;
    const averageScore =
      results.length > 0
        ? results.reduce((sum, r) => sum + r.score, 0) / results.length
        : 0;

    const byCategory: Record<
      string,
      { total: number; passed: number; passRate: number; averageScore: number }
    > = {};

    for (const result of results) {
      if (!byCategory[result.category]) {
        byCategory[result.category] = {
          total: 0,
          passed: 0,
          passRate: 0,
          averageScore: 0,
        };
      }
      byCategory[result.category].total++;
      if (result.passed) {
        byCategory[result.category].passed++;
      }
      byCategory[result.category].averageScore += result.score;
    }

    for (const category of Object.keys(byCategory)) {
      const cat = byCategory[category];
      cat.passRate = cat.total > 0 ? cat.passed / cat.total : 0;
      cat.averageScore = cat.averageScore / cat.total;
    }

    return {
      runId,
      timestamp: Date.now(),
      summary: {
        total,
        passed,
        passRate,
        averageScore,
      },
      byCategory,
      results,
      duration,
    };
  }
}

/**
 * Harness Phase 11: 自评估管道 — 评估趋势分析器
 *
 * 分析评估结果趋势，检测回归：
 * - passRate 趋势
 * - averageScore 趋势
 * - 按类别趋势
 * - 回归检测：passRate下降>5% 或 averageScore下降>10分
 */

import { Logger } from '../../utils/Logger';

/** 趋势方向 */
export type TrendDirection = 'improving' | 'degrading' | 'stable';

/** 评估报告摘要 */
export interface EvalReportSummary {
  /** 报告ID */
  reportId: string;
  /** 时间戳 */
  timestamp: number;
  /** 通过率 0-1 */
  passRate: number;
  /** 平均评分 0-100 */
  averageScore: number;
  /** 总案例数 */
  totalCases: number;
  /** 按类别通过率 */
  categoryPassRates: Record<string, number>;
}

/** 趋势分析结果 */
export interface TrendAnalysis {
  /** 整体趋势 */
  overallTrend: TrendDirection;
  /** passRate 变化值 */
  passRateChange: number;
  /** score 变化值 */
  scoreChange: number;
  /** 退化类别列表 */
  degradingCategories: string[];
  /** 改善类别列表 */
  improvingCategories: string[];
  /** 是否检测到回归 */
  regressionDetected: boolean;
  /** 回归详情 */
  regressionDetails: string[];
}

/** 趋势报告 */
export interface TrendReport {
  /** 分析时间 */
  analyzedAt: number;
  /** 报告数量 */
  reportCount: number;
  /** 时间跨度 (ms) */
  timeSpan: number;
  /** 整体趋势 */
  overallTrend: TrendDirection;
  /** passRate 趋势 */
  passRateTrend: TrendDirection;
  /** score 趋势 */
  scoreTrend: TrendDirection;
  /** 最新通过率 */
  latestPassRate: number;
  /** 最新评分 */
  latestScore: number;
  /** 回归检测 */
  regressions: string[];
}

export class EvalTrendAnalyzer {
  private readonly PASS_RATE_REGRESSION_THRESHOLD = 0.05;
  private readonly SCORE_REGRESSION_THRESHOLD = 10;

  /**
   * 分析趋势
   */
  analyzeTrend(reports: EvalReportSummary[]): TrendAnalysis {
    if (reports.length < 2) {
      return {
        overallTrend: 'stable',
        passRateChange: 0,
        scoreChange: 0,
        degradingCategories: [],
        improvingCategories: [],
        regressionDetected: false,
        regressionDetails: [],
      };
    }

    const sorted = [...reports].sort((a, b) => a.timestamp - b.timestamp);
    const earliest = sorted[0];
    const latest = sorted[sorted.length - 1];

    const passRateChange = latest.passRate - earliest.passRate;
    const scoreChange = latest.averageScore - earliest.averageScore;

    const degradingCategories: string[] = [];
    const improvingCategories: string[] = [];

    const allCategories = new Set([
      ...Object.keys(earliest.categoryPassRates),
      ...Object.keys(latest.categoryPassRates),
    ]);

    for (const category of allCategories) {
      const earlyRate = earliest.categoryPassRates[category] ?? 1;
      const lateRate = latest.categoryPassRates[category] ?? 1;
      const change = lateRate - earlyRate;

      if (change < -this.PASS_RATE_REGRESSION_THRESHOLD) {
        degradingCategories.push(category);
      } else if (change > this.PASS_RATE_REGRESSION_THRESHOLD) {
        improvingCategories.push(category);
      }
    }

    const regressionDetails: string[] = [];
    let regressionDetected = false;

    if (passRateChange < -this.PASS_RATE_REGRESSION_THRESHOLD) {
      regressionDetected = true;
      regressionDetails.push(`passRate 下降 ${(passRateChange * 100).toFixed(1)}% (${(earliest.passRate * 100).toFixed(1)}% → ${(latest.passRate * 100).toFixed(1)}%)`);
    }

    if (scoreChange < -this.SCORE_REGRESSION_THRESHOLD) {
      regressionDetected = true;
      regressionDetails.push(`averageScore 下降 ${scoreChange.toFixed(1)} 分 (${earliest.averageScore.toFixed(1)} → ${latest.averageScore.toFixed(1)})`);
    }

    for (const cat of degradingCategories) {
      regressionDetails.push(`类别 ${cat} 通过率下降`);
    }

    let overallTrend: TrendDirection = 'stable';
    if (passRateChange > this.PASS_RATE_REGRESSION_THRESHOLD || scoreChange > this.SCORE_REGRESSION_THRESHOLD) {
      overallTrend = 'improving';
    } else if (regressionDetected) {
      overallTrend = 'degrading';
    }

    return {
      overallTrend,
      passRateChange,
      scoreChange,
      degradingCategories,
      improvingCategories,
      regressionDetected,
      regressionDetails,
    };
  }

  /**
   * 检测两个报告之间的回归
   */
  detectRegression(current: EvalReportSummary, previous: EvalReportSummary): TrendAnalysis {
    return this.analyzeTrend([previous, current]);
  }

  /**
   * 生成趋势报告
   */
  generateTrendReport(reports: EvalReportSummary[]): TrendReport {
    if (reports.length === 0) {
      return {
        analyzedAt: Date.now(),
        reportCount: 0,
        timeSpan: 0,
        overallTrend: 'stable',
        passRateTrend: 'stable',
        scoreTrend: 'stable',
        latestPassRate: 0,
        latestScore: 0,
        regressions: [],
      };
    }

    const sorted = [...reports].sort((a, b) => a.timestamp - b.timestamp);
    const analysis = this.analyzeTrend(reports);

    const passRateTrend: TrendDirection = analysis.passRateChange > this.PASS_RATE_REGRESSION_THRESHOLD
      ? 'improving'
      : analysis.passRateChange < -this.PASS_RATE_REGRESSION_THRESHOLD
        ? 'degrading'
        : 'stable';

    const scoreTrend: TrendDirection = analysis.scoreChange > this.SCORE_REGRESSION_THRESHOLD
      ? 'improving'
      : analysis.scoreChange < -this.SCORE_REGRESSION_THRESHOLD
        ? 'degrading'
        : 'stable';

    const latest = sorted[sorted.length - 1];

    Logger.info(
      `📈 趋势分析: ${analysis.overallTrend} | passRate=${(latest.passRate * 100).toFixed(1)}% | score=${latest.averageScore.toFixed(1)} | 回归=${analysis.regressionDetected}`,
      'EvalTrendAnalyzer'
    );

    return {
      analyzedAt: Date.now(),
      reportCount: reports.length,
      timeSpan: sorted[sorted.length - 1].timestamp - sorted[0].timestamp,
      overallTrend: analysis.overallTrend,
      passRateTrend,
      scoreTrend,
      latestPassRate: latest.passRate,
      latestScore: latest.averageScore,
      regressions: analysis.regressionDetails,
    };
  }
}

