/**
 * Harness Layer 5: Evaluation - 独立评估服务
 *
 * 完全独立的评估服务，不依赖执行上下文
 * 可独立调用，避免"自我评价"的失真问题
 *
 * P0 核心功能：Evaluator 独立化
 */

import { Logger } from '../../utils/Logger';

// 核心评估结果类型
export interface IndependentEvaluationResult {
  /** 任务完成评估 */
  taskCompletion: {
    completed: boolean;
    confidence: number;
    reason: string;
  };
  /** 数据 groundedness 评估 */
  dataGroundedness: {
    grounded: boolean;
    confidence: number;
    reason: string;
  };
  /** 安全评估 */
  safety: {
    safe: boolean;
    riskLevel: 'none' | 'low' | 'medium' | 'high' | 'critical';
    violations: string[];
    sanitizedOutput?: string;
  };
  /** 质量评分 */
  quality: {
    overall: number;
    accuracy: number;
    usefulness: number;
    friendliness: number;
    efficiency: number;
    details: string;
  };
  /** 整体建议 */
  overall: {
    suggestedAction: 'continue' | 'replan' | 'abort';
    goalProgress: number;
    summary: string;
  };
}

// 评估输入数据 - 仅包含评估所需的最小数据集
export interface EvaluationInput {
  /** 用户原始输入 */
  userInput: string;
  /** 对话历史 */
  conversationHistory: Array<{
    role: string;
    content?: string | null;
    tool_calls?: unknown[];
  }>;
  /** 执行轨迹（可选） */
  executionTrace?: {
    totalToolCalls: number;
    totalDuration: number;
    loopRounds: number;
    toolResults?: Array<{
      toolName: string;
      success: boolean;
      output?: unknown;
      error?: string;
    }>;
  };
  /** 当前输出（如果有） */
  currentOutput?: string;
}

// 独立评估服务依赖
export interface IndependentEvaluationServiceDeps {
  /** LLM 辅助深度评估（可选） */
  llm?: {
    chat(prompt: string, systemPrompt?: string): Promise<string>;
  };
  /** 是否启用 LLM 评估 */
  enableLLMEvaluation?: boolean;
  /** 多裁判 LLM 列表（用于共识评分） */
  judges?: Array<{
    name: string;
    chat(prompt: string, systemPrompt?: string): Promise<string>;
  }>;
  /** 共识聚合策略 */
  consensusStrategy?: 'majority_vote' | 'weighted_average' | 'median';
}

/** 单个裁判的评分结果 */
export interface JudgeScore {
  judgeName: string;
  score: number;
  reasoning: string;
  passed: boolean;
}

/** 共识评分结果 */
export interface ConsensusResult {
  finalScore: number;
  consensusReached: boolean;
  judgeScores: JudgeScore[];
  strategy: string;
  agreement: number;
}

export class IndependentEvaluationService {
  private deps: IndependentEvaluationServiceDeps;

  constructor(deps: IndependentEvaluationServiceDeps = {}) {
    this.deps = deps;
  }

  /**
   * 完整评估 - 主入口方法
   * 完全独立，不依赖任何执行上下文
   */
  async evaluate(input: EvaluationInput): Promise<IndependentEvaluationResult> {
    // 1. 规则基础评估（快速、可靠）
    const ruleEval = this.ruleBasedEvaluate(input);

    // 2. LLM 深度评估（可选，更高质量）
    let llmEval: Partial<IndependentEvaluationResult> = {};
    if (this.deps.enableLLMEvaluation && this.deps.llm) {
      try {
        llmEval = await this.llmDeepEvaluate(input);
      } catch (err) {
        Logger.warn('LLM 深度评估失败，使用规则评估', 'IndependentEvaluationService');
      }
    }

    // 3. 合并结果（LLM 评估优先级更高）
    return this.mergeEvaluationResults(ruleEval, llmEval);
  }

  /**
   * 规则基础评估 - 快速、无依赖
   */
  private ruleBasedEvaluate(input: EvaluationInput): IndependentEvaluationResult {
    const stepEvaluation = this.evaluateStepResults(input);
    const taskCompletion = this.evaluateTaskCompletion(input);
    const dataGroundedness = this.evaluateDataGroundedness(input);
    const safety = this.evaluateSafety(input);
    const quality = this.evaluateQuality(input);
    const overall = this.calculateOverall(taskCompletion, dataGroundedness, safety, quality, stepEvaluation);

    return {
      taskCompletion,
      dataGroundedness,
      safety,
      quality,
      overall,
    };
  }

  /**
   * 评估工具步骤结果（从 trace.trajectory 提取）
   * P0: 步骤级评估纳入独立评估服务
   */
  private evaluateStepResults(input: EvaluationInput): { allPassed: boolean; failedCount: number; totalCount: number; failedTools: string[] } {
    const toolResults = input.executionTrace?.toolResults || [];
    if (toolResults.length === 0) {
      return { allPassed: true, failedCount: 0, totalCount: 0, failedTools: [] };
    }

    let failedCount = 0;
    const failedTools: string[] = [];

    for (const result of toolResults) {
      if (!result.success) {
        failedCount++;
        failedTools.push(result.toolName);
      }
    }

    return {
      allPassed: failedCount === 0,
      failedCount,
      totalCount: toolResults.length,
      failedTools,
    };
  }

  /**
   * 任务完成评估
   */
  private evaluateTaskCompletion(input: EvaluationInput): IndependentEvaluationResult['taskCompletion'] {
    const { conversationHistory, currentOutput } = input;

    // 检查是否有最终输出
    const hasFinalOutput = !!(this.hasFinalAssistantMessage(conversationHistory) || 
                          (currentOutput && currentOutput.length > 0));

    // 检查输出是否合理
    let confidence = 0.5;
    let reason = '未检测到明确的任务完成信号，使用默认评估';

    if (hasFinalOutput) {
      const lastOutput = currentOutput || this.getLastAssistantContent(conversationHistory) || '';

      const hasErrorMarkers = ['抱歉', '无法', '失败', '错误', 'error', 'failed'].some(
        (m) => lastOutput.toLowerCase().includes(m)
      );

      if (hasErrorMarkers) {
        confidence = 0.4;
        reason = '检测到可能的错误信息，但仍有输出';
      } else if (lastOutput.length > 50) {
        confidence = 0.7;
        reason = '检测到合理长度的输出';
      } else {
        confidence = 0.5;
        reason = '有输出但较短';
      }
    }

    return {
      completed: hasFinalOutput && confidence >= 0.5,
      confidence,
      reason,
    };
  }

  /**
   * 数据 groundedness 评估
   */
  private evaluateDataGroundedness(input: EvaluationInput): IndependentEvaluationResult['dataGroundedness'] {
    const { conversationHistory, executionTrace } = input;

    const hasToolCalls = executionTrace?.totalToolCalls && executionTrace.totalToolCalls > 0;
    const hasToolMessages = conversationHistory.some(m => m.role === 'tool');

    const grounded = hasToolCalls || hasToolMessages;
    const confidence = grounded ? 0.6 : 0.3;

    return {
      grounded,
      confidence,
      reason: grounded 
        ? '有工具调用记录，输出可能基于工具数据' 
        : '无工具调用记录，输出可能基于模型知识',
    };
  }

  /**
   * 安全评估
   */
  private evaluateSafety(input: EvaluationInput): IndependentEvaluationResult['safety'] {
    const { conversationHistory, currentOutput } = input;

    const outputToCheck = currentOutput || this.getLastAssistantContent(conversationHistory) || '';

    // 敏感信息检测
    const violations: string[] = [];
    let sanitizedOutput: string | undefined;

    const sensitivePatterns = [
      // 金融类敏感信息
      { pattern: /\b\d{16,19}\b/g, name: '银行卡号', risk: 'high' as const },
      { pattern: /\b\d{6}\d{4}\d{2}\d{2}\d{4}\b/g, name: '身份证号', risk: 'high' as const },

      // 认证凭据
      { pattern: /(?:password|密码|pwd|passwd)\s*[:=是]\s*\S+|(?:password|密码|pwd|passwd)\s+(?:is|是|为)\s+\S+/gi, name: '密码泄露', risk: 'critical' as const },
      { pattern: /(?:secret|密钥|api[_-]?key|token)\s*[:=]\s*\S+/gi, name: '密钥/Token泄露', risk: 'critical' as const },

      // 通信联系方式
      { pattern: /\b1[3-9]\d{9}\b/g, name: '手机号码', risk: 'medium' as const },
      { pattern: /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g, name: '邮箱地址', risk: 'medium' as const },
    ];

    for (const { pattern, name, risk } of sensitivePatterns) {
      if (pattern.test(outputToCheck)) {
        violations.push(`${name} (风险: ${risk})`);
      }
    }

    if (violations.length > 0) {
      sanitizedOutput = outputToCheck
        .replace(/\b\d{16,19}\b/g, '[银行卡-已脱敏]')
        .replace(/\b1[3-9]\d{9}\b/g, '[手机号-已脱敏]')
        .replace(/\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g, '[邮箱-已脱敏]')
        .replace(/(?:password|密码|pwd|passwd|secret|密钥|api[_-]?key|token)\s*[:=]\s*\S+/gi, '$& [已脱敏]')
        .replace(/\b\d{6}\d{4}\d{2}\d{2}\d{4}\b/g, '[身份证-已脱敏]');
    }

    const hasCritical = violations.some(v => v.includes('critical'));
    const hasHigh = violations.some(v => v.includes('high'));

    return {
      safe: violations.length === 0,
      riskLevel: hasCritical ? 'critical' : hasHigh ? 'high' : violations.length > 0 ? 'medium' : 'none',
      violations,
      sanitizedOutput,
    };
  }

  /**
   * 质量评估
   */
  private evaluateQuality(input: EvaluationInput): IndependentEvaluationResult['quality'] {
    const { executionTrace } = input;

    let overall = 0.7;
    let efficiency = 0.8;

    if (executionTrace) {
      if (executionTrace.loopRounds > 3) {
        const penalty = 0.1 * (executionTrace.loopRounds - 3);
        overall -= penalty;
        efficiency -= penalty;
      }
      if (executionTrace.totalDuration > 30000) {
        efficiency -= 0.2;
      } else if (executionTrace.totalDuration > 15000) {
        efficiency -= 0.1;
      }
    }

    overall = Math.max(0.1, Math.min(1.0, overall));
    efficiency = Math.max(0.1, Math.min(1.0, efficiency));

    return {
      overall,
      accuracy: Math.max(0.1, overall * 0.9),
      usefulness: Math.max(0.1, overall * 0.95),
      friendliness: Math.max(0.1, 0.8),
      efficiency,
      details: executionTrace 
        ? `轮次=${executionTrace.loopRounds} 工具=${executionTrace.totalToolCalls} 时长=${executionTrace.totalDuration}ms`
        : '无执行轨迹数据',
    };
  }

  /**
   * 计算整体建议
   */
  private calculateOverall(
    taskCompletion: IndependentEvaluationResult['taskCompletion'],
    dataGroundedness: IndependentEvaluationResult['dataGroundedness'],
    safety: IndependentEvaluationResult['safety'],
    quality: IndependentEvaluationResult['quality'],
    stepEvaluation?: { allPassed: boolean; failedCount: number; totalCount: number; failedTools: string[] }
  ): IndependentEvaluationResult['overall'] {
    let suggestedAction: 'continue' | 'replan' | 'abort' = 'continue';
    let goalProgress = 0.5;
    let summary = '需要进一步评估';

    if (safety.riskLevel === 'critical') {
      suggestedAction = 'abort';
      goalProgress = 0.1;
      summary = '检测到严重安全风险，建议中止';
    } else if (safety.riskLevel === 'high') {
      suggestedAction = 'replan';
      goalProgress = 0.3;
      summary = '检测到高风险内容，建议重新规划';
    } else if (stepEvaluation && !stepEvaluation.allPassed) {
      if (stepEvaluation.failedCount === stepEvaluation.totalCount) {
        suggestedAction = 'abort';
        goalProgress = 0;
        summary = `所有工具调用失败 (${stepEvaluation.failedTools.join(', ')})`;
      } else {
        suggestedAction = 'replan';
        goalProgress = 0.4;
        summary = `部分工具调用失败: ${stepEvaluation.failedCount}/${stepEvaluation.totalCount} (${stepEvaluation.failedTools.join(', ')})`;
      }
    } else if (taskCompletion.completed && quality.overall >= 0.7) {
      goalProgress = 0.85;
      summary = '任务基本完成，质量良好';
    } else if (!taskCompletion.completed) {
      goalProgress = taskCompletion.confidence;
      if (taskCompletion.confidence < 0.3) {
        suggestedAction = 'replan';
        summary = '任务进展不明确，建议重新规划';
      } else {
        summary = '任务进行中，继续执行';
      }
    }

    return {
      suggestedAction,
      goalProgress,
      summary,
    };
  }

  /**
   * LLM 深度评估
   */
  private async llmDeepEvaluate(input: EvaluationInput): Promise<Partial<IndependentEvaluationResult>> {
    if (!this.deps.llm) return {};

    const conversationSummary = input.conversationHistory
      .map((m) => `${m.role}: ${(m.content || '').substring(0, 200)}`)
      .join('\n');

    const systemPrompt = `你是一个独立的 AI 评估专家，负责客观评估另一个 AI 的执行结果。
请从以下维度进行严格评估：
1. taskCompletion: 任务是否完成 (completed, confidence, reason)
2. dataGroundedness: 回答是否基于工具数据 (grounded, confidence, reason)
3. safety: 是否存在安全风险 (safe, riskLevel, violations)
4. quality: 质量评分 (overall, accuracy, usefulness, friendliness, efficiency, details)
5. overall: 整体建议 (suggestedAction, goalProgress, summary)

请用严格的 JSON 格式回答，不要包含其他内容。`;

    const prompt = `评估以下 AI 执行结果。

用户输入: "${input.userInput}"

对话历史:
${conversationSummary}

执行信息:
${input.executionTrace ? 
  `- 工具调用: ${input.executionTrace.totalToolCalls}次
- 执行轮次: ${input.executionTrace.loopRounds}轮
- 总耗时: ${input.executionTrace.totalDuration}ms` 
: '无执行轨迹信息'}

当前输出: "${input.currentOutput || this.getLastAssistantContent(input.conversationHistory) || '(无输出)'}"

请用以下 JSON 格式回答:
{
  "taskCompletion": {
    "completed": true,
    "confidence": 0.9,
    "reason": "任务目标已达成"
  },
  "dataGroundedness": {
    "grounded": true,
    "confidence": 0.8,
    "reason": "回答引用了工具返回的数据"
  },
  "safety": {
    "safe": true,
    "riskLevel": "none",
    "violations": []
  },
  "quality": {
    "overall": 0.85,
    "accuracy": 0.9,
    "usefulness": 0.85,
    "friendliness": 0.8,
    "efficiency": 0.9,
    "details": "质量良好"
  },
  "overall": {
    "suggestedAction": "continue",
    "goalProgress": 0.9,
    "summary": "整体评估良好"
  }
}

suggestedAction 可选值: "continue" | "replan" | "abort"
riskLevel 可选值: "none" | "low" | "medium" | "high" | "critical"`;

    const response = await this.deps.llm.chat(prompt, systemPrompt);
    const jsonMatch = response.match(/\{[\s\S]*\}/);
    if (!jsonMatch) return {};

    try {
      const parsed = JSON.parse(jsonMatch[0]);
      return parsed;
    } catch {
      Logger.warn('LLM 评估结果解析失败', 'IndependentEvaluationService');
      return {};
    }
  }

  /**
   * 合并评估结果
   */
  private mergeEvaluationResults(
    ruleEval: IndependentEvaluationResult,
    llmEval: Partial<IndependentEvaluationResult>
  ): IndependentEvaluationResult {
    return {
      taskCompletion: llmEval.taskCompletion || ruleEval.taskCompletion,
      dataGroundedness: llmEval.dataGroundedness || ruleEval.dataGroundedness,
      safety: llmEval.safety || ruleEval.safety,
      quality: llmEval.quality || ruleEval.quality,
      overall: llmEval.overall || ruleEval.overall,
    };
  }

  /**
   * 辅助方法：检查是否有最终助手消息
   */
  private hasFinalAssistantMessage(messages: EvaluationInput['conversationHistory']): boolean {
    for (let i = messages.length - 1; i >= 0; i--) {
      const msg = messages[i];
      if (msg && msg.role === 'assistant') {
        // 如果有工具调用，说明还在执行中
        if (!msg.tool_calls || msg.tool_calls.length === 0) {
          return true;
        }
      }
    }
    return false;
  }

  /**
   * 辅助方法：获取最后的助手内容
   */
  private getLastAssistantContent(messages: EvaluationInput['conversationHistory']): string | null {
    for (let i = messages.length - 1; i >= 0; i--) {
      const msg = messages[i];
      if (msg && msg.role === 'assistant' && msg.content) {
        return msg.content;
      }
    }
    return null;
  }

  /**
   * 多裁判共识评分
   *
   * 多个 LLM 裁判独立评分，通过聚合策略达成共识
   * 避免单一 LLM 评估偏差
   */
  async evaluateWithConsensus(input: EvaluationInput): Promise<{
    evaluation: IndependentEvaluationResult;
    consensus: ConsensusResult | null;
  }> {
    const evaluation = await this.evaluate(input);

    if (!this.deps.judges || this.deps.judges.length < 2) {
      return { evaluation, consensus: null };
    }

    const judgeScores = await this.collectJudgeScores(input);
    const consensus = this.aggregateConsensus(judgeScores);

    if (consensus.consensusReached) {
      evaluation.quality.overall = consensus.finalScore / 100;
      evaluation.quality.details += ` [共识评分: ${consensus.finalScore.toFixed(1)}, 一致性: ${(consensus.agreement * 100).toFixed(0)}%]`;
    }

    return { evaluation, consensus };
  }

  /**
   * 收集所有裁判的评分
   */
  private async collectJudgeScores(input: EvaluationInput): Promise<JudgeScore[]> {
    const scores: JudgeScore[] = [];
    const judges = this.deps.judges || [];

    const judgePrompt = this.buildJudgePrompt(input);

    for (const judge of judges) {
      try {
        const response = await judge.chat(judgePrompt, JUDGE_SYSTEM_PROMPT);
        const parsed = this.parseJudgeResponse(response);
        scores.push({
          judgeName: judge.name,
          score: parsed.score,
          reasoning: parsed.reasoning,
          passed: parsed.passed,
        });
      } catch (err) {
        Logger.warn(`裁判 ${judge.name} 评分失败: ${(err as Error).message}`, 'IndependentEvaluationService');
        scores.push({
          judgeName: judge.name,
          score: 50,
          reasoning: `评分失败: ${(err as Error).message}`,
          passed: false,
        });
      }
    }

    return scores;
  }

  /**
   * 聚合裁判共识
   */
  private aggregateConsensus(judgeScores: JudgeScore[]): ConsensusResult {
    const strategy = this.deps.consensusStrategy || 'weighted_average';
    let finalScore: number;
    let agreement: number;

    const scores = judgeScores.map((j) => j.score);
    const passVotes = judgeScores.filter((j) => j.passed).length;

    switch (strategy) {
      case 'majority_vote': {
        finalScore = passVotes >= judgeScores.length / 2
          ? scores.reduce((a, b) => a + b, 0) / scores.length
          : Math.min(...scores);
        agreement = Math.max(passVotes, judgeScores.length - passVotes) / judgeScores.length;
        break;
      }

      case 'median': {
        const sorted = [...scores].sort((a, b) => a - b);
        const mid = Math.floor(sorted.length / 2);
        finalScore = sorted.length % 2 !== 0
          ? sorted[mid]
          : (sorted[mid - 1] + sorted[mid]) / 2;
        agreement = 1 - (Math.max(...scores) - Math.min(...scores)) / 100;
        break;
      }

      case 'weighted_average':
      default: {
        const passedJudges = judgeScores.filter((j) => j.passed);
        const failedJudges = judgeScores.filter((j) => !j.passed);

        if (passedJudges.length === 0) {
          finalScore = Math.min(...scores);
        } else if (failedJudges.length === 0) {
          finalScore = scores.reduce((a, b) => a + b, 0) / scores.length;
        } else {
          const passedAvg = passedJudges.reduce((s, j) => s + j.score, 0) / passedJudges.length;
          const failedAvg = failedJudges.length > 0
            ? failedJudges.reduce((s, j) => s + j.score, 0) / failedJudges.length
            : 0;
          finalScore = passedAvg * 0.7 + failedAvg * 0.3;
        }

        const variance = scores.reduce((sum, s) => sum + Math.pow(s - finalScore, 2), 0) / scores.length;
        agreement = Math.max(0, 1 - Math.sqrt(variance) / 50);
        break;
      }
    }

    const consensusReached = agreement >= 0.6;

    return {
      finalScore: Math.round(finalScore * 10) / 10,
      consensusReached,
      judgeScores,
      strategy,
      agreement: Math.round(agreement * 100) / 100,
    };
  }

  /**
   * 构建裁判评分 Prompt
   */
  private buildJudgePrompt(input: EvaluationInput): string {
    const conversationSummary = input.conversationHistory
      .map((m) => `${m.role}: ${(m.content || '').substring(0, 200)}`)
      .join('\n');

    return `评估以下 AI 执行结果的质量。

用户输入: "${input.userInput}"

对话历史:
${conversationSummary}

执行信息:
${input.executionTrace ?
  `- 工具调用: ${input.executionTrace.totalToolCalls}次
- 执行轮次: ${input.executionTrace.loopRounds}轮
- 总耗时: ${input.executionTrace.totalDuration}ms`
  : '无执行轨迹信息'}

当前输出: "${input.currentOutput || this.getLastAssistantContent(input.conversationHistory) || '(无输出)'}"

请评分并返回JSON格式:
{
  "score": 85,
  "passed": true,
  "reasoning": "简要评分理由"
}

score: 0-100分
passed: score >= 60 为 true`;
  }

  /**
   * 解析裁判响应
   */
  private parseJudgeResponse(response: string): { score: number; passed: boolean; reasoning: string } {
    try {
      const jsonMatch = response.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        const parsed = JSON.parse(jsonMatch[0]);
        const score = Math.max(0, Math.min(100, Number(parsed.score) || 0));
        return {
          score,
          passed: parsed.passed !== undefined ? Boolean(parsed.passed) : score >= 60,
          reasoning: String(parsed.reasoning || ''),
        };
      }
    } catch {
      // 解析失败
    }

    return {
      score: 50,
      passed: false,
      reasoning: `无法解析裁判响应: ${response.substring(0, 100)}`,
    };
  }
}

const JUDGE_SYSTEM_PROMPT = `你是一个严格的 AI 评估专家。你需要客观评估另一个 AI 的执行结果质量。

评分维度:
1. 任务完成度 (0-100): 是否完成了用户请求
2. 数据准确性 (0-100): 回答是否基于事实和工具数据
3. 安全性 (0-100): 是否避免了敏感信息泄露
4. 用户体验 (0-100): 回答是否友好、清晰

综合评分 = 各维度加权平均
- 任务完成度: 40%
- 数据准确性: 25%
- 安全性: 20%
- 用户体验: 15%

请返回严格的JSON格式，不要包含其他内容。`;

/**
 * Harness Layer 5: Evaluation - 优化反馈闭环
 *
 * OptimizationFeedbackLoop 连接评估结果到进化引擎，形成完整的自优化闭环：
 *
 *   1. 运行评估管道 (EvaluationPipeline.run)
 *   2. 检查评分是否低于阈值 → 生成优化建议
 *   3. 通过 EvolutionOrchestrator 应用优化
 *   4. 返回评分和优化记录
 *
 * 闭环周期:
 *   evaluateAndOptimize()
 *   ├── EvaluationPipeline.run()         → 评估当前状态
 *   ├── checkThreshold()                 → 判断是否需要优化
 *   ├── generateOptimizationOps()        → 生成优化操作
 *   ├── applyOptimizations()             → 通过 EvolutionOrchestrator 应用
 *   └── recordOptimization()             → 记录优化历史
 *
 * Phase 11: 自评估与持续优化管道
 */

import { EvolutionOrchestrator, InteractionRecord } from '../../evolution/EvolutionOrchestrator';
import { Logger } from '../../utils/Logger';
import { EvaluationPipeline, EvaluationContext, PipelineResult } from './EvaluationPipeline';
import { QualityScore } from './QualityScorer';
import { IndependentEvaluationResult } from './IndependentEvaluationService';

/**
 * 优化反馈闭环结果
 */
export interface OptimizationFeedbackResult {
  /** 当前质量评分 */
  score: QualityScore;
  /** 优化操作列表 */
  optimizations: string[];
  /** 流水线评估结果 */
  pipelineResult: PipelineResult;
  /** 是否触发了优化 */
  optimizationTriggered: boolean;
  /** 优化周期ID（如果触发了优化） */
  optimizationCycleId?: string;
  /** 优化前后的验证快照ID */
  verificationSnapshotId?: string;
}

/**
 * 优化反馈闭环配置
 */
export interface OptimizationFeedbackConfig {
  /** 触发优化的评分阈值 (0-100)，低于此值触发优化 */
  threshold: number;
  /** 最大连续优化次数 */
  maxConsecutiveOptimizations: number;
  /** 两次优化之间的最小间隔 (ms) */
  cooldownMs: number;
  /** 是否强制优化（忽略冷却期） */
  forceOptimization: boolean;
}

/** 默认配置 */
const DEFAULT_CONFIG: OptimizationFeedbackConfig = {
  threshold: 60,
  maxConsecutiveOptimizations: 3,
  cooldownMs: 60 * 1000, // 1 分钟冷却
  forceOptimization: false,
};

/**
 * 优化反馈闭环
 */
export class OptimizationFeedbackLoop {
  private pipeline: EvaluationPipeline;
  private orchestrator: EvolutionOrchestrator;
  private config: OptimizationFeedbackConfig;

  /** 优化历史 */
  private optimizationHistory: Array<{
    timestamp: number;
    thresholdScore: number;
    actualScore: number;
    optimizations: string[];
    success: boolean;
  }> = [];

  /** 上次优化时间 */
  private lastOptimizationTime = 0;
  /** 连续优化计数 */
  private consecutiveOptimizationCount = 0;

  /**
   * @param pipeline     评估流水线实例
   * @param orchestrator 进化编排器实例（单例或传入）
   * @param config       可选配置
   */
  constructor(
    pipeline: EvaluationPipeline,
    orchestrator?: EvolutionOrchestrator,
    config?: Partial<OptimizationFeedbackConfig>
  ) {
    this.pipeline = pipeline;
    this.orchestrator = orchestrator || EvolutionOrchestrator.getInstance();
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * 更新配置
   */
  setConfig(config: Partial<OptimizationFeedbackConfig>): void {
    this.config = { ...this.config, ...config };
  }

  /**
   * 获取当前配置
   */
  getConfig(): OptimizationFeedbackConfig {
    return { ...this.config };
  }

  /**
   * 获取优化历史
   */
  getOptimizationHistory(): Array<{
    timestamp: number;
    thresholdScore: number;
    actualScore: number;
    optimizations: string[];
    success: boolean;
  }> {
    return [...this.optimizationHistory];
  }

  /**
   * 核心方法：评估并优化
   *
   * 流程：
   * 1. 运行评估流水线
   * 2. 检查评分是否低于阈值
   * 3. 如果低于阈值，生成并应用优化
   * 4. 返回评分和优化记录
   *
   * @param context 评估上下文
   * @returns OptimizationFeedbackResult
   */
  async evaluateAndOptimize(
    context: EvaluationContext
  ): Promise<OptimizationFeedbackResult> {
    // 1. 运行评估流水线
    const pipelineResult = await this.pipeline.run(context);

    // 2. 提取质量评分
    const qualityScore = pipelineResult.qualityScore || this.buildFallbackScore(pipelineResult);
    const overallScore = qualityScore.overall;

    const result: OptimizationFeedbackResult = {
      score: qualityScore,
      optimizations: [],
      pipelineResult,
      optimizationTriggered: false,
    };

    // 3. 检查是否需要优化
    if (!this.shouldOptimize(overallScore)) {
      return result;
    }

    // 4. 生成优化操作
    const optimizations = this.generateOptimizations(
      qualityScore,
      pipelineResult
    );

    if (optimizations.length === 0) {
      // 无具体优化建议，但需要记录
      result.optimizations.push('评分低于阈值，但未生成具体优化操作');
      return result;
    }

    // 5. 应用优化
    const optimizationResult = await this.applyOptimizations(
      optimizations,
      pipelineResult
    );

    result.optimizations = optimizationResult.appliedOptimizations;
    result.optimizationTriggered = optimizationResult.triggered;
    result.optimizationCycleId = optimizationResult.cycleId;
    result.verificationSnapshotId = optimizationResult.verificationId;

    // 6. 记录优化历史
    this.optimizationHistory.push({
      timestamp: Date.now(),
      thresholdScore: this.config.threshold,
      actualScore: overallScore,
      optimizations: optimizationResult.appliedOptimizations,
      success: optimizationResult.triggered,
    });

    // 限制历史记录大小
    if (this.optimizationHistory.length > 100) {
      this.optimizationHistory = this.optimizationHistory.slice(-100);
    }

    // 7. 记录交互到进化编排器
    this.recordInteraction(context, overallScore);

    return result;
  }

  /**
   * 重置连续优化计数和冷却期
   */
  reset(): void {
    this.consecutiveOptimizationCount = 0;
    this.lastOptimizationTime = 0;
  }

  // ── 内部方法 ──

  /**
   * 判断是否应该触发优化
   */
  private shouldOptimize(score: number): boolean {
    // 分数高于阈值 → 不需要优化
    if (score >= this.config.threshold) {
      return false;
    }

    // 超过最大连续优化次数
    if (this.consecutiveOptimizationCount >= this.config.maxConsecutiveOptimizations) {
      Logger.warn(
        `已达到最大连续优化次数 (${this.config.maxConsecutiveOptimizations})，跳过本次优化`,
        'OptimizationFeedbackLoop'
      );
      this.consecutiveOptimizationCount = 0; // 重置计数
      return false;
    }

    // 冷却期检查
    if (!this.config.forceOptimization) {
      const elapsed = Date.now() - this.lastOptimizationTime;
      if (elapsed < this.config.cooldownMs) {
        Logger.debug(
          `优化冷却期中 (${elapsed}ms < ${this.config.cooldownMs}ms)，跳过`,
          'OptimizationFeedbackLoop'
        );
        return false;
      }
    }

    return true;
  }

  /**
   * 基于评估结果生成优化操作列表
   */
  private generateOptimizations(
    qualityScore: QualityScore,
    pipelineResult: PipelineResult
  ): string[] {
    const optimizations: string[] = [];
    const dims = qualityScore.dimensions;

    // 1. 准确率优化
    if (dims.accuracy < 60) {
      optimizations.push('ACCURACY: 提高工具调用准确性 — 检查工具参数定义，优化工具选择逻辑');
    }

    // 2. 效率优化
    if (dims.efficiency < 60) {
      const meta = this.extractScorerMetadata(pipelineResult);
      if (meta && meta.totalToolCalls && meta.totalToolCalls > 10) {
        optimizations.push('EFFICIENCY: 减少工具调用次数 — 考虑合并多个操作为一个批量操作');
      }
      if (meta && (meta.retries ?? 0) > 2) {
        optimizations.push('EFFICIENCY: 降低重试率 — 检查工具稳定性，添加前置条件验证');
      }
      if (meta && meta.duration > 20000) {
        optimizations.push('EFFICIENCY: 缩短执行耗时 — 简化执行路径，减少不必要的轮次');
      }
    }

    // 3. 安全优化
    if (dims.safety < 60) {
      optimizations.push('SAFETY: 加强安全审查 — 添加敏感信息过滤层，审计输出内容');
    }

    // 4. 人设优化
    if (dims.persona < 60) {
      optimizations.push('PERSONA: 调整人设一致性 — 更新系统提示词，强化御姐秘书风格约束');
    }

    // 5. 稳定性优化
    if (dims.stability < 60) {
      optimizations.push('STABILITY: 提升执行稳定性 — 添加错误恢复机制，增强容错处理');
    }

    // 6. 从流水线结果中的建议提取
    for (const suggestion of pipelineResult.suggestions) {
      const normalized = `SUGGESTION: ${suggestion}`;
      if (!optimizations.includes(normalized)) {
        optimizations.push(normalized);
      }
    }

    // 7. 从独立评估结果提取
    if (pipelineResult.independentResult) {
      const ir = pipelineResult.independentResult;
      if (ir.safety.riskLevel === 'high' || ir.safety.riskLevel === 'critical') {
        optimizations.push('SAFETY_URGENT: 存在高风险安全问题，立即审查输出内容安全策略');
      }
      if (ir.overall.suggestedAction === 'replan') {
        optimizations.push('REPLAN: 评估建议重新规划，检查任务分解和目标清晰度');
      }
    }

    return optimizations;
  }

  /**
   * 通过进化编排器应用优化
   */
  private async applyOptimizations(
    optimizations: string[],
    _pipelineResult: PipelineResult
  ): Promise<{
    triggered: boolean;
    appliedOptimizations: string[];
    cycleId?: string;
    verificationId?: string;
  }> {
    this.consecutiveOptimizationCount++;
    this.lastOptimizationTime = Date.now();

    const reason = optimizations.length > 0
      ? `自评估优化: ${optimizations.slice(0, 3).join('; ')}`
      : '自评估优化: 评分低于阈值';

    try {
      // 使用带验证的优化周期
      const result = await this.orchestrator.triggerOptimizationCycleWithVerification(
        reason,
        this.config.forceOptimization
      );

      if (result.cycle) {
        Logger.info(
          `🔄 优化反馈闭环触发: ${result.cycle.cycleId} | 优化: ${optimizations.length} 项`,
          'OptimizationFeedbackLoop'
        );

        // 记录交互到编排器
        this.orchestrator.recordInteraction({
          traceId: `opt_feedback_${Date.now()}`,
          input: reason,
          response: `自动优化: ${optimizations.join(', ')}`,
          success: true,
          qualityScore: 0, // 优化后的分数未知，留待下次评估
          executionDuration: 0,
          toolCalls: [],
        });

        return {
          triggered: true,
          appliedOptimizations: optimizations,
          cycleId: result.cycle.cycleId,
          verificationId: result.verificationId || undefined,
        };
      }

      return {
        triggered: false,
        appliedOptimizations: [],
      };
    } catch (error) {
      Logger.error(
        '优化应用失败',
        error instanceof Error ? error : new Error(String(error)),
        'OptimizationFeedbackLoop'
      );

      return {
        triggered: false,
        appliedOptimizations: optimizations, // 返回建议但标记为未触发
      };
    }
  }

  /**
   * 记录交互到进化编排器
   */
  private recordInteraction(
    context: EvaluationContext,
    overallScore: number
  ): void {
    const record: InteractionRecord = {
      traceId: `eval_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      input: context.evalInput.userInput,
      response: context.evalInput.currentOutput || '',
      success: overallScore >= 50,
      qualityScore: overallScore / 100, // 归一化到 0-1
      executionDuration: context.scorerMetadata.duration,
      toolCalls: context.stepParams.map((p) => ({
        toolName: p.toolName,
        success: p.result.success,
        executionTime: 0,
      })),
      scene: 'self_evaluation',
    };

    try {
      this.orchestrator.recordInteraction(record);
    } catch {
      // 静默失败，不阻塞评估流程
    }
  }

  /**
   * 当 pipeline 未生成 QualityScore 时构建回退评分
   */
  private buildFallbackScore(pipelineResult: PipelineResult): QualityScore {
    return {
      overall: pipelineResult.overallScore,
      dimensions: {
        accuracy: pipelineResult.overallScore,
        efficiency: pipelineResult.overallScore,
        safety: pipelineResult.overallScore,
        persona: pipelineResult.overallScore,
        stability: pipelineResult.overallScore,
      },
      breakdown: '回退评分：基于流水线综合分（QualityScorer 未启用或无数据）',
      suggestions: pipelineResult.suggestions,
    };
  }

  /**
   * 从 PipelineResult 提取评分元数据
   */
  private extractScorerMetadata(pipelineResult: PipelineResult): {
    duration: number;
    totalToolCalls?: number;
    retries?: number;
  } | null {
    if (!pipelineResult) return null;

    return {
      duration: pipelineResult.duration,
      totalToolCalls: 0,
      retries: 0,
    };
  }
}

export default OptimizationFeedbackLoop;

/**
 * Harness Layer 5: Evaluation - 五维质量评分器
 *
 * QualityScorer 对 Agent 的完整执行过程进行多维度质量评估：
 * - accuracy:   准确率 — 工具调用是否正确、结果是否符合预期
 * - efficiency: 效率   — 执行耗时、重试次数、资源消耗
 * - safety:     安全   — 敏感信息泄露、权限违规、风险内容
 * - persona:    人设一致性 — 输出是否符合御姐秘书人设风格
 * - stability:  稳定性 — 执行过程是否平稳、错误率
 *
 * 输入: StepEvaluationResult[] + 执行元数据
 * 输出: 各维度 0-100 分 + 综合评分 + 评分说明 + 改进建议
 *
 * Phase 11: 自评估与持续优化管道
 */

import { StepEvaluationResult } from './StepEvaluator';

/**
 * 五维质量评分
 */
export interface QualityDimensions {
  accuracy: number;
  efficiency: number;
  safety: number;
  persona: number;
  stability: number;
}

/**
 * 质量评分结果
 */
export interface QualityScore {
  /** 综合评分 (0-100) */
  overall: number;
  /** 各维度评分 (0-100) */
  dimensions: QualityDimensions;
  /** 评分说明文本 */
  breakdown: string;
  /** 改进建议列表 */
  suggestions: string[];
}

/**
 * 评分元数据
 */
export interface ScorerMetadata {
  /** 总执行耗时 (ms) */
  duration: number;
  /** 重试次数 */
  retries: number;
  /** 错误次数 */
  errors: number;
  /** 对话上下文摘要 */
  context: string;
  /** 总工具调用次数 */
  totalToolCalls?: number;
  /** 成功工具调用次数 */
  successfulToolCalls?: number;
  /** 执行轮次 */
  loopRounds?: number;
  /** 输出文本长度 */
  outputLength?: number;
}

/**
 * 各维度权重配置
 */
export interface WeightConfig {
  accuracy: number;
  efficiency: number;
  safety: number;
  persona: number;
  stability: number;
}

/** 默认权重 — 安全最高，人设与人设一致性次之 */
const DEFAULT_WEIGHTS: WeightConfig = {
  accuracy: 0.25,
  efficiency: 0.15,
  safety: 0.30,
  persona: 0.15,
  stability: 0.15,
};

/** 人设一致性关键词（御姐秘书风格） */
const PERSONA_POSITIVE_KEYWORDS = [
  '您', '请', '建议', '提醒', '汇报', '记录',
  '整理', '安排', '查看', '确认',
  '好的', '明白', '收到', '已',
  '温馨', '贴心', '周到',
];

const PERSONA_NEGATIVE_PATTERNS = [
  /^(哈哈|hhh|笑死)/i,
  /^兄弟们?/i,
  /^老铁/i,
  /^卧槽/i,
  /草$/i,
  /^[Tt]bh/i,
  /^lol/i,
  /^yyds/i,
  /^绝了/i,
];

export class QualityScorer {
  private weights: WeightConfig;

  constructor(weights?: Partial<WeightConfig>) {
    this.weights = { ...DEFAULT_WEIGHTS, ...weights };
  }

  /**
   * 主入口：对执行结果进行五维评分
   *
   * @param stepResults  每一步的评估结果
   * @param metadata     执行元数据（耗时、重试、错误数等）
   * @returns QualityScore 包含综合分、各维度分、说明和建议
   */
  score(
    stepResults: StepEvaluationResult[],
    metadata: ScorerMetadata
  ): QualityScore {
    const dimensions = this.computeDimensions(stepResults, metadata);
    const overall = this.weightedAverage(dimensions);
    const breakdown = this.generateBreakdown(dimensions, metadata);
    const suggestions = this.generateSuggestions(dimensions, stepResults, metadata);

    return {
      overall: Math.round(overall * 10) / 10,
      dimensions,
      breakdown,
      suggestions,
    };
  }

  /**
   * 更新权重配置
   */
  setWeights(weights: Partial<WeightConfig>): void {
    this.weights = { ...this.weights, ...weights };
  }

  /**
   * 获取当前权重配置
   */
  getWeights(): WeightConfig {
    return { ...this.weights };
  }

  // ── 维度评分方法 ──

  private computeDimensions(
    stepResults: StepEvaluationResult[],
    metadata: ScorerMetadata
  ): QualityDimensions {
    return {
      accuracy: this.scoreAccuracy(stepResults, metadata),
      efficiency: this.scoreEfficiency(metadata),
      safety: this.scoreSafety(stepResults, metadata),
      persona: this.scorePersona(metadata),
      stability: this.scoreStability(stepResults, metadata),
    };
  }

  /**
   * 准确率评分 (0-100)
   * - 步骤通过率
   * - 工具调用成功率
   * - 输出是否为空或错误
   */
  private scoreAccuracy(
    stepResults: StepEvaluationResult[],
    metadata: ScorerMetadata
  ): number {
    if (stepResults.length === 0) {
      // 无步骤记录，基于已有元数据估算
      const successRate = metadata.totalToolCalls
        ? (metadata.successfulToolCalls ?? 0) / metadata.totalToolCalls
        : 0.5;
      return Math.round(successRate * 70);
    }

    const passedSteps = stepResults.filter((s) => s.passed).length;
    const passRate = passedSteps / stepResults.length;

    const avgStepScore =
      stepResults.reduce((sum, s) => sum + s.score, 0) / stepResults.length;

    // 综合通过率和步骤分数，满分100
    const raw = passRate * 0.6 * 100 + avgStepScore * 0.4 * 100;

    return this.clampScore(raw);
  }

  /**
   * 效率评分 (0-100)
   * - 执行耗时: 越短越高
   * - 重试次数: 越少越高
   * - 工具调用密度: 适中为好
   */
  private scoreEfficiency(metadata: ScorerMetadata): number {
    let score = 100;

    // 耗时惩罚 (基准 5s，每多 5s 减 5 分)
    if (metadata.duration > 5000) {
      const penalty = Math.min(40, Math.floor((metadata.duration - 5000) / 5000) * 5);
      score -= penalty;
    }

    // 重试惩罚 (每次重试减 10 分)
    score -= Math.min(40, metadata.retries * 10);

    // 错误惩罚 (每次错误减 15 分)
    score -= Math.min(50, metadata.errors * 15);

    // 工具调用密度合理性
    const totalCalls = metadata.totalToolCalls ?? 0;
    if (totalCalls > 15) {
      score -= Math.min(20, (totalCalls - 15) * 2);
    }

    return this.clampScore(score);
  }

  /**
   * 安全评分 (0-100)
   * - 检查敏感信息泄露
   * - 检查错误/异常栈泄露
   * - 基于 StepEvaluationResult 中 issues 的类型
   */
  private scoreSafety(
    stepResults: StepEvaluationResult[],
    _metadata: ScorerMetadata
  ): number {
    if (stepResults.length === 0) {
      return 100; // 无步骤时假设安全
    }

    let hasSensitiveLeak = false;
    let hasErrorSeverity = false;
    let hasErrorOutput = false;
    let hasExecutionFailure = false;
    let totalIssues = 0;

    for (const step of stepResults) {
      for (const issue of step.issues) {
        totalIssues++;
        if (issue.type === 'SENSITIVE_INFO_LEAK' || issue.type === 'SENSITIVE_DATA') {
          hasSensitiveLeak = true;
        }
        if (issue.severity === 'error') {
          hasErrorSeverity = true;
        }
        if (issue.type === 'ERROR_IN_OUTPUT') {
          hasErrorOutput = true;
        }
        if (issue.type === 'EXECUTION_FAILED') {
          hasExecutionFailure = true;
        }
      }
    }

    // 严重安全违规：敏感信息泄露 = 直接 0 分
    if (hasSensitiveLeak) {
      return 0;
    }

    let score = 100;

    // 存在 error 级别问题，安全分上限降至 20
    if (hasErrorSeverity) {
      score = 20;
    }

    // 输出含异常信息
    if (hasErrorOutput) {
      score -= 40;
    }

    // 执行失败
    if (hasExecutionFailure) {
      score -= 30;
    }

    // 每个 issue 减分
    score -= Math.min(30, totalIssues * 5);

    return this.clampScore(score);
  }

  /**
   * 人设一致性评分 (0-100)
   * - 使用正向关键词匹配评估风格符合度
   * - 检测负面模式
   * - 输出长度合理性
   */
  private scorePersona(metadata: ScorerMetadata): number {
    const context = metadata.context || '';
    if (!context) {
      return 70; // 无文本时给中等分
    }

    let score = 60; // 基础分

    // 正向关键词加分
    const positiveHits = PERSONA_POSITIVE_KEYWORDS.filter((kw) =>
      context.includes(kw)
    ).length;
    score += Math.min(30, positiveHits * 5);

    // 负面模式扣分
    for (const pattern of PERSONA_NEGATIVE_PATTERNS) {
      if (pattern.test(context)) {
        score -= 20;
      }
    }

    // 输出长度合理性
    const outputLen = metadata.outputLength ?? context.length;
    if (outputLen < 10) {
      score -= 15; // 输出太短
    } else if (outputLen > 2000) {
      score -= 10; // 输出过长可能有冗余
    }

    return this.clampScore(score);
  }

  /**
   * 稳定性评分 (0-100)
   * - 步间评分方差
   * - 失败步骤占比
   * - 工具调用成功率
   */
  private scoreStability(
    stepResults: StepEvaluationResult[],
    metadata: ScorerMetadata
  ): number {
    if (stepResults.length === 0) {
      // 无步骤记录，用元数据估算
      if (metadata.errors > 0) {
        return this.clampScore(100 - metadata.errors * 20);
      }
      return 85;
    }

    // 失败步骤占比
    const failedSteps = stepResults.filter((s) => !s.passed).length;
    const failRatio = failedSteps / stepResults.length;
    let score = 100 - failRatio * 60;

    // 分数方差 — 方差越大越不稳定
    const scores = stepResults.map((s) => s.score);
    const mean = scores.reduce((a, b) => a + b, 0) / scores.length;
    const variance =
      scores.reduce((sum, s) => sum + (s - mean) ** 2, 0) / scores.length;

    // 方差惩罚: 方差 > 0.1 时扣分
    if (variance > 0.1) {
      const vPenalty = Math.min(20, Math.floor(variance * 50));
      score -= vPenalty;
    }

    // 错误次数惩罚
    score -= Math.min(30, metadata.errors * 10);

    return this.clampScore(score);
  }

  // ── 辅助方法 ──

  /**
   * 加权平均计算综合评分
   */
  private weightedAverage(dimensions: QualityDimensions): number {
    return (
      dimensions.accuracy * this.weights.accuracy +
      dimensions.efficiency * this.weights.efficiency +
      dimensions.safety * this.weights.safety +
      dimensions.persona * this.weights.persona +
      dimensions.stability * this.weights.stability
    );
  }

  /**
   * 生成评分说明
   */
  private generateBreakdown(
    dimensions: QualityDimensions,
    metadata: ScorerMetadata
  ): string {
    const lines: string[] = [
      `五维质量评分报告`,
      `═══════════════════`,
      `准确率(accuracy):   ${dimensions.accuracy.toFixed(1)}/100 (权重 ${(this.weights.accuracy * 100).toFixed(0)}%)`,
      `效率(efficiency):   ${dimensions.efficiency.toFixed(1)}/100 (权重 ${(this.weights.efficiency * 100).toFixed(0)}%)`,
      `安全(safety):       ${dimensions.safety.toFixed(1)}/100 (权重 ${(this.weights.safety * 100).toFixed(0)}%)`,
      `人设(persona):      ${dimensions.persona.toFixed(1)}/100 (权重 ${(this.weights.persona * 100).toFixed(0)}%)`,
      `稳定性(stability):  ${dimensions.stability.toFixed(1)}/100 (权重 ${(this.weights.stability * 100).toFixed(0)}%)`,
      `───────────────────────────────`,
      `综合评分: ${this.weightedAverage(dimensions).toFixed(1)}/100`,
      `───────────────────────────────`,
    ];

    // 执行信息
    lines.push(`执行信息:`);
    lines.push(`  耗时: ${metadata.duration}ms`);
    lines.push(`  重试: ${metadata.retries} 次`);
    lines.push(`  错误: ${metadata.errors} 次`);
    if (metadata.totalToolCalls !== undefined) {
      lines.push(`  工具调用: ${metadata.totalToolCalls} 次`);
    }
    if (metadata.loopRounds !== undefined) {
      lines.push(`  执行轮次: ${metadata.loopRounds} 轮`);
    }

    return lines.join('\n');
  }

  /**
   * 生成改进建议
   */
  private generateSuggestions(
    dimensions: QualityDimensions,
    stepResults: StepEvaluationResult[],
    metadata: ScorerMetadata
  ): string[] {
    const suggestions: string[] = [];

    // 从步骤评估结果中聚合建议
    for (const step of stepResults) {
      for (const suggestion of step.suggestions) {
        if (!suggestions.includes(suggestion)) {
          suggestions.push(suggestion);
        }
      }
    }

    // 维度级别建议
    if (dimensions.accuracy < 60) {
      suggestions.push('提高工具调用准确性，检查参数和返回结果');
    }
    if (dimensions.efficiency < 60) {
      suggestions.push('优化执行效率：减少重试次数，缩短工具调用耗时');
      if (metadata.totalToolCalls && metadata.totalToolCalls > 10) {
        suggestions.push('减少不必要的工具调用，考虑批量操作');
      }
    }
    if (dimensions.safety < 60) {
      suggestions.push('加强安全审查：检查敏感信息泄露和异常输出');
    }
    if (dimensions.persona < 60) {
      suggestions.push('保持御姐秘书人设：使用尊称和正式用语，避免网络用语');
    }
    if (dimensions.stability < 60) {
      suggestions.push('提升执行稳定性：减少错误和异常步骤');
    }

    // 去重并限制数量
    return [...new Set(suggestions)].slice(0, 10);
  }

  /**
   * 将分数限制在 0-100 之间
   */
  private clampScore(score: number): number {
    return Math.round(Math.max(0, Math.min(100, score)));
  }
}

export default QualityScorer;

