/**
 * Harness Layer 1: Loop - Executor 节点
 *
 * 执行 FC 循环，从 JiabaixingCore.executeFCLoop 提取核心逻辑
 */

import { Logger } from '../../utils/Logger';
import { EventBus } from '../../shared/EventBus';
import { LifecycleEvent } from '../types';
import type {
  ChatMessage,
  LoopContext,
  ExecutionPlan,
  ToolContext,
  ToolResult,
  TrajectoryStep,
  StepResult,
  BudgetState,
} from '../types';
import type { ExecutorOutput } from './LoopController';
import type { ToolRegistry } from '../tools/registry/ToolRegistry';
import type { SchemaValidator } from '../tools/registry/SchemaValidator';
import type { PermissionGuard } from '../tools/registry/PermissionGuard';
import { Permission } from '../types';
import { SkillRegistry } from '../../skills/SkillRegistry';
import type { SkillContext } from '../../skills/SkillInterface';
import type { TrajectoryDatabase } from '../persistence/TrajectoryDatabase';

/** Executor 依赖 */
export interface ExecutorDeps {
  /** LLM 提供者 */
  llm: {
    chatWithTools(
      messages: ChatMessage[],
      tools: Array<Record<string, unknown>>
    ): Promise<{
      content: string | null;
      toolCalls?: Array<{
        id: string;
        type: string;
        function: { name: string; arguments: string };
      }>;
    }>;
  };
  /** 工具注册表 */
  toolRegistry: ToolRegistry;
  /** Schema 验证器 */
  schemaValidator: SchemaValidator;
  /** 权限守卫 */
  permissionGuard: PermissionGuard;
  /** 验证服务 (P2 修复: 连接悬空的验证层) */
  verificationService?: {
    validateToolResult(toolName: string, result: { success: boolean; output?: unknown; error?: string }): {
      valid: boolean;
      sanitizedOutput: string;
      warnings: string[];
      errors: string[];
    };
    checkOutputSafety(output: string): {
      safe: boolean;
      riskLevel: string;
      violations: string[];
      sanitizedOutput?: string;
    };
  };
  /** 约束服务（生命周期钩子） */
  constraintsService?: {
    executeHooks(event: LifecycleEvent, context: { event: LifecycleEvent; toolName?: string; params?: Record<string, unknown>; result?: ToolResult; loopState?: string; budgetState?: BudgetState; metadata: Record<string, unknown> }): Promise<{ proceed: boolean; modifiedParams?: Record<string, unknown>; replacementResult?: ToolResult; reason?: string }>;
  };
  /** 轨迹数据库 */
  trajectoryDatabase?: TrajectoryDatabase;
}

/** 默认安全权限集 — 允许只读、记忆写入和低风险操作 */
const DEFAULT_SAFE_PERMISSIONS: Permission[] = [
  Permission.MEMORY_READ,
  Permission.MEMORY_WRITE,
  Permission.FILE_READ,
];

/** 默认限制 */
const HARD_TOOL_LIMIT = 8;
const SOFT_TOOL_LIMIT = 4;
const TOOL_TIMEOUT_MS = 30000;
const TOKEN_WARNING = 4500;
const MAX_TOOL_OUTPUT = 4000;

export class Executor {
  private deps: ExecutorDeps;

  constructor(deps: ExecutorDeps) {
    this.deps = deps;
  }

  /**
   * 执行 FC 循环
   */
  async execute(
    plan: ExecutionPlan,
    context: LoopContext
  ): Promise<ExecutorOutput> {
    const harnessTools = this.deps.toolRegistry.toOpenAITools() as unknown as Array<Record<string, unknown>>;
    const skillTools = SkillRegistry.getInstance().toOpenAITools() as Array<Record<string, unknown>>;
    const allTools = [...harnessTools, ...skillTools];

    // F0-01: 计划上下文已由 LoopController.injectPlanIntoContext() 注入到 context.messages
    // 不再在此处重复注入，避免 LLM 看到重复的计划信息
    let messages = [...context.messages];
    let loopCount = 0;
    let totalToolCalls = 0;
    let totalToolDuration = 0;

    // 进化闭环：注入工具可靠性提示
    const unreliableTools = this.deps.toolRegistry.getReliabilityTracker().getUnreliableTools(0.7);
    if (unreliableTools.length > 0) {
      messages.push({
        role: 'system',
        content: `【工具可靠性提示】以下工具近期成功率偏低，优先考虑替代方案：${unreliableTools.join('、')}`,
      });
    }

    // 首次 LLM 调用
    let fcResponse = await this.deps.llm.chatWithTools(messages, allTools);

    // FC 循环
    while (
      fcResponse.toolCalls &&
      fcResponse.toolCalls.length > 0 &&
      loopCount < HARD_TOOL_LIMIT
    ) {
      loopCount++;
      const toolNames = fcResponse.toolCalls
        .map((tc) => tc.function.name)
        .join(', ');
      Logger.info(
        `🔄 第${loopCount}轮: LLM 调用了 ${fcResponse.toolCalls.length} 个工具 [${toolNames}]`,
        'Executor'
      );

      // Token 预算管理
      const estimatedTokens = this.estimateMessagesTokens(messages);
      if (estimatedTokens > TOKEN_WARNING) {
        Logger.info(
          `📊 Token 预算警告: 当前约 ${estimatedTokens} tokens，开始压缩`,
          'Executor'
        );
        messages = this.compressMessages(messages, estimatedTokens);
      }

      // 软预算警告
      if (loopCount >= SOFT_TOOL_LIMIT) {
        messages.push({
          role: 'system',
          content: `注意：你已经进行了 ${loopCount} 轮工具调用。请尽量在 ${HARD_TOOL_LIMIT - loopCount} 轮内完成当前任务。如果已经收集到足够信息，直接回复用户。`,
        });
      }

      // 记录 assistant 消息
      messages.push({
        role: 'assistant',
        content: fcResponse.content || null,
        tool_calls: fcResponse.toolCalls,
      });

      // 并行执行工具调用
      const toolPromises = fcResponse.toolCalls.map(async (toolCall) => {
        const toolStart = Date.now();
        const toolName = toolCall.function.name;

        // 链路追踪
        this.traceToolCall(toolCall, 'started', context.trace.traceId);

        // 解析参数
        let args: Record<string, unknown> = {};
        try {
          args = JSON.parse(toolCall.function.arguments);
        } catch {
          args = {};
        }

        // P0 修复: BEFORE_TOOL_CALL 钩子
        let modifiedArgs = args;
        if (this.deps.constraintsService) {
          try {
            const beforeHookResult = await this.deps.constraintsService.executeHooks(
              LifecycleEvent.BEFORE_TOOL_CALL,
              {
                event: LifecycleEvent.BEFORE_TOOL_CALL,
                toolName,
                params: args,
                loopState: context.trace.state,
                budgetState: context.budget,
                metadata: {
                  traceId: context.trace.traceId,
                  loopCount,
                },
              }
            );
            if (!beforeHookResult.proceed) {
              Logger.info(
                `🛑 BEFORE_TOOL_CALL 钩子拦截: ${toolName} - ${beforeHookResult.reason}`,
                'Executor'
              );
              const hookResult: ToolResult = beforeHookResult.replacementResult || {
                success: false,
                output: `工具调用被拦截: ${beforeHookResult.reason}`,
                error: beforeHookResult.reason,
                duration: Date.now() - toolStart,
                validated: false,
              };
              const hookOutput = hookResult.output
                ? typeof hookResult.output === 'string'
                  ? hookResult.output
                  : JSON.stringify(hookResult.output)
                : `工具调用被拦截: ${beforeHookResult.reason}`;
              const hookError = hookResult.error
                ? typeof hookResult.error === 'string'
                  ? hookResult.error
                  : String(hookResult.error)
                : beforeHookResult.reason;
              return {
                toolCall,
                result: hookOutput,
                success: false,
                error: hookError,
                duration: Date.now() - toolStart,
              };
            }
            if (beforeHookResult.modifiedParams) {
              modifiedArgs = beforeHookResult.modifiedParams;
              Logger.debug(
                `📝 BEFORE_TOOL_CALL 修改参数: ${toolName}`,
                'Executor'
              );
            }
          } catch (hookErr) {
            Logger.warn(
              `⚠️ BEFORE_TOOL_CALL 钩子执行失败: ${(hookErr as Error).message}`,
              'Executor'
            );
          }
        }

        try {
          // Schema 验证
          const registeredTool = this.deps.toolRegistry.get(toolName);
          if (registeredTool) {
            const validation = this.deps.schemaValidator.validate(
              modifiedArgs,
              registeredTool.definition.parameters,
              registeredTool.definition.requiredParams
            );
            if (!validation.valid) {
              Logger.warn(
                `⚠️ 参数验证失败: ${toolName} - ${validation.errors.join('; ')}`,
                'Executor'
              );
              modifiedArgs = validation.sanitizedParams;
            }
          }

          // 权限检查
          const toolContext: ToolContext = {
            userId: context.metadata.userId as string | undefined,
            traceId: context.trace.traceId,
            permissions: this.resolvePermissions(context),
            metadata: {},
          };

          if (registeredTool) {
            const permCheck = this.deps.permissionGuard.check(
              toolName,
              registeredTool.definition.requiredPermissions,
              registeredTool.definition.riskLevel,
              toolContext
            );
            if (!permCheck.allowed) {
              this.traceToolCall(toolCall, 'failed', context.trace.traceId, Date.now() - toolStart, false, permCheck.reason);
              return {
                toolCall,
                result: `权限不足: ${permCheck.reason}`,
                success: false,
                duration: Date.now() - toolStart,
              };
            }
          }

          // 执行工具（带超时和重试），优先 Harness ToolRegistry，fallback 到 SkillRegistry
          let result: { success: boolean; output?: unknown; error?: string };
          if (registeredTool) {
            result = await this.executeWithRetry(toolName, modifiedArgs, toolContext);
          } else {
            Logger.info(
              `🔧 Harness 未注册该工具，降级到 SkillRegistry: ${toolName}`,
              'Executor'
            );
            const skillContext: SkillContext = {
              userId: context.metadata.userId as string | undefined,
              traceId: context.trace.traceId,
              sessionData: context.metadata as Record<string, unknown>,
            };
            result = await Promise.race([
              SkillRegistry.getInstance().executeToolCall(toolCall, skillContext),
              this.createTimeoutPromise(TOOL_TIMEOUT_MS, toolName),
            ]);
          }

          const toolDuration = Date.now() - toolStart;
          totalToolDuration += toolDuration;
          totalToolCalls++;

          // P2 修复: 使用 VerificationService 验证工具结果
          let output: string;
          if (result.success) {
            const rawOutput = typeof result.output === 'string'
              ? result.output
              : JSON.stringify(result.output);

            // 输出安全检查
            if (this.deps.verificationService) {
              const safetyCheck = this.deps.verificationService.checkOutputSafety(rawOutput);
              if (!safetyCheck.safe) {
                Logger.warn(
                  `⚠️ 工具输出安全警告 [${toolName}]: ${safetyCheck.violations.join('; ')}`,
                  'Executor'
                );
              }
              output = safetyCheck.sanitizedOutput || rawOutput;
            } else {
              output = this.validateToolOutput(result);
            }
          } else {
            output = `错误: ${result.error || '工具执行失败'}`;
          }

          this.traceToolCall(toolCall, 'completed', context.trace.traceId, toolDuration, result.success);

          // P0 修复: AFTER_TOOL_CALL 钩子
          if (this.deps.constraintsService) {
            try {
              const afterHookResult = await this.deps.constraintsService.executeHooks(
                LifecycleEvent.AFTER_TOOL_CALL,
                {
                  event: LifecycleEvent.AFTER_TOOL_CALL,
                  toolName,
                  params: modifiedArgs,
                  result: {
                    success: result.success,
                    output,
                    error: result.error,
                    duration: toolDuration,
                    validated: false,
                  },
                  loopState: context.trace.state,
                  budgetState: context.budget,
                  metadata: {
                    traceId: context.trace.traceId,
                    loopCount,
                    toolDuration,
                  },
                }
              );
              if (afterHookResult.replacementResult) {
                output = typeof afterHookResult.replacementResult.output === 'string'
                  ? afterHookResult.replacementResult.output
                  : JSON.stringify(afterHookResult.replacementResult.output);
                Logger.debug(
                  `📝 AFTER_TOOL_CALL 替换结果: ${toolName}`,
                  'Executor'
                );
              }
            } catch (hookErr) {
              Logger.warn(
                `⚠️ AFTER_TOOL_CALL 钩子执行失败: ${(hookErr as Error).message}`,
                'Executor'
              );
            }
          }

          // Track detailed trajectory step for tool call
          const trajectoryStepCall: TrajectoryStep = {
            type: 'tool_call',
            timestamp: toolStart,
            duration: toolDuration,
            toolName,
            toolParams: modifiedArgs,
            metadata: { toolCallId: toolCall.id }
          };
          context.trace.trajectory.push(trajectoryStepCall);

          const trajectoryStepResult: TrajectoryStep = {
            type: 'tool_result',
            timestamp: Date.now(),
            duration: 0,
            toolName,
            toolResult: {
              success: result.success,
              output: output,
              error: result.error,
              duration: toolDuration,
              validated: true,
              metadata: {}
            },
            metadata: { toolCallId: toolCall.id }
          };
          context.trace.trajectory.push(trajectoryStepResult);

          const stepResult: StepResult = {
            stepId: toolCall.id,
            toolName: toolName,
            success: result.success,
            output: output,
            duration: toolDuration,
            error: result.success ? undefined : result.error,
          };
          context.stepResults.set(toolCall.id, stepResult);

          return {
            toolCall,
            result: output,
            success: result.success,
            duration: toolDuration,
          };
        } catch (err) {
          const toolDuration = Date.now() - toolStart;
          totalToolDuration += toolDuration;
          totalToolCalls++;

          this.traceToolCall(toolCall, 'failed', context.trace.traceId, toolDuration, false, (err as Error).message);

          // P0 修复: ON_ERROR 钩子
          if (this.deps.constraintsService) {
            try {
              const errorHookResult = await this.deps.constraintsService.executeHooks(
                LifecycleEvent.ON_ERROR,
                {
                  event: LifecycleEvent.ON_ERROR,
                  toolName,
                  params: modifiedArgs,
                  result: {
                    success: false,
                    output: `错误: ${(err as Error).message}`,
                    error: (err as Error).message,
                    duration: toolDuration,
                    validated: false,
                  },
                  loopState: context.trace.state,
                  budgetState: context.budget,
                  metadata: {
                    traceId: context.trace.traceId,
                    loopCount,
                    errorMessage: (err as Error).message,
                  },
                }
              );
              if (!errorHookResult.proceed) {
                Logger.info(
                  `🛑 ON_ERROR 钩子拦截: ${toolName} - ${errorHookResult.reason}`,
                  'Executor'
                );
              }
            } catch (hookErr) {
              Logger.warn(
                `⚠️ ON_ERROR 钩子执行失败: ${(hookErr as Error).message}`,
                'Executor'
              );
            }
          }

          // Track detailed trajectory step for failed tool call
          const trajectoryStepCall: TrajectoryStep = {
            type: 'tool_call',
            timestamp: toolStart,
            duration: toolDuration,
            toolName,
            toolParams: modifiedArgs,
            metadata: { toolCallId: toolCall.id }
          };
          context.trace.trajectory.push(trajectoryStepCall);

          const trajectoryStepError: TrajectoryStep = {
            type: 'tool_result',
            timestamp: Date.now(),
            duration: 0,
            toolName,
            toolResult: {
              success: false,
              output: `错误: ${(err as Error).message}`,
              error: (err as Error).message,
              duration: toolDuration,
              validated: false,
              metadata: {}
            },
            metadata: { toolCallId: toolCall.id }
          };
          context.trace.trajectory.push(trajectoryStepError);

          const errorResult: StepResult = {
            stepId: toolCall.id,
            toolName: toolName,
            success: false,
            output: `错误: ${(err as Error).message}`,
            duration: toolDuration,
            error: (err as Error).message,
          };
          context.stepResults.set(toolCall.id, errorResult);

          return {
            toolCall,
            result: `错误: ${(err as Error).message}`,
            success: false,
            duration: toolDuration,
          };
        }
      });

      const toolResults = await Promise.all(toolPromises);

      // 将工具结果注入消息
      for (const tr of toolResults) {
        messages.push({
          role: 'tool',
          tool_call_id: tr.toolCall.id,
          name: tr.toolCall.function.name,
          content: tr.result,
        });
      }

      // 下一轮 LLM 调用
      fcResponse = await this.deps.llm.chatWithTools(messages, allTools);
    }

    // 如果 LLM 返回了文本响应（没有 tool_calls），追加到消息
    if (fcResponse.content && !fcResponse.toolCalls?.length) {
      messages.push({
        role: 'assistant',
        content: fcResponse.content,
      });
    }

    return {
      messages,
      toolCallsCount: totalToolCalls,
      toolDuration: totalToolDuration,
      completedNaturally: loopCount < HARD_TOOL_LIMIT,
    };
  }

  /**
   * 分类错误类型
   * @param error - 错误信息
   * @returns 错误分类
   */
  private classifyError(error: string): 'retryable' | 'non_retryable' {
    const retryablePatterns = /timeout|network|ECONNREFUSED|ETIMEDOUT|503|429/i;
    const nonRetryablePatterns = /permission|auth|invalid.?param|not.?found|权限|认证|参数无效|未找到/i;
    if (nonRetryablePatterns.test(error)) return 'non_retryable';
    if (retryablePatterns.test(error)) return 'retryable';
    return 'non_retryable';
  }

  /**
   * 带重试的工具执行
   * @param toolName - 工具名称
   * @param args - 工具参数
   * @param context - 工具上下文
   * @param maxRetries - 最大重试次数
   * @returns 工具执行结果
   */
  private async executeWithRetry(
    toolName: string,
    args: Record<string, unknown>,
    context: ToolContext,
    maxRetries: number = 2
  ): Promise<ToolResult> {
    let lastResult: ToolResult | null = null;
    let retryCount = 0;

    for (let attempt = 0; attempt <= maxRetries; attempt++) {
      try {
        const result = await Promise.race([
          this.deps.toolRegistry.execute(toolName, args, context),
          this.createTimeoutPromise(TOOL_TIMEOUT_MS, toolName),
        ]);

        if (result.success) {
          if (retryCount > 0) {
            result.metadata = { ...result.metadata, retryCount };
          }
          return result;
        }

        lastResult = result;
        const errorType = this.classifyError(result.error || '');

        if (errorType === 'non_retryable' || attempt >= maxRetries) {
          if (result.metadata) {
            result.metadata.retryCount = retryCount;
          } else {
            result.metadata = { retryCount };
          }
          return result;
        }

        retryCount++;
        Logger.info(
          `🔄 工具 ${toolName} 执行失败(可重试错误)，第${retryCount}次重试...`,
          'Executor'
        );
        await new Promise((resolve) => setTimeout(resolve, 500 * retryCount));
      } catch (err) {
        const errorMessage = (err as Error).message;
        const errorType = this.classifyError(errorMessage);

        lastResult = {
          success: false,
          output: null,
          error: errorMessage,
          duration: 0,
          validated: false,
          metadata: { retryCount },
        };

        if (errorType === 'non_retryable' || attempt >= maxRetries) {
          return lastResult;
        }

        retryCount++;
        Logger.info(
          `🔄 工具 ${toolName} 执行异常(可重试错误)，第${retryCount}次重试...`,
          'Executor'
        );
        await new Promise((resolve) => setTimeout(resolve, 500 * retryCount));
      }
    }

    return lastResult || {
      success: false,
      output: null,
      error: '工具执行失败：重试次数耗尽',
      duration: 0,
      validated: false,
      metadata: { retryCount },
    };
  }

  /**
   * 构建计划上下文注入消息
   */
  private buildPlanContext(plan: ExecutionPlan): string {
    const steps = plan.steps
      .map((s, i) => `${i + 1}. ${s.description}${s.toolName ? ` (使用 ${s.toolName})` : ''}`)
      .join('\n');

    return `【执行计划】\n以下是建议的执行步骤，请按需执行：\n${steps}\n\n你可以根据实际情况调整执行顺序或跳过不需要的步骤。`;
  }

  /**
   * 验证工具输出
   */
  private validateToolOutput(result: { success: boolean; output?: unknown; error?: string }): string {
    if (!result.success) {
      return `错误: ${result.error || '工具执行失败'}`;
    }

    const outputStr =
      typeof result.output === 'string'
        ? result.output
        : JSON.stringify(result.output);

    if (!outputStr || outputStr.trim().length === 0) {
      return '工具返回了空结果';
    }

    if (outputStr.length > MAX_TOOL_OUTPUT) {
      return outputStr.substring(0, MAX_TOOL_OUTPUT) + '\n...[内容已截断]';
    }

    return outputStr;
  }

  /**
   * 估算消息 token 数 (改进版：区分中英文)
   * 
   * 估算规则：
   * - 英文：约 4 字符 ≈ 1 token
   * - 中文：约 2 字符 ≈ 1 token (中文信息密度更高)
   * - 代码：约 4 字符 ≈ 1 token
   * - 数字/标点：约 3 字符 ≈ 1 token
   */
  private estimateMessagesTokens(messages: ChatMessage[]): number {
    let totalTokens = 0;

    for (const msg of messages) {
      totalTokens += 10;

      if (msg.content) {
        totalTokens += this.countTokens(msg.content);
      }

      if (msg.tool_calls) {
        for (const tc of msg.tool_calls as Array<{ function: { name: string; arguments: string } }>) {
          totalTokens += 4;
          if (tc.function?.name) {
            totalTokens += this.countTokens(tc.function.name);
          }
          if (tc.function?.arguments) {
            totalTokens += this.countTokens(tc.function.arguments);
          }
        }
      }

      if (msg.name) {
        totalTokens += this.countTokens(msg.name);
      }
    }

    return Math.ceil(totalTokens);
  }

  /**
   * 计算文本的 token 估算数
   */
  private countTokens(text: string): number {
    if (!text || text.length === 0) return 0;

    let chineseChars = 0;
    let englishChars = 0;
    let codeChars = 0;
    let otherChars = 0;

    let inCodeBlock = false;
    const codeStartPattern = /```/g;
    const codeEndPattern = /```/g;

    for (let i = 0; i < text.length; i++) {
      const char = text[i];
      const code = text.charCodeAt(i);

      if (char === '`' && i < text.length - 2 && text.substring(i, i + 3) === '```') {
        inCodeBlock = !inCodeBlock;
        i += 2;
        continue;
      }

      if (inCodeBlock || (char === '`' && text.substring(i, i + 2) === '``')) {
        codeChars++;
        if (char === '`') i++;
        continue;
      }

      if ((code >= 0x4E00 && code <= 0x9FFF) ||
          (code >= 0x3400 && code <= 0x4DBF) ||
          (code >= 0xF900 && code <= 0xFAFF)) {
        chineseChars++;
      } else if ((code >= 0x0041 && code <= 0x007A) ||
                 (code >= 0x0041 && code <= 0x005A) ||
                 (code >= 0x0030 && code <= 0x0039)) {
        englishChars++;
      } else if (/[{}()[\];,.<>:\+\-\*\/\\|&\s]/.test(char)) {
        otherChars++;
      } else {
        codeChars++;
      }
    }

    const chineseTokens = Math.ceil(chineseChars / 2);
    const englishTokens = Math.ceil(englishChars / 4);
    const codeTokens = Math.ceil(codeChars / 4);
    const otherTokens = Math.ceil(otherChars / 3);

    return chineseTokens + englishTokens + codeTokens + otherTokens;
  }

  /**
   * 压缩消息（保留 system + 最近 4 条非 system）
   */
  private compressMessages(messages: ChatMessage[], _currentTokens: number): ChatMessage[] {
    if (messages.length <= 5) return messages;

    const systemMessages: ChatMessage[] = [];
    const nonSystemMessages: ChatMessage[] = [];

    for (const msg of messages) {
      if (msg.role === 'system') {
        systemMessages.push(msg);
      } else {
        nonSystemMessages.push(msg);
      }
    }

    if (nonSystemMessages.length <= 4) return messages;

    const keptMessages = nonSystemMessages.slice(-4);
    const removedMessages = nonSystemMessages.slice(0, -4);

    const summaryParts: string[] = [];
    for (const msg of removedMessages) {
      if (msg.role === 'user' && msg.content) {
        summaryParts.push(`用户: ${msg.content.substring(0, 80)}`);
      } else if (msg.role === 'assistant' && msg.content) {
        summaryParts.push(`助手: ${msg.content.substring(0, 80)}`);
      } else if (msg.role === 'tool' && msg.name) {
        summaryParts.push(`工具[${msg.name}]: ${(msg.content || '').substring(0, 60)}`);
      }
    }

    const result: ChatMessage[] = [];

    const systemContent = systemMessages
      .map((m) => m.content || '')
      .filter(Boolean)
      .join('\n\n');
    if (systemContent) {
      result.push({ role: 'system', content: systemContent });
    }

    if (summaryParts.length > 0) {
      result.push({
        role: 'system',
        content: `【历史摘要（已压缩）】\n${summaryParts.join('\n')}`,
      });
    }

    result.push(...keptMessages);
    return result;
  }

  /**
   * 链路追踪
   */
  private traceToolCall(
    toolCall: { id: string; function: { name: string; arguments: string } },
    status: 'started' | 'completed' | 'failed',
    traceId: string,
    duration?: number,
    success?: boolean,
    errorMessage?: string
  ): void {
    const eventBusData = {
      timestamp: new Date().toISOString(),
      traceId,
      toolCallId: toolCall.id,
      toolName: toolCall.function.name,
      status,
      duration: duration || 0,
      success: success !== undefined ? success : null,
      errorMessage: errorMessage || null,
    };

    EventBus.emit('tool_trace', eventBusData);

    if (status === 'started') return;

    if (this.deps.trajectoryDatabase && traceId) {
      const stepIndex = 0;
      try {
        this.deps.trajectoryDatabase.recordToolInvocation({
          execution_id: traceId,
          step_index: stepIndex,
          tool_name: toolCall.function.name,
          args_json: toolCall.function.arguments,
          result_success: success === true ? 1 : 0,
          result_output: status === 'completed' ? '[truncated]' : undefined,
          duration: duration || 0,
          error_message: errorMessage || undefined,
          created_at: Date.now(),
        });
      } catch (err) {
        Logger.warn(
          `⚠️ 轨迹记录失败: ${(err as Error).message}`,
          'Executor'
        );
      }
    }
  }

  /**
   * 创建超时 Promise
   */
  private createTimeoutPromise(timeoutMs: number, toolName: string): Promise<never> {
    return new Promise((_, reject) => {
      setTimeout(() => {
        reject(new Error(`工具执行超时: ${toolName} (${timeoutMs}ms)`));
      }, timeoutMs);
    });
  }

  /**
   * 从 LoopContext 解析用户权限
   * 优先使用 metadata.permissions，否则使用默认安全权限集
   */
  private resolvePermissions(context: LoopContext): Set<Permission> {
    const metaPerms = context.metadata.permissions;
    if (Array.isArray(metaPerms) && metaPerms.length > 0) {
      const validPerms = metaPerms.filter((p: unknown) =>
        Object.values(Permission).includes(p as Permission)
      ) as Permission[];
      if (validPerms.length > 0) {
        return new Set(validPerms);
      }
    }
    return new Set(DEFAULT_SAFE_PERMISSIONS);
  }
}

/**
 * Harness Layer 1: Loop - 循环控制器
 *
 * Plan-Execute-Evaluate 状态机
 * 替代 JiabaixingCore.executeFCLoop 的单层 FC 循环
 */

import { Logger } from '../../utils/Logger';
import { perf } from '../../utils/PerformanceMonitor';
import { LoopState, LifecycleEvent } from '../types';
import { EventBus } from '../../shared/EventBus';
import type {
  ChatMessage,
  UserInput,
  AgentResult,
  LoopContext,
  LoopTrace,
  BudgetState,
  BudgetCheckResult,
  ExecutionPlan,
  StepResult,
  QualityScore,
  HookContext,
  HookResult,
} from '../types';
import type { ConstraintsService } from '../constraints/ConstraintsService';
import type { VerificationService } from '../verification/VerificationService';
import type { PersistenceService } from '../persistence/PersistenceService';
import type { TrajectoryDatabase } from '../persistence/TrajectoryDatabase';

/** 循环控制器依赖 */
export interface LoopControllerDeps {
  /** 规划器 */
  planner: {
    plan(input: UserInput, context: LoopContext): Promise<ExecutionPlan>;
  };
  /** 执行器 */
  executor: {
    execute(
      plan: ExecutionPlan,
      context: LoopContext
    ): Promise<ExecutorOutput>;
  };
  /** 评估器 */
  evaluator: {
    evaluate(
      input: UserInput,
      context: LoopContext
    ): Promise<EvaluatorOutput>;
  };
  /** 报告器 */
  reporter: {
    report(context: LoopContext): Promise<ReporterOutput>;
  };
  /** 约束服务 */
  constraintsService?: {
    checkBudget(state: BudgetState): BudgetCheckResult;
    executeHooks(event: LifecycleEvent, context: HookContext): Promise<HookResult>;
  };
  /** 验证服务 */
  verificationService?: VerificationService;
  /** 持久化服务 */
  persistenceService?: PersistenceService;
  /** 轨迹数据库 */
  trajectoryDatabase?: TrajectoryDatabase;
}

/** 执行器输出 */
export interface ExecutorOutput {
  messages: ChatMessage[];
  toolCallsCount: number;
  toolDuration: number;
  completedNaturally: boolean;
}

/** 评估器输出 */
export interface EvaluatorOutput {
  goalProgress: number;
  suggestedAction: 'continue' | 'replan' | 'abort';
  reason: string;
}

/** 报告器输出 */
export interface ReporterOutput {
  response: string;
  quality: QualityScore;
}

/** 默认预算 */
const DEFAULT_BUDGET: BudgetState = {
  roundsUsed: 0,
  softRoundLimit: 4,
  hardRoundLimit: 8,
  tokensUsed: 0,
  tokenWarningLimit: 4500,
  tokenHardLimit: 6000,
  startTime: 0,
  maxDurationMs: 60000,
  toolCallsUsed: 0,
  maxToolCalls: 20,
};

export class LoopController {
  private state: LoopState = LoopState.COMPLETED;
  private deps: LoopControllerDeps;
  private aborted = false;

  constructor(deps: LoopControllerDeps) {
    this.deps = deps;
  }

  /**
   * 运行 Plan-Execute-Evaluate 循环 (支持多轮迭代)
   */
  async run(input: UserInput, initialMessages: ChatMessage[]): Promise<AgentResult> {
    this.aborted = false;
    const traceId = input.traceId || `loop-${Date.now()}`;

    if (this.deps.trajectoryDatabase) {
      try {
        this.deps.trajectoryDatabase.recordExecution({
          id: traceId,
          user_id: input.userId,
          input: input.text,
          status: 'failed',
          loop_rounds: 0,
          total_tool_calls: 0,
          total_duration: 0,
          created_at: Date.now(),
          updated_at: Date.now(),
        });
      } catch (err) {
        Logger.warn(`⚠️ 轨迹记录失败: ${(err as Error).message}`, 'LoopController');
      }
    }

    // 初始化循环上下文
    const context: LoopContext = {
      messages: [...initialMessages],
      plan: null,
      currentStepIndex: 0,
      stepResults: new Map(),
      budget: { ...DEFAULT_BUDGET, startTime: Date.now() },
      trace: {
        traceId,
        state: LoopState.PLANNING,
        stateTransitions: [],
        trajectory: [],
        totalDuration: 0,
        totalToolCalls: 0,
        budgetState: DEFAULT_BUDGET,
      },
      metadata: { input: input.text },
    };

    Logger.info(`🔄 LoopController 启动 [${traceId}]`, 'LoopController');

    try {
      // Step 2: 保存任务状态 (Phase 1 之前)
      if (this.deps.persistenceService) {
        await this.deps.persistenceService.saveTaskState({
          taskId: traceId,
          userId: input.userId || 'default',
          description: input.text,
          status: 'in_progress',
          currentStepIndex: 0,
          createdAt: Date.now(),
          updatedAt: Date.now(),
        });
      }

      // BEFORE_LOOP 钩子
      await this.executeHook(LifecycleEvent.BEFORE_LOOP, context, {
        input: input.text,
      });

      // ─── 多轮迭代循环 ───
      let plan: import('../types').ExecutionPlan | null = null;
      let evalResult: EvaluatorOutput | null = null;
      let shouldContinueLoop = true;
      let replanNeeded = false;
      const MAX_REPLAN_COUNT = 2;

      while (shouldContinueLoop && !this.aborted) {
        // 检查预算
        const budgetCheck = this.checkBudget(context);
        if (!budgetCheck.withinBudget) {
          Logger.warn(
            `⚠️ 预算超限: ${budgetCheck.warnings.join('; ')}`,
            'LoopController'
          );
          await this.executeHook(LifecycleEvent.ON_BUDGET_EXCEEDED, context, {
            budgetState: context.budget,
          });
          this.transition(LoopState.BUDGET_EXCEEDED, context);
          shouldContinueLoop = false;
          break;
        }

        // ─── Phase 1: PLANNING (仅首次或需要 replan 时) ───
        if (!plan || replanNeeded) {
          const currentReplanCount = (context.metadata.replanCount as number) || 0;
          if (replanNeeded && currentReplanCount >= MAX_REPLAN_COUNT) {
            Logger.warn('⚠️ 重新规划次数已达上限，强制结束循环', 'LoopController');
            shouldContinueLoop = false;
            break;
          }

          this.transition(LoopState.PLANNING, context);
          plan = await perf.measure('planner.plan', () => this.deps.planner.plan(input, context), 'loop');
          context.plan = plan;
          context.metadata.replanCount = currentReplanCount + (replanNeeded ? 1 : 0);
          replanNeeded = false;

          this.recordSnapshot(context, 'planning', context.budget.roundsUsed, {
            planReasoning: plan.planReasoning?.substring(0, 500),
            stepsCount: plan.steps.length,
            isSimple: plan.simple,
          });

          if (plan.simple) {
            Logger.info('📋 简单任务，跳过规划直接执行', 'LoopController');
          } else {
            Logger.info(
              `📋 规划完成: ${plan.steps.length} 个步骤`,
              'LoopController'
            );
          }

          // F0-02: 将 Planner 的决策注入共享上下文，确保 Executor 和 Evaluator 看到完整规划
          this.injectPlanIntoContext(plan, context);

          await this.executeHook(LifecycleEvent.ON_PLAN_CREATED, context, {
            plan: plan.steps,
          });
        }

        // ─── Phase 2: EXECUTING ───
        this.transition(LoopState.EXECUTING, context);
        const executorOutput = await perf.measure('executor.execute', () => this.deps.executor.execute(plan!, context), 'loop');

        this.recordSnapshot(context, 'executing', context.budget.roundsUsed, {
          toolCallsCount: executorOutput.toolCallsCount,
          toolDuration: executorOutput.toolDuration,
          completedNaturally: executorOutput.completedNaturally,
          newMessagesCount: executorOutput.messages.length,
        });

        // 验证工具结果
        if (this.deps.verificationService) {
          const toolMessages = executorOutput.messages.filter(m => m.role === 'tool' && m.name);
          for (const toolMsg of toolMessages) {
            const toolName = toolMsg.name as string;
            const toolResult = {
              success: !(toolMsg.content as string).startsWith('错误:'),
              output: toolMsg.content,
              duration: 0,
              validated: false
            };
            const validation = this.deps.verificationService.validateToolResult(toolName, toolResult);
            if (validation.warnings.length > 0) {
              Logger.warn(`⚠️ 工具 ${toolName} 验证警告: ${validation.warnings.join('; ')}`, 'LoopController');
            }
            if (validation.errors.length > 0) {
              Logger.error(`❌ 工具 ${toolName} 验证错误: ${validation.errors.join('; ')}`, new Error(validation.errors.join('; ')), 'LoopController');
            }
          }
        }

        // 更新上下文
        context.messages = executorOutput.messages;
        context.budget.roundsUsed++;
        context.budget.toolCallsUsed += executorOutput.toolCallsCount;
        context.trace.totalToolCalls += executorOutput.toolCallsCount;

        // ─── Phase 3: EVALUATING ───
        this.transition(LoopState.EVALUATING, context);
        evalResult = await perf.measure('evaluator.evaluate', () => this.deps.evaluator.evaluate(input, context), 'loop');

        this.recordSnapshot(context, 'evaluating', context.budget.roundsUsed, {
          goalProgress: evalResult.goalProgress,
          suggestedAction: evalResult.suggestedAction,
          reason: evalResult.reason,
        });

        Logger.info(
          `📊 第 ${context.budget.roundsUsed} 轮: 进度=${(evalResult.goalProgress * 100).toFixed(0)}% 动作=${evalResult.suggestedAction}`,
          'LoopController'
        );

        // 根据评估结果决定下一步
        switch (evalResult.suggestedAction) {
          case 'continue':
            // 继续下一轮迭代，检查是否需要重新规划
            if (evalResult.goalProgress >= 0.9) {
              // 目标基本达成，结束循环
              shouldContinueLoop = false;
              Logger.info('✅ 目标已基本达成，结束循环', 'LoopController');
            } else if (context.budget.roundsUsed >= context.budget.softRoundLimit) {
              // 接近软限制，检查是否还有显著进展
              if (evalResult.goalProgress < 0.3) {
                // 进展缓慢且接近限制，强制结束
                shouldContinueLoop = false;
                Logger.info('⚠️ 进展缓慢且接近轮次限制，强制结束', 'LoopController');
              }
            }
            break;

          case 'replan':
            if (this.wasLastFailureRetryable(context)) {
              const lastStepResult = this.getLastFailedStepResult(context);
              const retryCount = (lastStepResult?.metadata?.retryCount as number) || 0;
              const maxRetries = 2;
              if (retryCount < maxRetries) {
                Logger.info(
                  `🔄 上次失败为可重试错误(retryCount=${retryCount})，跳过重新规划，重试当前计划`,
                  'LoopController'
                );
              } else {
                replanNeeded = true;
                Logger.info('🔄 可重试错误已达最大重试次数，重新规划', 'LoopController');
              }
            } else {
              replanNeeded = true;
              Logger.info('🔄 评估建议重新规划', 'LoopController');
            }
            break;

          case 'abort':
            // 主动中止
            shouldContinueLoop = false;
            Logger.info('🛑 评估建议中止执行', 'LoopController');
            break;

          default:
            // 未知动作，保守处理
            shouldContinueLoop = false;
            Logger.warn(`⚠️ 未知评估动作: ${evalResult.suggestedAction}`, 'LoopController');
        }

        // ON_STEP_COMPLETED 钩子
        await this.executeHook(LifecycleEvent.ON_STEP_COMPLETED, context, {
          goalProgress: evalResult.goalProgress,
          suggestedAction: evalResult.suggestedAction,
          roundsUsed: context.budget.roundsUsed,
        });
      }

      // ─── 循环结束 ───
      // BEFORE_RESPONSE 钩子
      await this.executeHook(LifecycleEvent.BEFORE_RESPONSE, context, {});

      // ─── Phase 4: REPORTING ───
      this.transition(LoopState.REPORTING, context);
      const report = await perf.measure('reporter.report', () => this.deps.reporter.report(context), 'loop');

      this.recordSnapshot(context, 'reporting', context.budget.roundsUsed, {
        responseLength: report.response.length,
        qualityOverall: report.quality.overall,
      });

      // 结合验证服务评估质量
      let finalQuality = report.quality;
      if (this.deps.verificationService) {
        const verificationQuality = this.deps.verificationService.scoreQuality({
          loopCount: context.budget.roundsUsed,
          totalToolCalls: context.trace.totalToolCalls,
          totalToolDuration: 0,
          totalDuration: Date.now() - context.budget.startTime,
          completedSuccessfully: true
        });

        // 合并质量评分，取平均值
        finalQuality = {
          overall: (report.quality.overall + verificationQuality.overall) / 2,
          accuracy: (report.quality.accuracy + verificationQuality.accuracy) / 2,
          usefulness: (report.quality.usefulness + verificationQuality.usefulness) / 2,
          friendliness: (report.quality.friendliness + verificationQuality.friendliness) / 2,
          efficiency: (report.quality.efficiency + verificationQuality.efficiency) / 2,
          details: `${report.quality.details} | ${verificationQuality.details}`
        };
      }

      // 完成
      this.transition(LoopState.COMPLETED, context);
      context.trace.totalDuration = Date.now() - context.budget.startTime;

      // 更新任务状态为 completed
      if (this.deps.persistenceService) {
        await this.deps.persistenceService.updateTaskStatus(traceId, 'completed');
      }

      // 轨迹数据库更新
      if (this.deps.trajectoryDatabase) {
        try {
          this.deps.trajectoryDatabase.updateExecutionStatus(traceId, 'success', report.response);
          const exec = this.deps.trajectoryDatabase.getExecution(traceId);
          if (exec) {
            exec.loop_rounds = context.budget.roundsUsed;
            exec.total_tool_calls = context.trace.totalToolCalls;
            exec.total_duration = context.trace.totalDuration;
            exec.quality_overall = finalQuality.overall;
            this.deps.trajectoryDatabase.recordExecution(exec);
          }
        } catch (err) {
          Logger.warn(`⚠️ 轨迹更新失败: ${(err as Error).message}`, 'LoopController');
        }
      }

      // AFTER_RESPONSE 钩子
      await this.executeHook(LifecycleEvent.AFTER_RESPONSE, context, {
        input: input.text,
        response: report.response,
        quality: finalQuality,
        loopRounds: context.budget.roundsUsed,
      });

      Logger.info(
        `✅ LoopController 完成 [${traceId}] 耗时=${context.trace.totalDuration}ms 轮次=${context.budget.roundsUsed} 工具=${context.trace.totalToolCalls}次`,
        'LoopController'
      );

      return {
        response: report.response,
        quality: finalQuality,
        trace: context.trace,
        metadata: {
          loopRounds: context.budget.roundsUsed,
          toolCalls: context.trace.totalToolCalls,
          duration: context.trace.totalDuration,
        },
      };
    } catch (err) {
      this.transition(LoopState.FAILED, context);
      Logger.error('LoopController 失败', err as Error, 'LoopController');

      if (this.deps.persistenceService) {
        await this.deps.persistenceService.updateTaskStatus(traceId, 'failed', (err as Error).message);
      }

      const lastAssistantMsg = this.getLastAssistantMessage(context);
      if (lastAssistantMsg) {
        Logger.info('⚠️ 返回部分响应（含质量警告）', 'LoopController');
        return {
          response: lastAssistantMsg,
          quality: { overall: 0.4, accuracy: 0.3, usefulness: 0.5, friendliness: 0.6, efficiency: 0.2, details: '部分响应（执行异常降级）' },
          trace: context.trace,
          metadata: { error: (err as Error).message, degraded: true },
        };
      }

      return {
        response: `抱歉，处理过程中出现了问题：${(err as Error).message}`,
        quality: { overall: 0.1, accuracy: 0, usefulness: 0, friendliness: 0.5, efficiency: 0, details: '执行失败' },
        trace: context.trace,
        metadata: { error: (err as Error).message },
      };
    }
  }

  /**
   * 获取当前状态
   */
  getState(): LoopState {
    return this.state;
  }

  /**
   * 中止循环
   */
  abort(): void {
    this.aborted = true;
    Logger.info('🛑 LoopController 中止', 'LoopController');
  }

  /**
   * 获取追踪信息
   */
  getTrace(context: LoopContext): LoopTrace {
    return context.trace;
  }

  /**
   * 状态转换
   */
  private transition(newState: LoopState, context: LoopContext): void {
    const prev = this.state;
    this.state = newState;
    context.trace.state = newState;
    context.trace.stateTransitions.push({
      state: newState,
      timestamp: Date.now(),
    });

    const phaseMap: Record<LoopState, string> = {
      [LoopState.PLANNING]: 'planning',
      [LoopState.EXECUTING]: 'executing',
      [LoopState.EVALUATING]: 'evaluating',
      [LoopState.REPORTING]: 'reporting',
      [LoopState.COMPLETED]: 'completed',
      [LoopState.FAILED]: 'failed',
      [LoopState.ABORTED]: 'aborted',
      [LoopState.BUDGET_EXCEEDED]: 'budget_exceeded',
    };

    const phaseName = phaseMap[newState] || 'unknown';
    const statusMap: Record<LoopState, string> = {
      [LoopState.PLANNING]: 'started',
      [LoopState.EXECUTING]: 'in_progress',
      [LoopState.EVALUATING]: 'in_progress',
      [LoopState.REPORTING]: 'in_progress',
      [LoopState.COMPLETED]: 'completed',
      [LoopState.FAILED]: 'failed',
      [LoopState.ABORTED]: 'aborted',
      [LoopState.BUDGET_EXCEEDED]: 'exceeded',
    };

    void EventBus.emit('agent_execution_update', {
      traceId: context.trace.traceId,
      phase: phaseName,
      status: statusMap[newState] || 'unknown',
      state: newState,
      roundsUsed: context.budget.roundsUsed,
      toolCallsUsed: context.budget.toolCallsUsed,
      elapsedMs: Date.now() - context.budget.startTime,
      timestamp: new Date().toISOString(),
    });

    if (this.deps.trajectoryDatabase) {
      try {
        this.deps.trajectoryDatabase.recordStateTransition({
          execution_id: context.trace.traceId,
          from_state: prev,
          to_state: newState,
          created_at: Date.now(),
        });
      } catch (err) {
        Logger.warn(`⚠️ 状态转换记录失败: ${(err as Error).message}`, 'LoopController');
      }
    }

    Logger.debug(`🔄 状态转换: ${prev} → ${newState}`, 'LoopController');
  }

  /**
   * 记录上下文快照到轨迹数据库
   * P0: 全轨迹审计增强 — 每步完整上下文快照
   */
  private recordSnapshot(
    context: LoopContext,
    phase: 'planning' | 'executing' | 'evaluating' | 'reporting' | 'tool_call' | 'tool_result' | 'llm_call',
    stepIndex: number,
    extra: Record<string, unknown> = {}
  ): void {
    if (!this.deps.trajectoryDatabase) return;

    try {
      const messagesSnapshot = context.messages.map((m) => ({
        role: m.role,
        content: typeof m.content === 'string'
          ? m.content.substring(0, 2000)
          : null,
        tool_calls: m.tool_calls
          ? (m.tool_calls as Array<Record<string, unknown>>).map((tc) => ({
              id: (tc as { id?: string }).id,
              type: (tc as { type?: string }).type,
              function: {
                name: ((tc as { function?: Record<string, unknown> }).function?.name as string) || 'unknown',
                arguments: typeof ((tc as { function?: Record<string, unknown> }).function?.arguments) === 'string'
                  ? ((tc as { function?: Record<string, unknown> }).function?.arguments as string).substring(0, 500)
                  : undefined,
              },
            }))
          : undefined,
      }));

      const snapshot = {
        phase,
        stepIndex,
        budget: {
          roundsUsed: context.budget.roundsUsed,
          tokensUsed: context.budget.tokensUsed,
          toolCallsUsed: context.budget.toolCallsUsed,
          elapsedMs: Date.now() - context.budget.startTime,
        },
        messagesCount: context.messages.length,
        messagesSnapshot,
        planSteps: context.plan?.steps?.map((s) => ({
          id: s.id,
          description: s.description,
          toolName: s.toolName,
        })) || null,
        stepResultsSummary: Object.fromEntries(
          Array.from(context.stepResults.entries()).map(([k, v]) => [
            k,
            { success: v.success, toolName: v.toolName, error: v.error },
          ])
        ),
        ...extra,
      };

      this.deps.trajectoryDatabase.recordContextSnapshot({
        execution_id: context.trace.traceId,
        phase,
        step_index: stepIndex,
        snapshot_json: JSON.stringify(snapshot),
        token_count: context.budget.tokensUsed,
        duration_ms: Date.now() - context.budget.startTime,
        created_at: Date.now(),
      });
    } catch (err) {
      Logger.warn(`⚠️ 上下文快照记录失败: ${(err as Error).message}`, 'LoopController');
    }
  }

  /**
   * 检查最近失败是否为可重试错误
   * @param context - 循环上下文
   * @returns 是否可重试
   */
  private wasLastFailureRetryable(context: LoopContext): boolean {
    const lastStepResult = this.getLastFailedStepResult(context);
    if (!lastStepResult) return false;
    const errorMsg = lastStepResult.error || '';
    const retryablePattern = /timeout|network|ECONNREFUSED|ETIMEDOUT|503|429|超时|网络/i;
    return retryablePattern.test(errorMsg);
  }

  /**
   * 获取最近失败的步骤结果
   * @param context - 循环上下文
   * @returns 失败的步骤结果或null
   */
  private getLastFailedStepResult(context: LoopContext): StepResult | null {
    const results = Array.from(context.stepResults.values());
    for (let i = results.length - 1; i >= 0; i--) {
      if (!results[i].success) return results[i];
    }
    return null;
  }

  /**
   * 获取上下文中最后的助手消息
   * @param context - 循环上下文
   * @returns 助手消息内容或null
   */
  private getLastAssistantMessage(context: LoopContext): string | null {
    for (let i = context.messages.length - 1; i >= 0; i--) {
      const msg = context.messages[i];
      if (msg.role === 'assistant' && msg.content) {
        return msg.content;
      }
    }
    return null;
  }

  /**
   * 检查预算 - 委托给 constraintsService
   */
  private checkBudget(context: LoopContext): {
    withinBudget: boolean;
    warnings: string[];
  } {
    if (this.deps.constraintsService) {
      const result = this.deps.constraintsService.checkBudget(context.budget);
      return {
        withinBudget: result.withinBudget,
        warnings: result.warnings,
      };
    }

    // Fallback: 本地实现
    const warnings: string[] = [];
    const budget = context.budget;

    if (budget.roundsUsed >= budget.hardRoundLimit) {
      warnings.push(`轮次超限: ${budget.roundsUsed}/${budget.hardRoundLimit}`);
    }

    if (budget.toolCallsUsed >= budget.maxToolCalls) {
      warnings.push(
        `工具调用超限: ${budget.toolCallsUsed}/${budget.maxToolCalls}`
      );
    }

    const elapsed = Date.now() - budget.startTime;
    if (elapsed >= budget.maxDurationMs) {
      warnings.push(`时间超限: ${elapsed}ms/${budget.maxDurationMs}ms`);
    }

    return { withinBudget: warnings.length === 0, warnings };
  }

  /**
   * 执行生命周期钩子
   */
  private async executeHook(
    event: LifecycleEvent,
    context: LoopContext,
    extra: Record<string, unknown>
  ): Promise<void> {
    if (!this.deps.constraintsService) return;

    try {
      const hookContext: HookContext = {
        event,
        loopState: this.state,
        budgetState: context.budget,
        metadata: {
          ...context.metadata,
          ...extra,
        },
      };

      const result = await this.deps.constraintsService.executeHooks(
        event,
        hookContext
      );

      if (!result.proceed) {
        Logger.info(
          `🛑 钩子拦截: ${event} - ${result.reason || '未提供原因'}`,
          'LoopController'
        );
      }
    } catch (err) {
      Logger.warn(
        `⚠️ 生命周期钩子执行失败: ${event} - ${(err as Error).message}`,
        'LoopController'
      );
    }
  }

  /**
   * F0-02: 将 Planner 的决策注入共享上下文
   * 确保 Executor 的 LLM 能看到完整的规划推理，而不是只看到步骤列表
   */
  private injectPlanIntoContext(plan: ExecutionPlan, context: LoopContext): void {
    if (plan.simple || plan.steps.length === 0) return;

    const hasExistingPlanMsg = context.messages.some(
      (m) => m.role === 'system' && m.content?.startsWith('【执行计划】')
    );
    if (hasExistingPlanMsg) return;

    const steps = plan.steps
      .map((s, i) => `${i + 1}. ${s.description}${s.toolName ? ` (使用 ${s.toolName})` : ''}`)
      .join('\n');

    const parts: string[] = [];
    parts.push('【执行计划】');

    if (plan.planReasoning) {
      parts.push(`任务分析: ${plan.planReasoning.substring(0, 500)}`);
      parts.push('');
    }

    parts.push(`执行步骤:\n${steps}`);
    parts.push('\n你可以根据实际情况调整执行顺序或跳过不需要的步骤。');

    context.messages.push({
      role: 'system',
      content: parts.join('\n'),
    });

    Logger.debug(
      `📋 计划上下文已注入共享消息 (含推理: ${!!plan.planReasoning})`,
      'LoopController'
    );
  }
}

/**
 * Harness Layer 1: Loop - Planner 节点
 *
 * 分析用户意图，生成执行计划
 * 简单任务跳过规划，复杂任务分解为步骤
 */

import { Logger } from '../../utils/Logger';
import type {
  UserInput,
  LoopContext,
  ExecutionPlan,
  PlanStep,
} from '../types';

/** Planner 依赖 */
export interface PlannerDeps {
  /** LLM 判断是否需要规划 */
  llm: {
    chat(prompt: string, systemPrompt?: string): Promise<string>;
  };
  /** 进化纠错示例提供者（进化闭环：PromptExample 注入规划 prompt） */
  evolutionExamples?: {
    getPromptExamples(): Array<{
      trigger: string;
      correction: string;
      example: string;
      frequency: number;
    }>;
  };
}

/** 简单任务关键词 — 直接执行不需要规划 */
const SIMPLE_TASK_PATTERNS = [
  /^(你好|hi|hello|嗨|早上好|晚上好|下午好)/i,
  /^(谢谢|感谢|thanks)/i,
  /^(再见|拜拜|bye)/i,
  /^(帮我|请|能不能|可以)/,
  /^(什么是|什么是|解释|说明|定义)/,
  /^(读|查看|打开|显示).*(文件|目录|内容)/,
  /^(搜索|查找|找).*(文件|内容|代码)/,
];

/** 复杂任务关键词 — 需要规划 */
const COMPLEX_TASK_PATTERNS = [
  /重构/,
  /迁移/,
  /升级/,
  /改造/,
  /优化.*系统/,
  /设计.*架构/,
  /实现.*功能.*包括/,
  /同时.*修改.*多个/,
  /步骤|流程|方案/,
  /先.*再.*然后/,
  /第一.*第二.*第三/,
];

export class Planner {
  private deps: PlannerDeps;
  private budgetAccuracyHistory: Array<{ estimated: number; actual: number }> = [];
  private replanCount = 0;
  private totalPlans = 0;

  constructor(deps: PlannerDeps) {
    this.deps = deps;
  }

  /**
   * 分析用户输入，生成执行计划
   */
  async plan(input: UserInput, context: LoopContext): Promise<ExecutionPlan> {
    this.totalPlans++;
    const text = input.text.trim();

    // 1. 快速判断：简单任务直接执行
    if (this.isSimpleTask(text)) {
      Logger.info(`📋 简单任务: "${text.substring(0, 50)}"`, 'Planner');
      return {
        steps: [
          {
            id: 'direct-execute',
            description: text,
            retryCount: 0,
            maxRetries: 0,
          },
        ],
        dependencies: new Map(),
        estimatedBudget: {
          maxRounds: 4,
          maxToolCalls: 5,
          maxTokens: 3000,
          maxDurationMs: 30000,
        },
        simple: true,
      };
    }

    // 2. 快速判断：明显复杂任务
    if (this.isComplexTask(text)) {
      Logger.info(`📋 复杂任务: "${text.substring(0, 50)}"`, 'Planner');
      return this.generatePlan(input, context);
    }

    // 3. 中间地带：让 LLM 判断
    try {
      const needsPlan = await this.llmJudgeNeedsPlan(text);
      if (!needsPlan) {
        Logger.info('📋 LLM判断为简单任务', 'Planner');
        return {
          steps: [
            {
              id: 'direct-execute',
              description: text,
              retryCount: 0,
              maxRetries: 0,
            },
          ],
          dependencies: new Map(),
          estimatedBudget: {
            maxRounds: 4,
            maxToolCalls: 5,
            maxTokens: 3000,
            maxDurationMs: 30000,
          },
          simple: true,
        };
      }
    } catch {
      // LLM 不可用时降级为简单任务
      Logger.info('📋 LLM不可用，降级为简单任务', 'Planner');
      return {
        steps: [
          {
            id: 'direct-execute',
            description: text,
            retryCount: 0,
            maxRetries: 0,
          },
        ],
        dependencies: new Map(),
        estimatedBudget: {
          maxRounds: 6,
          maxToolCalls: 8,
          maxTokens: 4000,
          maxDurationMs: 45000,
        },
        simple: true,
      };
    }

    // 4. 生成执行计划
    return this.generatePlan(input, context);
  }

  /**
   * 判断是否为简单任务
   */
  private isSimpleTask(text: string): boolean {
    return SIMPLE_TASK_PATTERNS.some((p) => p.test(text));
  }

  /**
   * 判断是否为复杂任务
   */
  private isComplexTask(text: string): boolean {
    return COMPLEX_TASK_PATTERNS.some((p) => p.test(text));
  }

  /**
   * 让 LLM 判断是否需要规划
   */
  private async llmJudgeNeedsPlan(text: string): Promise<boolean> {
    const prompt = `判断以下用户请求是否需要多步骤规划才能完成。

需要规划的任务特征：
- 需要调用3个以上工具
- 需要修改多个文件
- 需要先分析再执行
- 有明确的先后依赖关系

不需要规划的任务特征：
- 简单问答
- 单文件操作
- 单工具调用
- 日常对话

用户请求: "${text}"

只回答 YES 或 NO`;

    const response = await this.deps.llm.chat(prompt);
    return response.trim().toUpperCase().includes('YES');
  }

  /**
   * 记录预算准确度
   * @param estimated - 预估预算
   * @param actual - 实际使用量
   */
  recordBudgetAccuracy(estimated: number, actual: number): void {
    this.budgetAccuracyHistory.push({ estimated, actual });
  }

  /**
   * 获取调整后的预算乘数
   * 基于历史预算准确度动态调整
   * @returns 预算乘数 (1.0-2.0)
   */
  getAdjustedBudgetMultiplier(): number {
    if (this.budgetAccuracyHistory.length < 3) return 1.5;
    let totalRatio = 0;
    for (const entry of this.budgetAccuracyHistory) {
      totalRatio += entry.estimated > 0 ? entry.actual / entry.estimated : 1;
    }
    const avgRatio = totalRatio / this.budgetAccuracyHistory.length;
    return Math.max(1.0, Math.min(2.0, avgRatio));
  }

  /**
   * 获取重新规划率
   * @returns 重新规划率 (0-1)
   */
  getReplanRate(): number {
    if (this.totalPlans === 0) return 0;
    return this.replanCount / this.totalPlans;
  }

  /**
   * 生成执行计划
   */
  private async generatePlan(
    input: UserInput,
    _context: LoopContext
  ): Promise<ExecutionPlan> {
    try {
      let evolutionHint = '';
      if (this.deps.evolutionExamples) {
        const examples = this.deps.evolutionExamples.getPromptExamples();
        if (examples.length > 0) {
          const topExamples = examples
            .sort((a, b) => b.frequency - a.frequency)
            .slice(0, 3);
          evolutionHint = `\n\n【进化纠错提示】以下模式曾导致用户纠正，请避免：\n${
            topExamples.map((e, i) => `${i + 1}. 避免: ${e.trigger} → 正确做法: ${e.correction}`).join('\n')
          }`;
        }
      }

      const prompt = `为以下任务生成执行计划。每个步骤应该是一个独立的操作。

任务: "${input.text}"
${evolutionHint}
请用以下JSON格式输出（不要包含其他内容）:
{
  "steps": [
    {"id": "step1", "description": "步骤描述", "toolName": "工具名(可选)"},
    {"id": "step2", "description": "步骤描述", "toolName": "工具名(可选)"}
  ],
  "dependencies": {"step2": ["step1"]},
  "estimatedRounds": 3
}

注意：
- 步骤数量控制在2-5个
- 只在步骤间有明确依赖时才添加dependencies
- estimatedRounds是预估的工具调用轮次`;

      const response = await this.deps.llm.chat(prompt);
      const jsonMatch = response.match(/\{[\s\S]*\}/);
      if (!jsonMatch) {
        throw new Error('LLM 未返回有效 JSON');
      }

      const parsed = JSON.parse(jsonMatch[0]);
      const steps: PlanStep[] = (parsed.steps || []).map(
        (s: { id?: string; description?: string; toolName?: string }, i: number) => ({
          id: s.id || `step${i + 1}`,
          description: s.description || '',
          toolName: s.toolName,
          retryCount: 0,
          maxRetries: 1,
        })
      );

      const deps: Map<string, string[]> = new Map();
      if (parsed.dependencies) {
        for (const [key, value] of Object.entries(parsed.dependencies)) {
          deps.set(key, value as string[]);
        }
      }

      const multiplier = this.getAdjustedBudgetMultiplier();

      const planReasoning = response.trim();

      return {
        steps,
        dependencies: deps,
        estimatedBudget: {
          maxRounds: Math.ceil((parsed.estimatedRounds || 6) * multiplier),
          maxToolCalls: Math.ceil(steps.length * 3 * multiplier),
          maxTokens: Math.ceil(5000 * multiplier),
          maxDurationMs: Math.ceil(60000 * multiplier),
        },
        fallbackStrategy: 'replan',
        planReasoning,
      };
    } catch (err) {
      Logger.warn(
        `规划生成失败，降级为直接执行: ${(err as Error).message}`,
        'Planner'
      );
      return {
        steps: [
          {
            id: 'direct-execute',
            description: input.text,
            retryCount: 0,
            maxRetries: 0,
          },
        ],
        dependencies: new Map(),
        estimatedBudget: {
          maxRounds: 6,
          maxToolCalls: 8,
          maxTokens: 4000,
          maxDurationMs: 45000,
        },
        simple: true,
      };
    }
  }
}

/**
 * Harness Layer 1: Loop - Reporter 节点
 *
 * 生成最终响应 + 质量评分
 */

import { Logger } from '../../utils/Logger';
import type { LoopContext, QualityScore } from '../types';
import type { ReporterOutput } from './LoopController';

export class Reporter {
  /**
   * 生成最终响应和质量评分
   */
  async report(context: LoopContext): Promise<ReporterOutput> {
    // 查找最后一条 assistant 消息作为响应
    const response = this.extractResponse(context.messages);
    const quality = this.computeQuality(context);

    Logger.info(
      `📊 质量评分: ${quality.overall.toFixed(2)} (准确=${quality.accuracy.toFixed(2)} 有用=${quality.usefulness.toFixed(2)} 效率=${quality.efficiency.toFixed(2)})`,
      'Reporter'
    );

    return { response, quality };
  }

  /**
   * 从消息中提取最终响应
   */
  private extractResponse(messages: Array<{ role: string; content?: string | null }>): string {
    // 从后往前找最后一条 assistant 消息
    for (let i = messages.length - 1; i >= 0; i--) {
      if (messages[i].role === 'assistant' && messages[i].content) {
        return messages[i].content!;
      }
    }

    // 降级：返回最后一条非 system 消息
    for (let i = messages.length - 1; i >= 0; i--) {
      if (messages[i].role !== 'system' && messages[i].content) {
        return messages[i].content!;
      }
    }

    return '抱歉，我无法处理您的请求。';
  }

  /**
   * 计算质量评分
   */
  private computeQuality(context: LoopContext): QualityScore {
    const budget = context.budget;
    const trace = context.trace;

    // 基础分
    let overall = 1.0;
    let efficiency = 1.0;

    // 惩罚过多轮次
    if (budget.roundsUsed > 3) {
      const penalty = 0.1 * (budget.roundsUsed - 3);
      overall -= penalty;
      efficiency -= penalty;
    }

    // 惩罚过多工具调用
    if (budget.toolCallsUsed > 5) {
      const penalty = 0.05 * (budget.toolCallsUsed - 5);
      efficiency -= penalty;
    }

    // 惩罚总时长
    const duration = Date.now() - budget.startTime;
    if (duration > 15000) efficiency -= 0.1;
    if (duration > 30000) efficiency -= 0.2;

    // 自然完成加分
    const completedNaturally = trace.state !== 'budget_exceeded' && trace.state !== 'failed';
    if (!completedNaturally) {
      overall -= 0.3;
    }

    // 限制范围
    overall = Math.max(0.1, Math.min(1.0, overall));
    efficiency = Math.max(0.1, Math.min(1.0, efficiency));

    return {
      overall,
      accuracy: Math.max(0.1, overall * 0.9),
      usefulness: Math.max(0.1, overall * 0.95),
      friendliness: Math.max(0.1, Math.min(1.0, 0.8)),
      efficiency,
      details: `轮次=${budget.roundsUsed} 工具=${budget.toolCallsUsed} 时长=${duration}ms 自然完成=${completedNaturally}`,
    };
  }
}

/**
 * Harness Phase 10: 多Agent编排 — Agent注册与发现服务
 *
 * 管理多Agent的注册、发现、状态跟踪。
 * 支持按能力查找可用Agent，提供运行时状态监控。
 * P10增强：健康检查、能力评分排序、心跳检测
 */

import { Logger } from '../../utils/Logger';

/** Agent能力声明 */
export interface AgentCapability {
  /** 能力名称 */
  name: string;
  /** 能力描述 */
  description: string;
  /** 该能力所需的工具列表 */
  tools: string[];
  /** 最大并发数（可选，默认1） */
  maxConcurrency?: number;
  /** 能力评分 0-100（可选，默认50） */
  score?: number;
}

/** Agent注册信息 */
export interface AgentRegistration {
  /** 唯一标识 */
  id: string;
  /** 显示名称 */
  name: string;
  /** 能力列表 */
  capabilities: AgentCapability[];
  /** 当前状态 */
  status: 'idle' | 'busy' | 'error';
  /** 创建时间 */
  createdAt: Date;
  /** 最后活跃时间 */
  lastActiveAt: Date;
}

/** Agent健康状态 */
export interface AgentHealth {
  /** 最后心跳时间 */
  lastHeartbeat: number;
  /** 成功率 0-1 */
  successRate: number;
  /** 平均响应时间 (ms) */
  avgResponseTime: number;
  /** 错误次数 */
  errorCount: number;
  /** 总执行次数 */
  totalExecutions: number;
}

const DEFAULT_HEALTH: AgentHealth = {
  lastHeartbeat: Date.now(),
  successRate: 1.0,
  avgResponseTime: 0,
  errorCount: 0,
  totalExecutions: 0,
};

export class AgentRegistry {
  private agents: Map<string, AgentRegistration> = new Map();
  private healthMap: Map<string, AgentHealth> = new Map();

  /**
   * 注册Agent
   * @param registration - Agent注册信息
   * @throws 如果agentId已存在则跳过（日志警告）
   */
  register(registration: AgentRegistration): void {
    if (this.agents.has(registration.id)) {
      Logger.warn(
        `Agent 已存在，跳过重复注册: ${registration.id} (${registration.name})`,
        'AgentRegistry'
      );
      return;
    }

    this.agents.set(registration.id, {
      ...registration,
      createdAt: registration.createdAt || new Date(),
      lastActiveAt: registration.lastActiveAt || new Date(),
    });

    this.healthMap.set(registration.id, { ...DEFAULT_HEALTH });

    Logger.info(
      `🤖 注册 Agent: ${registration.name} (${registration.id}) | 能力: ${registration.capabilities.map(c => c.name).join(', ') || '(无)'}`,
      'AgentRegistry'
    );
  }

  /**
   * 注销Agent
   * @param agentId - Agent唯一标识
   */
  unregister(agentId: string): void {
    const agent = this.agents.get(agentId);
    if (!agent) {
      Logger.warn(`Agent 不存在，无法注销: ${agentId}`, 'AgentRegistry');
      return;
    }

    this.agents.delete(agentId);
    this.healthMap.delete(agentId);
    Logger.info(`👋 注销 Agent: ${agent.name} (${agentId})`, 'AgentRegistry');
  }

  /**
   * 按工具能力查找合适的Agent（寻找空闲的、具备该工具的Agent）
   * @param toolName - 工具名称
   * @returns 第一个匹配的空闲Agent，或null
   */
  findAgentByCapability(toolName: string): AgentRegistration | null {
    for (const agent of this.agents.values()) {
      if (agent.status !== 'idle') continue;

      const hasCapability = agent.capabilities.some(cap =>
        cap.tools.includes(toolName)
      );
      if (hasCapability) {
        return agent;
      }
    }

    Logger.debug(`未找到具备工具能力的空闲 Agent: ${toolName}`, 'AgentRegistry');
    return null;
  }

  /**
   * 按能力评分 + 健康状态查找最佳Agent
   * P10增强：综合考虑能力评分、健康状态、成功率排序
   * @param toolName - 工具名称
   * @returns 最佳匹配的空闲Agent，或null
   */
  findBestAgent(toolName: string): AgentRegistration | null {
    const candidates: Array<{ agent: AgentRegistration; score: number }> = [];

    for (const agent of this.agents.values()) {
      if (agent.status !== 'idle') continue;

      const matchingCap = agent.capabilities.find(cap =>
        cap.tools.includes(toolName)
      );
      if (!matchingCap) continue;

      const health = this.healthMap.get(agent.id) || DEFAULT_HEALTH;
      const capabilityScore = matchingCap.score ?? 50;
      const healthBonus = health.successRate * 25;
      const latencyPenalty = Math.min(health.avgResponseTime / 1000, 10);
      const errorPenalty = Math.min(health.errorCount * 2, 20);

      const compositeScore = capabilityScore + healthBonus - latencyPenalty - errorPenalty;

      candidates.push({ agent, score: compositeScore });
    }

    if (candidates.length === 0) {
      Logger.debug(`未找到具备工具能力的空闲 Agent: ${toolName}`, 'AgentRegistry');
      return null;
    }

    candidates.sort((a, b) => b.score - a.score);
    return candidates[0].agent;
  }

  /**
   * 更新Agent健康状态
   * @param agentId - Agent唯一标识
   * @param healthUpdate - 健康状态更新（部分字段）
   */
  updateHealth(agentId: string, healthUpdate: Partial<AgentHealth>): void {
    const current = this.healthMap.get(agentId) || { ...DEFAULT_HEALTH };
    this.healthMap.set(agentId, { ...current, ...healthUpdate, lastHeartbeat: Date.now() });
  }

  /**
   * 记录Agent执行结果（自动更新健康指标）
   * @param agentId - Agent唯一标识
   * @param success - 是否成功
   * @param durationMs - 执行耗时
   */
  recordExecution(agentId: string, success: boolean, durationMs: number): void {
    const health = this.healthMap.get(agentId);
    if (!health) return;

    health.totalExecutions++;
    health.lastHeartbeat = Date.now();

    if (success) {
      const prevAvg = health.avgResponseTime;
      health.avgResponseTime = (prevAvg * (health.totalExecutions - 1) + durationMs) / health.totalExecutions;
      health.successRate = (health.successRate * (health.totalExecutions - 1) + 1) / health.totalExecutions;
    } else {
      health.errorCount++;
      health.successRate = (health.successRate * (health.totalExecutions - 1)) / health.totalExecutions;
    }

    const agent = this.agents.get(agentId);
    if (agent) {
      agent.lastActiveAt = new Date();
    }
  }

  /**
   * 获取Agent健康状态
   * @param agentId - Agent唯一标识
   * @returns 健康状态，或null
   */
  getHealthStatus(agentId: string): AgentHealth | null {
    return this.healthMap.get(agentId) || null;
  }

  /**
   * 清理超时无心跳的Agent（标记为error状态）
   * @param timeoutMs - 超时阈值（默认60秒）
   * @returns 被标记为error的Agent数量
   */
  cleanupStaleAgents(timeoutMs: number = 60000): number {
    const now = Date.now();
    let cleaned = 0;

    for (const [agentId, health] of this.healthMap) {
      if (now - health.lastHeartbeat > timeoutMs) {
        const agent = this.agents.get(agentId);
        if (agent && agent.status !== 'error') {
          agent.status = 'error';
          Logger.warn(
            `💀 Agent 心跳超时，标记为 error: ${agent.name} (${agentId})`,
            'AgentRegistry'
          );
          cleaned++;
        }
      }
    }

    return cleaned;
  }

  /**
   * 获取Agent信息
   * @param agentId - Agent唯一标识
   * @returns Agent注册信息，或undefined
   */
  getAgent(id: string): AgentRegistration | undefined {
    return this.agents.get(id);
  }

  /**
   * 列出所有Agent（可按状态过滤）
   * @param status - 可选的状态过滤器
   * @returns Agent注册信息列表
   */
  listAgents(status?: AgentRegistration['status']): AgentRegistration[] {
    const all = Array.from(this.agents.values());
    if (status === undefined) return all;
    return all.filter(a => a.status === status);
  }

  /**
   * 更新Agent状态
   * @param agentId - Agent唯一标识
   * @param status - 新状态
   * @throws 如果Agent不存在则日志警告
   */
  updateStatus(agentId: string, status: AgentRegistration['status']): void {
    const agent = this.agents.get(agentId);
    if (!agent) {
      Logger.warn(`Agent 不存在，无法更新状态: ${agentId}`, 'AgentRegistry');
      return;
    }

    agent.status = status;
    agent.lastActiveAt = new Date();

    if (this.healthMap.has(agentId)) {
      this.healthMap.get(agentId)!.lastHeartbeat = Date.now();
    }

    Logger.debug(`Agent 状态更新: ${agentId} → ${status}`, 'AgentRegistry');
  }

  /**
   * 获取当前注册的Agent数量
   */
  get size(): number {
    return this.agents.size;
  }

  /**
   * 获取空闲Agent列表
   */
  getIdleAgents(): AgentRegistration[] {
    return this.listAgents('idle');
  }

  /**
   * 获取忙碌Agent列表
   */
  getBusyAgents(): AgentRegistration[] {
    return this.listAgents('busy');
  }

  /**
   * 获取异常Agent列表
   */
  getErrorAgents(): AgentRegistration[] {
    return this.listAgents('error');
  }
}

/**
 * Harness Phase 10: 多Agent编排 — 顶层协调Agent
 *
 * OrchestratorAgent 是用户目标和多Agent编排之间的桥梁：
 * 1. 接收用户目标
 * 2. 分析复杂度 → 简单任务直通 / 复杂任务拆解
 * 3. 调用 LLM 将目标拆解为 DAG TaskNode[]
 * 4. 通过 SubAgentFanout 扇出执行
 * 5. 通过 ResultAggregator 聚合结果
 * 6. 返回最终聚合报告
 *
 * P10增强：复杂度分析集成、Sub-Agent扇出、降级处理
 */

import { Logger } from '../../utils/Logger';
import { TaskDispatcher, type TaskNode, type TaskExecutor } from './TaskDispatcher';
import { ResultAggregator, type AggregatedResult } from './ResultAggregator';
import { AgentRegistry } from './AgentRegistry';
import { SubAgentFanout, type FanoutConfig } from './SubAgentFanout';
import { QualityScorer, ScorerMetadata } from '../evaluation/QualityScorer';
import { StepEvaluator } from '../evaluation/StepEvaluator';
import { EvolutionOrchestrator } from '../../evolution/EvolutionOrchestrator';
import { TaskComplexityAnalyzer } from '../../core/TaskComplexityAnalyzer';

/** LLM 接口（遵循现有系统风格） */
export interface OrchestratorLLM {
  /**
   * 将用户目标拆解为DAG任务列表
   * @param userGoal - 用户目标
   * @param context - 上下文
   * @returns 解析后的任务节点数组
   */
  decomposeGoal(
    userGoal: string,
    context?: string
  ): Promise<TaskNode[]>;
}

/** OrchestratorAgent 配置 */
export interface OrchestratorConfig {
  /** 是否启用多Agent编排，默认 true */
  enableMultiAgent: boolean;
  /** 触发多Agent的复杂度阈值，默认 'complex' */
  complexityThreshold: 'simple' | 'medium' | 'complex' | 'very_complex';
  /** 最大子Agent数，默认 5 */
  maxSubAgents: number;
  /** 扇出配置 */
  fanoutConfig?: Partial<FanoutConfig>;
}

const DEFAULT_ORCHESTRATOR_CONFIG: OrchestratorConfig = {
  enableMultiAgent: true,
  complexityThreshold: 'complex',
  maxSubAgents: 5,
};

/** OrchestratorAgent 依赖 */
export interface OrchestratorAgentDeps {
  /** Agent注册中心 */
  registry: AgentRegistry;
  /** LLM 接口 */
  llm: OrchestratorLLM;
  /** 任务执行器（可选，用于实际执行任务） */
  executor?: TaskExecutor;
  /** 配置（可选） */
  config?: Partial<OrchestratorConfig>;
}

const COMPLEXITY_ORDER: Record<string, number> = {
  simple: 0,
  medium: 1,
  complex: 2,
  very_complex: 3,
};

export class OrchestratorAgent {
  private dispatcher: TaskDispatcher;
  private aggregator: ResultAggregator;
  private fanout: SubAgentFanout;
  private llm: OrchestratorLLM;
  private qualityScorer: QualityScorer;
  private stepEvaluator: StepEvaluator;
  private complexityAnalyzer: TaskComplexityAnalyzer;
  private config: OrchestratorConfig;

  constructor(deps: OrchestratorAgentDeps) {
    this.config = { ...DEFAULT_ORCHESTRATOR_CONFIG, ...deps.config };
    this.dispatcher = new TaskDispatcher(deps.registry, deps.executor);
    this.aggregator = new ResultAggregator();
    this.fanout = new SubAgentFanout(
      deps.registry,
      deps.executor,
      this.config.fanoutConfig
    );
    this.llm = deps.llm;
    this.qualityScorer = new QualityScorer();
    this.stepEvaluator = new StepEvaluator();
    this.complexityAnalyzer = new TaskComplexityAnalyzer();
  }

  /**
   * 处理用户目标 — 复杂度分析 → 拆解 → 扇出 → 聚合
   *
   * P10增强：
   * - 简单任务直通单Agent路径
   * - 复杂任务走多Agent编排路径
   * - LLM不可用时降级到TaskComplexityAnalyzer拆解
   */
  async processGoal(
    userGoal: string,
    context?: string
  ): Promise<AggregatedResult> {
    const startTime = Date.now();
    Logger.info(
      `🎯 OrchestratorAgent 处理目标: ${userGoal.substring(0, 80)}`,
      'OrchestratorAgent'
    );

    try {
      // Step 0: 复杂度分析
      const complexityResult = this.complexityAnalyzer.analyzeComplexity(userGoal);
      Logger.info(
        `📊 复杂度分析: ${complexityResult.complexity} | 预估步骤=${complexityResult.estimatedSteps} | 可并行=${complexityResult.parallelizable}`,
        'OrchestratorAgent'
      );

      // 简单任务直通
      if (!this.config.enableMultiAgent || !this.shouldUseMultiAgent(complexityResult.complexity)) {
        Logger.info('⚡ 简单任务，走单Agent直通路径', 'OrchestratorAgent');
        return this.processSimpleGoal(userGoal, context, startTime);
      }

      // Step 1: 调用LLM拆解目标为DAG任务
      Logger.info('🧠 正在拆解用户目标...', 'OrchestratorAgent');
      let tasks: TaskNode[];

      try {
        tasks = await this.llm.decomposeGoal(userGoal, context);
      } catch (llmError) {
        Logger.warn(
          `⚠️ LLM拆解失败，降级到TaskComplexityAnalyzer: ${(llmError as Error).message}`,
          'OrchestratorAgent'
        );
        tasks = this.decomposeWithAnalyzer(userGoal);
      }

      if (!tasks || tasks.length === 0) {
        return {
          success: false,
          summary: '❌ 目标拆解失败: 未生成任何任务',
          details: new Map(),
          totalTasks: 0,
          completedTasks: 0,
          failedTasks: 0,
          duration: Date.now() - startTime,
        };
      }

      Logger.info(
        `📋 目标拆解完成: ${tasks.length} 个任务`,
        'OrchestratorAgent'
      );

      // Step 2: 判断是否需要扇出执行
      if (tasks.length > 1 && complexityResult.parallelizable) {
        Logger.info(`🔀 使用 Sub-Agent 扇出执行 (${tasks.length} 个子任务)`, 'OrchestratorAgent');
        const fanoutResult = await this.fanout.fanout(
          `parent_${Date.now()}`,
          tasks,
          { maxFanout: this.config.maxSubAgents }
        );

        const results = new Map<string, unknown>();
        for (const sub of fanoutResult.subResults) {
          results.set(sub.taskId, sub.success ? sub.result : { error: sub.error });
        }

        const aggregated = this.aggregator.aggregate(results, tasks);
        const finalResult: AggregatedResult = {
          ...aggregated,
          duration: Date.now() - startTime,
          summary: fanoutResult.allSucceeded
            ? `✅ 目标完成(扇出): ${userGoal.substring(0, 60)}`
            : `⚠️ 目标部分完成(扇出): ${userGoal.substring(0, 60)} (${fanoutResult.failedCount} 个子任务失败)`,
        };

        const qualityScore = this.evaluateExecution(tasks, finalResult, userGoal, finalResult.duration);
        finalResult.qualityScore = qualityScore;
        this.recordToEvolution(userGoal, finalResult, finalResult.duration);

        return finalResult;
      }

      // Step 3: DAG分发执行（有依赖关系的任务）
      Logger.info('🚀 使用 DAG 分发执行...', 'OrchestratorAgent');
      const results = await this.dispatcher.dispatch(tasks);

      // Step 4: 聚合结果
      Logger.info('📊 聚合执行结果...', 'OrchestratorAgent');
      const aggregated = this.aggregator.aggregate(results, tasks);

      const actualDuration = Date.now() - startTime;
      const finalResult: AggregatedResult = {
        ...aggregated,
        duration: actualDuration,
        summary: aggregated.success
          ? `✅ 目标完成: ${userGoal.substring(0, 60)}`
          : `⚠️ 目标部分完成: ${userGoal.substring(0, 60)}`,
      };

      const qualityScore = this.evaluateExecution(tasks, finalResult, userGoal, actualDuration);
      finalResult.qualityScore = qualityScore;

      this.recordToEvolution(userGoal, finalResult, actualDuration);

      Logger.info(
        `🏁 OrchestratorAgent 完成 | 耗时=${actualDuration}ms | 成功=${finalResult.completedTasks}/${finalResult.totalTasks} | 质量=${qualityScore.overall}`,
        'OrchestratorAgent'
      );

      return finalResult;
    } catch (err) {
      const errorMsg = (err as Error).message || String(err);
      Logger.error(
        'OrchestratorAgent 处理失败',
        err as Error,
        'OrchestratorAgent'
      );

      return {
        success: false,
        summary: `❌ OrchestratorAgent 处理失败: ${errorMsg}`,
        details: new Map(),
        totalTasks: 0,
        completedTasks: 0,
        failedTasks: 0,
        duration: Date.now() - startTime,
      };
    }
  }

  /**
   * 简单任务直通处理
   */
  private async processSimpleGoal(
    userGoal: string,
    context: string | undefined,
    startTime: number
  ): Promise<AggregatedResult> {
    const singleTask: TaskNode = {
      id: `simple_${Date.now()}`,
      goal: userGoal,
      context: context || '',
      dependencies: [],
      priority: 5,
      status: 'pending',
    };

    const results = await this.dispatcher.dispatch([singleTask]);
    const aggregated = this.aggregator.aggregate(results, [singleTask]);

    const duration = Date.now() - startTime;
    return {
      ...aggregated,
      duration,
      summary: aggregated.success
        ? `✅ 任务完成: ${userGoal.substring(0, 60)}`
        : `❌ 任务失败: ${userGoal.substring(0, 60)}`,
    };
  }

  /**
   * 使用TaskComplexityAnalyzer降级拆解
   */
  private decomposeWithAnalyzer(userGoal: string): TaskNode[] {
    const decomposition = this.complexityAnalyzer.decomposeTask(userGoal);
    return decomposition.subTasks.map((sub, index) => ({
      id: sub.id,
      goal: sub.description,
      context: `子任务 ${index + 1}/${decomposition.subTasks.length}`,
      dependencies: sub.dependencies,
      priority: sub.complexity === 'very_complex' ? 8 : sub.complexity === 'complex' ? 6 : 4,
      tools: sub.tools,
      status: 'pending' as const,
    }));
  }

  /**
   * 判断是否需要多Agent编排
   */
  private shouldUseMultiAgent(complexity: string): boolean {
    const threshold = COMPLEXITY_ORDER[this.config.complexityThreshold] ?? 2;
    const current = COMPLEXITY_ORDER[complexity] ?? 0;
    return current >= threshold;
  }

  /**
   * 获取底层的 TaskDispatcher
   */
  getDispatcher(): TaskDispatcher {
    return this.dispatcher;
  }

  /**
   * 获取底层的 ResultAggregator
   */
  getAggregator(): ResultAggregator {
    return this.aggregator;
  }

  /**
   * 获取 SubAgentFanout
   */
  getFanout(): SubAgentFanout {
    return this.fanout;
  }

  /**
   * 自动评估执行结果 — 五维质量评分
   */
  private evaluateExecution(
    tasks: TaskNode[],
    result: AggregatedResult,
    userGoal: string,
    duration: number
  ): import('../evaluation/QualityScorer').QualityScore {
    const stepParams = tasks.map((task) => ({
      stepId: task.id,
      toolName: task.assignedTo || 'unknown',
      args: { goal: task.goal, context: task.context },
      result: {
        success: task.status === 'completed',
        output: task.result,
        error: task.error,
      },
      timestamp: Date.now(),
    }));

    const stepResults = stepParams.map((p) => this.stepEvaluator.evaluateStep(p));

    const scorerMetadata: ScorerMetadata = {
      duration,
      retries: 0,
      errors: result.failedTasks,
      context: userGoal,
      totalToolCalls: tasks.length,
      successfulToolCalls: result.completedTasks,
      loopRounds: 1,
      outputLength: result.summary?.length || 0,
    };

    const qualityScore = this.qualityScorer.score(stepResults, scorerMetadata);

    Logger.info(
      `📊 自动评估完成 | 综合=${qualityScore.overall} | 准确=${qualityScore.dimensions.accuracy} 效率=${qualityScore.dimensions.efficiency} 安全=${qualityScore.dimensions.safety} 人设=${qualityScore.dimensions.persona} 稳定=${qualityScore.dimensions.stability}`,
      'OrchestratorAgent'
    );

    return qualityScore;
  }

  /**
   * 记录执行结果到进化编排器
   */
  private recordToEvolution(
    userGoal: string,
    result: AggregatedResult,
    duration: number
  ): void {
    try {
      const orchestrator = EvolutionOrchestrator.getInstance();
      const qualityScore = result.qualityScore?.overall || 0;

      orchestrator.recordInteraction({
        traceId: `orch_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
        input: userGoal,
        response: result.summary || '',
        success: result.success && result.failedTasks === 0,
        qualityScore: qualityScore / 100,
        executionDuration: duration,
        toolCalls: Array.from(result.details.entries()).map(([taskId, detail]) => {
            const d = detail as unknown as Record<string, unknown>;
            return {
              toolName: (d.agentId as string) || taskId,
              success: d.success !== false,
              executionTime: 0,
            };
          }),
        scene: 'orchestration',
      });

      Logger.debug('已记录编排执行结果到进化编排器', 'OrchestratorAgent');
    } catch (error) {
      Logger.debug(
        `记录到进化编排器失败（非关键）: ${(error as Error).message}`,
        'OrchestratorAgent'
      );
    }
  }
}

/**
 * Harness Phase 10: 多Agent编排 — 结果聚合器
 *
 * 合并多个Agent的执行结果，生成结构化摘要报告。
 * 提供成功/失败统计、执行时长、详细追踪等维度。
 * P10增强：LLM摘要生成、冲突检测
 */

import { Logger } from '../../utils/Logger';
import type { TaskNode } from './TaskDispatcher';

/** 单个任务详情 */
export interface TaskDetail {
  /** 任务ID */
  taskId: string;
  /** 完成状态 */
  status: 'completed' | 'failed';
  /** 执行结果 */
  result?: unknown;
  /** 错误信息 */
  error?: string;
}

/** 结果冲突 */
export interface ResultConflict {
  /** 冲突类型 */
  type: 'file_write' | 'data_inconsistency' | 'resource_contention';
  /** 冲突描述 */
  description: string;
  /** 涉及的任务ID */
  involvedTasks: string[];
  /** 严重程度 */
  severity: 'low' | 'medium' | 'high';
}

/** 聚合结果 */
export interface AggregatedResult {
  /** 整体是否成功（全部任务成功） */
  success: boolean;
  /** 摘要文本 */
  summary: string;
  /** 详细结果映射 (taskId → TaskDetail) */
  details: Map<string, TaskDetail>;
  /** 总任务数 */
  totalTasks: number;
  /** 成功任务数 */
  completedTasks: number;
  /** 失败任务数 */
  failedTasks: number;
  /** 执行总时长 (ms) */
  duration: number;
  /** 五维质量评分（自动评估生成） */
  qualityScore?: import('../evaluation/QualityScorer').QualityScore;
  /** P10: 检测到的冲突 */
  conflicts?: ResultConflict[];
  /** P10: LLM生成的自然语言摘要 */
  llmSummary?: string;
}

export class ResultAggregator {
  private llm?: { chat(prompt: string, systemPrompt?: string): Promise<string> };

  constructor(llm?: { chat(prompt: string, systemPrompt?: string): Promise<string> }) {
    this.llm = llm;
  }

  /**
   * 聚合所有Agent的执行结果
   */
  aggregate(
    agentResults: Map<string, unknown>,
    taskNodes: TaskNode[]
  ): AggregatedResult {
    const startTime = Date.now();
    const details = new Map<string, TaskDetail>();

    let completedCount = 0;
    let failedCount = 0;
    const failedTasks: string[] = [];

    const taskMap = new Map<string, TaskNode>();
    for (const task of taskNodes) {
      taskMap.set(task.id, task);
    }

    for (const task of taskNodes) {
      const detail: TaskDetail = {
        taskId: task.id,
        status: 'failed',
      };

      if (task.status === 'completed' && agentResults.has(task.id)) {
        detail.status = 'completed';
        detail.result = agentResults.get(task.id);
        completedCount++;
      } else if (task.status === 'failed') {
        detail.status = 'failed';
        detail.error = task.error || '未知错误';
        failedCount++;
        failedTasks.push(task.id);
      } else {
        detail.status = 'failed';
        detail.error = `任务未完成 (状态: ${task.status})`;
        failedCount++;
        failedTasks.push(task.id);
      }

      details.set(task.id, detail);
    }

    const success = failedCount === 0;
    const duration = Date.now() - startTime;

    const conflicts = this.detectConflicts(agentResults, taskNodes);

    const summary = this.buildSummary(
      success,
      taskNodes.length,
      completedCount,
      failedCount,
      failedTasks,
      duration
    );

    Logger.info(
      `📊 结果聚合: ${completedCount}/${taskNodes.length} 成功 | 耗时 ${duration}ms | 冲突 ${conflicts.length}`,
      'ResultAggregator'
    );

    return {
      success,
      summary,
      details,
      totalTasks: taskNodes.length,
      completedTasks: completedCount,
      failedTasks: failedCount,
      duration,
      conflicts,
    };
  }

  /**
   * 聚合并生成LLM自然语言摘要
   */
  async aggregateWithSummary(
    agentResults: Map<string, unknown>,
    taskNodes: TaskNode[]
  ): Promise<AggregatedResult> {
    const result = this.aggregate(agentResults, taskNodes);

    if (this.llm && result.totalTasks > 0) {
      try {
        const taskSummaries = taskNodes
          .map(t => `- ${t.id}: ${t.status} | 目标: ${t.goal.substring(0, 80)}`)
          .join('\n');

        const prompt = `请用简洁的中文总结以下多Agent编排执行结果：

总任务数: ${result.totalTasks}
成功: ${result.completedTasks}
失败: ${result.failedTasks}
冲突: ${result.conflicts?.length || 0}

任务详情:
${taskSummaries}

请生成一段100字以内的执行摘要。`;

        result.llmSummary = await this.llm.chat(prompt);
      } catch (err) {
        Logger.debug(`LLM摘要生成失败: ${(err as Error).message}`, 'ResultAggregator');
      }
    }

    return result;
  }

  /**
   * 检测不同Agent结果之间的冲突
   */
  detectConflicts(
    agentResults: Map<string, unknown>,
    taskNodes: TaskNode[]
  ): ResultConflict[] {
    const conflicts: ResultConflict[] = [];

    const fileWriteMap = new Map<string, string[]>();
    for (const task of taskNodes) {
      if (task.status !== 'completed') continue;
      const result = agentResults.get(task.id);
      if (!result || typeof result !== 'object') continue;

      const resultObj = result as Record<string, unknown>;
      const filePath = resultObj.filePath || resultObj.path || resultObj.file_path;
      if (typeof filePath === 'string') {
        if (!fileWriteMap.has(filePath)) {
          fileWriteMap.set(filePath, []);
        }
        fileWriteMap.get(filePath)!.push(task.id);
      }
    }

    for (const [filePath, taskIds] of fileWriteMap) {
      if (taskIds.length > 1) {
        conflicts.push({
          type: 'file_write',
          description: `多个Agent写入同一文件: ${filePath}`,
          involvedTasks: taskIds,
          severity: 'high',
        });
      }
    }

    return conflicts;
  }

  /**
   * 构建可读的摘要文本
   */
  private buildSummary(
    success: boolean,
    total: number,
    completed: number,
    failed: number,
    failedTaskIds: string[],
    duration: number
  ): string {
    const lines: string[] = [];
    const statusEmoji = success ? '✅' : '⚠️';
    const statusText = success ? '全部任务执行成功' : '部分任务执行失败';

    lines.push(`${statusEmoji} 多Agent编排: ${statusText}`);
    lines.push(`   总任务数: ${total}`);
    lines.push(`   成功: ${completed}`);
    lines.push(`   失败: ${failed}`);
    lines.push(`   总耗时: ${duration}ms`);

    if (!success && failedTaskIds.length > 0) {
      lines.push(`   失败任务: ${failedTaskIds.join(', ')}`);
    }

    return lines.join('\n');
  }

  /**
   * 快速检查结果是否全部成功
   */
  static isAllSuccessful(result: AggregatedResult): boolean {
    return result.success;
  }

  /**
   * 提取所有失败任务的详细信息
   */
  static getFailedDetails(result: AggregatedResult): TaskDetail[] {
    const failed: TaskDetail[] = [];
    for (const detail of result.details.values()) {
      if (detail.status === 'failed') {
        failed.push(detail);
      }
    }
    return failed;
  }
}

/**
 * Harness Phase 10: 多Agent编排 — Sub-Agent 扇出机制
 *
 * 管理子 Agent 的扇出执行：
 * - parallel: 所有子任务并行执行（无依赖时）
 * - sequential: 顺序执行（有依赖时）
 * - adaptive: 根据 TaskComplexityAnalyzer 自动选择
 *
 * 每个 Sub-Agent 拥有独立的上下文窗口，确保上下文隔离。
 */

import { Logger } from '../../utils/Logger';
import type { TaskNode, TaskExecutor } from './TaskDispatcher';
import { AgentRegistry } from './AgentRegistry';

/** 扇出策略 */
export type FanoutStrategy = 'parallel' | 'sequential' | 'adaptive';

/** 扇出配置 */
export interface FanoutConfig {
  /** 最大扇出数，默认5 */
  maxFanout: number;
  /** 执行策略，默认 adaptive */
  strategy: FanoutStrategy;
  /** 单个子任务超时 (ms)，默认30000 */
  taskTimeoutMs: number;
  /** 部分失败时是否继续，默认 true */
  continueOnPartialFailure: boolean;
}

const DEFAULT_FANOUT_CONFIG: FanoutConfig = {
  maxFanout: 5,
  strategy: 'adaptive',
  taskTimeoutMs: 30000,
  continueOnPartialFailure: true,
};

/** 子任务执行结果 */
export interface SubTaskResult {
  /** 子任务ID */
  taskId: string;
  /** 是否成功 */
  success: boolean;
  /** 执行结果 */
  result?: unknown;
  /** 错误信息 */
  error?: string;
  /** 执行耗时 (ms) */
  duration: number;
  /** 执行Agent ID */
  agentId?: string;
}

/** 扇出执行结果 */
export interface FanoutResult {
  /** 父任务ID */
  parentTaskId: string;
  /** 使用的策略 */
  strategy: FanoutStrategy;
  /** 所有子任务结果 */
  subResults: SubTaskResult[];
  /** 成功数 */
  successCount: number;
  /** 失败数 */
  failedCount: number;
  /** 总耗时 (ms) */
  totalDuration: number;
  /** 是否全部成功 */
  allSucceeded: boolean;
}

export class SubAgentFanout {
  private registry: AgentRegistry;
  private executor: TaskExecutor | null;
  private config: FanoutConfig;

  constructor(
    registry: AgentRegistry,
    executor?: TaskExecutor,
    config?: Partial<FanoutConfig>
  ) {
    this.registry = registry;
    this.executor = executor || null;
    this.config = { ...DEFAULT_FANOUT_CONFIG, ...config };
  }

  /**
   * 扇出执行子任务
   * @param parentTaskId - 父任务ID
   * @param subTasks - 子任务节点列表
   * @param configOverride - 可选的配置覆盖
   * @returns 扇出执行结果
   */
  async fanout(
    parentTaskId: string,
    subTasks: TaskNode[],
    configOverride?: Partial<FanoutConfig>
  ): Promise<FanoutResult> {
    const runConfig = { ...this.config, ...configOverride };
    const startTime = Date.now();

    const limitedTasks = subTasks.slice(0, runConfig.maxFanout);
    if (subTasks.length > runConfig.maxFanout) {
      Logger.warn(
        `⚠️ 子任务数 ${subTasks.length} 超过扇出限制 ${runConfig.maxFanout}，截断执行`,
        'SubAgentFanout'
      );
    }

    const strategy = this.resolveStrategy(limitedTasks, runConfig.strategy);
    Logger.info(
      `🔀 Sub-Agent 扇出: ${parentTaskId} | 策略=${strategy} | 子任务=${limitedTasks.length}`,
      'SubAgentFanout'
    );

    let subResults: SubTaskResult[];

    switch (strategy) {
      case 'parallel':
        subResults = await this.executeParallel(parentTaskId, limitedTasks, runConfig);
        break;
      case 'sequential':
        subResults = await this.executeSequential(parentTaskId, limitedTasks, runConfig);
        break;
      case 'adaptive':
      default:
        if (this.hasDependencies(limitedTasks)) {
          subResults = await this.executeSequential(parentTaskId, limitedTasks, runConfig);
        } else {
          subResults = await this.executeParallel(parentTaskId, limitedTasks, runConfig);
        }
        break;
    }

    const totalDuration = Date.now() - startTime;
    const successCount = subResults.filter(r => r.success).length;
    const failedCount = subResults.filter(r => !r.success).length;

    Logger.info(
      `🏁 Sub-Agent 扇出完成: ${parentTaskId} | 成功=${successCount} 失败=${failedCount} | 耗时=${totalDuration}ms`,
      'SubAgentFanout'
    );

    return {
      parentTaskId,
      strategy,
      subResults,
      successCount,
      failedCount,
      totalDuration,
      allSucceeded: failedCount === 0,
    };
  }

  /**
   * 并行执行所有子任务
   */
  private async executeParallel(
    parentTaskId: string,
    tasks: TaskNode[],
    config: FanoutConfig
  ): Promise<SubTaskResult[]> {
    const promises = tasks.map(task => this.executeSubTask(parentTaskId, task, config));

    const settled = await Promise.allSettled(promises);

    return settled.map((result, index) => {
      if (result.status === 'fulfilled') {
        return result.value;
      }
      return {
        taskId: tasks[index].id,
        success: false,
        error: result.reason?.message || String(result.reason),
        duration: 0,
      };
    });
  }

  /**
   * 顺序执行所有子任务
   */
  private async executeSequential(
    parentTaskId: string,
    tasks: TaskNode[],
    config: FanoutConfig
  ): Promise<SubTaskResult[]> {
    const results: SubTaskResult[] = [];

    for (const task of tasks) {
      try {
        const result = await this.executeSubTask(parentTaskId, task, config);
        results.push(result);

        if (!result.success && !config.continueOnPartialFailure) {
          for (const remaining of tasks.slice(results.length)) {
            results.push({
              taskId: remaining.id,
              success: false,
              error: '前置任务失败，跳过执行',
              duration: 0,
            });
          }
          break;
        }
      } catch (err) {
        results.push({
          taskId: task.id,
          success: false,
          error: (err as Error).message,
          duration: 0,
        });

        if (!config.continueOnPartialFailure) {
          for (const remaining of tasks.slice(results.length)) {
            results.push({
              taskId: remaining.id,
              success: false,
              error: '前置任务失败，跳过执行',
              duration: 0,
            });
          }
          break;
        }
      }
    }

    return results;
  }

  /**
   * 执行单个子任务
   */
  private async executeSubTask(
    parentTaskId: string,
    task: TaskNode,
    config: FanoutConfig
  ): Promise<SubTaskResult> {
    const startTime = Date.now();

    const agent = this.registry.findBestAgent(
      (task.tools && task.tools[0]) || ''
    ) || this.registry.findAgentByCapability(
      (task.tools && task.tools[0]) || ''
    );

    if (!agent) {
      return {
        taskId: task.id,
        success: false,
        error: `无可用的 Agent 执行子任务: ${task.id}`,
        duration: Date.now() - startTime,
      };
    }

    this.registry.updateStatus(agent.id, 'busy');

    try {
      const timeoutPromise = new Promise<never>((_, reject) => {
        setTimeout(() => reject(new Error(`子任务超时 (${config.taskTimeoutMs}ms)`)), config.taskTimeoutMs);
      });

      const result = this.executor
        ? await Promise.race([this.executor(task), timeoutPromise])
        : await Promise.race([
            Promise.resolve({ taskId: task.id, goal: task.goal, completedAt: Date.now() }),
            timeoutPromise,
          ]);

      const duration = Date.now() - startTime;
      this.registry.recordExecution(agent.id, true, duration);

      task.status = 'completed';
      task.result = result;
      task.assignedTo = agent.id;

      return {
        taskId: task.id,
        success: true,
        result,
        duration,
        agentId: agent.id,
      };
    } catch (err) {
      const duration = Date.now() - startTime;
      this.registry.recordExecution(agent.id, false, duration);

      task.status = 'failed';
      task.error = (err as Error).message;

      return {
        taskId: task.id,
        success: false,
        error: (err as Error).message,
        duration,
        agentId: agent.id,
      };
    } finally {
      this.registry.updateStatus(agent.id, 'idle');
    }
  }

  /**
   * 解析执行策略
   */
  private resolveStrategy(tasks: TaskNode[], configured: FanoutStrategy): FanoutStrategy {
    if (configured !== 'adaptive') return configured;
    return this.hasDependencies(tasks) ? 'sequential' : 'parallel';
  }

  /**
   * 检查任务间是否有依赖关系
   */
  private hasDependencies(tasks: TaskNode[]): boolean {
    return tasks.some(t => t.dependencies.length > 0);
  }
}

/**
 * Harness Phase 10: 多Agent编排 — DAG任务分发引擎
 *
 * 基于DAG依赖关系的智能任务调度：
 * - 拓扑排序分层，无依赖的并行执行
 * - 通过AgentRegistry自动分配Agent
 * - 支持优先级调度
 * - 完整的错误处理和状态追踪
 * P10增强：超时控制、自动重试、任务取消、并发限制
 */

import { Logger } from '../../utils/Logger';
import { AgentRegistry } from './AgentRegistry';

/** 任务节点 */
export interface TaskNode {
  /** 任务唯一标识 */
  id: string;
  /** 指定的Agent ID（可选，不指定则自动分配） */
  agentId?: string;
  /** 任务目标 */
  goal: string;
  /** 上下文信息 */
  context: string;
  /** 依赖的task id列表 */
  dependencies: string[];
  /** 优先级 1-10，越高越优先 */
  priority: number;
  /** 所需工具列表 */
  tools?: string[];
  /** 当前状态 */
  status: 'pending' | 'running' | 'completed' | 'failed' | 'cancelled';
  /** 执行结果 */
  result?: unknown;
  /** 错误信息 */
  error?: string;
  /** 分配给哪个Agent */
  assignedTo?: string;
}

/** DAG分层结果 */
interface DAGLayer {
  layer: number;
  tasks: TaskNode[];
}

/** 任务执行器 — 实际执行单个任务的回调 */
export type TaskExecutor = (task: TaskNode) => Promise<unknown>;

/** 任务分发器配置 */
export interface TaskDispatcherConfig {
  /** 单任务超时时间 (ms)，默认30000 */
  taskTimeoutMs?: number;
  /** 最大重试次数，默认2 */
  maxRetries?: number;
  /** 重试间隔 (ms)，默认1000 */
  retryDelayMs?: number;
  /** 每层最大并行任务数，默认5 */
  maxConcurrentPerLayer?: number;
}

const DEFAULT_DISPATCHER_CONFIG: Required<TaskDispatcherConfig> = {
  taskTimeoutMs: 30000,
  maxRetries: 2,
  retryDelayMs: 1000,
  maxConcurrentPerLayer: 5,
};

export class TaskDispatcher {
  private registry: AgentRegistry;
  private executor: TaskExecutor | null;
  private config: Required<TaskDispatcherConfig>;
  private activeControllers: Map<string, AbortController> = new Map();

  constructor(registry: AgentRegistry, executor?: TaskExecutor, config?: TaskDispatcherConfig) {
    this.registry = registry;
    this.executor = executor || null;
    this.config = { ...DEFAULT_DISPATCHER_CONFIG, ...config };
  }

  /**
   * 分发所有任务，按DAG依赖关系执行
   * @param tasks - 任务节点列表
   * @param config - 可选的运行时配置覆盖
   * @returns 所有任务的结果映射 (taskId → result)
   */
  async dispatch(tasks: TaskNode[], config?: TaskDispatcherConfig): Promise<Map<string, unknown>> {
    const runConfig = { ...this.config, ...config };
    const results = new Map<string, unknown>();
    const taskMap = new Map<string, TaskNode>();

    for (const task of tasks) {
      taskMap.set(task.id, { ...task, status: 'pending' });
    }

    this.validateDAG(tasks);

    const layers = this.buildDAG(tasks);
    Logger.info(
      `📋 DAG 分层完成: ${layers.length} 层, ${tasks.length} 个任务`,
      'TaskDispatcher'
    );

    for (const layer of layers) {
      Logger.info(
        `🏗️ 执行第 ${layer.layer + 1} 层 (${layer.tasks.length} 个任务)`,
        'TaskDispatcher'
      );

      const layerTasks = layer.tasks.slice(0, runConfig.maxConcurrentPerLayer);
      if (layer.tasks.length > runConfig.maxConcurrentPerLayer) {
        Logger.warn(
          `⚠️ 层任务数 ${layer.tasks.length} 超过并发限制 ${runConfig.maxConcurrentPerLayer}，截断执行`,
          'TaskDispatcher'
        );
      }

      const layerPromises = layerTasks.map(task =>
        this.executeTaskWithRetry(taskMap.get(task.id)!, results, runConfig)
      );

      const layerResults = await Promise.allSettled(layerPromises);

      for (let i = 0; i < layerResults.length; i++) {
        const task = layerTasks[i];
        const settled = layerResults[i];
        const node = taskMap.get(task.id)!;

        if (settled.status === 'fulfilled') {
          results.set(task.id, settled.value);
        } else {
          node.status = 'failed';
          node.error = settled.reason?.message || String(settled.reason);
          results.set(task.id, { error: node.error });
          Logger.error(
            `❌ 任务执行失败: ${task.id} (${task.goal})`,
            settled.reason as Error,
            'TaskDispatcher'
          );
        }
      }
    }

    for (const task of tasks) {
      const updated = taskMap.get(task.id);
      if (updated) {
        task.status = updated.status;
        task.result = updated.result;
        task.error = updated.error;
        task.assignedTo = updated.assignedTo;
      }
    }

    Logger.info(
      `✅ DAG 执行完成: ${tasks.length} 个任务, ${results.size} 个结果`,
      'TaskDispatcher'
    );

    return results;
  }

  /**
   * 取消正在执行的任务
   * @param taskId - 任务ID
   */
  cancel(taskId: string): void {
    const controller = this.activeControllers.get(taskId);
    if (controller) {
      controller.abort();
      this.activeControllers.delete(taskId);
      Logger.info(`🚫 任务已取消: ${taskId}`, 'TaskDispatcher');
    }
  }

  /**
   * 带重试的任务执行
   */
  private async executeTaskWithRetry(
    task: TaskNode,
    results: Map<string, unknown>,
    config: Required<TaskDispatcherConfig>
  ): Promise<unknown> {
    let lastError: Error | null = null;

    for (let attempt = 0; attempt <= config.maxRetries; attempt++) {
      if (task.status === 'cancelled') {
        throw new Error(`任务已取消: ${task.id}`);
      }

      try {
        return await this.executeTaskWithTimeout(task, results, config);
      } catch (err) {
        lastError = err as Error;

        if (this.isRetryableError(err as Error) && attempt < config.maxRetries) {
          Logger.info(
            `🔄 任务重试 (${attempt + 1}/${config.maxRetries}): ${task.id}`,
            'TaskDispatcher'
          );
          await this.delay(config.retryDelayMs * (attempt + 1));
        } else {
          break;
        }
      }
    }

    throw lastError || new Error(`任务执行失败: ${task.id}`);
  }

  /**
   * 带超时的任务执行
   */
  private async executeTaskWithTimeout(
    task: TaskNode,
    results: Map<string, unknown>,
    config: Required<TaskDispatcherConfig>
  ): Promise<unknown> {
    const controller = new AbortController();
    this.activeControllers.set(task.id, controller);

    const timeoutPromise = new Promise<never>((_, reject) => {
      const timer = setTimeout(() => {
        controller.abort();
        reject(new Error(`任务超时 (${config.taskTimeoutMs}ms): ${task.id}`));
      }, config.taskTimeoutMs);
      controller.signal.addEventListener('abort', () => clearTimeout(timer));
    });

    try {
      const result = await Promise.race([
        this.executeTask(task, results),
        timeoutPromise,
      ]);
      return result;
    } finally {
      this.activeControllers.delete(task.id);
    }
  }

  /**
   * 执行单个任务
   */
  private async executeTask(
    task: TaskNode,
    results: Map<string, unknown>
  ): Promise<unknown> {
    task.status = 'running';

    const agent = this.assignAgent(task);
    if (!agent) {
      task.status = 'failed';
      task.error = `无可用的 Agent 执行任务: ${task.id} (需要工具: ${(task.tools || []).join(', ') || '(不限)'})`;
      throw new Error(task.error);
    }

    task.assignedTo = agent.id;
    this.registry.updateStatus(agent.id, 'busy');

    const execStart = Date.now();

    Logger.info(
      `🎯 执行任务: ${task.id} | Agent: ${agent.name} | 目标: ${task.goal.substring(0, 60)}`,
      'TaskDispatcher'
    );

    try {
      const dependencyContext = this.buildDependencyContext(task, results);

      const result = this.executor
        ? await this.executor({
            ...task,
            context: task.context
              ? `${task.context}\n依赖结果: ${JSON.stringify(dependencyContext)}`
              : `依赖结果: ${JSON.stringify(dependencyContext)}`,
          })
        : await Promise.resolve({
            taskId: task.id,
            goal: task.goal,
            context: task.context,
            dependencyContext,
            completedAt: Date.now(),
          });

      task.status = 'completed';
      task.result = result;

      const execDuration = Date.now() - execStart;
      this.registry.recordExecution(agent.id, true, execDuration);

      Logger.info(
        `✅ 任务完成: ${task.id} | Agent: ${agent.name}`,
        'TaskDispatcher'
      );

      return result;
    } catch (err) {
      task.status = 'failed';
      task.error = (err as Error).message;

      const execDuration = Date.now() - execStart;
      this.registry.recordExecution(agent.id, false, execDuration);

      throw err;
    } finally {
      this.registry.updateStatus(agent.id, 'idle');
    }
  }

  /**
   * 判断错误是否可重试
   */
  private isRetryableError(error: Error): boolean {
    const retryablePatterns = ['timeout', 'ETIMEDOUT', 'ECONNRESET', 'rate_limit', '503', '429', 'ECONNREFUSED'];
    const msg = error.message.toLowerCase();
    return retryablePatterns.some(p => msg.includes(p.toLowerCase()));
  }

  /**
   * 延迟
   */
  private delay(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  /**
   * 构建DAG分层（拓扑排序）
   */
  private buildDAG(tasks: TaskNode[]): DAGLayer[] {
    const taskIds = new Set(tasks.map(t => t.id));
    const visited = new Set<string>();
    const inDegree = new Map<string, number>();
    const dependents = new Map<string, Set<string>>();

    for (const task of tasks) {
      inDegree.set(task.id, 0);
      dependents.set(task.id, new Set());
    }

    for (const task of tasks) {
      for (const depId of task.dependencies) {
        if (!taskIds.has(depId)) {
          Logger.warn(
            `依赖任务不存在: ${depId} (来自: ${task.id})`,
            'TaskDispatcher'
          );
          continue;
        }
        inDegree.set(task.id, (inDegree.get(task.id) || 0) + 1);
        const depSet = dependents.get(depId) || new Set();
        depSet.add(task.id);
        dependents.set(depId, depSet);
      }
    }

    const layers: DAGLayer[] = [];
    let layerIndex = 0;
    let remaining = tasks.length;

    const currentLayer = new Set<string>();

    for (const [taskId, degree] of inDegree) {
      if (degree === 0) {
        currentLayer.add(taskId);
      }
    }

    while (currentLayer.size > 0) {
      const layerTasks: TaskNode[] = [];
      const nextLayer = new Set<string>();

      const sorted = Array.from(currentLayer)
        .map(id => tasks.find(t => t.id === id)!)
        .filter(Boolean)
        .sort((a, b) => b.priority - a.priority);

      for (const task of sorted) {
        layerTasks.push(task);
        visited.add(task.id);
        remaining--;

        const deps = dependents.get(task.id) || new Set();
        for (const dependentId of deps) {
          const newDegree = (inDegree.get(dependentId) || 1) - 1;
          inDegree.set(dependentId, newDegree);
          if (newDegree === 0 && !visited.has(dependentId)) {
            nextLayer.add(dependentId);
          }
        }
      }

      layers.push({ layer: layerIndex, tasks: layerTasks });
      layerIndex++;
      currentLayer.clear();
      for (const id of nextLayer) {
        currentLayer.add(id);
      }
    }

    if (remaining > 0) {
      Logger.warn(
        `⚠️ DAG 可能存在环路: ${remaining} 个任务无法排序`,
        'TaskDispatcher'
      );
    }

    return layers;
  }

  /**
   * 验证DAG合法性
   */
  private validateDAG(tasks: TaskNode[]): void {
    const taskIds = new Set<string>();

    for (const task of tasks) {
      if (taskIds.has(task.id)) {
        throw new Error(`重复的任务ID: ${task.id}`);
      }
      taskIds.add(task.id);

      if (task.dependencies.includes(task.id)) {
        throw new Error(`任务自依赖: ${task.id}`);
      }

      if (task.priority < 1 || task.priority > 10) {
        throw new Error(
          `优先级超出范围 (1-10): ${task.id} → ${task.priority}`
        );
      }
    }
  }

  /**
   * 为任务分配Agent（使用findBestAgent优先）
   */
  private assignAgent(task: TaskNode): import('./AgentRegistry').AgentRegistration | null {
    if (task.agentId) {
      const agent = this.registry.getAgent(task.agentId);
      if (!agent) {
        Logger.warn(`指定的 Agent 不存在: ${task.agentId}`, 'TaskDispatcher');
        return null;
      }
      if (agent.status !== 'idle') {
        Logger.warn(`指定的 Agent 不空闲: ${task.agentId} (${agent.status})`, 'TaskDispatcher');
        return null;
      }
      return agent;
    }

    if (task.tools && task.tools.length > 0) {
      for (const toolName of task.tools) {
        const agent = this.registry.findBestAgent(toolName) || this.registry.findAgentByCapability(toolName);
        if (agent) return agent;
      }
      Logger.warn(
        `未找到具备任何所需工具的 Agent: ${task.tools.join(', ')}`,
        'TaskDispatcher'
      );
      return null;
    }

    const agents = this.registry.getIdleAgents();
    if (agents.length === 0) {
      Logger.warn('没有空闲的 Agent 可用', 'TaskDispatcher');
      return null;
    }

    return agents[0];
  }

  /**
   * 构建依赖上下文
   */
  private buildDependencyContext(
    task: TaskNode,
    results: Map<string, unknown>
  ): Record<string, unknown> {
    const context: Record<string, unknown> = {};

    for (const depId of task.dependencies) {
      if (results.has(depId)) {
        context[depId] = results.get(depId);
      } else {
        Logger.warn(
          `依赖任务结果不存在: ${depId} (来自: ${task.id})`,
          'TaskDispatcher'
        );
      }
    }

    return context;
  }
}

