/**
 * Harness Layer 4: Persistence - 统一持久化服务
 *
 * 统一包装分散在 MemoryEngine/ConversationHistoryManager/ChatService/EventBus/UserProfile 等模块的持久化逻辑
 * 新增跨会话任务状态管理
 */

import { Logger } from '../../utils/Logger';
import type { ChatMessage } from '../types';
import fs from 'fs';
import path from 'path';

// ============ 类型定义 ============

/** 记忆存储选项 */
export interface MemoryStoreOptions {
  type?: 'instant' | 'short_term' | 'long_term';
  scene?: string;
  emotion?: string;
  traceId?: string;
  source?: string;
  importance?: number;
}

/** 记忆检索选项 */
export interface MemoryRecallOptions {
  limit?: number;
  scene?: string;
  emotion?: string;
  startTime?: number;
  endTime?: number;
}

/** 记忆条目 */
export interface MemoryItem {
  id: string;
  content: string;
  type: string;
  timestamp: number;
  scene?: string;
  emotion?: string;
  relevanceScore?: number;
  importance?: number;
  accessCount?: number;
  lastAccessedAt?: number;
}

/** 跨会话任务状态 */
export interface TaskState {
  taskId: string;
  userId: string;
  description: string;
  status: 'pending' | 'in_progress' | 'paused' | 'completed' | 'failed';
  planJson?: string;
  currentStepIndex: number;
  stepResultsJson?: string;
  createdAt: number;
  updatedAt: number;
  resumeContext?: string;
}

/** 用户画像 */
export interface UserProfile {
  name?: string;
  preferences: Record<string, string[]>;
  facts: string[];
  communicationStyle?: string;
  activeHours?: string;
  lastUpdated: number;
}

/** 进化指标 */
export interface EvolutionMetric {
  metricType: string;
  value: number;
  timestamp: number;
  metadata?: Record<string, unknown>;
}

// ============ 持久化依赖 ============

/** PersistenceService 依赖 — 委托给现有模块 */
export interface PersistenceServiceDeps {
  /** 记忆引擎 */
  memoryEngine?: {
    storeShortTermMemory(content: string, scene?: string, emotion?: string): Promise<unknown>;
    storeLongTermMemory(content: string, scene?: string, emotion?: string): Promise<unknown>;
    storeInstantMemory(content: string, scene?: string, emotion?: string): Promise<unknown>;
    preciseHybridRetrieval(query: {
      query: string;
      scene?: string;
      emotion?: string;
      topK?: number;
    }): Promise<MemoryItem[]>;
    storeFeedbackSignal(data: {
      feedbackType: string;
      rating?: number;
      message?: string;
      traceId?: string;
      toolName?: string;
      userId?: string;
      timestamp?: number;
    }): Promise<void>;
  } | null;

  /** 对话历史管理器 */
  conversationHistory?: {
    addUserMessage(content: string): void;
    addAssistantMessage(content: string): void;
    getRecent(count?: number): Array<{ role: string; content: string }>;
    formatForLLM(): Array<{ role: string; content: string }>;
    saveState(): Promise<void>;
    clear(): Promise<void>;
  } | null;

  /** 用户画像 */
  userProfile?: {
    load(): Promise<void>;
    save(): Promise<void>;
    getData(): UserProfile | null;
    update(data: Partial<UserProfile>): Promise<void>;
  } | null;
}

export class PersistenceService {
  private deps: PersistenceServiceDeps;
  /** 跨会话任务状态 — 内存缓存 + 文件持久化 */
  private taskStates: Map<string, TaskState> = new Map();
  /** 进化指标 — 内存缓存 */
  private evolutionMetrics: EvolutionMetric[] = [];
  private initialized = false;
  private taskStatesPath: string;
  private evolutionMetricsPath: string;
  private evolutionMetricsSinceLastFlush = 0;
  private flushTimer: ReturnType<typeof setInterval> | null = null;

  constructor(deps: PersistenceServiceDeps, dataDir?: string) {
    this.deps = deps;
    const baseDir = dataDir || path.resolve(process.cwd(), 'data', 'persistence');
    this.taskStatesPath = path.join(baseDir, 'task-states.json');
    this.evolutionMetricsPath = path.join(baseDir, 'evolution-metrics.json');
  }

  /**
   * 初始化
   */
  async initialize(): Promise<void> {
    if (this.initialized) return;
    Logger.info('💾 PersistenceService 初始化', 'PersistenceService');
    await this.loadTaskStatesFromDisk();
    await this.loadEvolutionMetricsFromDisk();
    this.flushTimer = setInterval(() => {
      void this.flushTaskStatesToDisk();
      void this.flushEvolutionMetricsToDisk();
      this.promoteMemories().catch((err: Error) => {
        Logger.error('定时记忆晋升失败', err, 'PersistenceService');
      });
    }, 30_000);
    this.initialized = true;
  }

  // ============ 记忆 CRUD ============

  /**
   * 存储记忆
   */
  async storeMemory(
    content: string,
    options: MemoryStoreOptions = {}
  ): Promise<string> {
    const { type = 'short_term', scene, emotion } = options;

    if (!this.deps.memoryEngine) {
      Logger.warn('记忆引擎不可用，跳过存储', 'PersistenceService');
      return '';
    }

    try {
      switch (type) {
        case 'instant':
          await this.deps.memoryEngine.storeInstantMemory(content, scene, emotion);
          break;
        case 'long_term':
          await this.deps.memoryEngine.storeLongTermMemory(content, scene, emotion);
          break;
        default:
          await this.deps.memoryEngine.storeShortTermMemory(content, scene, emotion);
      }
      return 'stored';
    } catch (err) {
      Logger.error('记忆存储失败', err as Error, 'PersistenceService');
      return '';
    }
  }

  /**
   * 检索记忆
   */
  async recallMemory(
    query: string,
    options: MemoryRecallOptions = {}
  ): Promise<MemoryItem[]> {
    if (!this.deps.memoryEngine) return [];

    try {
      return await this.deps.memoryEngine.preciseHybridRetrieval({
        query,
        scene: options.scene,
        emotion: options.emotion,
        topK: options.limit || 5,
      });
    } catch (err) {
      Logger.error('记忆检索失败', err as Error, 'PersistenceService');
      return [];
    }
  }

  /**
   * 存储反馈信号
   */
  async storeFeedback(data: {
    feedbackType: string;
    rating?: number;
    message?: string;
    traceId?: string;
    toolName?: string;
  }): Promise<void> {
    if (!this.deps.memoryEngine) return;

    try {
      await this.deps.memoryEngine.storeFeedbackSignal({
        ...data,
        timestamp: Date.now(),
      });
    } catch (err) {
      Logger.error('反馈存储失败', err as Error, 'PersistenceService');
    }
  }

  // ============ 记忆生命周期管理 ============

  /**
   * 晋升短期记忆为长期记忆
   *
   * 扫描短期记忆，将满足以下条件之一的记忆晋升为长期记忆：
   * - importance >= 7（高重要性）
   * - accessCount >= 3（频繁访问）
   *
   * 晋升后从短期存储中移除已晋升的条目
   *
   * @returns 晋升的记忆数量
   */
  async promoteMemories(): Promise<number> {
    if (!this.deps.memoryEngine) {
      Logger.warn('记忆引擎不可用，跳过晋升', 'PersistenceService');
      return 0;
    }

    try {
      const shortTermMemories = await this.deps.memoryEngine.preciseHybridRetrieval({
        query: '',
        topK: 100,
      });

      const candidates = shortTermMemories.filter(
        (m) =>
          m.type === 'short_term' &&
          ((m.importance != null && m.importance >= 7) ||
            (m.accessCount != null && m.accessCount >= 3))
      );

      if (candidates.length === 0) {
        return 0;
      }

      let promoted = 0;
      for (const memory of candidates) {
        try {
          await this.deps.memoryEngine.storeLongTermMemory(
            memory.content,
            memory.scene,
            memory.emotion
          );
          promoted++;
          Logger.info(
            `💾 记忆晋升: id=${memory.id} importance=${memory.importance ?? '-'} accessCount=${memory.accessCount ?? '-'}`,
            'PersistenceService'
          );
        } catch (err) {
          Logger.error(
            `记忆晋升失败: id=${memory.id}`,
            err as Error,
            'PersistenceService'
          );
        }
      }

      if (promoted > 0) {
        Logger.info(
          `💾 记忆晋升完成: ${promoted}/${candidates.length} 条记忆已晋升为长期记忆`,
          'PersistenceService'
        );
      }

      return promoted;
    } catch (err) {
      Logger.error('记忆晋升扫描失败', err as Error, 'PersistenceService');
      return 0;
    }
  }

  // ============ 对话历史 ============

  /**
   * 保存对话消息
   */
  saveConversationMessage(role: 'user' | 'assistant', content: string): void {
    if (!this.deps.conversationHistory) return;

    if (role === 'user') {
      this.deps.conversationHistory.addUserMessage(content);
    } else {
      this.deps.conversationHistory.addAssistantMessage(content);
    }
  }

  /**
   * 获取对话历史
   */
  getConversationHistory(limit?: number): ChatMessage[] {
    if (!this.deps.conversationHistory) return [];

    const recent = this.deps.conversationHistory.getRecent(limit || 20);
    return recent.map((entry) => ({
      role: entry.role as ChatMessage['role'],
      content: entry.content,
    }));
  }

  /**
   * 持久化对话状态
   */
  async saveConversationState(): Promise<void> {
    if (!this.deps.conversationHistory) return;
    try {
      await this.deps.conversationHistory.saveState();
    } catch (err) {
      Logger.error('对话状态保存失败', err as Error, 'PersistenceService');
    }
  }

  /**
   * 清空对话历史
   */
  async clearConversation(): Promise<void> {
    if (!this.deps.conversationHistory) return;
    try {
      await this.deps.conversationHistory.clear();
    } catch (err) {
      Logger.error('对话清空失败', err as Error, 'PersistenceService');
    }
  }

  // ============ 跨会话任务状态（新增） ============

  /**
   * 保存任务状态
   */
  async saveTaskState(task: TaskState): Promise<void> {
    task.updatedAt = Date.now();
    this.taskStates.set(task.taskId, task);
    Logger.info(
      `💾 任务状态保存: ${task.taskId} status=${task.status}`,
      'PersistenceService'
    );
    await this.flushTaskStatesToDisk();
  }

  /**
   * 加载任务状态
   */
  async loadTaskState(taskId: string): Promise<TaskState | null> {
    return this.taskStates.get(taskId) || null;
  }

  /**
   * 列出活跃任务
   */
  async listActiveTasks(): Promise<TaskState[]> {
    return Array.from(this.taskStates.values()).filter(
      (t) => t.status === 'pending' || t.status === 'in_progress' || t.status === 'paused'
    );
  }

  /**
   * 更新任务状态
   */
  async updateTaskStatus(
    taskId: string,
    status: TaskState['status'],
    resumeContext?: string
  ): Promise<boolean> {
    const task = this.taskStates.get(taskId);
    if (!task) return false;

    task.status = status;
    task.updatedAt = Date.now();
    if (resumeContext) task.resumeContext = resumeContext;
    await this.flushTaskStatesToDisk();
    return true;
  }

  /**
   * 删除任务
   */
  async deleteTask(taskId: string): Promise<boolean> {
    const deleted = this.taskStates.delete(taskId);
    if (deleted) {
      await this.flushTaskStatesToDisk();
    }
    return deleted;
  }

  // ============ 用户画像 ============

  /**
   * 加载用户画像
   */
  async loadUserProfile(): Promise<UserProfile | null> {
    if (!this.deps.userProfile) return null;

    try {
      await this.deps.userProfile.load();
      return this.deps.userProfile.getData();
    } catch (err) {
      Logger.error('用户画像加载失败', err as Error, 'PersistenceService');
      return null;
    }
  }

  /**
   * 保存用户画像
   */
  async saveUserProfile(data: Partial<UserProfile>): Promise<void> {
    if (!this.deps.userProfile) return;

    try {
      await this.deps.userProfile.update(data);
    } catch (err) {
      Logger.error('用户画像保存失败', err as Error, 'PersistenceService');
    }
  }

  // ============ 进化指标 ============

  /**
   * 记录进化指标
   */
  recordEvolutionMetric(metric: EvolutionMetric): void {
    this.evolutionMetrics.push(metric);
    if (this.evolutionMetrics.length > 1000) {
      this.evolutionMetrics = this.evolutionMetrics.slice(-1000);
    }
    this.evolutionMetricsSinceLastFlush++;
    if (this.evolutionMetricsSinceLastFlush >= 10) {
      void this.flushEvolutionMetricsToDisk();
    }
  }

  /**
   * 获取进化指标
   */
  getEvolutionMetrics(
    metricType?: string,
    limit?: number
  ): EvolutionMetric[] {
    let metrics = this.evolutionMetrics;
    if (metricType) {
      metrics = metrics.filter((m) => m.metricType === metricType);
    }
    if (limit) {
      metrics = metrics.slice(-limit);
    }
    return metrics;
  }

  // ============ 生命周期 ============

  /**
   * 关闭
   */
  async shutdown(): Promise<void> {
    if (this.flushTimer) {
      clearInterval(this.flushTimer);
      this.flushTimer = null;
    }
    await this.flushTaskStatesToDisk();
    await this.flushEvolutionMetricsToDisk();
    Logger.info('💾 PersistenceService 关闭', 'PersistenceService');
    this.initialized = false;
  }

  // ============ 文件持久化 ============

  /**
   * 将任务状态写入磁盘
   */
  private async flushTaskStatesToDisk(): Promise<void> {
    try {
      const dir = path.dirname(this.taskStatesPath);
      if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true });
      }
      const data = Array.from(this.taskStates.values());
      fs.writeFileSync(this.taskStatesPath, JSON.stringify(data, null, 2), 'utf-8');
    } catch (err) {
      Logger.error('任务状态刷盘失败', err as Error, 'PersistenceService');
    }
  }

  /**
   * 从磁盘加载任务状态
   */
  private async loadTaskStatesFromDisk(): Promise<void> {
    try {
      if (!fs.existsSync(this.taskStatesPath)) {
        Logger.info('💾 无持久化任务状态文件，跳过加载', 'PersistenceService');
        return;
      }
      const raw = fs.readFileSync(this.taskStatesPath, 'utf-8');
      const data = JSON.parse(raw) as TaskState[];
      for (const task of data) {
        this.taskStates.set(task.taskId, task);
      }
      Logger.info(
        `💾 已从磁盘加载 ${data.length} 个任务状态`,
        'PersistenceService'
      );
    } catch (err) {
      Logger.error('任务状态加载失败', err as Error, 'PersistenceService');
    }
  }

  private async flushEvolutionMetricsToDisk(): Promise<void> {
    try {
      const dir = path.dirname(this.evolutionMetricsPath);
      if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true });
      }
      fs.writeFileSync(this.evolutionMetricsPath, JSON.stringify(this.evolutionMetrics, null, 2), 'utf-8');
      this.evolutionMetricsSinceLastFlush = 0;
    } catch (err) {
      Logger.error('进化指标刷盘失败', err as Error, 'PersistenceService');
    }
  }

  private async loadEvolutionMetricsFromDisk(): Promise<void> {
    try {
      if (!fs.existsSync(this.evolutionMetricsPath)) {
        Logger.info('💾 无持久化进化指标文件，跳过加载', 'PersistenceService');
        return;
      }
      const raw = fs.readFileSync(this.evolutionMetricsPath, 'utf-8');
      const data = JSON.parse(raw) as EvolutionMetric[];
      this.evolutionMetrics = data.slice(-1000);
      Logger.info(
        `💾 已从磁盘加载 ${this.evolutionMetrics.length} 条进化指标`,
        'PersistenceService'
      );
    } catch (err) {
      Logger.error('进化指标加载失败', err as Error, 'PersistenceService');
    }
  }
}

/**
 * Harness Layer 4: Persistence - Trajectory Database
 *
 * SQLite 轨迹持久化，完整记录 FC 循环执行轨迹
 */

import Database from 'better-sqlite3';
import fs from 'fs';
import path from 'path';
import { Logger } from '../../utils/Logger';

export interface ExecutionRecord {
  id: string;
  user_id?: string;
  input: string;
  response?: string;
  intent?: string;
  status: 'success' | 'failed' | 'aborted';
  quality_overall?: number;
  loop_rounds?: number;
  total_tool_calls?: number;
  total_duration?: number;
  created_at: number;
  updated_at: number;
}

export interface ToolInvocationRecord {
  id?: number;
  execution_id: string;
  step_index: number;
  tool_name: string;
  args_json: string;
  result_success: number;
  result_output?: string;
  duration: number;
  error_message?: string;
  created_at: number;
}

export interface StateTransitionRecord {
  id?: number;
  execution_id: string;
  from_state: string;
  to_state: string;
  reason?: string;
  created_at: number;
}

export interface ContextSnapshotRecord {
  id?: number;
  execution_id: string;
  phase: 'planning' | 'executing' | 'evaluating' | 'reporting' | 'tool_call' | 'tool_result' | 'llm_call';
  step_index: number;
  snapshot_json: string;
  token_count?: number;
  duration_ms?: number;
  created_at: number;
}

export interface ExecutionStats {
  total: number;
  successRate: number;
  avgDuration: number;
  avgScore: number;
}

export class TrajectoryDatabase {
  private db: Database.Database;
  private dbPath: string;

  constructor(dbPath: string) {
    this.dbPath = dbPath;
    const dir = path.dirname(dbPath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    this.db = new Database(dbPath);
    this.db.pragma('journal_mode = WAL');
    this.initializeTables();
    Logger.info(`💾 TrajectoryDatabase 初始化: ${dbPath}`, 'TrajectoryDatabase');
  }

  private initializeTables(): void {
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS executions (
        id TEXT PRIMARY KEY,
        user_id TEXT,
        input TEXT NOT NULL,
        response TEXT,
        intent TEXT,
        status TEXT NOT NULL DEFAULT 'failed',
        quality_overall REAL,
        loop_rounds INTEGER DEFAULT 0,
        total_tool_calls INTEGER DEFAULT 0,
        total_duration INTEGER DEFAULT 0,
        created_at INTEGER NOT NULL,
        updated_at INTEGER NOT NULL
      );

      CREATE TABLE IF NOT EXISTS tool_invocations (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        execution_id TEXT NOT NULL,
        step_index INTEGER NOT NULL,
        tool_name TEXT NOT NULL,
        args_json TEXT NOT NULL,
        result_success INTEGER NOT NULL DEFAULT 0,
        result_output TEXT,
        duration INTEGER NOT NULL DEFAULT 0,
        error_message TEXT,
        created_at INTEGER NOT NULL,
        FOREIGN KEY (execution_id) REFERENCES executions(id) ON DELETE CASCADE
      );

      CREATE TABLE IF NOT EXISTS state_transitions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        execution_id TEXT NOT NULL,
        from_state TEXT NOT NULL,
        to_state TEXT NOT NULL,
        reason TEXT,
        created_at INTEGER NOT NULL,
        FOREIGN KEY (execution_id) REFERENCES executions(id) ON DELETE CASCADE
      );

      CREATE TABLE IF NOT EXISTS context_snapshots (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        execution_id TEXT NOT NULL,
        phase TEXT NOT NULL,
        step_index INTEGER NOT NULL,
        snapshot_json TEXT NOT NULL,
        token_count INTEGER,
        duration_ms INTEGER,
        created_at INTEGER NOT NULL,
        FOREIGN KEY (execution_id) REFERENCES executions(id) ON DELETE CASCADE
      );

      CREATE INDEX IF NOT EXISTS idx_tool_invocations_execution_id ON tool_invocations(execution_id);
      CREATE INDEX IF NOT EXISTS idx_tool_invocations_tool_name ON tool_invocations(tool_name);
      CREATE INDEX IF NOT EXISTS idx_state_transitions_execution_id ON state_transitions(execution_id);
      CREATE INDEX IF NOT EXISTS idx_context_snapshots_execution_id ON context_snapshots(execution_id);
      CREATE INDEX IF NOT EXISTS idx_context_snapshots_phase ON context_snapshots(phase);
      CREATE INDEX IF NOT EXISTS idx_executions_status ON executions(status);
      CREATE INDEX IF NOT EXISTS idx_executions_created_at ON executions(created_at);
    `);
  }

  recordExecution(exec: ExecutionRecord): void {
    const stmt = this.db.prepare(`
      INSERT OR REPLACE INTO executions (
        id, user_id, input, response, intent, status, quality_overall,
        loop_rounds, total_tool_calls, total_duration, created_at, updated_at
      ) VALUES (
        @id, @user_id, @input, @response, @intent, @status, @quality_overall,
        @loop_rounds, @total_tool_calls, @total_duration, @created_at, @updated_at
      )
    `);
    stmt.run({
      id: exec.id,
      user_id: exec.user_id || null,
      input: exec.input,
      response: exec.response || null,
      intent: exec.intent || null,
      status: exec.status,
      quality_overall: exec.quality_overall || null,
      loop_rounds: exec.loop_rounds || 0,
      total_tool_calls: exec.total_tool_calls || 0,
      total_duration: exec.total_duration || 0,
      created_at: exec.created_at,
      updated_at: exec.updated_at,
    });
  }

  updateExecutionStatus(id: string, status: string, response?: string): void {
    const stmt = this.db.prepare(`
      UPDATE executions
      SET status = @status, response = @response, updated_at = @updated_at
      WHERE id = @id
    `);
    stmt.run({
      id,
      status,
      response: response || null,
      updated_at: Date.now(),
    });
  }

  recordToolInvocation(invocation: ToolInvocationRecord): void {
    const stmt = this.db.prepare(`
      INSERT INTO tool_invocations (
        execution_id, step_index, tool_name, args_json, result_success,
        result_output, duration, error_message, created_at
      ) VALUES (
        @execution_id, @step_index, @tool_name, @args_json, @result_success,
        @result_output, @duration, @error_message, @created_at
      )
    `);
    stmt.run({
      execution_id: invocation.execution_id,
      step_index: invocation.step_index,
      tool_name: invocation.tool_name,
      args_json: invocation.args_json,
      result_success: invocation.result_success,
      result_output: invocation.result_output || null,
      duration: invocation.duration,
      error_message: invocation.error_message || null,
      created_at: invocation.created_at,
    });
  }

  recordStateTransition(transition: StateTransitionRecord): void {
    const stmt = this.db.prepare(`
      INSERT INTO state_transitions (
        execution_id, from_state, to_state, reason, created_at
      ) VALUES (
        @execution_id, @from_state, @to_state, @reason, @created_at
      )
    `);
    stmt.run({
      execution_id: transition.execution_id,
      from_state: transition.from_state,
      to_state: transition.to_state,
      reason: transition.reason || null,
      created_at: transition.created_at,
    });
  }

  recordContextSnapshot(snapshot: ContextSnapshotRecord): void {
    const stmt = this.db.prepare(`
      INSERT INTO context_snapshots (
        execution_id, phase, step_index, snapshot_json, token_count, duration_ms, created_at
      ) VALUES (
        @execution_id, @phase, @step_index, @snapshot_json, @token_count, @duration_ms, @created_at
      )
    `);
    stmt.run({
      execution_id: snapshot.execution_id,
      phase: snapshot.phase,
      step_index: snapshot.step_index,
      snapshot_json: snapshot.snapshot_json,
      token_count: snapshot.token_count || null,
      duration_ms: snapshot.duration_ms || null,
      created_at: snapshot.created_at,
    });
  }

  getContextSnapshots(executionId: string, phase?: string): ContextSnapshotRecord[] {
    if (phase) {
      const stmt = this.db.prepare(
        'SELECT * FROM context_snapshots WHERE execution_id = ? AND phase = ? ORDER BY step_index, id'
      );
      return stmt.all(executionId, phase) as ContextSnapshotRecord[];
    }
    const stmt = this.db.prepare(
      'SELECT * FROM context_snapshots WHERE execution_id = ? ORDER BY step_index, id'
    );
    return stmt.all(executionId) as ContextSnapshotRecord[];
  }

  getExecution(id: string): ExecutionRecord | null {
    const stmt = this.db.prepare('SELECT * FROM executions WHERE id = ?');
    return (stmt.get(id) as ExecutionRecord) || null;
  }

  getToolInvocations(executionId: string): ToolInvocationRecord[] {
    const stmt = this.db.prepare(
      'SELECT * FROM tool_invocations WHERE execution_id = ? ORDER BY step_index, id'
    );
    return stmt.all(executionId) as ToolInvocationRecord[];
  }

  getStateTransitions(executionId: string): StateTransitionRecord[] {
    const stmt = this.db.prepare(
      'SELECT * FROM state_transitions WHERE execution_id = ? ORDER BY id'
    );
    return stmt.all(executionId) as StateTransitionRecord[];
  }

  getRecentExecutions(limit: number): ExecutionRecord[] {
    const stmt = this.db.prepare(
      'SELECT * FROM executions ORDER BY created_at DESC LIMIT ?'
    );
    return stmt.all(limit) as ExecutionRecord[];
  }

  getExecutionStats(): ExecutionStats {
    const totalStmt = this.db.prepare('SELECT COUNT(*) as count FROM executions');
    const totalResult = totalStmt.get() as { count: number } | undefined;
    const total = totalResult?.count ?? 0;

    if (total === 0) {
      return { total: 0, successRate: 0, avgDuration: 0, avgScore: 0 };
    }

    const successStmt = this.db.prepare(
      "SELECT COUNT(*) as count FROM executions WHERE status = 'success'"
    );
    const successResult = successStmt.get() as { count: number } | undefined;
    const successCount = successResult?.count ?? 0;
    const successRate = successCount / total;

    const avgDurationStmt = this.db.prepare(
      'SELECT AVG(total_duration) as avg FROM executions WHERE total_duration > 0'
    );
    const avgDurationResult = avgDurationStmt.get() as { avg: number | null } | undefined;
    const avgDuration = avgDurationResult?.avg ?? 0;

    const avgScoreStmt = this.db.prepare(
      'SELECT AVG(quality_overall) as avg FROM executions WHERE quality_overall IS NOT NULL'
    );
    const avgScoreResult = avgScoreStmt.get() as { avg: number | null } | undefined;
    const avgScore = avgScoreResult?.avg ?? 0;

    return { total, successRate, avgDuration, avgScore };
  }

  close(): void {
    this.db.close();
    Logger.info('💾 TrajectoryDatabase 已关闭', 'TrajectoryDatabase');
  }
}

/**
 * Harness Layer 4: Persistence - Trajectory Query Service
 *
 * 轨迹查询服务，提供失败执行、工具成功率、质量趋势等分析
 */

import { Logger } from '../../utils/Logger';
import type { TrajectoryDatabase } from './TrajectoryDatabase';
import type { ExecutionRecord } from './TrajectoryDatabase';

export interface FailedExecutionsOptions {
  category?: string;
  limit?: number;
}

export interface ToolSuccessRate {
  total: number;
  success: number;
  rate: number;
}

export interface HourlyQuality {
  hour: number;
  avgScore: number;
  count: number;
}

export interface DailyTrend {
  date: string;
  avgScore: number;
  avgDuration: number;
  count: number;
}

export class TrajectoryQueryService {
  private db: TrajectoryDatabase;

  constructor(db: TrajectoryDatabase) {
    this.db = db;
  }

  getFailedExecutions(options: FailedExecutionsOptions = {}): ExecutionRecord[] {
    const limit = options.limit || 50;
    const category = options.category;

    if (category) {
      const allFailed = this.db.getRecentExecutions(1000).filter(
        (e) => e.status === 'failed' || e.status === 'aborted'
      );
      return allFailed
        .filter((e) => {
          const inputLower = e.input.toLowerCase();
          return inputLower.includes(category.toLowerCase());
        })
        .slice(0, limit);
    }

    const recent = this.db.getRecentExecutions(1000);
    return recent
      .filter((e) => e.status === 'failed' || e.status === 'aborted')
      .slice(0, limit);
  }

  getToolSuccessRates(options: { since?: number } = {}): Record<string, ToolSuccessRate> {
    const since = options.since || Date.now() - 7 * 24 * 60 * 60 * 1000;

    const recent = this.db.getRecentExecutions(1000);
    const executionIds = new Set(
      recent
        .filter((e) => e.created_at >= since)
        .map((e) => e.id)
    );

    if (executionIds.size === 0) {
      return {};
    }

    const placeholders = Array.from(executionIds)
      .map(() => '?')
      .join(',');
    const allInvocations = this.db.getToolInvocations('');

    const toolStats: Record<string, { total: number; success: number }> = {};

    for (const execId of executionIds) {
      const invocations = this.db.getToolInvocations(execId);
      for (const inv of invocations) {
        if (!toolStats[inv.tool_name]) {
          toolStats[inv.tool_name] = { total: 0, success: 0 };
        }
        toolStats[inv.tool_name].total++;
        if (inv.result_success === 1) {
          toolStats[inv.tool_name].success++;
        }
      }
    }

    const result: Record<string, ToolSuccessRate> = {};
    for (const [toolName, stats] of Object.entries(toolStats)) {
      result[toolName] = {
        total: stats.total,
        success: stats.success,
        rate: stats.total > 0 ? stats.success / stats.total : 0,
      };
    }

    return result;
  }

  getAverageQualityByHour(): HourlyQuality[] {
    const recent = this.db.getRecentExecutions(500);
    const scoredExecutions = recent.filter(
      (e) => e.quality_overall !== null && e.quality_overall !== undefined
    );

    if (scoredExecutions.length === 0) {
      return [];
    }

    const hourBuckets: Record<number, { total: number; count: number }> = {};

    for (const exec of scoredExecutions) {
      const date = new Date(exec.created_at);
      const hour = date.getHours();
      if (!hourBuckets[hour]) {
        hourBuckets[hour] = { total: 0, count: 0 };
      }
      hourBuckets[hour].total += exec.quality_overall!;
      hourBuckets[hour].count++;
    }

    const result: HourlyQuality[] = [];
    for (let hour = 0; hour < 24; hour++) {
      const bucket = hourBuckets[hour];
      result.push({
        hour,
        avgScore: bucket ? bucket.total / bucket.count : 0,
        count: bucket ? bucket.count : 0,
      });
    }

    return result;
  }

  getRecentTrend(days: number): DailyTrend[] {
    const since = Date.now() - days * 24 * 60 * 60 * 1000;
    const recent = this.db.getRecentExecutions(1000);

    const dayBuckets: Record<string, { totalScore: number; totalDuration: number; count: number }> = {};

    for (const exec of recent) {
      if (!exec.created_at || exec.created_at < since) continue;

      const date = new Date(exec.created_at);
      if (isNaN(date.getTime())) continue;

      const dateStr = date.toISOString().split('T')[0];

      if (!dayBuckets[dateStr]) {
        dayBuckets[dateStr] = { totalScore: 0, totalDuration: 0, count: 0 };
      }

      dayBuckets[dateStr].count++;
      dayBuckets[dateStr].totalDuration += exec.total_duration || 0;
      if (exec.quality_overall !== null && exec.quality_overall !== undefined) {
        dayBuckets[dateStr].totalScore += exec.quality_overall;
      }
    }

    const result: DailyTrend[] = [];
    for (const [dateStr, bucket] of Object.entries(dayBuckets)) {
      result.push({
        date: dateStr,
        avgScore: bucket.count > 0 ? bucket.totalScore / bucket.count : 0,
        avgDuration: bucket.count > 0 ? bucket.totalDuration / bucket.count : 0,
        count: bucket.count,
      });
    }

    result.sort((a, b) => a.date.localeCompare(b.date));
    return result;
  }
}

/**
 * Harness Tool: code_analyze - 分析代码质量和安全
 */

import type { ToolContext, ToolDefinition, ToolResult } from '../../types';
import { Permission, ToolCategory } from '../../types';

export const CODE_ANALYZE_DEF: ToolDefinition = {
  name: 'code_analyze',
  description:
    '分析代码的质量、安全和性能问题。适用场景：用户要求代码审查、检查潜在bug、评估代码质量。不适用：生成新代码（用 code_generate）、修复代码（用 code_fix）。',
  category: ToolCategory.CODE,
  parameters: {
    code: {
      type: 'string',
      description: '要分析的代码内容',
    },
    language: {
      type: 'string',
      description: '代码语言，如 typescript、python、java',
      default: 'typescript',
    },
    analysisType: {
      type: 'string',
      description: '分析类型: comprehensive=综合分析, security=安全检查, performance=性能分析',
      enum: ['comprehensive', 'security', 'performance'],
      default: 'comprehensive',
    },
  },
  requiredParams: ['code'],
  requiredPermissions: [Permission.CODE_EXECUTE],
  riskLevel: 'low',
  idempotent: true,
  timeout: 20000,
};

/** code_analyze 依赖接口 */
export interface CodeAnalyzeDeps {
  analyzeCode?: (params: {
    code: string;
    language: string;
    analysisType: string;
  }) => Promise<{
    issues: Array<{
      severity: 'error' | 'warning' | 'info';
      message: string;
      line?: number;
    }>;
    score: number;
    summary: string;
  }>;
}

/** 创建 code_analyze 执行器 */
export function createCodeAnalyzeExecutor(deps: CodeAnalyzeDeps) {
  return async (
    params: Record<string, unknown>,
    _context?: ToolContext
  ): Promise<ToolResult> => {
    const code = String(params.code || '');
    const language = (params.language as string) || 'typescript';
    const analysisType = (params.analysisType as string) || 'comprehensive';

    if (!deps.analyzeCode) {
      // 降级：基础静态分析
      const issues = performBasicAnalysis(code, analysisType);
      return {
        success: true,
        output: formatAnalysisResult(issues, 0, '基础静态分析（LLM分析不可用）'),
        duration: 0,
        validated: false,
        metadata: { analysisType, fallback: true },
      };
    }

    try {
      const result = await deps.analyzeCode({
        code,
        language,
        analysisType,
      });

      return {
        success: true,
        output: formatAnalysisResult(
          result.issues,
          result.score,
          result.summary
        ),
        duration: 0,
        validated: false,
        metadata: {
          analysisType,
          score: result.score,
          issueCount: result.issues.length,
        },
      };
    } catch (error) {
      return {
        success: false,
        output: `代码分析失败: ${(error as Error).message}`,
        error: (error as Error).message,
        duration: 0,
        validated: false,
      };
    }
  };
}

/** 基础静态分析（降级方案） */
function performBasicAnalysis(
  code: string,
  analysisType: string
): Array<{ severity: 'error' | 'warning' | 'info'; message: string; line?: number }> {
  const issues: Array<{
    severity: 'error' | 'warning' | 'info';
    message: string;
    line?: number;
  }> = [];

  const lines = code.split('\n');

  lines.forEach((line, i) => {
    const lineNum = i + 1;
    const trimmed = line.trim();

    if (analysisType === 'comprehensive' || analysisType === 'security') {
      if (/\beval\s*\(/.test(trimmed)) {
        issues.push({
          severity: 'error',
          message: '检测到 eval() 使用，存在代码注入风险',
          line: lineNum,
        });
      }
      if (/innerHTML\s*=/.test(trimmed) && !/sanitize/.test(trimmed)) {
        issues.push({
          severity: 'warning',
          message: '直接赋值 innerHTML，存在 XSS 风险',
          line: lineNum,
        });
      }
      if (/password|secret|api[_-]?key/i.test(trimmed) && /=/.test(trimmed)) {
        issues.push({
          severity: 'warning',
          message: '可能包含硬编码的敏感信息',
          line: lineNum,
        });
      }
    }

    if (analysisType === 'comprehensive' || analysisType === 'performance') {
      if (trimmed.length > 120) {
        issues.push({
          severity: 'info',
          message: '行长度超过120字符，建议拆分',
          line: lineNum,
        });
      }
    }

    if (analysisType === 'comprehensive') {
      if (/catch\s*\(\w*\)\s*\{\s*\}/.test(trimmed)) {
        issues.push({
          severity: 'warning',
          message: '空 catch 块，错误被静默吞没',
          line: lineNum,
        });
      }
      if (/console\.(log|error|warn)\(/.test(trimmed)) {
        issues.push({
          severity: 'info',
          message: '检测到 console 输出，生产环境应使用 Logger',
          line: lineNum,
        });
      }
    }
  });

  return issues;
}

/** 格式化分析结果 */
function formatAnalysisResult(
  issues: Array<{ severity: string; message: string; line?: number }>,
  score: number,
  summary: string
): string {
  const severityIcon: Record<string, string> = {
    error: '❌',
    warning: '⚠️',
    info: 'ℹ️',
  };

  const issueList = issues
    .map(
      (issue) =>
        `${severityIcon[issue.severity] || '•'} [${issue.severity.toUpperCase()}]${issue.line ? ` L${issue.line}` : ''} ${issue.message}`
    )
    .join('\n');

  return `${summary}\n\n${issueList}${score > 0 ? `\n\n质量评分: ${score}/100` : ''}`;
}

/**
 * Harness Tool: code_fix - 修复代码问题
 */

import type { ToolContext, ToolDefinition, ToolResult } from '../../types';
import { Permission, ToolCategory } from '../../types';

export const CODE_FIX_DEF: ToolDefinition = {
  name: 'code_fix',
  description:
    '修复代码中的错误或问题。适用场景：代码有bug需要修复、代码有安全漏洞需要修补、代码不符合规范需要调整。不适用：生成全新代码（用 code_generate）、仅分析不修复（用 code_analyze）。',
  category: ToolCategory.CODE,
  parameters: {
    code: {
      type: 'string',
      description: '需要修复的原始代码',
    },
    errorDescription: {
      type: 'string',
      description: '错误描述或修复要求，如"TypeError: Cannot read property of undefined"、"修复SQL注入漏洞"',
    },
    language: {
      type: 'string',
      description: '代码语言，如 typescript、python',
      default: 'typescript',
    },
  },
  requiredParams: ['code', 'errorDescription'],
  requiredPermissions: [Permission.CODE_EXECUTE, Permission.FILE_WRITE],
  riskLevel: 'medium',
  idempotent: false,
  timeout: 30000,
  requiresConfirmation: true,
};

/** code_fix 依赖接口 */
export interface CodeFixDeps {
  fixCode?: (params: {
    code: string;
    errorDescription: string;
    language: string;
  }) => Promise<{
    fixedCode: string;
    changes: Array<{
      type: 'fix' | 'improvement' | 'refactor';
      description: string;
    }>;
  }>;
}

/** 创建 code_fix 执行器 */
export function createCodeFixExecutor(deps: CodeFixDeps) {
  return async (
    params: Record<string, unknown>,
    _context?: ToolContext
  ): Promise<ToolResult> => {
    const code = String(params.code || '');
    const errorDescription = String(params.errorDescription || '');
    const language = (params.language as string) || 'typescript';

    if (!deps.fixCode) {
      const result = performBasicFix(code, language);
      const changeList = result.changes
        .map((c) => `- [${c.type}] ${c.description}`)
        .join('\n');
      const note =
        result.changes.length > 0
          ? `基础修复完成（LLM不可用，仅执行模式匹配修复），变更如下：\n${changeList}\n\n\`\`\`${language}\n${result.fixedCode}\n\`\`\``
          : `基础修复未发现可自动修复的问题（LLM不可用）。建议手动修复或启用LLM服务。`;
      return {
        success: result.changes.length > 0,
        output: note,
        duration: 0,
        validated: false,
        metadata: {
          changeCount: result.changes.length,
          language,
          fallback: true,
        },
      };
    }

    try {
      const result = await deps.fixCode({
        code,
        errorDescription,
        language,
      });

      const changeList = result.changes
        .map(
          (c) =>
            `- [${c.type}] ${c.description}`
        )
        .join('\n');

      const output = `修复完成，变更如下：\n${changeList}\n\n\`\`\`${language}\n${result.fixedCode}\n\`\`\``;

      return {
        success: true,
        output,
        duration: 0,
        validated: false,
        metadata: {
          changeCount: result.changes.length,
          language,
        },
      };
    } catch (error) {
      return {
        success: false,
        output: `代码修复失败: ${(error as Error).message}`,
        error: (error as Error).message,
        duration: 0,
        validated: false,
      };
    }
  };
}

function performBasicFix(
  code: string,
  language: string
): {
  fixedCode: string;
  changes: Array<{ type: 'fix' | 'improvement' | 'refactor'; description: string }>;
} {
  const changes: Array<{ type: 'fix' | 'improvement' | 'refactor'; description: string }> = [];
  let fixed = code;

  const isJsLike = ['typescript', 'javascript', 'ts', 'js'].includes(language.toLowerCase());
  const isPython = ['python', 'py'].includes(language.toLowerCase());

  if (isJsLike) {
    const varRegex = /\bvar\s+/g;
    const varMatches = fixed.match(varRegex);
    if (varMatches) {
      fixed = fixed.replace(/\bvar\s+(\w+)\s*=/g, (_match, name: string) => {
        const rest = fixed.slice(fixed.indexOf(_match) + _match.length);
        const isReassigned = new RegExp(`\\b${name}\\s*=`).test(rest);
        return `${isReassigned ? 'let' : 'const'} ${name} =`;
      });
      changes.push({ type: 'improvement', description: `替换 var 为 const/let (${varMatches.length}处)` });
    }

    const eqRegex = /([^=!<>])={2}([^=])/g;
    if (eqRegex.test(fixed)) {
      fixed = fixed.replace(/([^=!<>])={2}([^=])/g, '$1===$2');
      changes.push({ type: 'fix', description: '替换 == 为 ===' });
    }

    const lines = fixed.split('\n');
    const fixedLines: string[] = [];
    let addedSemi = false;
    for (const line of lines) {
      const trimmed = line.trimEnd();
      if (
        trimmed.length > 0 &&
        !trimmed.endsWith(';') &&
        !trimmed.endsWith('{') &&
        !trimmed.endsWith('}') &&
        !trimmed.endsWith(',') &&
        !trimmed.endsWith(':') &&
        !trimmed.endsWith(')') &&
        !trimmed.startsWith('//') &&
        !trimmed.startsWith('*') &&
        !trimmed.startsWith('/*')
      ) {
        if (
          /^(?:const|let|var|return|throw|break|continue|import|export)\s/.test(trimmed) ||
          /^\w+\.\w+\(.*\)$/.test(trimmed) ||
          /^\w+\s*=/.test(trimmed)
        ) {
          fixedLines.push(line + ';');
          addedSemi = true;
          continue;
        }
      }
      fixedLines.push(line);
    }
    if (addedSemi) {
      fixed = fixedLines.join('\n');
      changes.push({ type: 'fix', description: '添加缺失的分号' });
    }
  }

  if (isPython) {
    const trailingSemiRegex = /;+\s*$/gm;
    if (trailingSemiRegex.test(fixed)) {
      fixed = fixed.replace(/;+\s*$/gm, '');
      changes.push({ type: 'improvement', description: '移除Python代码中的尾部分号' });
    }
  }

  return { fixedCode: fixed, changes };
}

/**
