      description: '查询的组件',
      enum: ['all', 'memory', 'tools', 'harness', 'evolution', 'scheduler'],
      default: 'all',
    },
    detail_level: {
      type: 'string',
      description: '详情级别',
      enum: ['summary', 'detailed'],
      default: 'summary',
    },
  },
  requiredParams: [],
  requiredPermissions: [],
  riskLevel: 'low',
  idempotent: true,
  timeout: 5000,
};

export interface SystemStatusDeps {
  getMemoryStats: () => Record<string, unknown>;
  getToolStats: () => { registered: number; byCategory: Record<string, number> };
  getHarnessStats: () => { initialized: boolean; config: Record<string, boolean> };
  getEvolutionStats: () => Record<string, unknown>;
  getSchedulerStats: () => Record<string, unknown>;
}

function statusIcon(ok: boolean): string {
  return ok ? '✅' : '⚠️';
}

function formatMemoryStats(stats: Record<string, unknown>, detailed: boolean): string {
  const count = typeof stats.count === 'number' ? stats.count : 0;
  const line = `${statusIcon(true)} 记忆条目: ${count}`;
  if (!detailed) return line;
  const entries = Object.entries(stats)
    .filter(([k]) => k !== 'count')
    .map(([k, v]) => `  ${k}: ${JSON.stringify(v)}`)
    .join('\n');
  return line + (entries ? '\n' + entries : '');
}

function formatToolStats(stats: { registered: number; byCategory: Record<string, number> }, detailed: boolean): string {
  const line = `${statusIcon(true)} 已注册工具: ${stats.registered}`;
  if (!detailed) return line;
  const cats = Object.entries(stats.byCategory)
    .map(([k, v]) => `  ${k}: ${v}`)
    .join('\n');
  return line + (cats ? '\n' + cats : '');
}

function formatHarnessStats(stats: { initialized: boolean; config: Record<string, boolean> }, detailed: boolean): string {
  const icon = statusIcon(stats.initialized);
  const line = `${icon} Harness: ${stats.initialized ? '已初始化' : '未初始化'}`;
  if (!detailed) return line;
  const cfg = Object.entries(stats.config)
    .map(([k, v]) => `  ${k}: ${v ? '✅' : '❌'}`)
    .join('\n');
  return line + (cfg ? '\n' + cfg : '');
}

function formatGenericStats(name: string, stats: Record<string, unknown>, detailed: boolean): string {
  const hasData = Object.keys(stats).length > 0;
  const line = `${statusIcon(hasData)} ${name}: ${hasData ? '正常' : '无数据'}`;
  if (!detailed) return line;
  const entries = Object.entries(stats)
    .map(([k, v]) => `  ${k}: ${JSON.stringify(v)}`)
    .join('\n');
  return line + (entries ? '\n' + entries : '');
}

export function createSystemStatusExecutor(deps: SystemStatusDeps) {
  return async (
    params: Record<string, unknown>,
    _context?: ToolContext
  ): Promise<ToolResult> => {
    const component = String(params.component || 'all');
    const detailed = String(params.detail_level || 'summary') === 'detailed';

    try {
      const lines: string[] = ['📊 系统状态报告\n'];

      if (component === 'all' || component === 'memory') {
        lines.push(formatMemoryStats(deps.getMemoryStats(), detailed));
      }
      if (component === 'all' || component === 'tools') {
        lines.push(formatToolStats(deps.getToolStats(), detailed));
      }
      if (component === 'all' || component === 'harness') {
        lines.push(formatHarnessStats(deps.getHarnessStats(), detailed));
      }
      if (component === 'all' || component === 'evolution') {
        lines.push(formatGenericStats('进化系统', deps.getEvolutionStats(), detailed));
      }
      if (component === 'all' || component === 'scheduler') {
        lines.push(formatGenericStats('调度器', deps.getSchedulerStats(), detailed));
      }

      return { success: true, output: lines.join('\n'), duration: 0, validated: false };
    } catch (err) {
      return { success: false, output: null, error: `状态查询失败: ${(err as Error).message}`, duration: 0, validated: false };
    }
  };
}

/**
 * Harness Tool: task_manage - 任务/待办管理
 */

import type { ToolContext, ToolDefinition, ToolResult } from '../../types';
import { Permission, ToolCategory } from '../../types';

interface TaskEntry {
  id: string;
  title: string;
  description?: string;
  priority: string;
  status: 'pending' | 'completed';
  dueDate?: string;
  tags: string[];
  createdAt: number;
  completedAt?: number;
}

export const TASK_MANAGE_DEF: ToolDefinition = {
  name: 'task_manage',
  description:
    '管理任务和待办事项。支持创建、查看、完成、删除和更新任务。适用场景：用户需要记录待办、管理任务列表、追踪任务进度。不适用：纯信息查询。',
  category: ToolCategory.DAILY,
  parameters: {
    action: {
      type: 'string',
      description: '操作类型',
      enum: ['create', 'list', 'complete', 'delete', 'update'],
    },
    task_id: {
      type: 'string',
      description: '任务ID（list/complete/delete/update时需要）',
    },
    title: {
      type: 'string',
      description: '任务标题（create时需要）',
    },
    description: {
      type: 'string',
      description: '任务描述',
    },
    priority: {
      type: 'string',
      description: '优先级',
      enum: ['low', 'medium', 'high'],
      default: 'medium',
    },
    due_date: {
      type: 'string',
      description: '截止日期',
    },
    tags: {
      type: 'array',
      description: '标签',
      items: { type: 'string', description: '标签名' },
    },
  },
  requiredParams: ['action'],
  requiredPermissions: [Permission.MEMORY_WRITE],
  riskLevel: 'low',
  idempotent: false,
  timeout: 5000,
};

export interface TaskManageDeps {
  taskStore: {
    getTasks(): Promise<TaskEntry[]>;
    saveTask(task: TaskEntry): Promise<void>;
    deleteTask(id: string): Promise<void>;
  };
}

function generateId(): string {
  return Date.now().toString(36) + Math.random().toString(36).slice(2);
}

function formatTaskList(tasks: TaskEntry[]): string {
  if (tasks.length === 0) return '暂无任务';
  return tasks
    .map((t) => {
      const icon = t.status === 'completed' ? '✅' : '⏳';
      const priority = t.priority === 'high' ? '🔴' : t.priority === 'low' ? '🟢' : '🟡';
      const due = t.dueDate ? ` 📅${t.dueDate}` : '';
      const tagStr = t.tags.length > 0 ? ` [${t.tags.join(',')}]` : '';
      return `${icon} [${t.id}] ${t.title}${tagStr}${due} ${priority}`;
    })
    .join('\n');
}

export function createTaskManageExecutor(deps: TaskManageDeps) {
  return async (
    params: Record<string, unknown>,
    _context?: ToolContext
  ): Promise<ToolResult> => {
    const action = String(params.action || '');

    try {
      switch (action) {
        case 'create': {
          const title = String(params.title || '');
          if (!title) {
            return { success: false, output: null, error: '创建任务需要提供标题', duration: 0, validated: false };
          }
          const task: TaskEntry = {
            id: generateId(),
            title,
            description: params.description ? String(params.description) : undefined,
            priority: String(params.priority || 'medium'),
            status: 'pending',
            dueDate: params.due_date ? String(params.due_date) : undefined,
            tags: Array.isArray(params.tags) ? params.tags.map(String) : [],
            createdAt: Date.now(),
          };
          await deps.taskStore.saveTask(task);
          return { success: true, output: `任务已创建: [${task.id}] ${task.title}`, duration: 0, validated: false };
        }

        case 'list': {
          const tasks = await deps.taskStore.getTasks();
          return { success: true, output: formatTaskList(tasks), duration: 0, validated: false };
        }

        case 'complete': {
          const taskId = String(params.task_id || '');
          if (!taskId) {
            return { success: false, output: null, error: '完成任务需要提供task_id', duration: 0, validated: false };
          }
          const tasks = await deps.taskStore.getTasks();
          const task = tasks.find((t) => t.id === taskId);
          if (!task) {
            return { success: false, output: null, error: `任务不存在: ${taskId}`, duration: 0, validated: false };
          }
          task.status = 'completed';
          task.completedAt = Date.now();
          await deps.taskStore.saveTask(task);
          return { success: true, output: `任务已完成: [${task.id}] ${task.title}`, duration: 0, validated: false };
        }

        case 'delete': {
          const taskId = String(params.task_id || '');
          if (!taskId) {
            return { success: false, output: null, error: '删除任务需要提供task_id', duration: 0, validated: false };
          }
          await deps.taskStore.deleteTask(taskId);
          return { success: true, output: `任务已删除: ${taskId}`, duration: 0, validated: false };
        }

        case 'update': {
          const taskId = String(params.task_id || '');
          if (!taskId) {
            return { success: false, output: null, error: '更新任务需要提供task_id', duration: 0, validated: false };
          }
          const tasks = await deps.taskStore.getTasks();
          const task = tasks.find((t) => t.id === taskId);
          if (!task) {
            return { success: false, output: null, error: `任务不存在: ${taskId}`, duration: 0, validated: false };
          }
          if (params.title) task.title = String(params.title);
          if (params.description) task.description = String(params.description);
          if (params.priority) task.priority = String(params.priority);
          if (params.due_date) task.dueDate = String(params.due_date);
          if (Array.isArray(params.tags)) task.tags = params.tags.map(String);
          await deps.taskStore.saveTask(task);
          return { success: true, output: `任务已更新: [${task.id}] ${task.title}`, duration: 0, validated: false };
        }

        default:
          return { success: false, output: null, error: `未知操作: ${action}`, duration: 0, validated: false };
      }
    } catch (err) {
      return { success: false, output: null, error: `任务操作失败: ${(err as Error).message}`, duration: 0, validated: false };
    }
  };
}

/**
 * Harness Tool: desktop_screenshot - 截取屏幕截图
 */

import type { ToolContext, ToolDefinition, ToolResult } from '../../types';
import { Permission, ToolCategory } from '../../types';

export const DESKTOP_SCREENSHOT_DEF: ToolDefinition = {
  name: 'desktop_screenshot',
  description:
    '截取屏幕截图并可选进行视觉分析。适用场景：用户说"看看我屏幕上是什么"、"帮我截个图"、需要了解用户桌面状态时。不适用：自动化操作桌面（用 desktop_automate）。',
  category: ToolCategory.DESKTOP,
  parameters: {
    region: {
      type: 'object',
      description: '截取区域 {x, y, width, height}，不指定则截取全屏',
      properties: {
        x: { type: 'number', description: '起始X坐标' },
        y: { type: 'number', description: '起始Y坐标' },
        width: { type: 'number', description: '宽度' },
        height: { type: 'number', description: '高度' },
      },
    },
    screenIndex: {
      type: 'number',
      description: '显示器索引（多显示器时使用），默认0为主显示器',
      default: 0,
    },
    analyze: {
      type: 'boolean',
      description: '是否对截图进行视觉分析（描述截图内容）',
      default: false,
    },
  },
  requiredParams: [],
  requiredPermissions: [Permission.DESKTOP_CONTROL],
  riskLevel: 'high',
  idempotent: true,
  timeout: 15000,
  requiresConfirmation: true,
};

/** desktop_screenshot 依赖接口 */
export interface DesktopScreenshotDeps {
  captureScreen?: (params: {
    region?: { x: number; y: number; width: number; height: number };
    screenIndex?: number;
  }) => Promise<{
    buffer: Buffer;
    width: number;
    height: number;
  }>;
  analyzeImage?: (imageBuffer: Buffer) => Promise<string>;
}

/** 创建 desktop_screenshot 执行器 */
export function createDesktopScreenshotExecutor(deps: DesktopScreenshotDeps) {
  return async (
    params: Record<string, unknown>,
    _context?: ToolContext
  ): Promise<ToolResult> => {
    const region = params.region as
      | { x: number; y: number; width: number; height: number }
      | undefined;
    const screenIndex = Number(params.screenIndex) || 0;
    const analyze = Boolean(params.analyze);

    if (!deps.captureScreen) {
      return {
        success: false,
        output: '截图服务不可用。请确保已安装 screenshot-desktop 依赖。',
        duration: 0,
        validated: false,
      };
    }

    try {
      const screenshot = await deps.captureScreen({
        region,
        screenIndex,
      });

      let output = `截图成功: ${screenshot.width}x${screenshot.height}, 大小 ${(screenshot.buffer.length / 1024).toFixed(1)}KB`;

      if (analyze && deps.analyzeImage) {
        const analysis = await deps.analyzeImage(screenshot.buffer);
        output += `\n\n视觉分析: ${analysis}`;
      } else if (analyze) {
        output += '\n\n视觉分析不可用，仅返回截图数据。';
      }

      return {
        success: true,
        output,
        duration: 0,
        validated: false,
        metadata: {
          width: screenshot.width,
          height: screenshot.height,
          sizeKB: Math.round(screenshot.buffer.length / 1024),
          analyzed: analyze && !!deps.analyzeImage,
        },
      };
    } catch (error) {
      return {
        success: false,
        output: `截图失败: ${(error as Error).message}`,
        error: (error as Error).message,
        duration: 0,
        validated: false,
      };
    }
  };
}

/**
 * Harness Tool: file_list - 列出目录内容
 */

import type { ToolContext, ToolDefinition, ToolResult } from '../../types';
import { Permission, ToolCategory } from '../../types';

export const FILE_LIST_DEF: ToolDefinition = {
  name: 'file_list',
  description:
    '列出指定目录下的文件和子目录。适用场景：需要了解项目结构、查找某个目录下有哪些文件、确认文件是否存在。不适用：搜索文件内容（用 file_search）。',
  category: ToolCategory.FILE,
  parameters: {
    directory: {
      type: 'string',
      description: '要列出的目录路径，默认为项目根目录',
    },
    pattern: {
      type: 'string',
      description: '文件名匹配模式，如 "*.ts"、"src/**"',
      default: '*',
    },
    recursive: {
      type: 'boolean',
      description: '是否递归列出子目录内容',
      default: false,
    },
  },
  requiredParams: [],
  requiredPermissions: [Permission.FILE_READ],
  riskLevel: 'low',
  idempotent: true,
  timeout: 10000,
};

/** file_list 依赖接口 */
export interface FileListDeps {
  listDirectory?: (params: {
    directory: string;
    pattern: string;
    recursive: boolean;
  }) => Promise<
    Array<{
      name: string;
      path: string;
      type: 'file' | 'directory';
      size?: number;
    }>
  >;
}

/** 创建 file_list 执行器 */
export function createFileListExecutor(deps: FileListDeps) {
  return async (
    params: Record<string, unknown>,
    _context?: ToolContext
  ): Promise<ToolResult> => {
    const directory = (params.directory as string) || '.';
    const pattern = (params.pattern as string) || '*';
    const recursive = Boolean(params.recursive);

    if (!deps.listDirectory) {
      return {
        success: false,
        output: '目录列表服务不可用。请直接提供文件路径。',
        duration: 0,
        validated: false,
      };
    }

    try {
      const entries = await deps.listDirectory({
        directory,
        pattern,
        recursive,
      });

      if (entries.length === 0) {
        return {
          success: true,
          output: `目录 "${directory}" 为空或无匹配项`,
          duration: 0,
          validated: false,
        };
      }

      const formatted = entries
        .map((e) => `${e.type === 'directory' ? '📁' : '📄'} ${e.path}`)
        .join('\n');

      return {
        success: true,
        output: formatted,
        duration: 0,
        validated: false,
        metadata: {
          totalFiles: entries.filter((e) => e.type === 'file').length,
          totalDirs: entries.filter((e) => e.type === 'directory').length,
        },
      };
    } catch (error) {
      return {
        success: false,
        output: `目录列表失败: ${(error as Error).message}`,
        error: (error as Error).message,
        duration: 0,
        validated: false,
      };
    }
  };
}

/**
 * Harness Tool: file_search - 在文件内容中搜索关键词
 */

import type { ToolContext, ToolDefinition, ToolResult } from '../../types';
import { Permission, ToolCategory } from '../../types';

export const FILE_SEARCH_DEF: ToolDefinition = {
  name: 'file_search',
  description:
    '在文件内容中搜索关键词或模式。适用场景：查找某个函数定义、搜索包含特定文本的文件、定位代码中的某个配置项。不适用：按文件名查找（用 file_list）。',
  category: ToolCategory.FILE,
  parameters: {
    query: {
      type: 'string',
      description: '搜索关键词或正则表达式',
    },
    directory: {
      type: 'string',
      description: '搜索目录路径，默认为项目根目录',
    },
    filePattern: {
      type: 'string',
      description: '文件匹配模式，如 "*.ts"、"*.json"',
      default: '*',
    },
    maxResults: {
      type: 'number',
      description: '最大返回结果数，默认20',
      default: 20,
    },
  },
  requiredParams: ['query'],
  requiredPermissions: [Permission.FILE_READ],
  riskLevel: 'low',
  idempotent: true,
  timeout: 15000,
};

/** file_search 依赖接口 */
export interface FileSearchDeps {
  searchInFiles?: (params: {
    query: string;
    directory?: string;
    filePattern?: string;
    maxResults?: number;
  }) => Promise<
    Array<{
      filePath: string;
      line: number;
      content: string;
      match: string;
    }>
  >;
}

/** 创建 file_search 执行器 */
export function createFileSearchExecutor(deps: FileSearchDeps) {
  return async (
    params: Record<string, unknown>,
    _context?: ToolContext
  ): Promise<ToolResult> => {
    const query = String(params.query || '');
    const directory = params.directory as string | undefined;
    const filePattern = (params.filePattern as string) || '*';
    const maxResults = Number(params.maxResults) || 20;

    if (!deps.searchInFiles) {
      return {
        success: false,
        output: '文件搜索服务不可用。请直接提供文件路径。',
        duration: 0,
        validated: false,
      };
    }

    try {
      const results = await deps.searchInFiles({
        query,
        directory,
        filePattern,
        maxResults,
      });

      if (results.length === 0) {
        return {
          success: true,
          output: `未找到包含"${query}"的内容`,
          duration: 0,
          validated: false,
        };
      }

      const formatted = results
        .map(
          (r, i) =>
            `${i + 1}. ${r.filePath}:${r.line} — ${r.match}`
        )
        .join('\n');

      return {
        success: true,
        output: formatted,
        duration: 0,
        validated: false,
        metadata: { resultCount: results.length },
      };
    } catch (error) {
      return {
        success: false,
        output: `搜索失败: ${(error as Error).message}`,
        error: (error as Error).message,
        duration: 0,
        validated: false,
      };
    }
  };
}

