} from './memory/memory_search';
import {
  createMemoryStoreExecutor,
  type MemoryStoreDeps,
} from './memory/memory_store';
import { createAskClarificationExecutor } from './system/ask_clarification';
import { createPreviewExecutionExecutor } from './system/preview_execution';
import {
  createRollbackChangesExecutor,
  type RollbackChangesDeps,
} from './system/rollback_changes';

// === 日常管理工具执行器工厂 ===
import { createNoteTakeExecutor, type NoteTakeDeps } from './daily/note_take';
import { createReminderSetExecutor, type ReminderSetDeps } from './daily/reminder_set';
import { createSystemStatusExecutor, type SystemStatusDeps } from './daily/system_status';
import { createTaskManageExecutor, type TaskManageDeps } from './daily/task_manage';

// === 网络工具执行器工厂 ===
import { createWebSearchExecutor, type WebSearchDeps } from './network/web_search';
import { createSkillCreateExecutor, type SkillCreateDeps } from './network/skill_create';

/** 所有工具依赖的聚合接口 */
export interface HarnessToolDeps
  extends
    MemoryRecallDeps,
    MemoryStoreDeps,
    MemorySearchDeps,
    EmotionDetectDeps,
    SceneAnalyzeDeps,
    SelfReflectDeps,
    DesktopScreenshotDeps,
    RollbackChangesDeps,
    IncrementalEditDeps,
    MultiFileEditDeps,
    FileSearchDeps,
    FileListDeps,
    GetActiveFileDeps,
    CodeGenerateDeps,
    CodeAnalyzeDeps,
    CodeFixDeps,
    TaskManageDeps,
    ReminderSetDeps,
    NoteTakeDeps,
    SystemStatusDeps,
    WebSearchDeps,
    SkillCreateDeps {}

/** 工具注册结果 */
export interface ToolRegistrationResult {
  toolRegistry: ToolRegistry;
  schemaValidator: SchemaValidator;
  permissionGuard: PermissionGuard;
  registeredCount: number;
}

/**
 * 注册所有 Harness 工具到 ToolRegistry
 */
export function registerHarnessTools(
  deps: HarnessToolDeps
): ToolRegistrationResult {
  const toolRegistry = new ToolRegistry();
  const schemaValidator = new SchemaValidator();
  const permissionGuard = new PermissionGuard();

  // 记忆工具 (3)
  toolRegistry.register(MEMORY_RECALL_DEF, createMemoryRecallExecutor(deps));
  toolRegistry.register(MEMORY_STORE_DEF, createMemoryStoreExecutor(deps));
  toolRegistry.register(MEMORY_SEARCH_DEF, createMemorySearchExecutor(deps));

  // 认知工具 (3)
  toolRegistry.register(EMOTION_DETECT_DEF, createEmotionDetectExecutor(deps));
  toolRegistry.register(SCENE_ANALYZE_DEF, createSceneAnalyzeExecutor(deps));
  toolRegistry.register(SELF_REFLECT_DEF, createSelfReflectExecutor(deps));

  // 桌面工具 (2)
  toolRegistry.register(DESKTOP_AUTOMATE_DEF, createDesktopAutomateExecutor());
  toolRegistry.register(
    DESKTOP_SCREENSHOT_DEF,
    createDesktopScreenshotExecutor(deps)
  );

  // 系统工具 (3)
  toolRegistry.register(
    ASK_CLARIFICATION_DEF,
    createAskClarificationExecutor()
  );
  toolRegistry.register(
    PREVIEW_EXECUTION_DEF,
    createPreviewExecutionExecutor()
  );
  toolRegistry.register(
    ROLLBACK_CHANGES_DEF,
    createRollbackChangesExecutor(deps)
  );

  // 文件工具 (5)
  toolRegistry.register(GET_ACTIVE_FILE_DEF, createGetActiveFileExecutor(deps));
  toolRegistry.register(
    INCREMENTAL_EDIT_DEF,
    createIncrementalEditExecutor(deps)
  );
  toolRegistry.register(MULTI_FILE_EDIT_DEF, createMultiFileEditExecutor(deps));
  toolRegistry.register(FILE_SEARCH_DEF, createFileSearchExecutor(deps));
  toolRegistry.register(FILE_LIST_DEF, createFileListExecutor(deps));

  // 代码工具 (3)
  toolRegistry.register(CODE_GENERATE_DEF, createCodeGenerateExecutor(deps));
  toolRegistry.register(CODE_ANALYZE_DEF, createCodeAnalyzeExecutor(deps));
  toolRegistry.register(CODE_FIX_DEF, createCodeFixExecutor(deps));

  // 日常管理工具 (4)
  toolRegistry.register(TASK_MANAGE_DEF, createTaskManageExecutor(deps));
  toolRegistry.register(REMINDER_SET_DEF, createReminderSetExecutor(deps));
  toolRegistry.register(NOTE_TAKE_DEF, createNoteTakeExecutor(deps));
  toolRegistry.register(SYSTEM_STATUS_DEF, createSystemStatusExecutor(deps));

  // 网络工具 (2)
  toolRegistry.register(WEB_SEARCH_DEF, createWebSearchExecutor(deps));
  toolRegistry.register(SKILL_CREATE_DEF, createSkillCreateExecutor(deps));

  Logger.info(
    `🔧 Harness 工具注册完成: ${toolRegistry.size} 个工具`,
    'HarnessToolRegistrar'
  );

  return {
    toolRegistry,
    schemaValidator,
    permissionGuard,
    registeredCount: toolRegistry.size,
  };
}

/**
 * 将 Harness 工具同步注册到旧版 SkillRegistry（双写兼容）
 * 确保 InfrastructureToolRegistrar 的功能不退化
 */
export function syncToLegacySkillRegistry(
  toolRegistry: ToolRegistry,
  skillRegistry: SkillRegistry
): void {
  const tools = toolRegistry.getAll();

  for (const tool of tools) {
    const def = tool.definition;
    skillRegistry.registerInfrastructureTool({
      name: def.name,
      description: def.description,
      parameters: Object.entries(def.parameters).map(
        ([name, paramDef]: [string, import('../types').ToolParameterDef]) => ({
          name,
          type: paramDef.type,
          required: def.requiredParams.includes(name),
          description: paramDef.description,
        })
      ),
      execute: async (args, context) => {
        const userPerms = context?.sessionData?.permissions;
        const permissions = Array.isArray(userPerms) && userPerms.length > 0
          ? new Set<Permission>(userPerms as Permission[])
          : new Set<Permission>([
              Permission.MEMORY_READ,
              Permission.MEMORY_WRITE,
              Permission.FILE_READ,
            ]);
        const toolContext: import('../types').ToolContext = {
          userId: context?.userId,
          traceId: context?.traceId,
          permissions,
          metadata: {},
        };
        const result = await tool.execute(args, toolContext);
        return {
          success: result.success,
          output: result.output,
          error: result.error,
          metadata: result.metadata,
        };
      },
    });
  }

  Logger.info(
    `🔄 已同步 ${tools.length} 个 Harness 工具到旧版 SkillRegistry`,
    'HarnessToolRegistrar'
  );
}

/**
 * Harness Layer 2: Tools - 权限守卫
 *
 * 工具执行前的权限检查
 * 基于 Permission 枚举和 RiskLevel 分级控制
 */

import { Logger } from '../../../utils/Logger';
import { Permission } from '../../types';
import type { RiskLevel, ToolContext } from '../../types';

/** 权限检查结果 */
export interface PermissionCheckResult {
  allowed: boolean;
  missing: Permission[];
  reason?: string;
}

/** 风险等级对应的确认要求 */
const RISK_CONFIRMATION_MAP: Record<RiskLevel, boolean> = {
  low: false,
  medium: false,
  high: true,
  critical: true,
};

/** 默认权限集 — 普通用户 */
const DEFAULT_PERMISSIONS: Permission[] = [
  Permission.MEMORY_READ,
  Permission.MEMORY_WRITE,
  Permission.FILE_READ,
  Permission.FILE_WRITE,
  Permission.CODE_EXECUTE,
];

/** 管理员权限集 */
const ADMIN_PERMISSIONS: Permission[] = [
  ...DEFAULT_PERMISSIONS,
  Permission.DESKTOP_CONTROL,
  Permission.NETWORK_ACCESS,
  Permission.SYSTEM_ADMIN,
];

export class PermissionGuard {
  /** 用户权限缓存 */
  private userPermissions: Map<string, Set<Permission>> = new Map();

  /** 待确认的操作 */
  private pendingConfirmations: Map<
    string,
    {
      toolName: string;
      riskLevel: RiskLevel;
      resolve: (confirmed: boolean) => void;
    }
  > = new Map();

  /**
   * 检查工具执行权限
   */
  check(
    toolName: string,
    requiredPermissions: Permission[],
    riskLevel: RiskLevel,
    context: ToolContext
  ): PermissionCheckResult {
    const userPerms = context.permissions;

    // 检查缺失的权限
    const missing: Permission[] = [];
    for (const perm of requiredPermissions) {
      if (!userPerms.has(perm)) {
        missing.push(perm);
      }
    }

    if (missing.length > 0) {
      Logger.warn(
        `🚫 权限不足: ${toolName} 缺少 [${missing.join(', ')}]`,
        'PermissionGuard'
      );
      return {
        allowed: false,
        missing,
        reason: `缺少权限: ${missing.join(', ')}`,
      };
    }

    // 检查风险等级是否需要确认
    if (RISK_CONFIRMATION_MAP[riskLevel]) {
      Logger.info(
        `⚠️ 高风险操作: ${toolName} 风险=${riskLevel}，需要确认`,
        'PermissionGuard'
      );
      // 实际确认逻辑由 Constraints 层的 LifecycleHook 处理
      // 这里只记录，不阻止（确认是异步流程）
    }

    return { allowed: true, missing: [] };
  }

  /**
   * 获取用户权限集
   */
  getUserPermissions(userId: string): Set<Permission> {
    let perms = this.userPermissions.get(userId);
    if (!perms) {
      perms = new Set(DEFAULT_PERMISSIONS);
      this.userPermissions.set(userId, perms);
    }
    return perms;
  }

  /**
   * 授予用户权限
   */
  grantPermission(userId: string, permission: Permission): void {
    const perms = this.getUserPermissions(userId);
    perms.add(permission);
    Logger.info(
      `✅ 授予权限: ${permission} → 用户 ${userId}`,
      'PermissionGuard'
    );
  }

  /**
   * 撤销用户权限
   */
  revokePermission(userId: string, permission: Permission): void {
    const perms = this.getUserPermissions(userId);
    perms.delete(permission);
    Logger.info(
      `❌ 撤销权限: ${permission} → 用户 ${userId}`,
      'PermissionGuard'
    );
  }

  /**
   * 设置用户为管理员
   */
  setAdmin(userId: string): void {
    this.userPermissions.set(userId, new Set(ADMIN_PERMISSIONS));
    Logger.info(`👑 设置管理员: ${userId}`, 'PermissionGuard');
  }

  /**
   * 请求确认高风险操作
   */
  async requestConfirmation(
    toolName: string,
    riskLevel: RiskLevel,
    timeoutMs: number = 30000
  ): Promise<boolean> {
    const confirmationId = `${toolName}-${Date.now()}`;

    return new Promise<boolean>((resolve) => {
      this.pendingConfirmations.set(confirmationId, {
        toolName,
        riskLevel,
        resolve,
      });

      // 超时自动拒绝
      setTimeout(() => {
        const pending = this.pendingConfirmations.get(confirmationId);
        if (pending) {
          this.pendingConfirmations.delete(confirmationId);
          Logger.warn(
            `⏰ 确认超时: ${toolName}，自动拒绝`,
            'PermissionGuard'
          );
          resolve(false);
        }
      }, timeoutMs);
    });
  }

  /**
   * 确认操作
   */
  confirm(confirmationId: string, approved: boolean): void {
    const pending = this.pendingConfirmations.get(confirmationId);
    if (pending) {
      this.pendingConfirmations.delete(confirmationId);
      pending.resolve(approved);
      Logger.info(
        `${approved ? '✅' : '❌'} 用户${approved ? '确认' : '拒绝'}: ${pending.toolName}`,
        'PermissionGuard'
      );
    }
  }
}

/**
 * Harness Layer 2: Tools - Schema 验证器
 *
 * JSON Schema 风格的工具参数验证
 * 防止参数注入和类型错误
 */

import { Logger } from '../../../utils/Logger';
import type { ToolParameterDef } from '../../types';

/** 验证结果 */
export interface SchemaValidationResult {
  valid: boolean;
  errors: string[];
  /** 自动修复后的参数 */
  sanitizedParams: Record<string, unknown>;
}

export class SchemaValidator {
  /**
   * 验证工具参数
   * @param params 用户传入的参数
   * @param parameterDefs 工具参数定义
   * @param requiredParams 必填参数名列表
   */
  validate(
    params: Record<string, unknown>,
    parameterDefs: Record<string, ToolParameterDef>,
    requiredParams: string[]
  ): SchemaValidationResult {
    const errors: string[] = [];
    const sanitizedParams: Record<string, unknown> = {};

    // 检查必填参数
    for (const required of requiredParams) {
      if (params[required] === undefined || params[required] === null) {
        errors.push(`缺少必填参数: ${required}`);
      }
    }

    // 验证每个参数
    for (const [paramName, paramDef] of Object.entries(parameterDefs)) {
      const value = params[paramName];

      // 参数不存在
      if (value === undefined || value === null) {
        // 使用默认值
        if (paramDef.default !== undefined) {
          sanitizedParams[paramName] = paramDef.default;
        }
        continue;
      }

      // 类型验证
      const typeError = this.validateType(paramName, value, paramDef);
      if (typeError) {
        errors.push(typeError);
        continue;
      }

      // 枚举验证
      if (paramDef.enum && !paramDef.enum.includes(String(value))) {
        errors.push(
          `参数 ${paramName} 的值 "${value}" 不在允许范围内: [${paramDef.enum.join(', ')}]`
        );
        continue;
      }

      // 数组元素验证
      if (paramDef.type === 'array' && Array.isArray(value) && paramDef.items) {
        for (let i = 0; i < value.length; i++) {
          const itemError = this.validateType(
            `${paramName}[${i}]`,
            value[i],
            paramDef.items
          );
          if (itemError) {
            errors.push(itemError);
          }
        }
      }

      // 对象属性验证
      if (
        paramDef.type === 'object' &&
        typeof value === 'object' &&
        value !== null &&
        paramDef.properties
      ) {
        const objResult = this.validate(
          value as Record<string, unknown>,
          paramDef.properties,
          [] // 嵌套对象的必填检查由外层控制
        );
        if (!objResult.valid) {
          errors.push(...objResult.errors.map((e) => `${paramName}.${e}`));
        }
      }

      sanitizedParams[paramName] = value;
    }

    // 检查未知参数（仅警告，不阻止执行）
    for (const paramName of Object.keys(params)) {
      if (!(paramName in parameterDefs)) {
        Logger.debug(
          `未知参数: ${paramName}（已忽略）`,
          'SchemaValidator'
        );
        sanitizedParams[paramName] = params[paramName];
      }
    }

    return {
      valid: errors.length === 0,
      errors,
      sanitizedParams,
    };
  }

  /**
   * 验证参数类型
   */
  private validateType(
    paramName: string,
    value: unknown,
    paramDef: ToolParameterDef
  ): string | null {
    const actualType = this.getTypeOf(value);

    if (actualType !== paramDef.type) {
      // 宽松类型转换: string "123" → number
      if (paramDef.type === 'number' && typeof value === 'string') {
        const num = Number(value);
        if (!isNaN(num)) {
          return null; // 允许字符串数字
        }
      }

      // 宽松类型转换: string "true" → boolean
      if (paramDef.type === 'boolean' && typeof value === 'string') {
        if (value === 'true' || value === 'false') {
          return null;
        }
      }

      return `参数 ${paramName} 类型错误: 期望 ${paramDef.type}, 实际 ${actualType}`;
    }

    return null;
  }

  /**
   * 获取值的类型名
   */
  private getTypeOf(value: unknown): string {
    if (value === null) return 'null';
    if (value === undefined) return 'undefined';
    if (Array.isArray(value)) return 'array';
    return typeof value;
  }
}

