import {
  IntegrationPlatform,
  PlatformConfig,
  IntegrationPlatformInfo,
  IntegrationStatus,
  SendMessageRequest,
  SendMessageResponse,
  IncomingMessageEvent,
} from '../shared/contracts';
import { Logger } from '../utils/Logger';
import { BaseIntegrationAdapter } from './adapters/BaseIntegrationAdapter';
import { WeChatAdapter } from './adapters/WeChatAdapter';
import { WeChatQRAdapter } from './adapters/WeChatQRAdapter';
import { FeishuAdapter } from './adapters/FeishuAdapter';
import { DingTalkAdapter } from './adapters/DingTalkAdapter';
import { QQAdapter } from './adapters/QQAdapter';
import { EventBus } from '../shared/EventBus';
import type { JiabaixingCore } from '../core/JiabaixingCore';

const PLATFORM_INFO: Record<IntegrationPlatform, Omit<IntegrationPlatformInfo, 'status' | 'available'>> = {
  wechat: {
    id: 'wechat',
    name: '微信',
    icon: '💬',
    description: '扫码登录个人微信 / 企业号/公众号',
    enabled: true,
  },
  feishu: {
    id: 'feishu',
    name: '飞书',
    icon: '✈️',
    description: '连接到飞书平台',
    enabled: true,
  },
  dingtalk: {
    id: 'dingtalk',
    name: '钉钉',
    icon: '📌',
    description: '连接到钉钉平台',
    enabled: true,
  },
  qq: {
    id: 'qq',
    name: 'QQ',
    icon: '🐧',
    description: '通过 Mirai 连接 QQ 机器人',
    enabled: true,
  },
};

export class IntegrationManager {
  private adapters: Map<IntegrationPlatform, BaseIntegrationAdapter> =
    new Map();
  private static instance: IntegrationManager;
  private core: JiabaixingCore | null = null;

  private constructor() {
    this.initializeAdapters();
  }

  static getInstance(): IntegrationManager {
    if (!IntegrationManager.instance) {
      IntegrationManager.instance = new IntegrationManager();
    }
    return IntegrationManager.instance;
  }

  setCore(core: JiabaixingCore): void {
    this.core = core;
    Logger.info('✅ JiabaixingCore 已注入到 IntegrationManager', 'IntegrationManager');
  }

  private initializeAdapters(): void {
    // 默认用官方 API 模式
    this.adapters.set('wechat', new WeChatAdapter());
    this.adapters.set('feishu', new FeishuAdapter());
    this.adapters.set('dingtalk', new DingTalkAdapter());
    this.adapters.set('qq', new QQAdapter());

    // 为每个适配器注册消息处理
    for (const adapter of this.adapters.values()) {
      adapter.onMessage(async (message: IncomingMessageEvent) => {
        void this.handleIncomingMessage(message);
      });
    }

    Logger.info('集成管理器初始化完成', 'IntegrationManager');

    // 如果环境变量配置了 QQ，自动连接
    void this.autoConnectQQ();
  }

  /**
   * 从环境变量自动连接 QQ
   */
  private async autoConnectQQ(): Promise<void> {
    const qqConfig = QQAdapter.loadConfigFromEnv();
    if (!qqConfig) {
      Logger.info('QQ 自动连接未启用 (QQ_ENABLED=false)', 'IntegrationManager');
      return;
    }

    Logger.info('检测到 QQ 环境变量配置，正在自动连接...', 'IntegrationManager');

    // 等待 2 秒让系统完全就绪
    await new Promise(resolve => setTimeout(resolve, 2000));

    const success = await this.connectPlatform('qq', qqConfig);
    if (success) {
      Logger.info('QQ 机器人自动连接成功', 'IntegrationManager');
    } else {
      Logger.warn('QQ 机器人自动连接失败，将在后台自动重试', 'IntegrationManager');
    }
  }

  /**
   * 获取所有支持的平台信息
   */
  getPlatforms(): IntegrationPlatformInfo[] {
    const platforms: IntegrationPlatformInfo[] = [];
    for (const [key, info] of Object.entries(PLATFORM_INFO)) {
      const adapter = this.adapters.get(key as IntegrationPlatform);
      platforms.push({
        ...info,
        available: true,
        status: adapter?.getStatus(),
      });
    }
    return platforms;
  }

  /**
   * 连接到指定平台
   */
  async connectPlatform(
    platform: IntegrationPlatform,
    config: PlatformConfig
  ): Promise<boolean> {
    // 微信 QR 扫码模式：替换为 QR 适配器
    if (platform === 'wechat' && config.mode === 'qr') {
      const qrAdapter = new WeChatQRAdapter();
      this.adapters.set('wechat', qrAdapter);
      qrAdapter.onMessage(async (message: IncomingMessageEvent) => {
        void this.handleIncomingMessage(message);
      });
    }

    const adapter = this.adapters.get(platform);
    if (!adapter) {
      Logger.warn(`不支持的平台: ${platform}`, 'IntegrationManager');
      return false;
    }

    try {
      const success = await adapter.connect(config);
      if (success) {
        EventBus.emit('integration_connected', {
          platform,
          timestamp: new Date().toISOString(),
        });
        Logger.info(`成功连接到 ${platform}`, 'IntegrationManager');
      }
      return success;
    } catch (error) {
      Logger.error(
        `连接 ${platform} 失败`,
        error as Error,
        'IntegrationManager'
      );
      return false;
    }
  }

  /**
   * 断开平台连接
   */
  async disconnectPlatform(platform: IntegrationPlatform): Promise<void> {
    const adapter = this.adapters.get(platform);
    if (!adapter) {
      return;
    }
    await adapter.disconnect();
    EventBus.emit('integration_disconnected', {
      platform,
      timestamp: new Date().toISOString(),
    });
    Logger.info(`断开了 ${platform} 的连接`, 'IntegrationManager');
  }

  /**
   * 发送消息到指定平台
   */
  async sendMessage(
    request: SendMessageRequest
  ): Promise<SendMessageResponse> {
    const adapter = this.adapters.get(request.platform);
    if (!adapter) {
      return {
        success: false,
        error: '不支持的平台',
      };
    }
    return await adapter.sendMessage(
      request.message,
      request.to,
      request.imageUrls,
      request.mentions
    );
  }

  /**
   * 处理 Webhook
   */
  async handleWebhook(
    platform: IntegrationPlatform,
    payload: Record<string, unknown>
  ): Promise<{ success: boolean; response?: unknown }> {
    const adapter = this.adapters.get(platform);
    if (!adapter) {
      return { success: false };
    }
    return await adapter.handleWebhook(payload);
  }

  /**
   * 获取平台状态
   */
  getPlatformStatus(
    platform: IntegrationPlatform
  ): IntegrationStatus | undefined {
    return this.adapters.get(platform)?.getStatus();
  }

  /**
   * 获取微信 QR 扫码状态（仅限 QR 模式）
   */
  getWeChatQRState(): { qrCodeBase64: string | null; status: string; botNickname: string | null } | null {
    const adapter = this.adapters.get('wechat');
    if (adapter instanceof WeChatQRAdapter) {
      const state = adapter.getQRState();
      return {
        qrCodeBase64: state.qrCodeBase64,
        status: state.status,
        botNickname: state.botNickname,
      };
    }
    return null;
  }

  /**
   * 处理收到的消息
   */
  private async handleIncomingMessage(message: IncomingMessageEvent): Promise<void> {
    Logger.info(
      `收到来自 ${message.platform} 的消息: ${message.from}`,
      'IntegrationManager'
    );

    // 通过 EventBus 广播消息
    EventBus.emit('integration_message', {
      platform: message.platform,
      type: message.type,
      content: message.content,
      from: message.from,
      fromName: message.fromName,
      timestamp: message.timestamp || new Date().toISOString(),
      rawData: message.rawData,
    });

    // 如果 core 已注入，直接调用 core.processInput 并自动回复
    if (this.core) {
      try {
        Logger.info(
          `📨 路由消息到 core.processInput: ${message.platform} <- ${message.from}: ${message.content.substring(0, 50)}...`,
          'IntegrationManager'
        );

        const result = await this.core.processInput(
          message.content,
          message.from || 'gateway',
          undefined
        );

        if (result.response) {
          await this.sendMessage({
            platform: message.platform,
            message: result.response,
            to: message.from || '',
          });
          Logger.info(
            `📤 回复已发送: ${result.response.substring(0, 50)}...`,
            'IntegrationManager'
          );
        }
      } catch (error) {
        Logger.error(
          'IntegrationManager 处理消息失败',
          error as Error,
          'IntegrationManager'
        );
      }
    }
  }
}

/**
 * TRAE优化系统集成器
 * 将所有效率优化功能集成到jiabaixing系统中
 */

import { EventEmitter } from 'events';
import { ConfigLoader } from '../config/ConfigLoader';
import { MCPServerManager } from '../mcp/MCPServerManager';
import { PerformanceMonitor } from '../monitoring/PerformanceMonitor';
import { SkillRegistry } from '../skills/SkillRegistry';
import { Logger } from '../utils/Logger';

export interface TRAEOptimizationConfig {
  enableMCP: boolean;
  enablePerformanceMonitoring: boolean;
  enableSecurityAudit: boolean;
  enableAutoOptimization: boolean;
  monitoringInterval: number;
  autoOptimizationInterval: number;
}

export interface SystemHealthStatus {
  status: 'healthy' | 'degraded' | 'critical';
  mcpServers: { running: number; total: number };
  performance: {
    responseTime: number;
    memoryUsage: number;
    errorRate: number;
  };
  skills: { registered: number; active: number };
  security: { lastAudit: string; issues: number };
  timestamp: number;
}

export class TRAEOptimizationIntegrator extends EventEmitter {
  private static instance: TRAEOptimizationIntegrator | null = null;
  private config: TRAEOptimizationConfig;
  private mcpManager: MCPServerManager | null = null;
  private performanceMonitor: PerformanceMonitor | null = null;
  private configLoader: ConfigLoader | null = null;
  private skillRegistry: SkillRegistry | null = null;
  private optimizationInterval: NodeJS.Timeout | null = null;
  private healthCheckInterval: NodeJS.Timeout | null = null;
  private initialized: boolean = false;

  private constructor(config?: Partial<TRAEOptimizationConfig>) {
    super();
    this.config = {
      enableMCP: true,
      enablePerformanceMonitoring: true,
      enableSecurityAudit: true,
      enableAutoOptimization: true,
      monitoringInterval: 60000,
      autoOptimizationInterval: 3600000,
      ...config,
    };
  }

  public static getInstance(
    config?: Partial<TRAEOptimizationConfig>
  ): TRAEOptimizationIntegrator {
    if (!TRAEOptimizationIntegrator.instance) {
      TRAEOptimizationIntegrator.instance = new TRAEOptimizationIntegrator(
        config
      );
    }
    return TRAEOptimizationIntegrator.instance;
  }

  public async initialize(): Promise<void> {
    if (this.initialized) {
      Logger.warn('TRAE优化系统集成器已初始化', 'TRAEOptimizationIntegrator');
      return;
    }

    Logger.info(
      '🚀 开始初始化TRAE优化系统集成器...',
      'TRAEOptimizationIntegrator'
    );

    try {
      await this.initializeConfig();
      await this.initializeSkillRegistry();
      await this.initializeMCP();
      await this.initializePerformanceMonitoring();
      await this.registerOptimizedSkills();
      await this.startHealthChecks();
      await this.startAutoOptimization();

      this.initialized = true;
      Logger.info(
        '✅ TRAE优化系统集成器初始化完成',
        'TRAEOptimizationIntegrator'
      );
      this.emit('initialized');
    } catch (error) {
      Logger.error(
        'TRAE优化系统集成器初始化失败',
        error as Error,
        'TRAEOptimizationIntegrator'
      );
      throw error;
    }
  }

  private async initializeConfig(): Promise<void> {
    Logger.info('📋 初始化配置管理...', 'TRAEOptimizationIntegrator');

    this.configLoader = ConfigLoader.getInstance();
    const config = await this.configLoader.loadConfig();

    if (config?.monitoring?.enableMetrics) {
      this.config.enablePerformanceMonitoring = true;
    }

    Logger.info('✅ 配置管理初始化完成', 'TRAEOptimizationIntegrator');
  }

  private async initializeSkillRegistry(): Promise<void> {
    Logger.info('🔧 初始化技能注册中心...', 'TRAEOptimizationIntegrator');

    this.skillRegistry = SkillRegistry.getInstance();
    const skillCount = this.skillRegistry.getSkillCount();

    Logger.info(
      `✅ 技能注册中心初始化完成，已注册 ${skillCount} 个技能`,
      'TRAEOptimizationIntegrator'
    );
  }

  private async initializeMCP(): Promise<void> {
    if (!this.config.enableMCP) {
      Logger.info('⏭️ MCP集成已禁用', 'TRAEOptimizationIntegrator');
      return;
    }

    Logger.info('🌐 初始化MCP服务器管理器...', 'TRAEOptimizationIntegrator');

    this.mcpManager = MCPServerManager.getInstance();

    if (this.configLoader) {
      const mcpServers = this.configLoader.getConfig()?.mcpServers || {};
      Object.entries(mcpServers).forEach(
        ([name, serverConfig]: [string, any]) => {
          this.mcpManager?.registerServer({
            name,
            command: serverConfig._command,
            args: serverConfig._args,
            description: serverConfig._description,
            enabled: true,
          });
        }
      );
    }

    await this.mcpManager.startAllServers();

    const runningCount = this.mcpManager.getRunningServerCount();
    Logger.info(
      `✅ MCP服务器管理器初始化完成，${runningCount} 个服务器运行中`,
      'TRAEOptimizationIntegrator'
    );
  }

  private async initializePerformanceMonitoring(): Promise<void> {
    if (!this.config.enablePerformanceMonitoring) {
      Logger.info('⏭️ 性能监控已禁用', 'TRAEOptimizationIntegrator');
      return;
    }

    Logger.info('📊 初始化性能监控...', 'TRAEOptimizationIntegrator');

    let monitoringConfig = {};
    if (this.configLoader) {
      const config = this.configLoader.getConfig();
      if (config?.monitoring) {
        monitoringConfig = {
          enableMetrics: config.monitoring.enableMetrics,
          logLevel: config.monitoring.logLevel,
          alertThresholds: config.monitoring.alertThresholds,
          performanceTracking: config.monitoring.performanceTracking,
        };
      }
    }

    this.performanceMonitor = PerformanceMonitor.getInstance(monitoringConfig);
    this.performanceMonitor.startMonitoring(this.config.monitoringInterval);

    this.performanceMonitor.on('performanceAlert', (alert) => {
      Logger.warn(
        `⚠️ 性能告警: ${alert.message}`,
        'TRAEOptimizationIntegrator'
      );
      this.emit('performanceAlert', alert);
    });

    Logger.info('✅ 性能监控初始化完成', 'TRAEOptimizationIntegrator');
  }

  private async registerOptimizedSkills(): Promise<void> {
    Logger.info('🎯 优化技能已由 Harness ToolRegistry 统一管理', 'TRAEOptimizationIntegrator');
  }

  private async startHealthChecks(): Promise<void> {
    Logger.info('🏥 启动健康检查...', 'TRAEOptimizationIntegrator');

    this.healthCheckInterval = setInterval(() => {
      void this.performHealthCheck();
    }, 120000);

    Logger.info('✅ 健康检查已启动 (每2分钟)', 'TRAEOptimizationIntegrator');
  }

  private async startAutoOptimization(): Promise<void> {
    if (!this.config.enableAutoOptimization) {
      Logger.info('⏭️ 自动优化已禁用', 'TRAEOptimizationIntegrator');
      return;
    }

    Logger.info('⚡ 启动自动优化...', 'TRAEOptimizationIntegrator');

    this.optimizationInterval = setInterval(() => {
      void this.performAutoOptimization();
    }, this.config.autoOptimizationInterval);

    Logger.info(
      `✅ 自动优化已启动 (每${this.config.autoOptimizationInterval / 60000}分钟)`,
      'TRAEOptimizationIntegrator'
    );
  }

  private async performHealthCheck(): Promise<SystemHealthStatus> {
    const status: SystemHealthStatus = {
      status: 'healthy',
      mcpServers: { running: 0, total: 0 },
      performance: { responseTime: 0, memoryUsage: 0, errorRate: 0 },
      skills: { registered: 0, active: 0 },
      security: { lastAudit: '', issues: 0 },
      timestamp: Date.now(),
    };

    if (this.mcpManager) {
      status.mcpServers.running = this.mcpManager.getRunningServerCount();
      status.mcpServers.total = this.mcpManager.getServerCount();
    }

    if (this.performanceMonitor) {
      const summary = this.performanceMonitor.getSummary();
      status.performance = {
        responseTime: summary.averageResponseTime,
        memoryUsage: summary.currentMemoryUsage,
        errorRate: summary.currentErrorRate,
      };
    }

    if (this.skillRegistry) {
      status.skills.registered = this.skillRegistry.getSkillCount();
      status.skills.active = status.skills.registered;
    }

    if (this.configLoader?.getMonitoringConfig()?.alertThresholds) {
      const monitoringConfig = this.configLoader.getMonitoringConfig();
      if (monitoringConfig?.alertThresholds) {
        const thresholds = monitoringConfig.alertThresholds;

        if (
          status.performance.responseTime > thresholds.responseTime ||
          status.performance.memoryUsage > thresholds.memoryUsage ||
          status.performance.errorRate > thresholds.errorRate
        ) {
          status.status = 'degraded';
        }

        if (
          status.performance.responseTime > thresholds.responseTime * 2 ||
          status.performance.memoryUsage > thresholds.memoryUsage * 2
        ) {
          status.status = 'critical';
        }
      }
    }

    this.emit('healthCheck', status);

    if (status.status !== 'healthy') {
      Logger.warn(
        `⚠️ 系统健康状态: ${status.status}`,
        'TRAEOptimizationIntegrator'
      );
    }

    return status;
  }

  private async performAutoOptimization(): Promise<void> {
    Logger.info('🔧 执行自动优化...', 'TRAEOptimizationIntegrator');

    try {
      if (this.config.enableSecurityAudit && this.skillRegistry) {
        await this.runSecurityAudit();
      }

      if (this.performanceMonitor) {
        const metrics = this.performanceMonitor.getCurrentMetrics();
        if (metrics && metrics.errorRate > 0.1) {
          Logger.warn(
            '检测到高错误率，建议检查系统状态',
            'TRAEOptimizationIntegrator'
          );
        }
      }

      this.emit('autoOptimizationCompleted');
      Logger.info('✅ 自动优化完成', 'TRAEOptimizationIntegrator');
    } catch (error) {
      Logger.error(
        '自动优化失败',
        error as Error,
        'TRAEOptimizationIntegrator'
      );
    }
  }

  private async runSecurityAudit(): Promise<void> {
    if (!this.skillRegistry) return;

    try {
      const result = await this.skillRegistry.executeSkill('security_audit', {
        target: './src',
        auditType: 'code',
      });

      if (result.success && result.output) {
        const auditData = result.output as { summary?: string };
        Logger.info(
          `安全审计完成: ${auditData.summary || '完成'}`,
          'TRAEOptimizationIntegrator'
        );
      }
    } catch (error) {
      Logger.error(
        '安全审计失败',
        error as Error,
        'TRAEOptimizationIntegrator'
      );
    }
  }

  public getSystemHealth(): SystemHealthStatus {
    return {
      status: 'healthy',
      mcpServers: { running: 0, total: 0 },
      performance: { responseTime: 0, memoryUsage: 0, errorRate: 0 },
      skills: { registered: 0, active: 0 },
      security: { lastAudit: '', issues: 0 },
      timestamp: Date.now(),
    };
  }

  public getPerformanceMetrics() {
    return this.performanceMonitor?.getCurrentMetrics();
  }

  public getMCPStatus() {
    return this.mcpManager?.getAllServerStatus();
  }

  public getSkillStatus() {
    return {
      registered: this.skillRegistry?.getSkillCount() || 0,
      categories: this.skillRegistry?.getCategories() || [],
    };
  }

  public async executeOptimizedSkill(
    skillName: string,
    params: Record<string, unknown>
  ) {
    if (!this.skillRegistry) {
      throw new Error('技能注册中心未初始化');
    }

    const startTime = Date.now();
    const result = await this.skillRegistry.executeSkill(skillName, params);
    const responseTime = Date.now() - startTime;

    if (this.performanceMonitor) {
      this.performanceMonitor.recordRequest(responseTime, result.success);
    }

    return result;
  }

  public updateConfig(config: Partial<TRAEOptimizationConfig>): void {
    this.config = { ...this.config, ...config };
    Logger.info('配置已更新', 'TRAEOptimizationIntegrator');
  }

  public shutdown(): void {
    Logger.info('🛑 关闭TRAE优化系统集成器...', 'TRAEOptimizationIntegrator');

    if (this.optimizationInterval) {
      clearInterval(this.optimizationInterval);
      this.optimizationInterval = null;
    }

    if (this.healthCheckInterval) {
      clearInterval(this.healthCheckInterval);
      this.healthCheckInterval = null;
    }

    if (this.performanceMonitor) {
      this.performanceMonitor.stopMonitoring();
    }

    if (this.mcpManager) {
      this.mcpManager.stopAllServers();
    }

    this.initialized = false;
    Logger.info('✅ TRAE优化系统集成器已关闭', 'TRAEOptimizationIntegrator');
  }
}

export default TRAEOptimizationIntegrator;

import {
  IntegrationPlatform,
  PlatformConfig,
  IntegrationStatus,
  IncomingMessageEvent,
  SendMessageResponse,
} from '../../shared/contracts';
import { Logger } from '../../utils/Logger';

export abstract class BaseIntegrationAdapter {
  protected config: PlatformConfig;
  protected status: IntegrationStatus;
  protected messageHandlers: Array<(message: IncomingMessageEvent) => Promise<void>> = [];

  constructor(public readonly platform: IntegrationPlatform) {
    this.config = {};
    this.status = {
      platform,
      connected: false,
      status: 'disconnected',
    };
  }

  /**
   * 连接到平台
   */
  abstract connect(config: PlatformConfig): Promise<boolean>;

  /**
   * 断开平台连接
   */
  abstract disconnect(): Promise<void>;

  /**
   * 发送消息
   */
  abstract sendMessage(
    message: string,
    to?: string,
    imageUrls?: string[],
    mentions?: string[]
  ): Promise<SendMessageResponse>;

  /**
   * 处理 Webhook 请求
   */
  abstract handleWebhook(payload: Record<string, unknown>): Promise<{ success: boolean; response?: unknown }>;

  /**
   * 获取当前状态
   */
  getStatus(): IntegrationStatus {
    return { ...this.status };
  }

  /**
   * 注册消息处理器
   */
  onMessage(handler: (message: IncomingMessageEvent) => Promise<void>): void {
    this.messageHandlers.push(handler);
    Logger.info(`注册了新的消息处理器到 ${this.platform}`, 'IntegrationAdapter');
  }

  /**
   * 触发消息处理
   */
  protected async emitMessage(message: IncomingMessageEvent): Promise<void> {
    Logger.info(`接收到 ${this.platform} 消息`, 'IntegrationAdapter', {
      from: message.from,
      type: message.type,
    });
    for (const handler of this.messageHandlers) {
      try {
        await handler(message);
      } catch (error) {
        Logger.error('消息处理器失败', error as Error, 'IntegrationAdapter');
      }
    }
  }

  /**
   * 更新状态
   */
  protected updateStatus(
    status: IntegrationStatus['status'],
    error?: string
  ): void {
    this.status = {
      ...this.status,
      status,
      connected: status === 'connected',
      lastConnectedAt:
        status === 'connected' ? new Date().toISOString() : this.status.lastConnectedAt,
      error,
    };
    Logger.debug(`${this.platform} 状态更新`, 'IntegrationAdapter', this.status);
  }
}

import { BaseIntegrationAdapter } from './BaseIntegrationAdapter';
import {
  PlatformConfig,
  SendMessageResponse,
  IncomingMessageEvent,
} from '../../shared/contracts';
import { Logger } from '../../utils/Logger';

export class DingTalkAdapter extends BaseIntegrationAdapter {
  private accessToken?: string;

  constructor() {
    super('dingtalk');
  }

  async connect(config: PlatformConfig): Promise<boolean> {
    try {
      this.config = config;
      this.updateStatus('connecting');

      if (config.appId && config.appSecret) {
        Logger.info('正在连接到钉钉...', 'DingTalkAdapter');
        await this.fetchAccessToken();
        this.updateStatus('connected');
        return true;
      } else {
        throw new Error('缺少必要的钉钉配置参数');
      }
    } catch (error) {
      Logger.error('连接钉钉失败', error as Error, 'DingTalkAdapter');
      this.updateStatus('error', (error as Error).message);
      return false;
    }
  }

  async disconnect(): Promise<void> {
    this.updateStatus('disconnected');
    this.accessToken = undefined;
    Logger.info('已断开与钉钉的连接', 'DingTalkAdapter');
  }

  async sendMessage(
    message: string,
    to?: string,
    imageUrls?: string[],
    mentions?: string[]
  ): Promise<SendMessageResponse> {
    if (!this.status.connected) {
      return { success: false, error: '未连接到钉钉' };
    }

    try {
      Logger.info('正在发送消息到钉钉', 'DingTalkAdapter', { to, message });
      await new Promise(resolve => setTimeout(resolve, 200));

      return {
        success: true,
        messageId: `dt_msg_${Date.now()}`,
        timestamp: new Date().toISOString(),
      };
    } catch (error) {
      Logger.error('发送钉钉消息失败', error as Error, 'DingTalkAdapter');
      return {
        success: false,
        error: (error as Error).message,
      };
    }
  }

  async handleWebhook(
    payload: Record<string, unknown>
  ): Promise<{ success: boolean; response?: unknown }> {
    try {
      Logger.debug('处理钉钉 Webhook', 'DingTalkAdapter', { payload });

      const msgType = payload.msgtype as string;

      if (msgType === 'text') {
        const text = payload.text as Record<string, string>;
        const conversationType = payload.conversationType as string;
        const senderNick = payload.senderNick as string;

        const incomingMessage: IncomingMessageEvent = {
          platform: 'dingtalk',
          type: 'text',
          content: text.content || '',
          from: payload.senderStaffId as string || '',
          fromName: senderNick,
          timestamp: new Date().toISOString(),
          rawData: payload,
        };

        await this.emitMessage(incomingMessage);
      }

      return { success: true };
    } catch (error) {
      Logger.error('处理钉钉 Webhook 失败', error as Error, 'DingTalkAdapter');
      return { success: false };
    }
  }

  private async fetchAccessToken(): Promise<void> {
    this.accessToken = 'dingtalk_token_' + Date.now();
    Logger.info('成功获取钉钉访问令牌', 'DingTalkAdapter');
  }
}

import { BaseIntegrationAdapter } from './BaseIntegrationAdapter';
import {
  PlatformConfig,
  SendMessageResponse,
  IncomingMessageEvent,
} from '../../shared/contracts';
import { Logger } from '../../utils/Logger';

export class FeishuAdapter extends BaseIntegrationAdapter {
  private appAccessToken?: string;
  private tenantAccessToken?: string;

  constructor() {
    super('feishu');
  }

  async connect(config: PlatformConfig): Promise<boolean> {
    try {
      this.config = config;
      this.updateStatus('connecting');

      if (config.appId && config.appSecret) {
        Logger.info('正在连接到飞书...', 'FeishuAdapter');
        await this.fetchAppAccessToken();
        this.updateStatus('connected');
        return true;
      } else {
        throw new Error('缺少必要的飞书配置参数');
      }
    } catch (error) {
      Logger.error('连接飞书失败', error as Error, 'FeishuAdapter');
      this.updateStatus('error', (error as Error).message);
      return false;
    }
  }

  async disconnect(): Promise<void> {
    this.updateStatus('disconnected');
    this.appAccessToken = undefined;
    this.tenantAccessToken = undefined;
    Logger.info('已断开与飞书的连接', 'FeishuAdapter');
  }

  async sendMessage(
    message: string,
    to?: string,
    imageUrls?: string[],
    mentions?: string[]
  ): Promise<SendMessageResponse> {
    if (!this.status.connected) {
      return { success: false, error: '未连接到飞书' };
    }

    try {
      Logger.info('正在发送消息到飞书', 'FeishuAdapter', { to, message });
      await new Promise(resolve => setTimeout(resolve, 200));

      return {
        success: true,
        messageId: `fs_msg_${Date.now()}`,
        timestamp: new Date().toISOString(),
      };
    } catch (error) {
      Logger.error('发送飞书消息失败', error as Error, 'FeishuAdapter');
      return {
        success: false,
        error: (error as Error).message,
      };
    }
  }

  async handleWebhook(
    payload: Record<string, unknown>
  ): Promise<{ success: boolean; response?: unknown }> {
    try {
      Logger.debug('处理飞书 Webhook', 'FeishuAdapter', { payload });

      if (payload.challenge) {
        return {
          success: true,
          response: { challenge: payload.challenge },
        };
      }

      const header = payload.header as Record<string, unknown>;
      const eventType = header?.event_type as string;

      if (eventType === 'im.message.receive_v1') {
        const event = payload.event as Record<string, unknown>;
        const sender = event.sender as Record<string, unknown>;
        const senderId = sender.sender_id as Record<string, unknown>;
        const message = event.message as Record<string, unknown>;
        const contentRaw = message.content as string || '{}';
        let content: Record<string, unknown> = {};
        try {
          content = JSON.parse(contentRaw);
        } catch (e) {
          content = {};
        }

        const incomingMessage: IncomingMessageEvent = {
          platform: 'feishu',
          type: content.image_key ? 'image' : 'text',
          content: content.text as string || '',
          from: senderId.open_id as string || '',
          fromName: senderId.name as string || '',
          timestamp: new Date().toISOString(),
          rawData: payload,
        };

        await this.emitMessage(incomingMessage);
      }

      return { success: true };
    } catch (error) {
      Logger.error('处理飞书 Webhook 失败', error as Error, 'FeishuAdapter');
      return { success: false };
    }
  }

  private async fetchAppAccessToken(): Promise<void> {
    // 在实际生产环境中，这里应该调用飞书的 API 获取访问令牌
    this.appAccessToken = 'feishu_app_token_' + Date.now();
    this.tenantAccessToken = 'feishu_tenant_token_' + Date.now();
    Logger.info('成功获取飞书访问令牌', 'FeishuAdapter');
  }
}

import { BaseIntegrationAdapter } from './BaseIntegrationAdapter';
import {
  IntegrationPlatform,
  PlatformConfig,
  SendMessageResponse,
  IncomingMessageEvent,
} from '../../shared/contracts';
import { Logger } from '../../utils/Logger';

interface MiraiSession {
  sessionKey: string;
  code: number;
}

interface MiraiMessage {
  type: string;
  sender: {
    id: number;
    nickname: string;
    remark?: string;
  };
  messageChain: Array<{
    type: string;
    text?: string;
    imageId?: string;
    url?: string;
  }>;
}

const RECONNECT_DELAY_MS = 5000;
const MAX_RECONNECT_ATTEMPTS = 20;
const POLL_INTERVAL_MS = 1500;

export class QQAdapter extends BaseIntegrationAdapter {
  private sessionKey?: string;
  private httpBaseUrl: string = 'http://localhost:8080';
  private pollingTimer?: NodeJS.Timeout;
  private reconnectTimer?: NodeJS.Timeout;
  private reconnectAttempts: number = 0;
  private shouldAutoReconnect: boolean = true;
  private qqAccount?: string;
  private miraiVerifyKey?: string;

  constructor() {
    super('qq');
  }

  async connect(config: PlatformConfig): Promise<boolean> {
    try {
      this.config = config;
      this.updateStatus('connecting');
      this.reconnectAttempts = 0;
      this.shouldAutoReconnect = true;

      this.httpBaseUrl =
        `http://${config.miraiHttpHost || 'localhost'}:${config.miraiHttpPort || '8080'}`;
      this.qqAccount = config.qqAccount;
      this.miraiVerifyKey = config.miraiVerifyKey;

      Logger.info('正在通过 Mirai 连接到 QQ...', 'QQAdapter');

      const session = await this.verifySession(this.miraiVerifyKey || '');
      if (session.code !== 0) {
        const errorMap: Record<number, string> = {
          1: 'verifyKey 错误',
          2: 'Session 错误或过期',
          3: '未绑定 QQ 账号',
          4: ' mirai-api-http 版本不兼容',
        };
        throw new Error(errorMap[session.code] || `连接失败 (code: ${session.code})`);
      }

      this.sessionKey = session.sessionKey;

      if (this.qqAccount) {
        const bindResult = await this.bindQQ(this.qqAccount);
        if (!bindResult) {
          throw new Error(`绑定 QQ ${this.qqAccount} 失败`);
        }
      }

      this.updateStatus('connected');
      this.startPolling();
      this.reconnectAttempts = 0;

      Logger.info(
        `QQ 机器人已连接 (Session: ${this.sessionKey?.slice(0, 8)}...)`,
        'QQAdapter'
      );
      return true;
    } catch (error) {
      Logger.error('连接 QQ 失败', error as Error, 'QQAdapter');
      this.updateStatus('error', (error as Error).message);
      void this.scheduleReconnect();
      return false;
    }
  }

  async disconnect(): Promise<void> {
    this.shouldAutoReconnect = false;
    this.stopPolling();
    this.cancelReconnect();

    if (this.sessionKey && this.qqAccount) {
      try {
        await fetch(`${this.httpBaseUrl}/release`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            sessionKey: this.sessionKey,
            qq: Number(this.qqAccount),
          }),
        });
      } catch {
        // 忽略释放 session 时的错误
      }
    }

    this.sessionKey = undefined;
    this.updateStatus('disconnected');
    Logger.info('已断开 QQ 连接', 'QQAdapter');
  }

  async sendMessage(
    message: string,
    to?: string,
    imageUrls?: string[],
    mentions?: string[]
  ): Promise<SendMessageResponse> {
    if (!this.status.connected || !this.sessionKey) {
      return { success: false, error: '未连接到 QQ' };
    }

    try {
      const messageChain: Array<Record<string, unknown>> = [];

      if (mentions && mentions.length > 0) {
        for (const target of mentions) {
          messageChain.push({ type: 'At', target: Number(target) });
        }
      }

      if (imageUrls && imageUrls.length > 0) {
        for (const url of imageUrls) {
          messageChain.push({ type: 'Image', url });
        }
      }

      messageChain.push({ type: 'Plain', text: message });

      const targetId = to ? Number(to) : 0;
      if (!targetId) {
        return { success: false, error: '缺少接收人' };
      }

      const isGroup = to?.startsWith('g') || to?.startsWith('group_');
      const actualTarget = isGroup
        ? Number(to?.replace(/^(g|group_)/, ''))
        : targetId;

      let endpoint: string;
      let body: Record<string, unknown>;

      if (isGroup) {
        endpoint = `${this.httpBaseUrl}/sendGroupMessage`;
        body = {
          sessionKey: this.sessionKey,
          target: actualTarget,
          messageChain,
        };
      } else {
        endpoint = `${this.httpBaseUrl}/sendFriendMessage`;
        body = {
          sessionKey: this.sessionKey,
          target: actualTarget,
          messageChain,
        };
      }

      const response = await fetch(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });

      if (!response.ok) {
        throw new Error(`Mirai API 返回状态码: ${response.status}`);
      }

      const result = await response.json();
      if (result.code !== 0) {
        throw new Error(`Mirai 发送失败 (code: ${result.code})`);
      }

      return {
        success: true,
        messageId: `qq_msg_${Date.now()}`,
        timestamp: new Date().toISOString(),
      };
    } catch (error) {
      Logger.error('发送 QQ 消息失败', error as Error, 'QQAdapter');
      return {
        success: false,
        error: (error as Error).message,
      };
    }
  }

  async handleWebhook(
    payload: Record<string, unknown>
  ): Promise<{ success: boolean; response?: unknown }> {
    return { success: true, response: { handled: false } };
  }

  private async verifySession(verifyKey: string): Promise<MiraiSession> {
    Logger.info('正在验证 Mirai Session...', 'QQAdapter');

    const response = await fetch(`${this.httpBaseUrl}/verify`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ verifyKey }),
    });

    if (!response.ok) {
      throw new Error(`Mirai 服务未启动 (${response.status})`);
    }

    return response.json();
  }

  private async bindQQ(qq: string): Promise<boolean> {
    if (!this.sessionKey) return false;

    Logger.info(`正在绑定 QQ ${qq}...`, 'QQAdapter');

    const response = await fetch(`${this.httpBaseUrl}/bind`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        sessionKey: this.sessionKey,
        qq: Number(qq),
      }),
    });

    if (!response.ok) return false;

    const result = await response.json();
    return result.code === 0;
  }

  private async fetchNewMessages(): Promise<void> {
    if (!this.sessionKey || !this.status.connected) return;

    try {
      const response = await fetch(`${this.httpBaseUrl}/fetchMessage`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sessionKey: this.sessionKey, count: 10 }),
      });

      if (!response.ok) {
        if (response.status === 500) {
          Logger.warn('Mirai Session 可能已过期，准备重连', 'QQAdapter');
          this.updateStatus('error', 'Session 过期');
          void this.scheduleReconnect();
        }
        return;
      }

      const data = await response.json();
      const messages: MiraiMessage[] = data.data || [];

      for (const msg of messages) {
        const textContent = msg.messageChain
          .filter((c) => c.type === 'Plain')
          .map((c) => c.text || '')
          .join('');

        const hasImage = msg.messageChain.some((c) => c.type === 'Image');

        const incoming: IncomingMessageEvent = {
          platform: 'qq',
          type: hasImage ? 'image' : 'text',
          content: textContent,
          from: String(msg.sender.id),
          fromName: msg.sender.nickname || msg.sender.remark || String(msg.sender.id),
          timestamp: new Date().toISOString(),
          rawData: msg as unknown as Record<string, unknown>,
        };

        await this.emitMessage(incoming);
      }
    } catch {
      // 轮询失败，可能网络问题，下次轮询继续
    }
  }

  private startPolling(): void {
    this.stopPolling();
    this.pollingTimer = setInterval(() => {
      void this.fetchNewMessages();
    }, POLL_INTERVAL_MS);
    Logger.info('QQ 消息轮询已启动', 'QQAdapter');
  }

  private stopPolling(): void {
    if (this.pollingTimer) {
      clearInterval(this.pollingTimer);
      this.pollingTimer = undefined;
    }
  }

  private cancelReconnect(): void {
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = undefined;
    }
  }

  private async scheduleReconnect(): Promise<void> {
    if (!this.shouldAutoReconnect) return;

    this.reconnectAttempts++;
    if (this.reconnectAttempts > MAX_RECONNECT_ATTEMPTS) {
      Logger.error(
        `QQ 重连已达最大次数 (${MAX_RECONNECT_ATTEMPTS})，停止重连`,
        undefined,
        'QQAdapter'
      );
      return;
    }

    const delay = Math.min(
      RECONNECT_DELAY_MS * Math.pow(1.5, this.reconnectAttempts - 1),
      60000
    );

    Logger.info(
      `QQ 将在 ${Math.round(delay / 1000)} 秒后重连 (第 ${this.reconnectAttempts} 次)`,
      'QQAdapter'
    );

    this.reconnectTimer = setTimeout(async () => {
      Logger.info('正在重连 QQ...', 'QQAdapter');
      await this.connect({
        miraiHttpHost: this.config.miraiHttpHost,
        miraiHttpPort: this.config.miraiHttpPort,
        miraiVerifyKey: this.miraiVerifyKey,
        qqAccount: this.qqAccount,
      });
    }, delay);
  }

  /**
   * 从环境变量加载 QQ 配置
   */
  static loadConfigFromEnv(): PlatformConfig | null {
    const enabled = process.env.QQ_ENABLED === 'true';
    if (!enabled) return null;

    return {
      miraiHttpHost: process.env.MIRAI_HTTP_HOST || 'localhost',
      miraiHttpPort: process.env.MIRAI_HTTP_PORT || '8080',
      miraiVerifyKey: process.env.MIRAI_VERIFY_KEY || '',
      qqAccount: process.env.QQ_ACCOUNT || '',
    };
  }
}

import { BaseIntegrationAdapter } from './BaseIntegrationAdapter';
import {
  PlatformConfig,
  SendMessageResponse,
  IncomingMessageEvent,
} from '../../shared/contracts';
import { Logger } from '../../utils/Logger';

export class WeChatAdapter extends BaseIntegrationAdapter {
  private accessToken?: string;
  private accessTokenExpiry?: number;

  constructor() {
    super('wechat');
  }

  async connect(config: PlatformConfig): Promise<boolean> {
    try {
      this.config = config;
      this.updateStatus('connecting');

      // 在实际生产中应验证和获取访问令牌
      if (config.appId && config.appSecret) {
        // 模拟验证和连接过程
        Logger.info('正在连接到微信...', 'WeChatAdapter');
        await this.fetchAccessToken();

        this.updateStatus('connected');
        return true;
      } else {
        throw new Error('缺少必要的配置参数');
      }
    } catch (error) {
      Logger.error('连接微信失败', error as Error, 'WeChatAdapter');
      this.updateStatus('error', (error as Error).message);
      return false;
    }
  }

  async disconnect(): Promise<void> {
    this.updateStatus('disconnected');
    this.accessToken = undefined;
    this.accessTokenExpiry = undefined;
    Logger.info('已断开与微信的连接', 'WeChatAdapter');
  }

  async sendMessage(
    message: string,
    to?: string,
    imageUrls?: string[],
    mentions?: string[]
  ): Promise<SendMessageResponse> {
    if (!this.status.connected) {
      return { success: false, error: '未连接到微信' };
    }

    try {
      // 在实际生产中，这里应该调用微信的 API
      Logger.info('正在发送消息到微信', 'WeChatAdapter', { to, message });

      // 模拟 API 调用
      await new Promise(resolve => setTimeout(resolve, 200));

      return {
        success: true,
        messageId: `wx_msg_${Date.now()}`,
        timestamp: new Date().toISOString(),
      };
    } catch (error) {
      Logger.error('发送微信消息失败', error as Error, 'WeChatAdapter');
      return {
        success: false,
        error: (error as Error).message,
      };
    }
  }

  async handleWebhook(
    payload: Record<string, unknown>
  ): Promise<{ success: boolean; response?: unknown }> {
    try {
      // 验证签名
      const signature = payload.signature as string;
      const timestamp = payload.timestamp as string;
      const nonce = payload.nonce as string;

      // 在实际生产中验证请求签名
      Logger.debug('处理微信 Webhook', 'WeChatAdapter', {
        signature,
        timestamp,
        nonce,
      });

      // 验证通过，处理消息
      if (payload.msgtype === 'text') {
        const content = payload.content as string;
        const from = payload.fromusername as string;

        // 创建消息对象
        const message: IncomingMessageEvent = {
          platform: 'wechat',
          type: 'text',
          content,
          from,
          timestamp: new Date().toISOString(),
          rawData: payload,
        };

        // 处理并转发消息
        await this.emitMessage(message);
      }

      // 返回验证响应
      return {
        success: true,
        response: {
          success: true,
        },
      };
    } catch (error) {
      Logger.error('处理微信 Webhook 失败', error as Error, 'WeChatAdapter');
      return { success: false };
    }
  }

  private async fetchAccessToken(): Promise<void> {
    // 在实际生产环境中，这里应该调用微信的 API 获取访问令牌
    this.accessToken = 'wechat_demo_token_' + Date.now();
    this.accessTokenExpiry = Date.now() + 7200 * 1000;
    Logger.info('成功获取微信访问令牌', 'WeChatAdapter');
  }
}

import * as fs from 'fs';
import * as path from 'path';
import { BaseIntegrationAdapter } from './BaseIntegrationAdapter';
import {
  PlatformConfig,
  SendMessageResponse,
  IncomingMessageEvent,
} from '../../shared/contracts';
import { Logger } from '../../utils/Logger';

interface QRLoginState {
  qrCodePath: string | null;
  qrCodeBase64: string | null;
  status: 'waiting_scan' | 'scanned' | 'logged_in' | 'expired' | 'error';
  botWxid: string | null;
  botNickname: string | null;
  error?: string;
}

export class WeChatQRAdapter extends BaseIntegrationAdapter {
  private loginState: QRLoginState = {
    qrCodePath: null,
    qrCodeBase64: null,
    status: 'waiting_scan',
    botWxid: null,
    botNickname: null,
  };

  private browser: any = null;
  private page: any = null;
  private loginCheckTimer: NodeJS.Timeout | null = null;
  private messagePollTimer: NodeJS.Timeout | null = null;
  private contacts: Map<string, string> = new Map();

  constructor() {
    super('wechat');
  }

  getQRState(): QRLoginState {
    return { ...this.loginState };
  }

  async connect(config: PlatformConfig): Promise<boolean> {
    try {
      this.config = config;
      this.updateStatus('connecting');
      this.loginState = {
        qrCodePath: null,
        qrCodeBase64: null,
        status: 'waiting_scan',
        botWxid: null,
        botNickname: null,
      };

      Logger.info('正在启动微信扫码登录...', 'WeChatQRAdapter');

      // 使用 Playwright 打开 Web 微信
      const { chromium } = await import('playwright');
      this.browser = await chromium.launch({
        headless: true,
        args: ['--no-sandbox', '--disable-setuid-sandbox'],
      });

      const context = await this.browser.newContext({
        viewport: { width: 800, height: 600 },
        userAgent:
          'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
      });

      this.page = await context.newPage();

      // 打开微信网页版
      await this.page.goto('https://wx.qq.com/', {
        waitUntil: 'networkidle',
        timeout: 30000,
      });

      Logger.info('微信网页版已加载，等待二维码...', 'WeChatQRAdapter');

      // 等待二维码出现
      await this.page.waitForSelector('img[src*="qrcode"]', { timeout: 15000 });

      // 截取二维码
      await this.captureQRCode();

      // 开始监控扫码状态
      this.startLoginMonitor();

      // 开始消息轮询（登录后自动启用）
      this.startMessagePolling();

      this.updateStatus('connecting');
      return true;
    } catch (error) {
      Logger.error('启动微信扫码登录失败', error as Error, 'WeChatQRAdapter');
      this.loginState.status = 'error';
      this.loginState.error = (error as Error).message;
      this.updateStatus('error', (error as Error).message);
      await this.cleanup();
      return false;
    }
  }

  async disconnect(): Promise<void> {
    this.loginState.status = 'waiting_scan';
    this.loginState.qrCodeBase64 = null;
    this.loginState.qrCodePath = null;
    this.loginState.botWxid = null;
    this.loginState.botNickname = null;
    await this.cleanup();
    this.updateStatus('disconnected');
    Logger.info('已断开微信连接', 'WeChatQRAdapter');
  }

  async sendMessage(
    message: string,
    to?: string,
    imageUrls?: string[],
    mentions?: string[]
  ): Promise<SendMessageResponse> {
    if (this.loginState.status !== 'logged_in' || !this.page) {
      return { success: false, error: '微信未登录' };
    }

    try {
      // 通过页面控制台执行消息发送
      // 在 Web 微信中，需要找到对应的聊天窗口并发送消息
      if (to) {
        // 查找联系人
        await this.page.evaluate(
          (payload: { wxid: string; msg: string }) => {
            const win = window as any;
            if (win.msgSend) {
              win.msgSend(payload.wxid, payload.msg);
            }
          },
          { wxid: to, msg: message }
        );
      }

      return {
        success: true,
        messageId: `wx_${Date.now()}`,
        timestamp: new Date().toISOString(),
      };
    } catch (error) {
      Logger.error('发送微信消息失败', error as Error, 'WeChatQRAdapter');
      return {
        success: false,
        error: (error as Error).message,
      };
    }
  }

  async handleWebhook(
    payload: Record<string, unknown>
  ): Promise<{ success: boolean; response?: unknown }> {
    return { success: true, response: { handled: false } };
  }

  private async captureQRCode(): Promise<void> {
    try {
      if (!this.page) return;

      // 获取二维码图片
      const qrImg = await this.page.$('img[src*="qrcode"]');
      if (!qrImg) {
        throw new Error('未找到二维码图片');
      }

      // 截图保存
      const uploadsDir = path.join(process.cwd(), 'uploads');
      if (!fs.existsSync(uploadsDir)) {
        fs.mkdirSync(uploadsDir, { recursive: true });
      }

      const qrPath = path.join(uploadsDir, 'wechat-qr.png');
      await qrImg.screenshot({ path: qrPath });

      // 读取为 base64
      const imageBuffer = fs.readFileSync(qrPath);
      const base64 = imageBuffer.toString('base64');

      this.loginState.qrCodePath = qrPath;
      this.loginState.qrCodeBase64 = `data:image/png;base64,${base64}`;

      Logger.info('微信二维码已捕获', 'WeChatQRAdapter');
    } catch (error) {
      Logger.error('捕获二维码失败', error as Error, 'WeChatQRAdapter');
      throw error;
    }
  }

  private async refreshQRCode(): Promise<void> {
    try {
      await this.captureQRCode();
      this.loginState.status = 'waiting_scan';
    } catch {
      // 二维码刷新失败，继续等待
    }
  }

  private startLoginMonitor(): void {
    this.loginCheckTimer = setInterval(async () => {
      if (!this.page) return;

      try {
        // 检查是否已登录
        const isLoggedIn = await this.page.evaluate(() => {
          const win = window as any;
          // Web 微信登录后的标志
          return (
            typeof win.login !== 'undefined' ||
            document.querySelector('.chat') !== null ||
            document.querySelector('#chatArea') !== null
          );
        });

        if (isLoggedIn) {
          this.loginState.status = 'logged_in';

          // 获取用户信息
          const userInfo = await this.page.evaluate(() => {
            const win = window as any;
            return {
              wxid: win.__wxUser?.uin || win.uin || 'unknown',
              nickname:
                win.__wxUser?.nickName ||
                document.querySelector('.avatar_text')?.textContent ||
                'WeChat User',
            };
          });

          this.loginState.botWxid = userInfo.wxid;
          this.loginState.botNickname = userInfo.nickname;

          this.updateStatus('connected');
          Logger.info(
            `微信已登录: ${userInfo.nickname}`,
            'WeChatQRAdapter'
          );

          if (this.loginCheckTimer) {
            clearInterval(this.loginCheckTimer);
            this.loginCheckTimer = null;
          }
        }
      } catch {
        // 检查失败，继续
      }
    }, 2000);

    // 二维码每 5 分钟刷新一次
    setTimeout(() => {
      if (this.loginState.status === 'waiting_scan') {
        this.refreshQRCode();
      }
    }, 5 * 60 * 1000);
  }

  private startMessagePolling(): void {
    this.messagePollTimer = setInterval(async () => {
      if (this.loginState.status !== 'logged_in' || !this.page) return;

      try {
        const messages = await this.page.evaluate(() => {
          const win = window as any;
          // 获取新消息
          if (win.__newMessages && win.__newMessages.length > 0) {
            const msgs = win.__newMessages;
            win.__newMessages = [];
            return msgs;
          }
          return [];
        });

        if (Array.isArray(messages)) {
          for (const msg of messages) {
            const incoming: IncomingMessageEvent = {
              platform: 'wechat',
              type: msg.type === 'image' ? 'image' : 'text',
              content: msg.content || '',
              from: msg.from || msg.from_wxid,
              fromName: msg.from_name || msg.from_nickname,
              timestamp: new Date().toISOString(),
              rawData: msg,
            };
            await this.emitMessage(incoming);
          }
        }
      } catch {
        // 轮询失败，继续
      }
    }, 1500);
  }

  private async cleanup(): Promise<void> {
    if (this.loginCheckTimer) {
      clearInterval(this.loginCheckTimer);
      this.loginCheckTimer = null;
    }
    if (this.messagePollTimer) {
      clearInterval(this.messagePollTimer);
      this.messagePollTimer = null;
    }
    if (this.page) {
      try {
        await this.page.close();
      } catch {}
      this.page = null;
    }
    if (this.browser) {
      try {
        await this.browser.close();
      } catch {}
      this.browser = null;
    }
  }
}

