import { IntegrationManager } from './IntegrationManager';
import { Logger } from '../utils/Logger';
import { EventBus } from '../shared/EventBus';
import type {
  IntegrationPlatform,
  PlatformConfig,
  IncomingMessageEvent,
} from '../shared/contracts';

interface IpcMessage {
  id: string;
  type: string;
  payload?: unknown;
}

interface IpcResponse {
  id: string;
  success: boolean;
  data?: unknown;
  error?: string;
}

const im = IntegrationManager.getInstance();

function send(msg: IpcResponse): void {
  if (process.send) {
    process.send(msg);
  }
}

function handleMessage(msg: IpcMessage): void {
  switch (msg.type) {
    case 'connect': {
      const { platform, config } = msg.payload as {
        platform: IntegrationPlatform;
        config: PlatformConfig;
      };
      im.connectPlatform(platform, config)
        .then((success) => {
          send({ id: msg.id, success, data: { platform, status: success ? 'connected' : 'failed' } });
        })
        .catch((err: Error) => {
          send({ id: msg.id, success: false, error: err.message });
        });
      break;
    }
    case 'disconnect': {
      const { platform: dp } = msg.payload as { platform: IntegrationPlatform };
      im.disconnectPlatform(dp)
        .then(() => {
          send({ id: msg.id, success: true, data: { platform: dp } });
        })
        .catch((err: Error) => {
          send({ id: msg.id, success: false, error: err.message });
        });
      break;
    }
    case 'sendMessage': {
      const req = msg.payload as {
        platform: IntegrationPlatform;
        message: string;
        to?: string;
        imageUrls?: string[];
        mentions?: string[];
      };
      im.sendMessage(req)
        .then((result) => {
          send({ id: msg.id, success: result.success, data: result });
        })
        .catch((err: Error) => {
          send({ id: msg.id, success: false, error: err.message });
        });
      break;
    }
    case 'getPlatforms': {
      const platforms = im.getPlatforms();
      send({ id: msg.id, success: true, data: { platforms } });
      break;
    }
    case 'getStatus': {
      const { platform: sp } = msg.payload as { platform: IntegrationPlatform };
      const status = im.getPlatformStatus(sp);
      send({ id: msg.id, success: true, data: status });
      break;
    }
    case 'getWeChatQRState': {
      const qrState = im.getWeChatQRState();
      send({ id: msg.id, success: true, data: qrState });
      break;
    }
    case 'handleWebhook': {
      const { platform: wp, payload: wPayload } = msg.payload as {
        platform: IntegrationPlatform;
        payload: Record<string, unknown>;
      };
      im.handleWebhook(wp, wPayload)
        .then((result) => {
          send({ id: msg.id, success: result.success, data: result });
        })
        .catch((err: Error) => {
          send({ id: msg.id, success: false, error: err.message });
        });
      break;
    }
    case 'ping': {
      send({ id: msg.id, success: true, data: { status: 'alive', pid: process.pid } });
      break;
    }
    default:
      send({ id: msg.id, success: false, error: `Unknown message type: ${msg.type}` });
  }
}

EventBus.on('integration_message', (message: { platform: string; type: string; content: string; from?: string; fromName?: string; timestamp: string; rawData?: unknown }) => {
  send({
    id: `evt_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
    success: true,
    data: { type: 'incoming_message', payload: message },
  });
});

process.on('message', (msg: IpcMessage) => {
  handleMessage(msg);
});

process.on('uncaughtException', (error: Error) => {
  Logger.error('Gateway Worker 未捕获异常', error, 'GatewayWorker');
  send({
    id: `err_${Date.now()}`,
    success: false,
    error: `Worker uncaught exception: ${error.message}`,
  });
});

process.on('unhandledRejection', (reason: unknown) => {
  Logger.error('Gateway Worker 未处理的 Promise 拒绝', reason as Error, 'GatewayWorker');
  send({
    id: `err_${Date.now()}`,
    success: false,
    error: `Worker unhandled rejection: ${String(reason)}`,
  });
});

Logger.info('🟢 Gateway Worker 已启动', 'GatewayWorker');
send({
  id: 'worker_ready',
  success: true,
  data: { type: 'ready', pid: process.pid },
});

/**
 * 表情管理模块
 * 基于情绪和场景生成适当的表情，支持多模态交互
 */

import Logger from '../utils/Logger';

export interface EmojiOptions {
  emotion?: string; // 情绪类型
  scene?: string; // 场景类型
  intensity?: number; // 情绪强度
  context?: string; // 上下文内容
  style?: 'static' | 'animated'; // 表情风格
  service?: 'local' | 'api'; // 表情生成服务
}

export class EmojiManager {
  private initialized: boolean = false;
  private emotionEmojis: Record<string, string[]>;
  private sceneEmojis: Record<string, string[]>;
  private apiClient: unknown; // 表情生成API客户端
  private apiConfig: {
    apiKey: string;
    endpoint: string;
  };

  constructor() {
    // 初始化情绪表情映射
    this.emotionEmojis = {
      开心: ['😊', '😄', '😃', '😁', '🤗'],
      烦躁: ['😠', '😒', '😤', '😫', '😩'],
      疲惫: ['😴', '😪', '🤤', '😵', '😷'],
      焦虑: ['😰', '😨', '😥', '😓', '😖'],
      平静: ['😐', '😌', '😑', '😶', '🙂'],
    };

    // 初始化场景表情映射
    this.sceneEmojis = {
      development: ['💻', '🔧', '🚀', '⚙️', '🧩'],
      rest: ['🛌', '🍵', '📚', '🎵', '🧘'],
      entertainment: ['🎮', '🎬', '🎭', '🎯', '🎲'],
      work: ['💼', '📈', '📋', '✍️', '📎'],
      social: ['👥', '💬', '🎉', '🎊', '🤝'],
    };

    // API配置（实际应用中应该从环境变量或配置文件读取）
    this.apiConfig = {
      apiKey: process.env.EMOJI_API_KEY || '',
      endpoint:
        process.env.EMOJI_API_ENDPOINT || 'https://api.emoji-generator.example',
    };
  }

  /**
   * 初始化表情管理器
   */
  public async initialize(): Promise<void> {
    try {
      // 初始化表情生成API客户端
      if (this.apiConfig.apiKey) {
        // API客户端将在首次请求时按需初始化
      }

      this.initialized = true;
    } catch (error) {
      Logger.error('表情管理器初始化失败', error as Error, 'EmojiManager');
      this.initialized = false;
      throw error;
    }
  }

  /**
   * 根据情绪和场景生成表情
   */
  public async generateEmoji(options: EmojiOptions): Promise<string> {
    this.ensureInitialized();

    const {
      emotion = '平静',
      scene = 'general',
      intensity = 3,
      context = '',
      style = 'static',
      service = 'local',
    } = options;

    try {
      switch (service) {
        case 'api':
          return await this.generateEmojiWithApi(options);
        case 'local':
        default:
          return this.generateEmojiWithLocal(options);
      }
    } catch (error) {
      Logger.error('表情生成失败', error as Error, 'EmojiManager');
      // 失败时回退到本地生成
      return this.generateEmojiWithLocal(options);
    }
  }

  /**
   * 使用API生成表情
   */
  private async generateEmojiWithApi(options: EmojiOptions): Promise<string> {
    try {
      // 简化实现：实际应用中应该调用表情生成API
      Logger.info('表情管理器：使用API生成表情', 'EmojiManager');

      const {
        emotion = '平静',
        scene = 'general',
        intensity = 3,
        context = '',
        style = 'static',
      } = options;

      // 模拟API响应
      if (style === 'animated') {
        return `[动态表情: ${emotion}]`;
      } else {
        return `[API生成表情: ${emotion}]`;
      }
    } catch (error) {
      Logger.error('API表情生成失败', error as Error, 'EmojiManager');
      throw error;
    }
  }

  /**
   * 使用本地规则生成表情
   */
  private generateEmojiWithLocal(options: EmojiOptions): string {
    const {
      emotion = '平静',
      scene = 'general',
      intensity = 3,
      context = '',
    } = options;

    // 1. 基于情绪生成表情
    const emotionEmojiList =
      this.emotionEmojis[emotion] || this.emotionEmojis['平静'];
    const emotionEmoji = this.selectEmojiByIntensity(
      emotionEmojiList,
      intensity
    );

    // 2. 基于场景生成表情
    const sceneEmojiList = this.sceneEmojis[scene] || [];
    let sceneEmoji = '';
    if (sceneEmojiList.length > 0) {
      sceneEmoji =
        sceneEmojiList[Math.floor(Math.random() * sceneEmojiList.length)];
    }

    // 3. 组合表情
    const emojis = [emotionEmoji];
    if (sceneEmoji) {
      emojis.push(sceneEmoji);
    }

    // 4. 基于上下文调整表情
    const contextEmoji = this.getEmojiFromContext(context);
    if (contextEmoji) {
      emojis.push(contextEmoji);
    }

    return emojis.join(' ');
  }

  /**
   * 根据强度选择表情
   */
  private selectEmojiByIntensity(
    emojiList: string[],
    intensity: number
  ): string {
    // 强度范围：1-10
    const index = Math.min(
      Math.floor((intensity - 1) / 2), // 将强度映射到 0-4 的索引
      emojiList.length - 1
    );
    return emojiList[index];
  }

  /**
   * 从上下文中提取表情
   */
  private getEmojiFromContext(context: string): string {
    const contextLower = context.toLowerCase();

    // 基于上下文关键词生成表情
    const contextEmojiMap: Record<string, string> = {
      成功: '✅',
      完成: '✅',
      失败: '❌',
      错误: '❌',
      问题: '❓',
      帮助: '🤝',
      谢谢: '🙏',
      加油: '💪',
      休息: '😴',
      工作: '💼',
      学习: '📚',
      代码: '💻',
      测试: '🧪',
      部署: '🚀',
    };

    for (const [keyword, emoji] of Object.entries(contextEmojiMap)) {
      if (contextLower.includes(keyword)) {
        return emoji;
      }
    }

    return '';
  }

  /**
   * 获取情绪对应的表情列表
   */
  public getEmotionsWithEmojis(): Record<string, string[]> {
    return { ...this.emotionEmojis };
  }

  /**
   * 获取场景对应的表情列表
   */
  public getScenesWithEmojis(): Record<string, string[]> {
    return { ...this.sceneEmojis };
  }

  /**
   * 检查表情管理器是否已初始化
   */
  public isInitialized(): boolean {
    return this.initialized === true;
  }

  /**
   * 确保表情管理器已初始化
   */
  private ensureInitialized(): void {
    if (!this.initialized) {
      throw new Error('表情管理器未初始化！请先调用initialize方法。');
    }
  }

  /**
   * 关闭表情管理器
   */
  public async shutdown(): Promise<void> {
    this.initialized = false;
  }
}

/**
 * jiabaixing 拟人化交互引擎 v2
 * 彻底消除模板化回复，完全由 LLM + 记忆上下文 + 人格规则驱动
 *
 * 核心变化：
 * - 删除所有 responseTemplates 硬编码模板
 * - 删除 getRandomTemplate / generateResponseBasedOnUserInput 等模板方法
 * - 所有回复通过 DialogueGenerator 生成，PersonaRules 只做语气微调
 * - 深度集成记忆：自动提取用户画像、情绪模式、行为偏好注入上下文
 */

import { DAGTask } from '../core/DAGTask';
import { EmotionTag, SceneTag } from '../interfaces';
import { LLMContextBuilder } from '../memory/LLMContextBuilder';
import { MemoryItem } from '../memory/MemoryEngine';
import { UserProfile } from '../memory/UserProfile';
import { SpeechRecognizer } from '../multimodal/SpeechRecognizer';
import {
  DialogueGenerator,
  MemoryContextItem,
  UserProfileSummary,
} from '../persona/DialogueGenerator';
import { PersonaRules } from '../persona/PersonaRules';
import { EventBus } from '../shared/EventBus';
import { Logger } from '../utils/Logger';
import { ContinuousDialogManager } from './ContinuousDialogManager';
import { EmojiManager } from './EmojiManager';
import { SpeechSynthesizer } from './SpeechSynthesizer';

interface CoreEngineLike {
  processInput(
    input: string,
    userId: string,
    traceId?: string
  ): Promise<unknown>;
}

/**
 * 交互计划接口
 */
export interface InteractionPlan {
  estimatedTime: number;
  needEmotionSupport: boolean;
  progressUpdateFrequency: number;
  emotionSupportContent: string;
}

export interface PersonaAwareResponse {
  content: string;
  emotion: string;
  scene: string;
  persona: string;
  confidence: number;
}

export interface TrackedResponseResult {
  success: boolean;
  response?: string;
  personaAwareResponse?: PersonaAwareResponse;
  duration: number;
  traceId: string;
  error?: string;
}

/**
 * 交互引擎类 v2
 * 模板已死，LLM + 记忆永生
 */
export class InteractionEngine {
  private personaRules: PersonaRules;
  private personaEngine: unknown = null;
  private speechSynthesizer: SpeechSynthesizer;
  private emojiManager: EmojiManager;
  private voiceprintRecognizer: unknown = null;
  private continuousDialogManager: ContinuousDialogManager;
  private userProfile: UserProfile;
  private interactionHistory: Array<{
    type: string;
    content: unknown;
    timestamp: Date;
    emotion?: string;
    scene?: string;
  }> = [];
  private isSpeaking: boolean = false;
  private core: CoreEngineLike | null = null;
  private dialogueGenerator: DialogueGenerator | null = null;
  private contextBuilder: LLMContextBuilder;

  // v2: 多模态处理器（复用现有架构）
  private speechRecognizer: SpeechRecognizer;

  constructor(
    userProfile?: UserProfile,
    dialogueGenerator?: DialogueGenerator
  ) {
    this.personaRules = new PersonaRules();
    this.personaEngine = null;
    this.speechSynthesizer = new SpeechSynthesizer();
    this.emojiManager = new EmojiManager();
    // VoiceprintRecognizer removed in v4.0
    this.continuousDialogManager = new ContinuousDialogManager();
    this.userProfile = userProfile || new UserProfile();
    this.dialogueGenerator = dialogueGenerator || null;
    this.contextBuilder = new LLMContextBuilder();

    // v2: 初始化多模态处理器（复用现有类）
    this.speechRecognizer = new SpeechRecognizer();

    this.setupEventBusListeners();
  }

  /**
   * 设置对话生成器（由 JiabaixingCore 注入）
   */
  public setDialogueGenerator(generator: DialogueGenerator): void {
    this.dialogueGenerator = generator;
  }

  /**
   * 安全获取表情管理器实例（优雅降级）
   */
  private async safeGenerateEmoji(options: {
    emotion?: string;
    scene?: string;
    context?: string;
    style?: 'static' | 'animated';
    service?: 'local' | 'api';
  }): Promise<string> {
    if (!this.emojiManager || !this.emojiManager.isInitialized()) {
      return '';
    }
    try {
      return await this.emojiManager.generateEmoji(options);
    } catch (error) {
      Logger.warn(
        '⚠️ EmojiManager generateEmoji 降级处理:',
        (error as Error).message,
        'InteractionEngine'
      );
      return '';
    }
  }

  /**
   * 设置核心引擎引用
   */
  public setCore(core: CoreEngineLike): void {
    this.core = core;
  }

  /**
   * 初始化交互引擎
   */
  public async initialize(): Promise<void> {
    // PersonaEngine removed in v4.0
    await this.speechSynthesizer.initialize();
    await this.emojiManager.initialize();
    // VoiceprintRecognizer removed in v4.0
    await this.continuousDialogManager.initialize();
    await this.userProfile.load();
  }

  /**
   * 生成任务执行前的回复
   * 不再使用模板，而是通过 DialogueGenerator 生成自然回复
   */
  public async generatePreExecutionResponse(
    taskGraph: DAGTask,
    plan: InteractionPlan,
    emotion?: string,
    scene?: string
  ): Promise<void> {
    let response = '';

    if (this.dialogueGenerator) {
      // 使用 LLM 生成自然的确认回复
      const sceneTag = scene || 'daily';
      const memoryContext = this.buildMemoryContextFromHistory();
      const userProfileSummary = this.buildUserProfileSummary();

      const preExecPrompt = `用户刚刚要求我执行一个任务，预计需要 ${Math.ceil(plan.estimatedTime / 60)} 分钟。
任务名称：${taskGraph.getName() || '未指定'}

请生成一句简短，自然的确认回复。像一位专业的秘书确认收到任务一样。不要啰嗦。`;

      try {
        response = await this.dialogueGenerator.generate(
          preExecPrompt,
          sceneTag,
          memoryContext,
          userProfileSummary
        );
      } catch {
        // LLM 失败时降级到极简确认
        response =
          plan.estimatedTime < 10
            ? '好的，马上处理。'
            : `收到，预计需要 ${Math.ceil(plan.estimatedTime / 60)} 分钟。`;
      }
    } else {
      // 无 DialogueGenerator 时的极简降级
      response =
        plan.estimatedTime < 10
          ? '好的，马上处理。'
          : `收到，预计需要 ${Math.ceil(plan.estimatedTime / 60)} 分钟。`;
    }

    // 如果需要情绪支持，添加情绪安抚内容
    if (plan.needEmotionSupport && plan.emotionSupportContent) {
      response = `${plan.emotionSupportContent}\n${response}`;
    }

    // 应用人设规则（语气微调，非硬拦截）
    const finalResponse = this.personaRules.adjustTone(
      response,
      scene || 'daily'
    ).adjustedContent;

    // 输出回复
    await this.outputResponseInternal(finalResponse, emotion, scene);

    // 保存到交互历史
    this.interactionHistory.push({
      type: 'pre_execution',
      content: finalResponse,
      emotion,
      scene,
      timestamp: new Date(),
    });
  }

  /**
   * 生成任务执行结果的回复
   * 完全基于 LLM + 记忆上下文，消除模板
   */
  public async generateResultResponse(
    result: unknown,
    emotion: EmotionTag,
    scene: SceneTag,
    memoryContext: MemoryItem[]
  ): Promise<string> {
    // 获取用户画像信息
    const userBasicInfo = this.userProfile.getBasicInfo();
    const userDevHabits = this.userProfile.getDevelopmentHabits();
    const userEmotionPatterns = this.userProfile.getEmotionalPatterns();

    // 获取最近的用户输入
    let userInput = '';
    if (this.interactionHistory.length > 0) {
      const lastInteraction =
        this.interactionHistory[this.interactionHistory.length - 1];
      if (lastInteraction.type === 'user_input') {
        userInput = lastInteraction.content as string;
      }
    }

    let response = '';

    // 优先使用 DialogueGenerator 生成回复
    if (this.dialogueGenerator) {
      try {
        const memoryCtx = memoryContext.map((m) => {
          const contentStr =
            typeof m.content === 'string'
              ? m.content
              : JSON.stringify(m.content);
          return {
            content: contentStr,
            type: m.type || 'memory',
            relevance: m.relevanceScore,
          };
        });

        const userProfileSummary: UserProfileSummary = {
          name: userBasicInfo.name,
          preferredLanguage: userDevHabits.preferredLanguages[0],
          preferredFrameworks: userDevHabits.preferredFrameworks,
          recentTopics: [],
          behaviorHints: [
            ...userEmotionPatterns.commonEmotions.map(
              (e) => `常表达${e.type}情绪`
            ),
            userDevHabits.codingStyle
              ? `编码风格: ${JSON.stringify(userDevHabits.codingStyle)}`
              : '',
          ].filter(Boolean),
        };

        // 构建结果摘要作为用户输入
        const resultSummary = this.summarizeResult(result);
        const prompt = userInput
          ? `用户之前说："${userInput}"\n\n任务执行结果：${resultSummary}\n\n请根据结果生成回复。`
          : `任务执行结果：${resultSummary}\n\n请生成回复。`;

        response = await this.dialogueGenerator.generate(
          prompt,
          scene.type,
          memoryCtx,
          userProfileSummary
        );
      } catch (error) {
        Logger.warn(
          `DialogueGenerator 失败，使用降级回复: ${(error as Error).message}`,
          'InteractionEngine'
        );
        response = this.summarizeResult(result);
      }
    } else {
      // 无 DialogueGenerator 时的降级
      response = this.summarizeResult(result);
    }

    // 应用人设规则
    const finalResponse = this.personaRules.adjustTone(
      response,
      scene.type
    ).adjustedContent;

    // 输出回复
    await this.outputResponseInternal(finalResponse, emotion.type, scene.type);

    // 保存到交互历史
    this.interactionHistory.push({
      type: 'result',
      content: finalResponse,
      emotion: emotion.type,
      scene: scene.type,
      timestamp: new Date(),
    });

    return finalResponse;
  }

  /**
   * 格式化结果为自然语言摘要
   */
  private summarizeResult(result: unknown): string {
    if (!result) return '任务已完成。';

    const r = result as Record<string, unknown>;

    // 提取关键信息
    const parts: string[] = [];

    if (r.success === true) {
      parts.push('执行成功');
    } else if (r.success === false) {
      parts.push('执行未成功');
    }

    if (r.summary && typeof r.summary === 'string') {
      parts.push(r.summary);
    }

    if (r.message && typeof r.message === 'string') {
      parts.push(r.message);
    }

    if (r.output) {
      const outputStr =
        typeof r.output === 'string'
          ? r.output
          : JSON.stringify(r.output).substring(0, 200);
      if (outputStr && outputStr !== '{}') {
        parts.push(`输出: ${outputStr}`);
      }
    }

    if (parts.length > 1) {
      return parts.join('。') + '。';
    }

    return parts[0] || '任务已完成。';
  }

  /**
   * 为前端格式化结果（御姐秘书口吻）
   */
  public async formatResultForOwner(
    result: unknown,
    taskDescription: string,
    _scene: string,
    emotion?: string
  ): Promise<string> {
    if (!this.dialogueGenerator) {
      return this.summarizeResult(result);
    }

    const memoryContext = this.buildMemoryContextFromHistory();
    const userProfileSummary = this.buildUserProfileSummary();

    const prompt = `我刚刚完成了一个任务：${taskDescription}
执行结果：${JSON.stringify(result, null, 2).substring(0, 800)}

请用自然、专业的语气向用户汇报结果。像一位可靠的秘书汇报工作一样。
要具体、有信息量，但不要说教。如果结果中有错误，客观说明，不要过度道歉。`;

    try {
      const response = await this.dialogueGenerator.generate(
        prompt,
        'work',
        memoryContext,
        userProfileSummary
      );

      // 应用人设规则
      return this.personaRules.adjustTone(response, emotion || 'daily')
        .adjustedContent;
    } catch {
      return this.summarizeResult(result);
    }
  }

  /**
   * 生成对话式回复（供 JiabaixingCore 直接调用）
   * 这是主要的对外接口，完全基于 LLM + 记忆
   *
   * v2 优化：使用 LLMContextBuilder 智能筛选记忆
   */
  public async generateChatResponse(
    input: string,
    scene: string,
    memoryContext: MemoryContextItem[],
    userProfileSummary?: UserProfileSummary
  ): Promise<string> {
    if (!this.dialogueGenerator) {
      Logger.warn(
        'DialogueGenerator 未注入，使用降级回复',
        'InteractionEngine'
      );
      return '我在。有什么可以帮你的？';
    }

    try {
      // 使用 LLMContextBuilder 智能筛选和排序记忆
      const memoryItems: MemoryItem[] = memoryContext.map((mc) => ({
        id: `ctx_${Math.random().toString(36).substring(2, 11)}`,
        type: mc.type as import('../memory/MemoryEngine').MemoryType,
        content: mc.content,
        timestamp: mc.timestamp || new Date(),
        relevanceScore: mc.relevance,
      }));

      const builtContext = this.contextBuilder.buildContext(
        input,
        memoryItems,
        scene,
        userProfileSummary?.behaviorHints?.[0] || '平静'
      );

      const optimizedContext = LLMContextBuilder.toMemoryContextItems(
        builtContext.memories
      );

      Logger.info(
        `🧠 记忆优化: ${memoryContext.length}→${optimizedContext.length}条 | ` +
          `去重${builtContext.deduplicatedCount} | 压缩${builtContext.compressedCount}`,
        'InteractionEngine'
      );

      const response = await this.dialogueGenerator.generate(
        input,
        scene,
        optimizedContext,
        userProfileSummary
      );

      // 应用人设规则（语气微调）
      const toneResult = this.personaRules.adjustTone(response, scene);

      // 保存到交互历史
      this.interactionHistory.push({
        type: 'chat_response',
        content: toneResult.adjustedContent,
        scene,
        timestamp: new Date(),
      });

      return toneResult.adjustedContent;
    } catch (error) {
      Logger.error('生成对话回复失败', error as Error, 'InteractionEngine');
      return '抱歉，我暂时无法回应。请稍后再试。';
    }
  }

  /**
   * 生成主动关怀消息
   */
  public async generateProactiveMessage(
    reason: string,
    scene: string,
    context: string,
    _memoryContext: MemoryItem[]
  ): Promise<string> {
    if (!this.dialogueGenerator) {
      return '有什么我可以帮你的吗？';
    }

    const memoryContext = this.buildMemoryContextFromHistory();
    const userProfileSummary = this.buildUserProfileSummary();

    const prompt = `作为用户的私人秘书，我需要主动发起一次交互。
原因：${reason}
上下文：${context}

请生成一条自然、不突兀的主动消息。像一位细心的秘书在合适的时机开口一样。
不要问"有什么可以帮你的"这种套话，而是基于上下文给出具体的关切或提醒。`;

    try {
      const response = await this.dialogueGenerator.generate(
        prompt,
        scene,
        memoryContext,
        userProfileSummary
      );

      return this.personaRules.adjustTone(response, scene).adjustedContent;
    } catch {
      return context || '有什么新情况需要我关注吗？';
    }
  }

  /**
   * 处理用户输入（供外部调用）
   */
  public async processUserInput(
    input: string,
    emotion: string = '平静',
    scene: string = 'daily'
  ): Promise<string> {
    // 保存用户输入到历史
    this.interactionHistory.push({
      type: 'user_input',
      content: input,
      emotion,
      scene,
      timestamp: new Date(),
    });

    // 如果有核心引擎，交给核心引擎处理
    if (this.core) {
      const result = await this.core.processInput(input, 'default');
      return (result as { response?: string }).response || '';
    }

    return '';
  }

  // ═══════════════════════════ v2: 多模态输入处理 ═══════════════════════════

  /**
   * 处理音频输入（语音转文字）
   */
  public async processAudioInput(
    audioBuffer: Buffer,
    _mimeType: string = 'audio/wav'
  ): Promise<{ text: string; confidence: number }> {
    try {
      Logger.info('🎤 处理音频输入', 'InteractionEngine');

      // 使用现有的 SpeechRecognizer（已集成 Whisper）
      const result = await this.speechRecognizer.recognize(audioBuffer);

      Logger.info(
        `🎤 语音识别结果: ${result.text} (置信度: ${result.confidence?.toFixed(2)})`,
        'InteractionEngine'
      );

      return {
        text: result.text,
        confidence: result.confidence || 0,
      };
    } catch (error) {
      Logger.error('❌ 音频处理失败', error as Error, 'InteractionEngine');
      return { text: '', confidence: 0 };
    }
  }

  /**
   * 处理图像输入
   */
  public async processImageInput(
    imageBuffer: Buffer,
    mimeType: string
  ): Promise<{ description: string; base64: string }> {
    try {
      Logger.info('🖼️ 处理图像输入', 'InteractionEngine');

      const base64 = imageBuffer.toString('base64');

      Logger.info(
        `🖼️ 图像处理完成: ${mimeType}`,
        'InteractionEngine'
      );

      return {
        description: `图像 (${mimeType})`,
        base64,
      };
    } catch (error) {
      Logger.error('❌ 图像处理失败', error as Error, 'InteractionEngine');
      return { description: '', base64: '' };
    }
  }

  /**
   * 处理文件输入
   */
  public async processFileInput(
    fileBuffer: Buffer,
    fileName: string,
    mimeType: string
  ): Promise<{ content: string; summary: string }> {
    try {
      Logger.info(`📄 处理文件输入: ${fileName}`, 'InteractionEngine');

      const content = fileBuffer.toString('utf-8');
      const summary = `${fileName} (${mimeType})`;

      Logger.info(
        `📄 文件分析完成: ${fileName}`,
        'InteractionEngine'
      );

      return {
        content,
        summary,
      };
    } catch (error) {
      Logger.error(
        `❌ 文件处理失败: ${fileName}`,
        error as Error,
        'InteractionEngine'
      );
      return { content: '', summary: `无法解析文件: ${fileName}` };
    }
  }

  // ═══════════════════════════ 内部方法 ═══════════════════════════

  private setupEventBusListeners(): void {
    EventBus.on('ws_send', (data: unknown) => {
      const message = data as Record<string, unknown>;
      this.interactionHistory.push({
        type: 'ws_send',
        content: message,
        timestamp: new Date(),
      });
    });

    EventBus.on('user_input', (data: unknown) => {
      const input = data as Record<string, unknown>;
      this.interactionHistory.push({
        type: 'user_input',
        content: input.text,
        timestamp: new Date(),
      });
    });
  }

  private async outputResponseInternal(
    response: string,
    _emotion?: string,
    _scene?: string
  ): Promise<void> {
    void EventBus.emit('response_ready', {
      response,
      traceId: Logger.getTraceId() || `ie_${Date.now()}`,
      success: true,
    });
  }

  private buildMemoryContextFromHistory(): MemoryContextItem[] {
    return this.interactionHistory.slice(-10).map((h) => ({
      content:
        typeof h.content === 'string' ? h.content : JSON.stringify(h.content),
      type: h.type,
      timestamp: h.timestamp,
    }));
  }

  private buildUserProfileSummary(): UserProfileSummary {
    const basicInfo = this.userProfile.getBasicInfo();
    const devHabits = this.userProfile.getDevelopmentHabits();
    const emotionPatterns = this.userProfile.getEmotionalPatterns();

    return {
      name: basicInfo.name,
      preferredLanguage: devHabits.preferredLanguages[0],
      preferredFrameworks: devHabits.preferredFrameworks,
      recentTopics: [],
      behaviorHints: [
        ...emotionPatterns.commonEmotions.map((e) => `常表达${e.type}情绪`),
        devHabits.codingStyle
          ? `编码风格: ${JSON.stringify(devHabits.codingStyle)}`
          : '',
      ].filter(Boolean),
    };
  }

  /**
   * 生成最大重试次数响应
   */
  public async generateMaxRetryResponse(): Promise<string> {
    if (this.dialogueGenerator) {
      try {
        return await this.dialogueGenerator.generate(
          '我已经尝试了很多次，但似乎遇到了困难。请告诉我更多细节，或者换个方式描述您的需求。',
          'work',
          [],
          this.buildUserProfileSummary()
        );
      } catch {
        return '抱歉，经过多次尝试仍无法完成。请提供更多细节，或换个方式描述需求。';
      }
    }
    return '抱歉，经过多次尝试仍无法完成。请提供更多细节，或换个方式描述需求。';
  }

  /**
   * 生成错误响应
   */
  public async generateErrorResponse(error: Error): Promise<string> {
    const errorMsg = error?.message || '未知错误';

    if (this.dialogueGenerator) {
      try {
        return await this.dialogueGenerator.generate(
          `执行过程中遇到问题：${errorMsg}。请确认相关服务是否正常运行。`,
          'work',
          [],
          this.buildUserProfileSummary()
        );
      } catch {
        return `执行遇到问题：${errorMsg}。`;
      }
    }
    return `执行遇到问题：${errorMsg}。`;
  }

  /**
   * 关闭交互引擎（兼容 JiaBaiXing 主类）
   */
  public async shutdown(): Promise<void> {
    Logger.info('正在关闭 InteractionEngine...', 'InteractionEngine');
    this.interactionHistory = [];
    this.isSpeaking = false;
  }

  public async generateResponseWithPersona(
    input: string,
    emotion: string,
    scene: string,
    context: MemoryItem[],
    traceId?: string
  ): Promise<TrackedResponseResult> {
    const finalTraceId =
      traceId ||
      `ie_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`;
    const startTime = Date.now();

    EventBus.startTrace(finalTraceId, 'interaction_generate_response', {
      input: input.substring(0, 50),
      emotion,
      scene,
      contextCount: context.length,
    });

    try {
      const memoryContextItems: MemoryContextItem[] = context.map((item) => ({
        content:
          typeof item.content === 'string'
            ? item.content
            : JSON.stringify(item.content),
        type: item.type,
        timestamp: item.timestamp,
      }));

      const baseResponse = await this.generateChatResponse(
        input,
        scene,
        memoryContextItems
      );

      const personaAdjusted = this.personaRules.adjustTone(baseResponse, scene);

      const emotionAdjusted = this.adjustByEmotion(
        personaAdjusted.adjustedContent,
        emotion
      );

      const currentPersona = this.getCurrentPersona();

      const confidence = this.calculateConfidence(emotion, scene);

      EventBus.completeTrace(finalTraceId, true);

      void EventBus.emit('response_ready', {
        response: emotionAdjusted,
        traceId: finalTraceId,
        success: true,
        duration: Date.now() - startTime,
      });

      return {
        success: true,
        response: emotionAdjusted,
        personaAwareResponse: {
          content: emotionAdjusted,
          emotion,
          scene,
          persona: currentPersona,
          confidence,
        },
        duration: Date.now() - startTime,
        traceId: finalTraceId,
      };
    } catch (error) {
      EventBus.failTrace(finalTraceId, (error as Error).message);

      return {
        success: false,
        error: (error as Error).message,
        duration: Date.now() - startTime,
        traceId: finalTraceId,
      };
    }
  }

  private adjustByEmotion(response: string, emotion: string): string {
    const emotionAdjustments: Record<string, (response: string) => string> = {
      开心: (r) => `😊 ${r}`,
      难过: (r) => `抱抱你，${r}`,
      生气: (r) => `我理解你的感受，${r}`,
      焦虑: (r) => `别担心，${r}`,
      平静: (r) => r,
    };

    const adjust = emotionAdjustments[emotion] || emotionAdjustments['平静'];
    return adjust(response);
  }

  private getCurrentPersona(): string {
    return '御姐秘书';
  }

  private calculateConfidence(emotion: string, scene: string): number {
    let confidence = 0.8;

    if (emotion === '平静') {
      confidence += 0.1;
    }

    if (scene === 'development' || scene === 'work') {
      confidence += 0.1;
    }

    return Math.min(1, confidence);
  }
}

