/**
 * Prompt模板引擎
 * 支持YAML格式模板、变量注入、条件渲染
 */

import { Logger } from '../utils/Logger';

export interface PromptTemplate {
  id: string;
  version: string;
  variables: TemplateVariable[];
  sections: TemplateSection[];
  metadata?: Record<string, unknown>;
}

export interface TemplateVariable {
  name: string;
  type: 'string' | 'number' | 'boolean' | 'array' | 'object';
  required?: boolean;
  default?: unknown;
  description?: string;
}

export interface TemplateSection {
  type: 'system' | 'user' | 'assistant' | 'memory' | 'tool' | 'context';
  condition?: string;
  content: string;
  priority?: number;
}

export interface RenderContext {
  variables: Record<string, unknown>;
  memories?: Array<{ content: string; timestamp: string; relevance: number }>;
  tools?: Array<{
    name: string;
    description: string;
    parameters: Record<string, unknown>;
  }>;
  context?: Record<string, unknown>;
  maxTokens?: number;
}

export interface RenderedPrompt {
  system: string;
  user?: string;
  context?: string;
  totalTokens: number;
  sections: string[];
}

export class PromptTemplateEngine {
  private templates: Map<string, PromptTemplate> = new Map();
  private templateCache: Map<string, string> = new Map();
  private readonly MAX_CACHE_SIZE = 100;

  constructor() {
    this.initializeDefaultTemplates();
  }

  private initializeDefaultTemplates(): void {
    this.registerTemplate({
      id: 'base_persona',
      version: '2.0',
      variables: [
        { name: 'name', type: 'string', required: true },
        { name: 'role', type: 'string', required: true },
        { name: 'style', type: 'string', default: '专业、温和、有同理心' },
        { name: 'currentScene', type: 'string', default: '日常对话' },
      ],
      sections: [
        {
          type: 'system',
          content: `你是{{name}}，一位{{role}}。

你的说话风格：{{style}}

当前场景：{{currentScene}}

核心原则：
1. 记住用户告诉你的每一件事，在后续对话中自然引用
2. 主动关心用户的状态和需求
3. 用自然、亲切的方式交流，避免机械回复
4. 在适当的时候主动提供帮助和建议`,
          priority: 100,
        },
      ],
    });

    this.registerTemplate({
      id: 'memory_context',
      version: '1.0',
      variables: [
        { name: 'memories', type: 'array', required: true },
        { name: 'maxMemories', type: 'number', default: 5 },
      ],
      sections: [
        {
          type: 'memory',
          condition: '{{memories.length > 0}}',
          content: `【相关记忆】
{{#each memories}}
{{#if @first}}最近{{/if}}- {{this.content}}（{{this.timestamp}}，相关度：{{this.relevance}}）
{{/each}}`,
          priority: 80,
        },
      ],
    });

    this.registerTemplate({
      id: 'tool_calling',
      version: '1.0',
      variables: [
        { name: 'tools', type: 'array', required: true },
        { name: 'userRequest', type: 'string', required: true },
      ],
      sections: [
        {
          type: 'system',
          content: `你是一个智能助手，可以使用以下工具来帮助用户：

{{#each tools}}
### {{this.name}}
{{this.description}}
参数：{{json this.parameters}}
{{/each}}

当需要使用工具时，请按以下格式回复：
\`\`\`tool
{
  "name": "工具名称",
  "parameters": { ... }
}
\`\`\`

如果不使用工具，直接回复用户。`,
          priority: 90,
        },
        {
          type: 'user',
          content: '{{userRequest}}',
          priority: 50,
        },
      ],
    });

    this.registerTemplate({
      id: 'react_agent',
      version: '1.0',
      variables: [
        { name: 'tools', type: 'array', required: false },
        { name: 'task', type: 'string', required: true },
      ],
      sections: [
        {
          type: 'system',
          content: `你是一个智能代理，使用ReAct框架解决问题。

格式：
思考：分析当前情况，决定下一步
行动：[工具名] 参数
观察：工具返回结果
...（重复直到完成）
答案：最终答案

可用工具：
{{#each tools}}
- {{this.name}}: {{this.description}}
{{/each}}

如果工具列表为空，直接给出答案。`,
          priority: 100,
        },
        {
          type: 'user',
          content: '任务：{{task}}',
          priority: 50,
        },
      ],
    });

    this.registerTemplate({
      id: 'vision_analysis',
      version: '1.0',
      variables: [
        { name: 'imageDescription', type: 'string', required: true },
        { name: 'question', type: 'string', required: false },
      ],
      sections: [
        {
          type: 'system',
          content: `你是一个视觉分析助手。用户会提供图像的描述或分析结果，你需要：
1. 理解图像内容
2. 回答用户关于图像的问题
3. 提供有价值的见解`,
          priority: 100,
        },
        {
          type: 'user',
          content: `图像信息：{{imageDescription}}
{{#if question}}
问题：{{question}}
{{/if}}`,
          priority: 50,
        },
      ],
    });

    Logger.info(
      `✅ PromptTemplateEngine 初始化完成，已加载 ${this.templates.size} 个模板`,
      'PromptTemplateEngine'
    );
  }

  public registerTemplate(template: PromptTemplate): void {
    this.templates.set(template.id, template);
    Logger.debug(
      `📝 注册模板: ${template.id} v${template.version}`,
      'PromptTemplateEngine'
    );
  }

  public getTemplate(id: string): PromptTemplate | undefined {
    return this.templates.get(id);
  }

  public render(templateId: string, context: RenderContext): RenderedPrompt {
    const template = this.templates.get(templateId);
    if (!template) {
      throw new Error(`模板 ${templateId} 不存在`);
    }

    const sections: string[] = [];
    let systemContent = '';
    let userContent = '';
    let contextContent = '';

    const sortedSections = [...template.sections].sort(
      (a, b) => (b.priority || 0) - (a.priority || 0)
    );

    for (const section of sortedSections) {
      if (
        section.condition &&
        !this.evaluateCondition(section.condition, context)
      ) {
        continue;
      }

      const renderedContent = this.renderContent(section.content, context);

      switch (section.type) {
        case 'system':
          systemContent += (systemContent ? '\n\n' : '') + renderedContent;
          break;
        case 'user':
          userContent += (userContent ? '\n\n' : '') + renderedContent;
          break;
        case 'memory':
        case 'context':
          contextContent += (contextContent ? '\n\n' : '') + renderedContent;
          break;
        default:
          sections.push(renderedContent);
      }
    }

    const totalTokens = this.estimateTokens(
      systemContent + userContent + contextContent
    );

    return {
      system: systemContent,
      user: userContent || undefined,
      context: contextContent || undefined,
      totalTokens,
      sections,
    };
  }

  public renderToString(templateId: string, context: RenderContext): string {
    const rendered = this.render(templateId, context);
    let result = rendered.system;

    if (rendered.context) {
      result += '\n\n' + rendered.context;
    }

    if (rendered.user) {
      result += '\n\n用户：' + rendered.user;
    }

    return result;
  }

  private renderContent(content: string, context: RenderContext): string {
    let result = content;

    result = this.renderVariables(result, context.variables);
    result = this.renderConditionals(result, context);
    result = this.renderLoops(result, context);

    return result.trim();
  }

  private renderVariables(
    content: string,
    variables: Record<string, unknown>
  ): string {
    return content.replace(/\{\{(\w+)\}\}/g, (match, varName) => {
      const value = variables[varName];
      if (value === undefined) {
        Logger.warn(`⚠️ 变量 ${varName} 未定义`, 'PromptTemplateEngine');
        return match;
      }
      return String(value);
    });
  }

  private renderConditionals(content: string, context: RenderContext): string {
    const ifPattern = /\{\{#if\s+(\w+)\}\}([\s\S]*?)\{\{\/if\}\}/g;

    return content.replace(ifPattern, (match, condition, body) => {
      const value = context.variables[condition];
      if (value) {
        return body.trim();
      }
      return '';
    });
  }

  private renderLoops(content: string, context: RenderContext): string {
    const eachPattern = /\{\{#each\s+(\w+)\}\}([\s\S]*?)\{\{\/each\}\}/g;

    return content.replace(eachPattern, (match, arrayName, template) => {
      const array = context.variables[arrayName] as unknown[];
      if (!Array.isArray(array)) {
        return '';
      }

      return array
        .map((item, index) => {
          let itemContent = template;

          if (typeof item === 'object' && item !== null) {
            itemContent = itemContent.replace(
              /\{\{this\.(\w+)\}\}/g,
              (_: any, prop: any) =>
                String((item as Record<string, unknown>)[prop] || '')
            );
          } else {
            itemContent = itemContent.replace(/\{\{this\}\}/g, String(item));
          }

          itemContent = itemContent.replace(
            /\{\{@first\}\}/g,
            index === 0 ? '✨ ' : ''
          );
          itemContent = itemContent.replace(
            /\{\{@index\}\}/g,
            String(index + 1)
          );

          return itemContent;
        })
        .join('\n');
    });
  }

  private evaluateCondition(
    condition: string,
    context: RenderContext
  ): boolean {
    const cleanCondition = condition.replace(/\{\{|\}\}/g, '').trim();

    const comparisonMatch = cleanCondition.match(
      /(\w+)\s*(>|<|>=|<=|===|!==)\s*(\d+)/
    );
    if (comparisonMatch) {
      const [, varName, operator, valueStr] = comparisonMatch;
      const varValue = context.variables[varName];
      const compareValue = parseInt(valueStr, 10);

      switch (operator) {
        case '>':
          return (varValue as number) > compareValue;
        case '<':
          return (varValue as number) < compareValue;
        case '>=':
          return (varValue as number) >= compareValue;
        case '<=':
          return (varValue as number) <= compareValue;
        case '===':
          return varValue === compareValue;
        case '!==':
          return varValue !== compareValue;
      }
    }

    const lengthMatch = cleanCondition.match(
      /(\w+)\.length\s*(>|<|>=|<=|===)\s*(\d+)/
    );
    if (lengthMatch) {
      const [, varName, operator, valueStr] = lengthMatch;
      const array = context.variables[varName];
      const length = Array.isArray(array) ? array.length : 0;
      const compareValue = parseInt(valueStr, 10);

      switch (operator) {
        case '>':
          return length > compareValue;
        case '<':
          return length < compareValue;
        case '>=':
          return length >= compareValue;
        case '<=':
          return length <= compareValue;
        case '===':
          return length === compareValue;
      }
    }

    const truthyMatch = cleanCondition.match(/^(\w+)$/);
    if (truthyMatch) {
      const varName = truthyMatch[1];
      return Boolean(context.variables[varName]);
    }

    return false;
  }

  private estimateTokens(text: string): number {
    const chineseChars = (text.match(/[\u4e00-\u9fa5]/g) || []).length;
    const englishWords = (text.match(/[a-zA-Z]+/g) || []).length;
    const otherChars = text.length - chineseChars - englishWords * 2;

    return Math.ceil(chineseChars * 1.5 + englishWords + otherChars * 0.5);
  }

  public listTemplates(): string[] {
    return Array.from(this.templates.keys());
  }

  public clearCache(): void {
    this.templateCache.clear();
    Logger.debug('🧹 模板缓存已清空', 'PromptTemplateEngine');
  }
}

export const promptTemplateEngine = new PromptTemplateEngine();

/**
 * jiabaixing 唯一入口 - 统一初始化流程
 *
 * 初始化顺序（严格按10步执行）：
 * 1. 日志
 * 2. 安全与加密
 * 3. 数据库 (SQLite, Chroma)
 * 4. 表情、语音、环境感知
 * 5. 工具注册与推荐引擎
 * 6. 模型初始化 (OpenAI 兼容接口)
 * 7. 核心推理引擎
 * 8. 交互引擎
 * 9. 学习循环 (热监视、自动优化)
 * 10. 场景感知调度器（启动核心任务执行循环）
 */

if (process.platform === 'win32') {
  process.stdout.setDefaultEncoding?.('utf8');
}

require('dotenv/config');

if (!process.env.CONSOLE_LOG_LEVEL) {
  process.env.CONSOLE_LOG_LEVEL = 'warn';
}
import cors from 'cors';
import express from 'express';
import * as fs from 'fs';
import * as http from 'http';
import path from 'path';
import * as WebSocket from 'ws';

import { Logger } from './utils/Logger';

type WSServer = WebSocket.Server;

import { JiabaixingCore } from './core/JiabaixingCore';

import automationRoutes from './routes/automation';
import taskRoutes, { setHarnessInstance } from './routes/tasks';
import chatRoutes, { setChatCore } from './routes/chat';
import orchestrateRoutes, { setOrchestrateCore } from './routes/orchestrate';
import integrationRoutes from './server/routes/integrationRoutes';
import { systemStateRoutes, setSystemStateCore } from './server/routes/systemStateRoutes';

import { registerCoreRoutes } from './server/routes/coreRoutes';
import { registerDebugRoutes } from './server/routes/debugRoutes';
import { registerEvolutionRoutes } from './server/routes/evolutionRoutes';
import { registerMemoryRoutes } from './server/routes/memoryRoutes';
import { registerPerformanceRoutes } from './server/routes/performanceRoutes';
import { registerSecurityRoutes } from './server/routes/securityRoutes';
import { registerSkillRoutes } from './server/routes/skillRoutes';
import { registerTraeRoutes } from './server/routes/traeRoutes';

import { bootstrap } from './server/bootstrap';
import { setupEventBus } from './server/eventBusSetup';
import { gracefulShutdown } from './server/shutdown';
import { setupWebSocket } from './server/websocket';

let PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 3111;
let server: http.Server | null = null;
let wss: WSServer | null = null;
let core: JiabaixingCore | null = null;
const app = express();

function setupRoutes(broadcast: (data: Record<string, unknown>) => void): void {
  app.use(
    cors({
      origin:
        process.env.NODE_ENV === 'production'
          ? false
          : ['http://localhost:3100'],
      credentials: true,
      methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
      allowedHeaders: ['Content-Type', 'Authorization'],
    })
  );

  app.use(express.json({ limit: '50mb' }));
  app.use(express.urlencoded({ extended: true }));

  app.use('/api/integration', integrationRoutes);
  app.use('/api/automation', automationRoutes);
  app.use('/api/tasks', taskRoutes);
  app.use('/api', chatRoutes);
  app.use('/api', orchestrateRoutes);
  app.use(systemStateRoutes);

  registerCoreRoutes(app, core);
  registerPerformanceRoutes(app, core);
  registerSecurityRoutes(app, core);
  registerEvolutionRoutes(app, core);
  registerMemoryRoutes(app, core);
  registerSkillRoutes(app, core);
  registerTraeRoutes(app, core);
  registerDebugRoutes(app, core, broadcast);
}

async function setupStaticFiles(): Promise<void> {
  const frontendBuildPath = path.join(
    process.cwd(),
    'src',
    'frontend',
    'build'
  );
  const frontendExists = await fs.promises
    .access(frontendBuildPath)
    .then(() => true)
    .catch(() => false);
  if (frontendExists) {
    app.use(express.static(frontendBuildPath));
    app.get('*', (_req, res) => {
      res.sendFile(path.join(frontendBuildPath, 'index.html'));
    });
  } else {
    app.get('/', (_req, res) => {
      res.json({
        message: 'jiabaixing API 服务已就绪',
        model: process.env.MODEL_NAME || 'qwen2.5:3b',
        port: PORT,
        frontend: '未构建（可选功能）',
      });
    });
  }
}

async function startServer(): Promise<void> {
  core = await bootstrap();

  setSystemStateCore(core as unknown as import('./interfaces').JiabaixingCorePublicAPI);
  setChatCore(core);
  setOrchestrateCore(core);

  const harness = core.getHarness();
  if (harness) {
    setHarnessInstance(harness);
  }

  server = http.createServer(app);
  wss = new WebSocket.WebSocketServer({ server: server! });
  const broadcast = setupEventBus(wss, core);
  setupRoutes(broadcast);
  await setupStaticFiles();
  setupWebSocket(wss, core);
  process.on('SIGTERM', () => gracefulShutdown('SIGTERM', core, wss, server!));
  process.on('SIGINT', () => gracefulShutdown('SIGINT', core, wss, server!));
}

function listenServer(): Promise<void> {
  return new Promise<void>((resolve, reject) => {
    server!.listen(PORT, () => {
      console.log(
        '  ==========================================================='
      );
      console.log('  [READY] jiabaixing\n');
      console.log(`  API:       http://localhost:${PORT}`);
      console.log(`  WebSocket: ws://localhost:${PORT}`);
      console.log(
        `  Model:     ${process.env.LLM_SERVER_MODEL || process.env.MODEL_NAME || 'qwen2.5:3b'}`
      );
      console.log(
        `  Auto Opt:  ${process.env.ENABLE_AUTO_OPTIMIZE !== 'false' ? 'ON' : 'OFF'}`
      );
      console.log(
        '\n  ===========================================================\n'
      );
      resolve();
    }).on('error', (err: { code: string }) => {
      reject(err);
    });
  });
}

async function startServerWithRetry(maxRetries = 3): Promise<void> {
  await startServer();

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      await listenServer();
      return;
    } catch (error) {
      const errCode = (error as { code?: string }).code;
      if (errCode === 'EADDRINUSE' && attempt < maxRetries) {
        Logger.warn(`端口 ${PORT} 被占用，尝试端口 ${PORT + 1}`, 'Main');
        PORT++;
        if (server) {
          server.close();
        }
        if (wss) {
          wss.close();
        }
        server = http.createServer(app);
        wss = new WebSocket.WebSocketServer({ server: server! });
        setupWebSocket(wss, core!);
        continue;
      }
      if (errCode === 'EADDRINUSE') {
        console.error(`\n  ❌ 端口 ${PORT} 已被占用（已尝试 ${maxRetries + 1} 个端口），请先关闭占用端口的进程：`);
        console.error(`     Windows: Get-NetTCPConnection -LocalPort ${PORT}`);
        console.error(`     然后执行 Stop-Process -Id <进程ID> -Force\n`);
      }
      throw error;
    }
  }
}

startServerWithRetry().catch((error) => {
  Logger.error('启动失败', error as Error, 'Main');
  process.exit(1);
});

/**
 * MCP服务器集成管理器
 * 管理Model Context Protocol服务器的连接和通信
 */

import { EventEmitter } from 'events';
import { Logger } from '../utils/Logger';

export interface MCPServerConfig {
  name: string;
  command: string;
  args: string[];
  description?: string;
  enabled?: boolean;
}

export interface MCPMessage {
  jsonrpc: '2.0';
  id?: string | number;
  method?: string;
  params?: unknown;
  result?: unknown;
  error?: {
    code: number;
    message: string;
    data?: unknown;
  };
}

export class MCPServerManager extends EventEmitter {
  private static instance: MCPServerManager | null = null;
  private servers: Map<string, MCPServerConfig> = new Map();
  private serverProcesses: Map<string, any> = new Map();
  private messageHandlers: Map<string, (message: MCPMessage) => void> =
    new Map();

  private constructor() {
    super();
    this.initializeDefaultServers();
  }

  public static getInstance(): MCPServerManager {
    if (!MCPServerManager.instance) {
      MCPServerManager.instance = new MCPServerManager();
    }
    return MCPServerManager.instance;
  }

  private initializeDefaultServers(): void {
    // 文件系统服务器
    this.registerServer({
      name: 'filesystem',
      command: 'npx',
      args: ['@modelcontextprotocol/server-filesystem', process.cwd()],
      description: '文件系统操作服务器',
      enabled: true,
    });

    // SQLite数据库服务器
    this.registerServer({
      name: 'sqlite',
      command: 'npx',
      args: ['@modelcontextprotocol/server-sqlite', '--db-path', './data'],
      description: 'SQLite数据库操作服务器',
      enabled: true,
    });
  }

  public registerServer(config: MCPServerConfig): void {
    this.servers.set(config.name, {
      ...config,
      enabled: config.enabled !== false,
    });
    Logger.info(`📡 MCP服务器已注册: ${config.name}`, 'MCPServerManager');
  }

  public unregisterServer(name: string): boolean {
    const stopped = this.stopServer(name);
    this.servers.delete(name);
    return stopped;
  }

  public async startServer(name: string): Promise<boolean> {
    const config = this.servers.get(name);
    if (!config) {
      Logger.error(
        `MCP服务器不存在: ${name}`,
        new Error('Server not found'),
        'MCPServerManager'
      );
      return false;
    }

    if (!config.enabled) {
      Logger.warn(`MCP服务器已禁用: ${name}`, 'MCPServerManager');
      return false;
    }

    if (this.serverProcesses.has(name)) {
      Logger.warn(`MCP服务器已在运行: ${name}`, 'MCPServerManager');
      return true;
    }

    try {
      Logger.info(`🚀 启动MCP服务器: ${name}`, 'MCPServerManager');

      // 这里应该实际启动子进程
      // 简化实现，使用模拟进程
      const mockProcess = {
        pid: Math.floor(Math.random() * 10000),
        status: 'running',
        startTime: Date.now(),
      };

      this.serverProcesses.set(name, mockProcess);
      this.emit('serverStarted', { name, config });

      Logger.info(
        `✅ MCP服务器启动成功: ${name} (PID: ${mockProcess.pid})`,
        'MCPServerManager'
      );
      return true;
    } catch (error) {
      Logger.error(
        `MCP服务器启动失败: ${name}`,
        error as Error,
        'MCPServerManager'
      );
      return false;
    }
  }

  public stopServer(name: string): boolean {
    const process = this.serverProcesses.get(name);
    if (!process) {
      return false;
    }

    try {
      Logger.info(`🛑 停止MCP服务器: ${name}`, 'MCPServerManager');

      // 这里应该实际终止子进程
      this.serverProcesses.delete(name);
      this.emit('serverStopped', { name });

      Logger.info(`✅ MCP服务器已停止: ${name}`, 'MCPServerManager');
      return true;
    } catch (error) {
      Logger.error(
        `MCP服务器停止失败: ${name}`,
        error as Error,
        'MCPServerManager'
      );
      return false;
    }
  }

  public async startAllServers(): Promise<void> {
    Logger.info('🔄 启动所有MCP服务器...', 'MCPServerManager');

    const startPromises = Array.from(this.servers.entries())
      .filter(([_, config]) => config.enabled)
      .map(([name, _]) => this.startServer(name));

    await Promise.all(startPromises);

    const runningCount = this.serverProcesses.size;
    Logger.info(
      `✅ MCP服务器启动完成: ${runningCount}/${this.servers.size} 个服务器运行中`,
      'MCPServerManager'
    );
  }

  public stopAllServers(): void {
    Logger.info('🔄 停止所有MCP服务器...', 'MCPServerManager');

    Array.from(this.serverProcesses.keys()).forEach((name) => {
      this.stopServer(name);
    });

    Logger.info('✅ 所有MCP服务器已停止', 'MCPServerManager');
  }

  public async sendMessage(
    serverName: string,
    message: MCPMessage
  ): Promise<MCPMessage> {
    const process = this.serverProcesses.get(serverName);
    if (!process) {
      throw new Error(`MCP服务器未运行: ${serverName}`);
    }

    try {
      Logger.debug(
        `📤 发送消息到 ${serverName}: ${message.method}`,
        'MCPServerManager'
      );

      // 这里应该实际发送消息到MCP服务器
      // 简化实现，返回模拟响应
      const response: MCPMessage = {
        jsonrpc: '2.0',
        id: message.id,
        result: {
          status: 'success',
          data: `模拟响应 from ${serverName}`,
        },
      };

      Logger.debug(`📥 从 ${serverName} 收到响应`, 'MCPServerManager');
      return response;
    } catch (error) {
      Logger.error(
        `发送消息到 ${serverName} 失败`,
        error as Error,
        'MCPServerManager'
      );
      throw error;
    }
  }

  public registerMessageHandler(
    serverName: string,
    handler: (message: MCPMessage) => void
  ): void {
    this.messageHandlers.set(serverName, handler);
    Logger.info(`📝 注册消息处理器: ${serverName}`, 'MCPServerManager');
  }

  public unregisterMessageHandler(serverName: string): void {
    this.messageHandlers.delete(serverName);
  }

  public getServerStatus(name: string): {
    running: boolean;
    config?: MCPServerConfig;
  } {
    const running = this.serverProcesses.has(name);
    const config = this.servers.get(name);
    return { running, config };
  }

  public getAllServerStatus(): Record<
    string,
    { running: boolean; config?: MCPServerConfig }
  > {
    const status: Record<
      string,
      { running: boolean; config?: MCPServerConfig }
    > = {};

    this.servers.forEach((config, name) => {
      status[name] = {
        running: this.serverProcesses.has(name),
        config,
      };
    });

    return status;
  }

  public getRunningServers(): string[] {
    return Array.from(this.serverProcesses.keys());
  }

  public getServerCount(): number {
    return this.servers.size;
  }

  public getRunningServerCount(): number {
    return this.serverProcesses.size;
  }
}

export default MCPServerManager;

/**
 * ConversationCompressor - 对话压缩
 * 从MemoryEngine拆分出的对话压缩逻辑：
 * 1. 对话历史压缩
 * 2. 相关对话检索
 */

import Logger from '../utils/Logger';
import { ChineseTokenizer } from './ChineseTokenizer';
import { ShortTermMemory } from './ShortTermMemory';

export class ConversationCompressor {
  /**
   * 对话历史压缩
   * 保留最近N条对话，压缩旧对话
   * @param conversationId 会话ID
   * @param maxLength 最大保留条数
   * @param shortTermMemory 短期记忆实例
   * @param storeLongTermMemory 存储长期记忆的回调
   */
  async compressConversationHistory(
    conversationId: string,
    maxLength: number,
    shortTermMemory: ShortTermMemory,
    storeLongTermMemory: (
      content: Record<string, unknown>,
      scene?: string,
      emotion?: string
    ) => Promise<unknown>
  ): Promise<void> {
    try {
      const conversations = await shortTermMemory.getRecentConversations(
        maxLength * 3
      );

      if (conversations.length <= maxLength) {
        return;
      }

      const toCompress = conversations.slice(0, -maxLength);
      const toKeep = conversations.slice(-maxLength);

      if (toCompress.length === 0) {
        return;
      }

      const summaryParts: string[] = [];
      const topicSet = new Set<string>();
      const entityMap = new Map<string, number>();

      for (const conv of toCompress) {
        const content =
          typeof conv.content === 'string'
            ? conv.content
            : JSON.stringify(conv.content);

        const sentences = content.split(/[。！？；\n]/).filter((s) => s.trim());
        for (const sentence of sentences) {
          if (sentence.length > 10 && sentence.length < 100) {
            topicSet.add(sentence.trim());
          }
        }

        const entityPatterns = [
          /(?:我喜欢|我讨厌)\s*[?]*\s*([^\s'"]+)/g,
          /(?:我想要|我需要)\s*[?]*\s*([^\s'"]+)/g,
          /(?:我的|我们的)\s*(?:名字|名字是)\s*([^\s'"]{2,20})/g,
        ];

        for (const pattern of entityPatterns) {
          let match;
          while ((match = pattern.exec(content)) !== null) {
            const entity = match[1].trim();
            if (entity.length > 1 && entity.length < 30) {
              entityMap.set(entity, (entityMap.get(entity) || 0) + 1);
            }
          }
        }
      }

      const topTopics = Array.from(topicSet).slice(0, 5);
      if (topTopics.length > 0) {
        summaryParts.push('主题: ' + topTopics.join('; '));
      }

      const topEntities = Array.from(entityMap.entries())
        .sort((a, b) => b[1] - a[1])
        .slice(0, 5)
        .map(([entity]) => entity);
      if (topEntities.length > 0) {
        summaryParts.push('实体: ' + topEntities.join(', '));
      }

      const summary = summaryParts.join('\n');
      if (summary) {
        await storeLongTermMemory(
          {
            type: 'conversation_summary',
            conversationId,
            summary,
            compressedCount: toCompress.length,
            timestamp: new Date().toISOString(),
          },
          'conversation',
          'neutral'
        );

        Logger.info(
          '对话历史已压缩: 压缩了 ' + toCompress.length + ' 条记录',
          'ConversationCompressor'
        );
      }

      for (const conv of toKeep) {
        await shortTermMemory.store(conv.content, conv.scene, conv.emotion);
      }
    } catch (error) {
      Logger.error('对话历史压缩失败', error as Error, 'ConversationCompressor');
    }
  }

  /**
   * 检索相关对话
   * 根据当前输入检索相关历史对话
   * @param currentInput 当前输入
   * @param limit 最大返回数量
   * @param shortTermMemory 短期记忆实例
   */
  async retrieveRelevantConversations(
    currentInput: string,
    limit: number,
    shortTermMemory: ShortTermMemory
  ): Promise<
    Array<{
      id: string;
      content: string;
      timestamp: Date;
      relevance: number;
      scene?: string;
      emotion?: string;
    }>
  > {
    try {
      const inputTokens = new Set(ChineseTokenizer.tokenize(currentInput));

      if (inputTokens.size === 0) {
        return [];
      }

      const conversations =
        await shortTermMemory.getRecentConversations(50);

      const scored: Array<{
        conversation: (typeof conversations)[0];
        score: number;
      }> = [];

      for (const conv of conversations) {
        const content =
          typeof conv.content === 'string'
            ? conv.content
            : JSON.stringify(conv.content);

        const convTokens = ChineseTokenizer.tokenize(content);

        const intersection = convTokens.filter((t) => inputTokens.has(t));
        const union = new Set([...inputTokens, ...convTokens]);

        const jaccardSimilarity =
          union.size > 0 ? intersection.length / union.size : 0;

        const keywordMatch = intersection.length;

        const recencyBonus =
          (Date.now() - new Date(conv.timestamp).getTime()) /
          (1000 * 60 * 60 * 24);
        const recencyWeight = Math.exp(-recencyBonus / 7);

        const score =
          jaccardSimilarity * 0.5 + keywordMatch * 0.1 + recencyWeight * 0.4;

        if (score > 0.05) {
          scored.push({ conversation: conv, score });
        }
      }

      scored.sort((a, b) => b.score - a.score);

      return scored.slice(0, limit).map(({ conversation, score }) => ({
        id: conversation.id,
        content:
          typeof conversation.content === 'string'
            ? conversation.content
            : JSON.stringify(conversation.content),
        timestamp: conversation.timestamp,
        relevance: score,
        scene: conversation.scene,
        emotion: conversation.emotion,
      }));
    } catch (error) {
      Logger.error('检索相关对话失败', error as Error, 'ConversationCompressor');
      return [];
    }
  }
}

/**
 * KnowledgeGraphBuilder - 知识图谱构建
 * 从MemoryEngine拆分出的知识图谱逻辑：
 * 1. 实体提取
 * 2. 关系提取
 * 3. 实体分类
 * 4. 图谱构建
 */

import Logger from '../utils/Logger';
import { MemoryItem, GraphNode, GraphEdge, KnowledgeGraph } from './MemoryEngine';

export class KnowledgeGraphBuilder {
  /**
   * 构建知识图谱
   * 从记忆中提取实体和关系，构建知识图谱
   * @param memories 记忆列表
   * @returns 知识图谱数据
   */
  getKnowledgeGraph(memories: MemoryItem[]): KnowledgeGraph {
    const startTime = Date.now();

    try {
      const nodeMap = new Map<string, GraphNode>();
      const edgeList: GraphEdge[] = [];
      const entityRelations: Map<string, number> = new Map();

      for (const memory of memories) {
        const text = this.memoryToText(memory);

        const entities = this.extractEntities(text);
        for (const entity of entities) {
          const existing = nodeMap.get(entity);
          if (existing) {
            existing.weight = (existing.weight || 1) + 1;
          } else {
            nodeMap.set(entity, {
              id: entity,
              label: entity,
              type: this.classifyEntityType(entity),
              weight: 1,
            });
          }
        }

        const relations = this.extractRelations(text);
        for (const relation of relations) {
          const edgeKey =
            relation.subject + '|' + relation.predicate + '|' + relation.object;

          const existingCount = entityRelations.get(edgeKey) || 0;
          entityRelations.set(edgeKey, existingCount + 1);

          if (existingCount === 0) {
            edgeList.push({
              source: relation.subject,
              target: relation.object,
              label: relation.predicate,
              weight: 1,
            });
          }
        }
      }

      const filteredNodes = Array.from(nodeMap.values())
        .filter((n) => (n.weight || 0) >= 2)
        .sort((a, b) => (b.weight || 0) - (a.weight || 0))
        .slice(0, 50);

      const nodeIds = new Set(filteredNodes.map((n) => n.id));
      const filteredEdges = edgeList
        .filter((e) => nodeIds.has(e.source) && nodeIds.has(e.target))
        .slice(0, 100);

      const duration = Date.now() - startTime;
      Logger.info(
        '知识图谱构建完成: ' +
          filteredNodes.length +
          '个节点, ' +
          filteredEdges.length +
          '条边, 耗时' +
          duration +
          'ms',
        'KnowledgeGraphBuilder'
      );

      return {
        nodes: filteredNodes,
        edges: filteredEdges,
      };
    } catch (error) {
      Logger.error('构建知识图谱失败', error as Error, 'KnowledgeGraphBuilder');
      return { nodes: [], edges: [] };
    }
  }

  /** 从文本提取实体 */
  private extractEntities(text: string): string[] {
    const entities: string[] = [];

    const entityPatterns = [
      /(?:我喜欢|我讨厌)\s*[?]*\s*([^\s'"]+)/g,
      /(?:我想要|我需要)\s*[?]*\s*([^\s'"]+)/g,
      /(?:我的|我们的)\s*(?:名字|名字是)\s*([^\s'"]{2,20})/g,
      /([A-Z][a-z]+(?:[A-Z][a-z]+)+)/g,
      /(?:import|from|require)\s+['"]([^'"]+)['"]/g,
      /\b(?:TODO|FIXME|HACK|NOTE)\s*[?]?\s*([^\n]+)/gi,
    ];

    for (const pattern of entityPatterns) {
      let match;
      while ((match = pattern.exec(text)) !== null) {
        const entity = match[1].trim();
        if (entity.length > 1 && entity.length < 50) {
          entities.push(entity);
        }
      }
    }

    const nounPatterns = [
      /(\d{4}年\d{1,2}月\d{1,2}日)/g,
      /(\d{1,2}:\d{2})/g,
      /(今天|明天|后天)/g,
    ];

    for (const pattern of nounPatterns) {
      let match;
      while ((match = pattern.exec(text)) !== null) {
        entities.push(match[1]);
      }
    }

    return [...new Set(entities)];
  }

  /** 从文本提取关系 */
  private extractRelations(text: string): Array<{
    subject: string;
    predicate: string;
    object: string;
  }> {
    const relations: Array<{
      subject: string;
      predicate: string;
      object: string;
    }> = [];

    const relationPatterns = [
      {
        pattern: /(.+?)\s*(?:是|等于|就是)\s*(.+)/g,
        predicate: '是',
      },
      {
        pattern: /(.+?)\s*(?:有|拥有|包含)\s*(.+)/g,
        predicate: '有',
      },
      {
        pattern: /(.+?)\s*(?:喜欢|爱)\s*(.+)/g,
        predicate: '喜欢',
      },
      {
        pattern: /(.+?)\s*(?:讨厌|恨)\s*(.+)/g,
        predicate: '讨厌',
      },
      {
        pattern: /(.+?)\s*(?:需要|想要)\s*(.+)/g,
        predicate: '需要',
      },
    ];

    for (const { pattern, predicate } of relationPatterns) {
      let match;
      while ((match = pattern.exec(text)) !== null) {
        const subject = match[1].trim();
        const object = match[2].trim();

        if (
          subject.length > 1 &&
          subject.length < 50 &&
          object.length > 1 &&
          object.length < 50
        ) {
          relations.push({ subject, predicate, object });
        }
      }
    }

    return relations;
  }

  /** 分类实体类型 */
  private classifyEntityType(entity: string): 'entity' | 'concept' | 'event' {
    if (/^\d{4}年\d{1,2}月\d{1,2}日$/.test(entity)) {
      return 'event';
    }

    if (/^\d{1,2}:\d{2}$/.test(entity) || /^(今天|明天|后天)$/.test(entity)) {
      return 'event';
    }

    const conceptKeywords = [
      '项目',
      '任务',
      '记忆',
      '目标',
      '计划',
      '想法',
      '问题',
    ];
    if (conceptKeywords.some((kw) => entity.includes(kw))) {
      return 'concept';
    }

    return 'entity';
  }

  /** 将记忆转为文本 */
  private memoryToText(memoryItem: MemoryItem): string {
    if (typeof memoryItem.content === 'string') return memoryItem.content;
    if (memoryItem.content && !Array.isArray(memoryItem.content)) {
      const obj = memoryItem.content as Record<string, unknown>;
      if (obj.input && typeof obj.input === 'string') return obj.input;
      if (obj.summary && typeof obj.summary === 'string') return obj.summary;
      return JSON.stringify(memoryItem.content);
    }
    return '';
  }
}

/**
 * MemoryEngine v2 - Performance Optimized
 * Key Optimizations:
 * 1. Vector cache: avoid duplicate query embedding generation
 * 2. Chinese semantic enhancement: N-gram + synonym expansion
 * 3. Tiered retrieval: hot/warm/cold memory layers
 * 4. Batch embedding: reduce LLM API calls
 *
 * 拆分后的模块：
 * - MemoryRetriever: 记忆检索与RRF融合
 * - KnowledgeGraphBuilder: 知识图谱构建
 * - ConversationCompressor: 对话压缩
 * - MemoryEncryption: 加密管理
 * - MemoryTracker: 验证与追踪
 */

import { EmotionTag, SceneTag } from '../interfaces';
import { MultimodalInput } from '../multimodal/MultimodalInput';
import Logger from '../utils/Logger';
import { perf } from '../utils/PerformanceMonitor';
import { ConversationCompressor } from './ConversationCompressor';
import { MemoryDatabase, MemoryRecord } from './Database';
import { KnowledgeGraphBuilder } from './KnowledgeGraphBuilder';
import { LongTermMemory } from './LongTermMemory';
import { MemoryEncryption } from './MemoryEncryption';
import {
    LLMEmbeddingModel,
    MemoryRetriever,
    SemanticEmbeddingModel,
} from './MemoryRetriever';
import { MemoryTracker } from './MemoryTracker';
import { ShortTermMemory } from './ShortTermMemory';
import { UserProfile } from './UserProfile';
import {
    VectorDatabase as CloseableVectorDatabase,
    VectorDatabaseFactory,
} from './VectorDatabaseFactory';

// ==================== 类型导出 ====================

export enum MemoryType {
  INSTANT = 'instant',
  SHORT_TERM = 'short_term',
  LONG_TERM = 'long_term',
}

export enum MemoryTier {
  HOT = 'hot',
  WARM = 'warm',
  COLD = 'cold',
}

export type MemoryContent = string | Record<string, unknown> | unknown[];

export interface MemoryItem {
  id: string;
  type: MemoryType;
  content: MemoryContent;
  timestamp: Date;
  scene?: string;
  emotion?: string;
  relevanceScore?: number;
  keywordScore?: number;
  vectorScore?: number;
  accessCount?: number;
  lastAccessTime?: number;
}

export interface TrackedResult {
  success: boolean;
  traceId: string;
  duration: number;
  data?: MemoryItem | MemoryItem[];
  error?: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: string[];
  warnings: string[];
}

export interface GraphNode {
  id: string;
  label: string;
  type: 'entity' | 'concept' | 'event';
  weight?: number;
}

export interface GraphEdge {
  source: string;
  target: string;
  label: string;
  weight?: number;
}

export interface KnowledgeGraph {
  nodes: GraphNode[];
  edges: GraphEdge[];
}

// ==================== MemoryEngine 主类 ====================

export class MemoryEngine {
  private userProfile: UserProfile;
  private shortTermMemory: ShortTermMemory;
  private longTermMemory: LongTermMemory;
  private instantMemory: MemoryItem[] = [];
  private instantMemoryExpiry: number = 3600;
  private embeddingModel: SemanticEmbeddingModel;
  private memoryVectors: Map<string, number[]> = new Map();
  private writeQueue: Array<{
    type: string;
    content: unknown;
    scene?: string;
    emotion?: string;
    retryCount: number;
  }> = [];
  private isWriting: boolean = false;
  private readonly MAX_WRITE_QUEUE_SIZE = 1000;
  private readonly MAX_RETRY_COUNT = 3;
  private vectorDatabase: CloseableVectorDatabase | null = null;
  private memoryTierMap: Map<string, MemoryTier> = new Map();
  private memoryAccessCount: Map<string, number> = new Map();
  private memoryLastAccess: Map<string, number> = new Map();
  /** 语义相似度引擎存根（原 SemanticSimilarityEngine 已删除） */
  private semanticSimilarityEngine: {
    initialize(): Promise<void>;
  } = { async initialize() {} };
  private memoryDatabase: MemoryDatabase;

  // 共享的缓存Map（与MemoryRetriever共享引用）
  private queryVectorCache: Map<
    string,
    { vector: number[]; timestamp: number }
  > = new Map();
  private hotMemoryCache: Map<string, MemoryItem> = new Map();

  // 拆分出的子模块
  private memoryRetriever: MemoryRetriever;
  private knowledgeGraphBuilder: KnowledgeGraphBuilder;
  private conversationCompressor: ConversationCompressor;
  private memoryEncryption: MemoryEncryption;
  private memoryTracker: MemoryTracker;

  constructor() {
    this.userProfile = new UserProfile();
    this.shortTermMemory = new ShortTermMemory();
    this.longTermMemory = new LongTermMemory();
    this.embeddingModel = new LLMEmbeddingModel();
    this.semanticSimilarityEngine = { async initialize() {} };
    this.vectorDatabase = null;
    this.memoryDatabase = MemoryDatabase.getInstance();

    // 初始化子模块
    this.memoryEncryption = new MemoryEncryption();

    this.memoryRetriever = new MemoryRetriever({
      semanticSimilarityEngine: this.semanticSimilarityEngine,
      embeddingModel: this.embeddingModel,
      memoryVectors: this.memoryVectors,
      hotMemoryCache: this.hotMemoryCache,
      memoryAccessCount: this.memoryAccessCount,
      memoryLastAccess: this.memoryLastAccess,
      memoryTierMap: this.memoryTierMap,
      vectorDatabase: this.vectorDatabase,
      instantMemoryRef: () => this.instantMemory,
      queryVectorCache: this.queryVectorCache,
    });

    this.knowledgeGraphBuilder = new KnowledgeGraphBuilder();
    this.conversationCompressor = new ConversationCompressor();
    this.memoryTracker = new MemoryTracker();

    this.startMemoryManagement();
  }

  // ==================== 初始化 ====================

  public async initialize(): Promise<void> {
    try {
      await this.shortTermMemory.initialize();
      await this.longTermMemory.initialize();
      await this.userProfile.load();
      await this.semanticSimilarityEngine.initialize();
      this.memoryDatabase = MemoryDatabase.getInstance();
      this.vectorDatabase = await VectorDatabaseFactory.createVectorDatabase();

      // 初始化加密模块
      await this.memoryEncryption.initialize();

      // 更新子模块引用
      this.memoryRetriever.setVectorDatabase(this.vectorDatabase);
      this.memoryRetriever.setMemoryRefs(
        this.shortTermMemory,
        this.longTermMemory
      );
    } catch (error) {
      Logger.error('记忆引擎初始化失败', error as Error);
      throw error;
    }
  }

  // ==================== 存储 ====================

  public async storeShortTermMemory(
    content: MemoryContent,
    scene?: string,
    emotion?: string
  ): Promise<MemoryItem> {
    return perf.measure('memory.storeShortTerm', async () => {
    const memoryItem: MemoryItem = {
      id: `short_term_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`,
      type: MemoryType.SHORT_TERM,
      content,
      timestamp: new Date(),
      scene,
      emotion,
    };

    const contentStr =
      typeof content === 'string' ? content : JSON.stringify(content);
    this.memoryDatabase.add(contentStr, 'short_term', 'core', 0.6);

    try {
      await this.shortTermMemory.store(content, scene, emotion);
    } catch (error) {
      Logger.warn('短期记忆直接存储失败，回退到写入队列: ' + (error as Error).message, 'MemoryEngine');
      this.enqueueWrite({ type: 'short_term', content, scene, emotion });
    }

    void this.memoryRetriever.scheduleEmbeddingGeneration(memoryItem);

    return memoryItem;
    }, 'memory');
  }

  public async storeLongTermMemory(
    content: MemoryContent,
    scene?: string,
    emotion?: string
  ): Promise<MemoryItem> {
    return perf.measure('memory.storeLongTerm', async () => {
    const memoryItem: MemoryItem = {
      id: `long_term_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`,
      type: MemoryType.LONG_TERM,
      content,
      timestamp: new Date(),
      scene,
      emotion,
    };

    const contentStr =
      typeof content === 'string' ? content : JSON.stringify(content);
    const importance = this.shouldStoreToLongTerm(
      content,
      undefined,
      emotion || 'neutral'
    )
      ? 0.8
      : 0.5;

    try {
      const encryptedContent =
        await this.memoryEncryption.storeEncryptedLongTermMemory({
          content,
          scene,
          emotion,
        });
      this.memoryDatabase.add(
        encryptedContent,
        'long_term_encrypted',
        'core',
        importance
      );
    } catch {
      this.memoryDatabase.add(contentStr, 'long_term', 'core', importance);
    }

    this.enqueueWrite({ type: 'long_term', content, scene, emotion });
    void this.memoryRetriever.scheduleEmbeddingGeneration(memoryItem);

    return memoryItem;
    }, 'memory');
  }

  public async storeInstantMemory(
    content: MemoryContent,
    scene?: string,
    emotion?: string
  ): Promise<MemoryItem> {
    return perf.measure('memory.storeInstant', async () => {
    const memoryItem: MemoryItem = {
      id: `instant_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`,
      type: MemoryType.INSTANT,
      content,
      timestamp: new Date(),
      scene,
      emotion,
    };

    this.instantMemory.push(memoryItem);
    const contentStr =
      typeof content === 'string' ? content : JSON.stringify(content);
    this.memoryDatabase.add(contentStr, 'instant', 'core', 0.3);
    void this.memoryRetriever.scheduleEmbeddingGeneration(memoryItem);
    this.cleanupInstantMemory();

    return memoryItem;
    }, 'memory');
  }

