      this.memoryManagementTimer = null;
    }
    try {
      await this.shortTermMemory.shutdown?.();
      await this.longTermMemory.shutdown?.();
      await this.userProfile.save?.();
      if (this.vectorDatabase) {
        await this.vectorDatabase.close();
