/**
 * MemoryRetriever - 记忆检索与RRF融合
 * 从MemoryEngine拆分出的检索逻辑：
 * 1. 查询向量缓存
 * 2. 热缓存检索
 * 3. 关键词检索（N-gram + 同义词扩展）
 * 4. 向量相似度检索
 * 5. RRF融合算法
 * 6. 权重计算（时间/场景/情感）
 * 7. 访问统计与分层
 */

import Logger from '../utils/Logger';
import { ChineseTokenizer } from './ChineseTokenizer';
import { MemoryItem, MemoryTier } from './MemoryEngine';
import { ShortTermMemory } from './ShortTermMemory';
import { LongTermMemory } from './LongTermMemory';

/** SemanticSimilarityEngine 存根（原模块已删除） */
class SemanticSimilarityEngine {
  async initialize(): Promise<void> {}
}

/** 记忆存储接口（支持获取所有记忆项） */
interface MemoryStoreWithGetAll {
  getAll(): MemoryItem[];
}

/** 向量数据库接口 */
export interface VectorDatabase {
  storeVector(
    id: string,
    vector: number[],
    metadata: Record<string, unknown>
  ): Promise<void>;
  searchVectors(
    query: number[],
    topK: number
  ): Promise<{ id: string; similarity: number }[]>;
}

/** 嵌入模型接口 */
export interface SemanticEmbeddingModel {
  embed(text: string): Promise<number[]>;
}

/** 基于LLM的嵌入模型实现 */
export class LLMEmbeddingModel implements SemanticEmbeddingModel {
  async embed(text: string): Promise<number[]> {
    const tokens = ChineseTokenizer.tokenize(text);
    const vectorDim = 256;
    const vector = new Array(vectorDim).fill(0);

    tokens.forEach((token, i) => {
      const hash = this.simpleHash(token) % vectorDim;
      vector[hash] += 1 + (tokens.length - i) / tokens.length;
    });

    // 归一化向量
    const norm = Math.sqrt(vector.reduce((sum, v) => sum + v * v, 0));
    if (norm > 0) {
      return vector.map((v) => v / norm);
    }
    return vector;
  }

  private simpleHash(str: string): number {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = ((hash << 5) - hash + char) | 0;
    }
    return Math.abs(hash);
  }
}

export class MemoryRetriever {
  private semanticSimilarityEngine: SemanticSimilarityEngine;
  private embeddingModel: SemanticEmbeddingModel;
  private memoryVectors: Map<string, number[]>;
  private hotMemoryCache: Map<string, MemoryItem>;
  private queryVectorCache: Map<string, { vector: number[]; timestamp: number }>;
  private memoryAccessCount: Map<string, number>;
  private memoryLastAccess: Map<string, number>;
  private memoryTierMap: Map<string, MemoryTier>;
  private vectorDatabase: VectorDatabase | null;

  /** 获取即时记忆的回调（避免数组引用失效） */
  private getInstantMemory: () => MemoryItem[];

  /** 分层阈值 */
  private tierThresholds = { hot: 3600, warm: 86400 };

  // 常量
  private readonly QUERY_CACHE_TTL = 5 * 60 * 1000;
  private readonly QUERY_CACHE_MAX_SIZE = 100;
  private readonly HOT_CACHE_MAX_SIZE = 50;

  /** 嵌入批处理队列 */
  private embeddingBatchQueue: Array<{
    memoryItem: MemoryItem;
    resolve: (value: void) => void;
    reject: (reason: Error) => void;
  }> = [];
  private embeddingBatchTimer: ReturnType<typeof setTimeout> | null = null;
  private readonly EMBEDDING_BATCH_SIZE = 10;
  private readonly EMBEDDING_BATCH_DELAY = 100;

  constructor(deps: {
    semanticSimilarityEngine: SemanticSimilarityEngine;
    embeddingModel: SemanticEmbeddingModel;
    memoryVectors: Map<string, number[]>;
    hotMemoryCache: Map<string, MemoryItem>;
    memoryAccessCount: Map<string, number>;
    memoryLastAccess: Map<string, number>;
    memoryTierMap: Map<string, MemoryTier>;
    vectorDatabase: VectorDatabase | null;
    instantMemoryRef: MemoryItem[] | (() => MemoryItem[]);
    queryVectorCache: Map<string, { vector: number[]; timestamp: number }>;
  }) {
    this.semanticSimilarityEngine = deps.semanticSimilarityEngine;
    this.embeddingModel = deps.embeddingModel;
    this.memoryVectors = deps.memoryVectors;
    this.hotMemoryCache = deps.hotMemoryCache;
    this.memoryAccessCount = deps.memoryAccessCount;
    this.memoryLastAccess = deps.memoryLastAccess;
    this.memoryTierMap = deps.memoryTierMap;
    this.vectorDatabase = deps.vectorDatabase;
    this.getInstantMemory =
      typeof deps.instantMemoryRef === 'function'
        ? deps.instantMemoryRef
        : () => deps.instantMemoryRef as MemoryItem[];
    this.queryVectorCache = deps.queryVectorCache;
  }

  /** 更新向量数据库引用（initialize后调用） */
  setVectorDatabase(vdb: VectorDatabase | null): void {
    this.vectorDatabase = vdb;
  }

  // ==================== 精确混合检索 v2 ====================

  /**
   * 精确混合检索v2
   * 步骤：
   * 1. 查询向量缓存
   * 2. 多路召回
   * 3. RRF融合排序
   */
  async preciseHybridRetrieval(
    query: string,
    scene?: string,
    emotion?: string,
    topK: number = 10,
    shortTermMemory?: ShortTermMemory,
    longTermMemory?: LongTermMemory
  ): Promise<MemoryItem[]> {
    const startTime = Date.now();

    // 1. 查询向量缓存
    const queryEmbedding = await this.getCachedQueryVector(query);

    // 2. 多路召回并行执行
    const hotResults = this.retrieveFromHotCache(
      query,
      scene,
      emotion,
      Math.ceil(topK * 0.3)
    );
    const [keywordResults, vectorResults] = await Promise.all([
      this.keywordRetrieval(
        query,
        scene,
        emotion,
        Math.ceil(topK * 0.7),
        shortTermMemory,
        longTermMemory
      ),
      this.vectorSimilarityRetrieval(
        queryEmbedding,
        Math.ceil(topK * 0.7),
        shortTermMemory,
        longTermMemory
      ),
    ]);

    // 3. 应用RRF融合算法
    const mergedResults = this.applyRRFAlgorithm(
      [...hotResults, ...keywordResults],
      vectorResults,
      scene,
      emotion
    );

    // 4. 更新访问统计
    mergedResults.slice(0, topK).forEach((m) => this.updateAccessStats(m.id));

    const duration = Date.now() - startTime;
    if (mergedResults.length > 0 || duration > 100) {
      Logger.info(
        '查询完成: ' +
          query.substring(0, 20) +
          '... | ' +
          mergedResults.length +
          '条 | ' +
          duration +
          'ms',
        'MemoryRetriever'
      );
    }

    return mergedResults.slice(0, topK);
  }

  // ==================== 查询向量缓存 ====================

  /** 查询向量缓存 */
  private async getCachedQueryVector(query: string): Promise<number[]> {
    const cached = this.queryVectorCache.get(query);
    if (cached && Date.now() - cached.timestamp < this.QUERY_CACHE_TTL) {
      return cached.vector;
    }

    const vector = await this.embeddingModel.embed(query);

    // LRU 淘汰
    if (this.queryVectorCache.size >= this.QUERY_CACHE_MAX_SIZE) {
      const oldestKey = this.queryVectorCache.keys().next().value;
      if (oldestKey) {
        this.queryVectorCache.delete(oldestKey);
      }
    }

    this.queryVectorCache.set(query, { vector, timestamp: Date.now() });
    return vector;
  }

  // ==================== 热缓存检索 ====================

  /** 热缓存检索 */
  private retrieveFromHotCache(
    query: string,
    scene?: string,
    emotion?: string,
    limit: number = 5
  ): MemoryItem[] {
    const queryTokens = new Set(ChineseTokenizer.tokenize(query));
    const results: Array<{ item: MemoryItem; score: number }> = [];

    for (const item of this.hotMemoryCache.values()) {
      const text = this.memoryToText(item);
      const tokens = ChineseTokenizer.tokenize(text);
      const overlap = tokens.filter((t) => queryTokens.has(t)).length;
      if (overlap === 0) continue;

      let score = overlap / Math.max(queryTokens.size, tokens.length);

      if (scene && item.scene === scene) score *= 1.2;
      if (emotion && item.emotion === emotion) score *= 1.2;

      // 访问频率加权
      const accessCount = this.memoryAccessCount.get(item.id) || 0;
      score *= 1 + Math.log1p(accessCount);

      results.push({ item, score });
    }

    return results
      .sort((a, b) => b.score - a.score)
      .slice(0, limit)
      .map((r) => r.item);
  }

  // ==================== 关键词检索 ====================

  /**
   * 关键词检索v2：N-gram + 同义词扩展
   */
  private async keywordRetrieval(
    query: string,
    scene?: string,
    emotion?: string,
    limit: number = 20,
    shortTermMemory?: ShortTermMemory,
    longTermMemory?: LongTermMemory
  ): Promise<MemoryItem[]> {
    // 分词 + 扩展
    const queryTokens = ChineseTokenizer.tokenize(query);
    const expandedTokens = this.expandQueryTokens(queryTokens);

    const stm = shortTermMemory || this.shortTermMemoryHack;
    const ltm = longTermMemory || this.longTermMemoryHack;

    const stmMemories = stm
      ? ('retrieve' in stm
        ? await (stm as ShortTermMemory).retrieve(query, []).catch(() => [] as MemoryItem[])
        : (stm as MemoryStoreWithGetAll).getAll())
      : [];
    const ltmMemories = ltm
      ? ('retrieve' in ltm
        ? await (ltm as LongTermMemory).retrieve(query, []).catch(() => [] as MemoryItem[])
        : (ltm as MemoryStoreWithGetAll).getAll())
      : [];

    const allMemories = [
      ...this.getInstantMemory(),
      ...stmMemories,
      ...ltmMemories,
    ];

    if (allMemories.length === 0) return [];

    const scored = allMemories.map((memory) => {
      const text = this.memoryToText(memory);
      const docTokens = ChineseTokenizer.tokenize(text);

      // 加权重叠度：位置加权
      let overlapScore = 0;
      expandedTokens.forEach((token, idx) => {
        const weight = 1 + (expandedTokens.length - idx) * 0.1;
        if (docTokens.includes(token)) {
          overlapScore += weight;
        }
      });

      // Jaccard 相似度
      const intersection = new Set(
        docTokens.filter((t) => expandedTokens.includes(t))
      ).size;
      const union = new Set([...docTokens, ...expandedTokens]).size;
      const jaccard = union > 0 ? intersection / union : 0;

      let score = overlapScore * 0.6 + jaccard * 0.4;

      // 场景/情感加权
      if (scene && memory.scene === scene) score *= 1.3;
      if (emotion && memory.emotion === emotion) score *= 1.3;

      // 时间衰减
      const timestamp =
        typeof memory.timestamp === 'number'
          ? memory.timestamp
          : new Date(memory.timestamp).getTime();
      const ageHours = (Date.now() - timestamp) / (1000 * 60 * 60);
      score *= Math.exp(-ageHours / 168); // 一周衰减

      return { memory, score };
    });

    return scored
      .filter((s) => s.score > 0.05)
      .sort((a, b) => b.score - a.score)
      .slice(0, limit)
      .map((s) => ({ ...s.memory, keywordScore: s.score }));
  }

  /** Expand query tokens with synonyms */
  private expandQueryTokens(tokens: string[]): string[] {
    const expanded = new Set(tokens);
    const synonyms: Record<string, string[]> = {
      error: ['exception', 'fail', 'bug'],
      bug: ['issue', 'problem', 'defect'],
      feature: ['function', 'capability', 'enhancement'],
      query: ['search', 'find', 'lookup'],
      task: ['todo', 'job', 'item'],
      code: ['source', 'program', 'script'],
      test: ['unit-test', 'integration-test', 'e2e'],
      data: ['information', 'content', 'record'],
    };

    tokens.forEach((token) => {
      if (synonyms[token]) {
        synonyms[token].forEach((s) => expanded.add(s));
      }
    });

    return Array.from(expanded);
  }

  // ==================== 向量相似度检索 ====================

  /** 向量相似度检索：支持索引和内存回退 */
  private async vectorSimilarityRetrieval(
    queryEmbedding: number[],
    topK: number = 20,
    shortTermMemory?: ShortTermMemory,
    longTermMemory?: LongTermMemory
  ): Promise<MemoryItem[]> {
    let indexResults: { id: string; similarity: number }[] = [];

    if (this.vectorDatabase) {
      indexResults = await this.vectorDatabase.searchVectors(
        queryEmbedding,
        topK
      );
    } else {
      // 内存回退搜索
      for (const [id, vector] of this.memoryVectors.entries()) {
        const similarity = this.cosineSimilarity(vector, queryEmbedding);
        indexResults.push({ id, similarity });
      }
      indexResults.sort((a, b) => b.similarity - a.similarity);
      indexResults = indexResults.slice(0, topK);
    }

    const stm = shortTermMemory || this.shortTermMemoryHack;
    const ltm = longTermMemory || this.longTermMemoryHack;

    const stmMemories = stm
      ? ('retrieve' in stm
        ? await (stm as ShortTermMemory).retrieve('', []).catch(() => [] as MemoryItem[])
        : (stm as MemoryStoreWithGetAll).getAll())
      : [];
    const ltmMemories = ltm
      ? ('retrieve' in ltm
        ? await (ltm as LongTermMemory).retrieve('', []).catch(() => [] as MemoryItem[])
        : (ltm as MemoryStoreWithGetAll).getAll())
      : [];

    const allMemories = [
      ...this.getInstantMemory(),
      ...stmMemories,
      ...ltmMemories,
    ];

    const memoryMap = new Map(allMemories.map((m) => [m.id, m]));
    const results: MemoryItem[] = [];

    for (const { id, similarity } of indexResults) {
      const memory = memoryMap.get(id);
      if (memory) {
        results.push({ ...memory, vectorScore: similarity });
      }
    }

    return results;
  }

  // ==================== 嵌入批处理 ====================

  /** 调度嵌入向量生成（批处理） */
  scheduleEmbeddingGeneration(memoryItem: MemoryItem): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      this.embeddingBatchQueue.push({ memoryItem, resolve, reject });

      if (!this.embeddingBatchTimer) {
        this.embeddingBatchTimer = setTimeout(() => {
          void this.processEmbeddingBatch();
        }, this.EMBEDDING_BATCH_DELAY);
      }
    });
  }

  /** 处理嵌入批处理请求 */
  private async processEmbeddingBatch(): Promise<void> {
    if (this.embeddingBatchTimer) {
      clearTimeout(this.embeddingBatchTimer);
      this.embeddingBatchTimer = null;
    }

    const batch = this.embeddingBatchQueue.splice(0, this.EMBEDDING_BATCH_SIZE);
    if (batch.length === 0) return;

    try {
      // 并行生成嵌入向量
      const embeddings = await Promise.all(
        batch.map((item) =>
          this.embeddingModel.embed(this.memoryToText(item.memoryItem))
        )
      );

      batch.forEach((item, index) => {
        const embedding = embeddings[index];
        this.memoryVectors.set(item.memoryItem.id, embedding);

        if (this.vectorDatabase) {
          this.vectorDatabase
            .storeVector(item.memoryItem.id, embedding, {
              type: item.memoryItem.type,
              scene: item.memoryItem.scene,
              emotion: item.memoryItem.emotion,
              timestamp: item.memoryItem.timestamp.toISOString(),
            })
            .catch((err: Error) =>
              Logger.error('存储向量失败', err, 'MemoryRetriever')
            );
        }

        this.assignMemoryTier(item.memoryItem);
        item.resolve();
      });
    } catch (error) {
      batch.forEach((item) => item.reject(error as Error));
    }

    // 重新调度批处理
    if (this.embeddingBatchQueue.length > 0) {
      this.embeddingBatchTimer = setTimeout(() => {
        void this.processEmbeddingBatch();
      }, this.EMBEDDING_BATCH_DELAY);
    }
  }

  // ==================== 访问统计 ====================

  /** 更新访问统计 */
  private updateAccessStats(memoryId: string): void {
    const count = (this.memoryAccessCount.get(memoryId) || 0) + 1;
    this.memoryAccessCount.set(memoryId, count);
    this.memoryLastAccess.set(memoryId, Date.now());

    // 热缓存更新
    const allMemories = [
      ...this.getInstantMemory(),
      ...(this.shortTermMemoryHack?.getAll() || []),
      ...(this.longTermMemoryHack?.getAll() || []),
    ];

    const memory = allMemories.find((m) => m.id === memoryId);
    if (memory) {
      this.hotMemoryCache.set(memoryId, memory);

      // LRU 淘汰
      if (this.hotMemoryCache.size > this.HOT_CACHE_MAX_SIZE) {
        const oldestKey = this.hotMemoryCache.keys().next().value;
        if (oldestKey) {
          this.hotMemoryCache.delete(oldestKey);
        }
      }
    }
  }

  /** hack引用，由MemoryEngine设置 */
  private shortTermMemoryHack: MemoryStoreWithGetAll | null = null;
  private longTermMemoryHack: MemoryStoreWithGetAll | null = null;

  /** 设置短期/长期记忆引用（用于访问统计中的热缓存更新） */
  setMemoryRefs(stm: ShortTermMemory, ltm: LongTermMemory): void {
    this.shortTermMemoryHack = stm;
    this.longTermMemoryHack = ltm;
  }

  // ==================== RRF融合算法 ====================

  private applyRRFAlgorithm(
    keywordResults: MemoryItem[],
    vectorResults: MemoryItem[],
    scene?: string,
    emotion?: string
  ): MemoryItem[] {
    const keywordRanks = new Map<string, number>();
    keywordResults.forEach((memory, index) =>
      keywordRanks.set(memory.id, index + 1)
    );

    const vectorRanks = new Map<string, number>();
    vectorResults.forEach((memory, index) =>
      vectorRanks.set(memory.id, index + 1)
    );

    const allMemoryIds = new Set([
      ...keywordResults.map((m) => m.id),
      ...vectorResults.map((m) => m.id),
    ]);

    const scoredMemories: MemoryItem[] = [];
    const k = 60;

    allMemoryIds.forEach((memoryId) => {
      const memory =
        keywordResults.find((m) => m.id === memoryId) ||
        vectorResults.find((m) => m.id === memoryId);
      if (!memory) return;

      const keywordRank =
        keywordRanks.get(memoryId) || keywordResults.length + 1;
      const vectorRank = vectorRanks.get(memoryId) || vectorResults.length + 1;
      let rrfScore = 1 / (k + keywordRank) + 1 / (k + vectorRank);

      rrfScore *= this.calculateTimeWeight(memory.timestamp);
      if (scene && memory.scene)
        rrfScore *= this.calculateSceneWeight(memory.scene, scene);
      if (emotion && memory.emotion)
        rrfScore *= this.calculateEmotionWeight(memory.emotion, emotion);

      memory.relevanceScore = rrfScore;
      scoredMemories.push(memory);
    });

    return scoredMemories.sort(
      (a, b) => (b.relevanceScore || 0) - (a.relevanceScore || 0)
    );
  }

  // ==================== 权重计算 ====================

  private calculateTimeWeight(timestamp: Date | string | number): number {
    const ts = typeof timestamp === 'number'
      ? timestamp
      : timestamp instanceof Date
        ? timestamp.getTime()
        : new Date(timestamp).getTime();
    const ageInHours = (Date.now() - ts) / (1000 * 60 * 60);
    if (ageInHours < 1) return 1.0;
    if (ageInHours < 24) return 0.8;
    if (ageInHours < 72) return 0.6;
    if (ageInHours < 168) return 0.4;
    return 0.2;
  }

  private calculateSceneWeight(
    memoryScene: string,
    currentScene: string
  ): number {
    return memoryScene === currentScene ? 1.2 : 0.8;
  }

  private calculateEmotionWeight(
    memoryEmotion: string,
    currentEmotion: string
  ): number {
    return memoryEmotion === currentEmotion ? 1.2 : 0.8;
  }

  // ==================== 工具方法 ====================

  cosineSimilarity(a: number[], b: number[]): number {
    let dot = 0,
      normA = 0,
      normB = 0;
    for (let i = 0; i < a.length; i++) {
      dot += a[i] * b[i];
      normA += a[i] * a[i];
      normB += b[i] * b[i];
    }
    return normA === 0 || normB === 0
      ? 0
      : dot / (Math.sqrt(normA) * Math.sqrt(normB));
  }

  memoryToText(memoryItem: MemoryItem): string {
    if (typeof memoryItem.content === 'string') return memoryItem.content;
    if (memoryItem.content && !Array.isArray(memoryItem.content)) {
      const obj = memoryItem.content as Record<string, unknown>;
      if (obj.input && typeof obj.input === 'string') return obj.input;
      if (obj.summary && typeof obj.summary === 'string') return obj.summary;
      return JSON.stringify(memoryItem.content);
    }
    return '';
  }

  private assignMemoryTier(memoryItem: MemoryItem): void {
    const ts = typeof memoryItem.timestamp === 'number'
      ? memoryItem.timestamp
      : memoryItem.timestamp instanceof Date
        ? memoryItem.timestamp.getTime()
        : new Date(memoryItem.timestamp).getTime();
    const ageSeconds = (Date.now() - ts) / 1000;
    if (ageSeconds < this.tierThresholds.hot) {
      this.memoryTierMap.set(memoryItem.id, MemoryTier.HOT);
    } else if (ageSeconds < this.tierThresholds.warm) {
      this.memoryTierMap.set(memoryItem.id, MemoryTier.WARM);
    } else {
      this.memoryTierMap.set(memoryItem.id, MemoryTier.COLD);
    }
  }

  // ==================== 缓存清理 ====================

  cleanupQueryVectorCache(): void {
    const now = Date.now();
    for (const [key, value] of this.queryVectorCache.entries()) {
      if (now - value.timestamp > this.QUERY_CACHE_TTL) {
        this.queryVectorCache.delete(key);
      }
    }
  }

  cleanupHotMemoryCache(): void {
    if (this.hotMemoryCache.size <= this.HOT_CACHE_MAX_SIZE) return;
    const sorted = Array.from(this.hotMemoryCache.entries()).sort((a, b) => {
      const countA = this.memoryAccessCount.get(a[0]) || 0;
      const countB = this.memoryAccessCount.get(b[0]) || 0;
      return countB - countA;
    });
    // 清空并重建（因为hotMemoryCache是共享引用）
    this.hotMemoryCache.clear();
    sorted.slice(0, this.HOT_CACHE_MAX_SIZE).forEach(([k, v]) => {
      this.hotMemoryCache.set(k, v);
    });
  }
}

/**
 * 偏好注入器
 * 将用户偏好和进化学习示例动态注入到 LLM system prompt 中
 */

import { OptimizationResultDispatcher } from '../evolution/OptimizationResultDispatcher';
import { PreferenceManager } from './PreferenceManager';

/**
 * 构建偏好注入块，追加到 system prompt 末尾
 */
export function buildPreferenceBlock(): string {
  const prefManager = PreferenceManager.getInstance();
  if (prefManager.count === 0) return '';

  const summary = prefManager.getSummary();
  const blocks: string[] = [];

  if (summary.namingRules.length > 0) {
    blocks.push(`命名规范：${summary.namingRules.join('；')}`);
  }

  if (summary.codingStyle.length > 0) {
    blocks.push(`代码风格：${summary.codingStyle.join('；')}`);
  }

  if (summary.frameworkPreferences.length > 0) {
    blocks.push(`框架偏好：${summary.frameworkPreferences.join('；')}`);
  }

  if (summary.workflowPreferences.length > 0) {
    blocks.push(`工作流程：${summary.workflowPreferences.join('；')}`);
  }

  if (summary.recentCorrections.length > 0) {
    blocks.push(
      `最近用户纠错（务必注意）：${summary.recentCorrections.join('；')}`
    );
  }

  if (blocks.length === 0) return '';

  return `\n\n【用户偏好】\n${blocks.join('\n')}`;
}

/**
 * 构建进化学习示例注入块
 * 从 OptimizationResultDispatcher 获取最新的 PromptExamples 并注入
 */
export function buildEvolutionExamplesBlock(): string {
  const dispatcher = OptimizationResultDispatcher.getInstance();
  const snapshot = dispatcher.getLastSnapshot();
  if (!snapshot || !snapshot.promptExamples || snapshot.promptExamples.length === 0) {
    return '';
  }

  const examples = snapshot.promptExamples.slice(-5);
  const lines: string[] = [];

  for (const ex of examples) {
    lines.push(`- 当用户说"${ex.trigger}"时，正确做法：${ex.correction}`);
  }

  if (lines.length === 0) return '';

  return `\n\n【进化学习示例】（从历史纠错中学习，务必遵循）\n${lines.join('\n')}`;
}

/**
 * 将偏好和进化学习示例注入到 system prompt 中
 */
export function injectPreferences(systemPrompt: string): string {
  const prefBlock = buildPreferenceBlock();
  const examplesBlock = buildEvolutionExamplesBlock();

  let result = systemPrompt;
  if (prefBlock) result += prefBlock;
  if (examplesBlock) result += examplesBlock;

  return result;
}

/**
 * 语义相似度计算引擎
 * 实现高级语义相似度计算，支持向量相似度检索
 */

import { MemoryItem, MemoryType } from './MemoryEngine';

export interface SemanticVector {
  id: string;
  vector: number[];
  memoryId: string;
  memoryType: MemoryType;
  timestamp: Date;
  metadata: {
    text: string;
    scene?: string;
    emotion?: string;
    tags?: string[];
  };
}

export interface SimilarityResult {
  memory: MemoryItem;
  similarity: number;
  semanticScore: number;
  keywordScore: number;
  contextualScore: number;
  combinedScore: number;
  explanation: string[];
}

export interface SemanticSearchOptions {
  topK?: number;
  threshold?: number;
  memoryTypes?: MemoryType[];
  scenes?: string[];
  emotions?: string[];
  recencyWeight?: number; // 时间权重 0-1
  semanticWeight?: number; // 语义权重 0-1
  keywordWeight?: number; // 关键词权重 0-1
}

export class SemanticSimilarityEngine {
  private vectors: Map<string, SemanticVector> = new Map();
  private vectorDimension = 384; // 标准sentence-transformers维度
  private embeddingCache: Map<string, number[]> = new Map();
  private maxCacheSize = 1000;
  private usePreTrainedModel = false; // 实际应用中应设置为true

  /**
   * 初始化语义相似度引擎
   */
  async initialize(): Promise<void> {
    console.log('🔍 语义相似度引擎：初始化中...');

    try {
      // 实际应用中应加载预训练模型
      // this.model = await loadModel('sentence-transformers/all-MiniLM-L6-v2');

      // 模拟模型加载
      await new Promise(resolve => setTimeout(resolve, 1000));

      this.usePreTrainedModel = true;
      console.log('✅ 语义相似度引擎：初始化完成');
    } catch (error) {
      console.error('❌ 语义相似度引擎初始化失败：', error);
      // 失败时回退到基础实现
      this.usePreTrainedModel = false;
      console.log('⚠️  语义相似度引擎：回退到基础实现');
    }
  }

  /**
   * 生成文本的语义向量
   */
  async generateVector(text: string): Promise<number[]> {
    // 检查缓存
    if (this.embeddingCache.has(text)) {
      return this.embeddingCache.get(text)!;
    }

    let vector: number[];

    if (this.usePreTrainedModel) {
      // 实际应用中使用预训练模型
      // vector = await this.model.encode(text);
      vector = this.generateMockVector(text);
    } else {
      // 基础实现：基于词频和语义特征
      vector = this.generateBasicVector(text);
    }

    // 归一化向量
    vector = this.normalizeVector(vector);

    // 缓存结果
    this.cacheEmbedding(text, vector);

    return vector;
  }

  /**
   * 存储记忆的语义向量
   */
  async storeVector(memory: MemoryItem): Promise<SemanticVector> {
    const text = this.extractMemoryText(memory);
    const vector = await this.generateVector(text);

    const semanticVector: SemanticVector = {
      id: `vec_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      vector,
      memoryId: memory.id,
      memoryType: memory.type,
      timestamp: new Date(),
      metadata: {
        text,
        scene: memory.scene,
        emotion: memory.emotion,
        tags: this.extractTags(memory)
      }
    };

    this.vectors.set(memory.id, semanticVector);
    return semanticVector;
  }

  /**
   * 批量存储记忆向量
   */
  async batchStoreVectors(memories: MemoryItem[]): Promise<void> {
    for (const memory of memories) {
      await this.storeVector(memory);
    }
  }

  /**
   * 计算查询与记忆的相似度
   */
  async computeSimilarity(query: string, memories: MemoryItem[]): Promise<SimilarityResult[]> {
    const queryVector = await this.generateVector(query);
    const queryWords = this.tokenize(query);
    const queryScenes = this.extractScenesFromText(query);
    const queryEmotions = this.extractEmotionsFromText(query);

    const results: SimilarityResult[] = [];

    for (const memory of memories) {
      const storedVector = this.vectors.get(memory.id);

      // 计算语义相似度
      let semanticScore = 0;
      if (storedVector) {
        semanticScore = this.cosineSimilarity(queryVector, storedVector.vector);
      } else {
        // 如果没有预存储的向量，实时生成
        const memoryText = this.extractMemoryText(memory);
        const memoryVector = await this.generateVector(memoryText);
        semanticScore = this.cosineSimilarity(queryVector, memoryVector);
      }

      // 计算关键词匹配分数
      const keywordScore = this.calculateKeywordScore(queryWords, memory);

      // 计算上下文相关性分数
      const contextualScore = this.calculateContextualScore(
        { scenes: queryScenes, emotions: queryEmotions },
        memory
      );

      // 计算时间权重
      const recencyScore = this.calculateRecencyScore(memory);

      // 综合分数
      const combinedScore = this.calculateCombinedScore(
        semanticScore, keywordScore, contextualScore, recencyScore
      );

      // 生成解释
      const explanation = this.generateExplanation(
        semanticScore, keywordScore, contextualScore, recencyScore, memory
      );

      results.push({
        memory,
        similarity: combinedScore,
        semanticScore,
        keywordScore,
        contextualScore,
        combinedScore,
        explanation
      });
    }

    // 按综合分数排序
    return results.sort((a, b) => b.combinedScore - a.combinedScore);
  }

  /**
   * 语义搜索
   */
  async search(
    query: string,
    memories: MemoryItem[],
    options: SemanticSearchOptions = {}
  ): Promise<MemoryItem[]> {
    const {
      topK = 5,
      threshold = 0.3,
      memoryTypes,
      scenes,
      emotions
    } = options;

    // 过滤记忆
    let filteredMemories = memories;

    if (memoryTypes && memoryTypes.length > 0) {
      filteredMemories = filteredMemories.filter(m => memoryTypes.includes(m.type));
    }

    if (scenes && scenes.length > 0) {
      filteredMemories = filteredMemories.filter(m =>
        m.scene && scenes.includes(m.scene)
      );
    }

    if (emotions && emotions.length > 0) {
      filteredMemories = filteredMemories.filter(m =>
        m.emotion && emotions.includes(m.emotion)
      );
    }

    // 计算相似度
    const results = await this.computeSimilarity(query, filteredMemories);

    // 过滤并返回结果
    return results
      .filter(result => result.combinedScore >= threshold)
      .slice(0, topK)
      .map(result => result.memory);
  }

  /**
   * 计算两个向量的余弦相似度
   */
  private cosineSimilarity(vec1: number[], vec2: number[]): number {
    if (vec1.length !== vec2.length) {
      throw new Error('向量维度不匹配');
    }

    let dotProduct = 0;
    let norm1 = 0;
    let norm2 = 0;

    for (let i = 0; i < vec1.length; i++) {
      dotProduct += vec1[i] * vec2[i];
      norm1 += vec1[i] * vec1[i];
      norm2 += vec2[i] * vec2[i];
    }

    const denominator = Math.sqrt(norm1) * Math.sqrt(norm2);
    return denominator === 0 ? 0 : dotProduct / denominator;
  }

  /**
   * 归一化向量
   */
  private normalizeVector(vector: number[]): number[] {
    const magnitude = Math.sqrt(vector.reduce((sum, v) => sum + v * v, 0));
    return magnitude === 0 ? vector : vector.map(v => v / magnitude);
  }

  /**
   * 计算关键词匹配分数
   */
  private calculateKeywordScore(queryWords: string[], memory: MemoryItem): number {
    const memoryText = this.extractMemoryText(memory);
    const memoryWords = this.tokenize(memoryText);

    if (queryWords.length === 0) return 0;

    // Jaccard相似度
    const querySet = new Set(queryWords);
    const memorySet = new Set(memoryWords);
    const intersection = new Set([...querySet].filter(word => memorySet.has(word)));
    const union = new Set([...querySet, ...memorySet]);

    return union.size === 0 ? 0 : intersection.size / union.size;
  }

  /**
   * 计算上下文相关性分数
   */
  private calculateContextualScore(
    queryContext: { scenes: string[]; emotions: string[] },
    memory: MemoryItem
  ): number {
    let score = 0.5; // 基础分数

    // 场景匹配
    if (queryContext.scenes.length > 0 && memory.scene) {
      const sceneMatch = queryContext.scenes.some(scene =>
        memory.scene!.toLowerCase().includes(scene.toLowerCase()) ||
        scene.toLowerCase().includes(memory.scene!.toLowerCase())
      );
      if (sceneMatch) score += 0.3;
    }

    // 情绪匹配
    if (queryContext.emotions.length > 0 && memory.emotion) {
      const emotionMatch = queryContext.emotions.some(emotion =>
        memory.emotion!.toLowerCase().includes(emotion.toLowerCase()) ||
        emotion.toLowerCase().includes(memory.emotion!.toLowerCase())
      );
      if (emotionMatch) score += 0.2;
    }

    return Math.min(1, score);
  }

  /**
   * 计算时间权重分数
   */
  private calculateRecencyScore(memory: MemoryItem): number {
    const now = new Date();
    const memoryTime = memory.timestamp;
    const ageInHours = (now.getTime() - memoryTime.getTime()) / (1000 * 60 * 60);

    // 时间衰减函数
    if (ageInHours < 1) return 1; // 1小时内
    if (ageInHours < 24) return 0.9; // 1天内
    if (ageInHours < 72) return 0.7; // 3天内
    if (ageInHours < 168) return 0.5; // 1周内
    if (ageInHours < 720) return 0.3; // 1个月内
    return 0.1; // 1个月以上
  }

  /**
   * 计算综合分数
   */
  private calculateCombinedScore(
    semanticScore: number,
    keywordScore: number,
    contextualScore: number,
    recencyScore: number
  ): number {
    // 权重分配
    const semanticWeight = 0.4;
    const keywordWeight = 0.2;
    const contextualWeight = 0.2;
    const recencyWeight = 0.2;

    return (
      semanticScore * semanticWeight +
      keywordScore * keywordWeight +
      contextualScore * contextualWeight +
      recencyScore * recencyWeight
    );
  }

  /**
   * 生成相似度解释
   */
  private generateExplanation(
    semanticScore: number,
    keywordScore: number,
    contextualScore: number,
    recencyScore: number,
    memory: MemoryItem
  ): string[] {
    const explanations: string[] = [];

    if (semanticScore > 0.7) {
      explanations.push('语义内容高度相关');
    } else if (semanticScore > 0.4) {
      explanations.push('语义内容部分相关');
    }

    if (keywordScore > 0.6) {
      explanations.push('包含多个匹配关键词');
    }

    if (contextualScore > 0.7) {
      explanations.push('场景和情绪匹配度高');
    }

    if (recencyScore > 0.8) {
      explanations.push('近期记忆，相关性高');
    }

    return explanations;
  }

  /**
   * 提取记忆文本
   */
  private extractMemoryText(memory: MemoryItem): string {
    if (typeof memory.content === 'string') {
      return memory.content;
    }
    if (typeof memory.content === 'object') {
      return JSON.stringify(memory.content);
    }
    return '';
  }

  /**
   * 分词
   */
  private tokenize(text: string): string[] {
    return text.toLowerCase()
      .replace(/[^\w\s\u4e00-\u9fa5]/g, ' ')
      .split(/\s+/)
      .filter(word => word.length > 1);
  }

  /**
   * 从文本中提取场景
   */
  private extractScenesFromText(text: string): string[] {
    const sceneKeywords = ['工作', '学习', '娱乐', '休息', '运动', '购物', '社交', '家庭', '旅行', '会议'];
    const lowerText = text.toLowerCase();

    return sceneKeywords.filter(keyword =>
      lowerText.includes(keyword.toLowerCase())
    );
  }

  /**
   * 从文本中提取情绪
   */
  private extractEmotionsFromText(text: string): string[] {
    const emotionKeywords = ['开心', '高兴', '快乐', '悲伤', '难过', '愤怒', '生气', '平静', '紧张', '焦虑'];
    const lowerText = text.toLowerCase();

    return emotionKeywords.filter(keyword =>
      lowerText.includes(keyword.toLowerCase())
    );
  }

  /**
   * 提取记忆标签
   */
  private extractTags(memory: MemoryItem): string[] {
    const tags: string[] = [];

    if (memory.scene) tags.push(memory.scene);
    if (memory.emotion) tags.push(memory.emotion);

    // 从内容中提取标签
    const contentText = this.extractMemoryText(memory);
    const contentWords = this.tokenize(contentText);

    // 提取高频词作为标签
    const wordCount = new Map<string, number>();
    contentWords.forEach(word => {
      wordCount.set(word, (wordCount.get(word) || 0) + 1);
    });

    const topWords = Array.from(wordCount.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, 5)
      .map(([word]) => word);

    return [...tags, ...topWords];
  }

  /**
   * 缓存嵌入向量
   */
  private cacheEmbedding(text: string, vector: number[]): void {
    if (this.embeddingCache.size >= this.maxCacheSize) {
      // 移除最旧的缓存
      const oldestKey = this.embeddingCache.keys().next().value;
      if (oldestKey !== undefined) {
        this.embeddingCache.delete(oldestKey);
      }
    }
    this.embeddingCache.set(text, vector);
  }

  /**
   * 生成模拟向量（用于演示）
   */
  private generateMockVector(text: string): number[] {
    const vector = new Array(this.vectorDimension).fill(0);
    const words = text.toLowerCase().split(/\s+/);

    for (let i = 0; i < vector.length; i++) {
      const wordIndex = i % words.length;
      const word = words[wordIndex] || '';
      vector[i] = word.charCodeAt(0) / 255 * Math.sin(i * 0.1);
    }

    return vector;
  }

  /**
   * 生成基础向量（无预训练模型时使用）
   */
  private generateBasicVector(text: string): number[] {
    const vector = new Array(128).fill(0); // 简化维度
    const words = this.tokenize(text);

    // 基于词频和位置生成向量
    words.forEach((word, index) => {
      const wordHash = word.split('').reduce((hash, char) => {
        return hash * 31 + char.charCodeAt(0);
      }, 0);

      const vectorIndex = Math.abs(wordHash) % vector.length;
      vector[vectorIndex] += 1 / (index + 1); // 位置越靠前权重越高
    });

    return vector;
  }

  /**
   * 清除向量缓存
   */
  clearVectors(): void {
    this.vectors.clear();
    this.embeddingCache.clear();
  }

  /**
   * 获取向量统计信息
   */
  getVectorStatistics(): {
    totalVectors: number;
    cacheSize: number;
    memoryTypeDistribution: { [key: string]: number };
  } {
    const memoryTypeDistribution: { [key: string]: number } = {};

    this.vectors.forEach(vector => {
      const type = vector.memoryType;
      memoryTypeDistribution[type] = (memoryTypeDistribution[type] || 0) + 1;
    });

    return {
      totalVectors: this.vectors.size,
      cacheSize: this.embeddingCache.size,
      memoryTypeDistribution
    };
  }
}

