    for (const [key, value] of Object.entries(DEPLOYMENT_MAP)) {
      if (lowerInput.includes(key)) {
        this.developmentHabits.deploymentProcess = value;
        break;
      }
    }

    for (const [key, value] of Object.entries(CODE_REVIEW_MAP)) {
      if (lowerInput.includes(key)) {
