import { ModelInput } from '../core/ModelInterface';
import {
  RegisteredModel,
  RoutingResult,
  RoutingStrategy,
} from './types';

export class ModelSelector {
  private static instance: ModelSelector | null = null;
  private roundRobinIndex: number = 0;

  private constructor() {}

  public static getInstance(): ModelSelector {
    if (!ModelSelector.instance) {
      ModelSelector.instance = new ModelSelector();
    }
    return ModelSelector.instance;
  }

  public static reset(): void {
    ModelSelector.instance = null;
  }

  public route(
    availableModels: RegisteredModel[],
    input: ModelInput,
    strategy: RoutingStrategy
  ): RoutingResult {
    if (availableModels.length === 0) {
      throw new Error('没有可用的模型');
    }

    let selectedModel: RegisteredModel;
    let reason: string;

    switch (strategy) {
      case RoutingStrategy.PRIORITY:
        selectedModel = this.routeByPriority(availableModels);
        reason = '优先级最高';
        break;
      case RoutingStrategy.CAPABILITY:
        selectedModel = this.routeByCapability(availableModels, input);
        reason = '能力最匹配';
        break;
      case RoutingStrategy.LATENCY:
        selectedModel = this.routeByLatency(availableModels);
        reason = '延迟最低';
        break;
      case RoutingStrategy.ROUND_ROBIN:
        selectedModel = this.routeByRoundRobin(availableModels);
        reason = '轮询';
        break;
      case RoutingStrategy.RANDOM:
        selectedModel = this.routeByRandom(availableModels);
        reason = '随机';
        break;
      default:
        selectedModel = this.routeByPriority(availableModels);
        reason = '默认优先级';
    }

    const fallbackChain = availableModels
      .filter((m) => m.id !== selectedModel.id)
      .sort((a, b) => a.priority - b.priority)
      .map((m) => m.id);

    return {
      modelId: selectedModel.id,
      modelName: selectedModel.name,
      reason,
      fallbackChain,
    };
  }

  public routeByPriority(models: RegisteredModel[]): RegisteredModel {
    return [...models].sort((a, b) => a.priority - b.priority)[0];
  }

  public routeByCapability(
    models: RegisteredModel[],
    input: ModelInput
  ): RegisteredModel {
    let bestModel = models[0];
    let bestScore = 0;

    for (const model of models) {
      let score = 0;

      if (input.images && input.images.length > 0) {
        score += model.capabilities.visionScore * 2;
      }

      if (input.prompt && this.isCodingPrompt(input.prompt)) {
        score += model.capabilities.codingScore * 2;
      }

      score += model.capabilities.reasoningScore;
      score += model.capabilities.speedScore;

      if (score > bestScore) {
        bestScore = score;
        bestModel = model;
      }
    }

    return bestModel;
  }

  public routeByLatency(models: RegisteredModel[]): RegisteredModel {
    return [...models].sort(
      (a, b) => a.health.averageLatencyMs - b.health.averageLatencyMs
    )[0];
  }

  public routeByRoundRobin(models: RegisteredModel[]): RegisteredModel {
    const model = models[this.roundRobinIndex % models.length];
    this.roundRobinIndex++;
    return model;
  }

  public routeByRandom(models: RegisteredModel[]): RegisteredModel {
    return models[Math.floor(Math.random() * models.length)];
  }

  public isCodingPrompt(prompt: string): boolean {
    const codingKeywords = [
      'code',
      '编程',
      '程序',
      '函数',
      'class',
      'import',
      'def ',
      'const ',
      'let ',
      'var ',
      'function ',
      '代码',
      'bug',
      'debug',
      'error',
      'exception',
    ];
    return codingKeywords.some((keyword) =>
      prompt.toLowerCase().includes(keyword.toLowerCase())
    );
  }
}

import {
  ModelConfig,
  ModelInput,
  ModelOutput,
} from '../core/ModelInterface';
import { Logger } from '../utils/Logger';
import { OpenAICompatibleModel } from './OpenAICompatibleModel';
import { ModelSelector } from './ModelSelector';
import {
  ModelCapabilityProfile,
  ModelHealthStatus,
  MultiModelConfig,
  RegisteredModel,
  RoutingResult,
  RoutingStrategy,
} from './types';

export type {
  ModelCapabilityProfile,
  ModelHealthStatus,
  MultiModelConfig,
  RegisteredModel,
  RoutingResult,
} from './types';

export { RoutingStrategy } from './types';

export class MultiModelLLMProvider {
  private static instance: MultiModelLLMProvider | null = null;
  private models: Map<string, RegisteredModel> = new Map();
  private config: Required<MultiModelConfig>;
  private initialized: boolean = false;
  private healthCheckTimer?: NodeJS.Timeout;
  private modelSelector: ModelSelector;

  private constructor(config: MultiModelConfig = {}) {
    this.config = {
      defaultStrategy: config.defaultStrategy || RoutingStrategy.PRIORITY,
      healthCheckIntervalMs: config.healthCheckIntervalMs || 30000,
      maxConsecutiveFailures: config.maxConsecutiveFailures || 3,
      requestTimeoutMs: config.requestTimeoutMs || 30000,
      enableHealthCheck: config.enableHealthCheck ?? true,
    };
    this.modelSelector = ModelSelector.getInstance();
  }

  public static getInstance(config?: MultiModelConfig): MultiModelLLMProvider {
    if (!MultiModelLLMProvider.instance) {
      MultiModelLLMProvider.instance = new MultiModelLLMProvider(config);
    }
    return MultiModelLLMProvider.instance;
  }

  public static reset(): void {
    if (MultiModelLLMProvider.instance) {
      MultiModelLLMProvider.instance.cleanup();
    }
    MultiModelLLMProvider.instance = null;
  }

  public async initialize(): Promise<void> {
    if (this.initialized) return;

    await this.registerDefaultModels();

    if (this.config.enableHealthCheck) {
      this.startHealthCheck();
    }

    this.initialized = true;
    Logger.info(
      `✅ MultiModelLLMProvider 初始化完成，已注册 ${this.models.size} 个模型`,
      'MultiModelLLMProvider'
    );
  }

  private async registerDefaultModels(): Promise<void> {
    const localBaseUrl =
      process.env.OPENAI_API_BASE ||
      process.env.LLM_BASE_URL ||
      'http://127.0.0.1:8001/v1';
    const localApiKey =
      process.env.OPENAI_API_KEY || process.env.LLM_API_KEY || 'not-needed';
    const localModelName = process.env.LLM_MODEL || 'qwen2.5:3b';

    await this.registerModel(
      'local-llm',
      localModelName,
      {
        name: localModelName,
        baseUrl: localBaseUrl,
        apiKey: localApiKey,
        timeout: 30000,
        maxTokens: 4096,
        temperature: 0.7,
        topP: 0.9,
        frequencyPenalty: 0,
        presencePenalty: 0,
      },
      {
        visionScore: 60,
        codingScore: 50,
        reasoningScore: 50,
        speedScore: 90,
        contextLength: 8192,
        features: ['chat', 'code'],
      },
      10
    );
    Logger.info(
      `✅ 已注册本地模型: ${localModelName} @ ${localBaseUrl}`,
      'MultiModelLLMProvider'
    );

    const zhipuApiKey = process.env.ZHIPU_API_KEY;
    const zhipuBaseUrl =
      process.env.ZHIPU_BASE_URL || 'https://open.bigmodel.cn/api/paas/v4';
    const zhipuModelName = process.env.ZHIPU_MODEL || 'glm-4.5-air';

    if (zhipuApiKey) {
      await this.registerModel(
        'zhipu',
        zhipuModelName,
        {
          name: zhipuModelName,
          baseUrl: zhipuBaseUrl,
          apiKey: zhipuApiKey,
          timeout: 60000,
          maxTokens: 4096,
          temperature: 0.7,
          topP: 0.9,
          frequencyPenalty: 0,
          presencePenalty: 0,
        },
        {
          visionScore: 70,
          codingScore: 80,
          reasoningScore: 85,
          speedScore: 70,
          contextLength: 128000,
          features: ['chat', 'code', 'analysis', 'review'],
        },
        20
      );
      Logger.info(
        `✅ 已注册智谱模型: ${zhipuModelName} @ ${zhipuBaseUrl}`,
        'MultiModelLLMProvider'
      );
    } else {
      Logger.info(
        'ℹ️ 未配置 ZHIPU_API_KEY，跳过智谱模型注册',
        'MultiModelLLMProvider'
      );
    }
  }

  private ensureInitialized(): void {
    if (!this.initialized) {
      throw new Error('MultiModelLLMProvider 未初始化，请先调用 initialize()');
    }
  }

  public async registerModel(
    id: string,
    name: string,
    config: ModelConfig,
    capabilities: ModelCapabilityProfile,
    priority: number = 10
  ): Promise<void> {
    const model = new OpenAICompatibleModel({
      baseUrl: config.baseUrl,
      apiKey: config.apiKey,
      modelName: name,
    });

    try {
      await model.initialize();
    } catch (err) {
      Logger.warn(
        `⚠️ 模型 ${name} 初始化失败: ${(err as Error).message}`,
        'MultiModelLLMProvider'
      );
    }

    const registeredModel: RegisteredModel = {
      id,
      name,
      model,
      config,
      capabilities,
      health: {
        available: true,
        averageLatencyMs: 0,
        successRate: 1,
        lastCheckTime: Date.now(),
        consecutiveFailures: 0,
      },
      priority,
      enabled: true,
    };

    this.models.set(id, registeredModel);
  }

  public unregisterModel(id: string): boolean {
    this.ensureInitialized();

    const model = this.models.get(id);
    if (!model) {
      Logger.warn(`⚠️ 模型未找到: ${id}`, 'MultiModelLLMProvider');
      return false;
    }

    this.models.delete(id);
    return true;
  }

  public listModels(): RegisteredModel[] {
    return Array.from(this.models.values());
  }

  public getModel(id: string): RegisteredModel | undefined {
    return this.models.get(id);
  }

  public getModels(): Map<string, RegisteredModel> {
    return this.models;
  }

  public setModelPriority(id: string, priority: number): void {
    const model = this.models.get(id);
    if (model) {
      model.priority = priority;
    }
  }

  public setModelEnabled(id: string, enabled: boolean): void {
    const model = this.models.get(id);
    if (model) {
      model.enabled = enabled;
      Logger.info(
        `${enabled ? '✅' : '❌'} 模型 ${model.name} 已${enabled ? '启用' : '禁用'}`,
        'MultiModelLLMProvider'
      );
    }
  }

  public route(input: ModelInput, strategy?: RoutingStrategy): RoutingResult {
    this.ensureInitialized();

    const activeStrategy = strategy || this.config.defaultStrategy;
    const availableModels = this.getAvailableModels();

    return this.modelSelector.route(availableModels, input, activeStrategy);
  }

  public async generate(
    input: ModelInput,
    strategy?: RoutingStrategy
  ): Promise<ModelOutput> {
    this.ensureInitialized();

    const routingResult = this.route(input, strategy);
    const fallbackChain = [
      routingResult.modelId,
      ...routingResult.fallbackChain,
    ];

    let lastError: Error | undefined;

    for (const modelId of fallbackChain) {
      const model = this.models.get(modelId);
      if (!model || !model.enabled) {
        continue;
      }

      if (!model.health.available) {
        Logger.info(
          `⏭️ 跳过不可用模型 ${model.name}（上次失败: ${model.health.lastError || '未知'}）`,
          'MultiModelLLMProvider'
        );
        continue;
      }

      try {
        Logger.info(
          `🎯 使用模型: ${model.name} (原因: ${routingResult.reason})`,
          'MultiModelLLMProvider'
        );

        const startTime = Date.now();
        const output = await this.executeWithTimeout(model, input);
        const latency = Date.now() - startTime;

        if (!output.text) {
          throw new Error('模型返回空内容');
        }

        this.updateHealthStatus(model, true, latency);

        output.modelName = model.name;
        output.isFallback = modelId !== routingResult.modelId;

        Logger.info(
          `✅ 模型 ${model.name} 生成成功 (${latency}ms)`,
          'MultiModelLLMProvider'
        );
        return output;
      } catch (error) {
        lastError = error as Error;
        this.updateHealthStatus(model, false, 0, (error as Error).message);
        Logger.warn(
          `⚠️ 模型 ${model.name} 失败，尝试降级: ${(error as Error).message}`,
          'MultiModelLLMProvider'
        );

        const errorMsg = (error as Error).message.toLowerCase();
        if (
          errorMsg.includes('econnrefused') ||
          errorMsg.includes('econnreset') ||
          errorMsg.includes('connection refused') ||
          errorMsg.includes('fetch failed') ||
          errorMsg.includes('abort')
        ) {
          model.health.available = false;
          Logger.warn(
            `🚫 连接错误，立即禁用模型 ${model.name}`,
            'MultiModelLLMProvider'
          );
        }
      }
    }

    throw new Error(`所有模型均失败: ${lastError?.message || '未知错误'}`);
  }

  public async *stream(
    input: ModelInput,
    strategy?: RoutingStrategy
  ): AsyncGenerator<string> {
    this.ensureInitialized();

    const routingResult = this.route(input, strategy);
    const model = this.models.get(routingResult.modelId);

    if (!model) {
      throw new Error('路由失败：模型未找到');
    }

    yield* model.model.stream(input);
  }

  public async benchmarkModel(
    modelId: string
  ): Promise<ModelCapabilityProfile> {
    const model = this.models.get(modelId);
    if (!model) {
      throw new Error(`模型未找到: ${modelId}`);
    }

    Logger.info(`📊 开始评估模型: ${model.name}`, 'MultiModelLLMProvider');

    const speedScore = await this.testSpeed(model);
    const codingScore = await this.testCoding(model);
    const reasoningScore = await this.testReasoning(model);
    const visionScore = model.capabilities.features.includes('vision')
      ? await this.testVision(model)
      : 0;

    const profile: ModelCapabilityProfile = {
      visionScore,
      codingScore,
      reasoningScore,
      speedScore,
      contextLength: model.capabilities.contextLength,
      features: model.capabilities.features,
    };

    model.capabilities = profile;

    Logger.info(
      `📊 模型 ${model.name} 评估完成: 速度=${speedScore}, 代码=${codingScore}, 推理=${reasoningScore}, 视觉=${visionScore}`,
      'MultiModelLLMProvider'
    );

    return profile;
  }

  public getModelName(): string {
    const availableModels = this.getAvailableModels();
    if (availableModels.length === 0) {
      return '无可用模型';
    }
    const best = this.modelSelector.routeByPriority(availableModels);
    return best.name;
  }

  public isAvailable(): boolean {
    return this.getAvailableModels().length > 0;
  }

  public async healthCheck(): Promise<{ available: boolean; message: string }> {
    if (!this.initialized) {
      return { available: false, message: 'MultiModelLLMProvider 未初始化' };
    }

    const availableModels = this.getAvailableModels();
    if (availableModels.length === 0) {
      return { available: false, message: '没有可用模型' };
    }

    const modelNames = availableModels.map((m) => m.name).join(', ');
    return {
      available: true,
      message: `多模型Provider可用，活跃模型: ${modelNames}`,
    };
  }

  public async chat(
    message: string,
    history: Array<{ role: string; content: string }> = [],
    systemPromptOverride?: string
  ): Promise<string> {
    this.ensureInitialized();

    const defaultPrompt = `你是家百星，28岁私人秘书。成熟、专业、从容。
回复要求：
1. 语气成熟自然，像有经验的专业人士
2. 简洁高效，不啰嗦，不堆砌空洞的关心
3. 如果是技术问题，要专业严谨
4. 如果是闲聊，要保持温暖但不过度
5. 不使用"～""哦""呢""呀"等幼化语气词`;

    const systemPrompt = systemPromptOverride || defaultPrompt;
    const historyPrompt = history
      .map((h) => `${h.role}: ${h.content}`)
      .join('\n');
    const fullPrompt = `${historyPrompt}\n\n用户: ${message}`;

    const routingResult = this.route(
      { prompt: fullPrompt, systemPrompt, maxTokens: 1024, temperature: 0.8 },
      RoutingStrategy.PRIORITY
    );

    const fallbackChain = [
      routingResult.modelId,
      ...routingResult.fallbackChain,
    ];

    let lastError: Error | undefined;

    for (const modelId of fallbackChain) {
      const registeredModel = this.models.get(modelId);
      if (
        !registeredModel ||
        !registeredModel.enabled ||
        !registeredModel.health.available
      ) {
        continue;
      }

      try {
        const startTime = Date.now();
        const output = await this.executeWithTimeout(registeredModel, {
          prompt: fullPrompt,
          systemPrompt,
          temperature: 0.8,
          maxTokens: 1024,
        });
        const latency = Date.now() - startTime;

        this.updateHealthStatus(registeredModel, true, latency);

        if (!output.text) {
          throw new Error('模型未返回内容');
        }

        return output.text;
      } catch (error) {
        lastError = error as Error;
        this.updateHealthStatus(
          registeredModel,
          false,
          0,
          (error as Error).message
        );
        Logger.warn(
          `⚠️ 模型 ${registeredModel.name} chat失败，尝试降级: ${(error as Error).message}`,
          'MultiModelLLMProvider'
        );
      }
    }

    throw new Error(`所有模型chat均失败: ${lastError?.message || '未知错误'}`);
  }

  public async analyzeCode(
    filePath: string,
    content: string,
    input: string
  ): Promise<string> {
    const prompt = `分析代码文件: ${filePath}\n\n代码内容:\n${content}\n\n用户查询: ${input}\n\n请分析代码并提供详细说明。`;
    return this.chat(prompt);
  }

  public async generateModifiedFileContent(
    filePath: string,
    content: string,
    instruction: string,
    fileExists: boolean = true
  ): Promise<string> {
    const existsHint = fileExists
      ? '请直接输出修改后的完整文件内容'
      : '文件不存在，请生成新的完整文件内容';
    const prompt = `文件: ${filePath}\n\n原始内容:\n${content}\n\n修改指令: ${instruction}\n\n${existsHint}，不要添加额外说明。`;
    return this.chat(prompt);
  }

  public async devGenerateCode(
    userRequest: string,
    filePath?: string,
    existingContent?: string
  ): Promise<string> {
    const systemPrompt = `你是一名专业的软件开发工程师助手。请根据用户需求生成高质量、规范、可运行的代码。

要求：
- 代码必须完整，包含所有必要的导入（import）和类型定义
- 使用现代最佳实践和语言最新特性
- 代码要规范、易读、有适当的注释
- 如果是修改现有文件，保持原有代码风格
- 如果是新文件，生成完整的文件内容
- 直接输出可用的代码，不要包含解释性文字
- 代码块不要用 markdown 代码块包裹`;

    const fileContext = filePath ? `\n目标文件路径：${filePath}` : '';
    const existingCodeContext = existingContent
      ? `\n\n当前文件内容：\n${existingContent}`
      : '\n（新文件，当前不存在）';

    const prompt = `用户需求：${userRequest}${fileContext}${existingCodeContext}\n\n请生成代码。`;

    const output = await this.generate(
      { prompt, systemPrompt, temperature: 0.3, maxTokens: 4096 },
      RoutingStrategy.CAPABILITY
    );

    if (!output.text) {
      throw new Error('模型未返回内容');
    }

    return output.text;
  }

  public getHealthStatus(): Record<string, ModelHealthStatus> {
    const status: Record<string, ModelHealthStatus> = {};
    this.models.forEach((model, id) => {
      status[id] = { ...model.health };
    });
    return status;
  }

  public async shutdown(): Promise<void> {
    this.cleanup();
    Logger.info('🛑 MultiModelLLMProvider 已关闭', 'MultiModelLLMProvider');
  }

  public async checkAllModelsHealth(): Promise<void> {
    await this.checkModelsHealth();
  }

  public getAvailableModels(): RegisteredModel[] {
    return Array.from(this.models.values()).filter(
      (m) => m.enabled && m.health.available
    );
  }

  private async executeWithTimeout(
    model: RegisteredModel,
    input: ModelInput
  ): Promise<ModelOutput> {
    return new Promise((resolve, reject) => {
      const timeout = setTimeout(() => {
        reject(new Error(`请求超时 (${this.config.requestTimeoutMs}ms)`));
      }, this.config.requestTimeoutMs);

      model.model
        .generate(input)
        .then((output) => {
          clearTimeout(timeout);
          resolve(output);
        })
        .catch((error) => {
          clearTimeout(timeout);
          reject(error);
        });
    });
  }

  private updateHealthStatus(
    model: RegisteredModel,
    success: boolean,
    latency: number,
    error?: string
  ): void {
    if (success) {
      model.health.consecutiveFailures = 0;
      model.health.successRate = model.health.successRate * 0.9 + 0.1;
      if (latency > 0) {
        model.health.averageLatencyMs =
          model.health.averageLatencyMs * 0.9 + latency * 0.1;
      }
    } else {
      model.health.consecutiveFailures++;
      model.health.successRate = model.health.successRate * 0.9;
      model.health.lastError = error;

      if (
        model.health.consecutiveFailures >= this.config.maxConsecutiveFailures
      ) {
        model.health.available = false;
        Logger.warn(
          `🚫 模型 ${model.name} 连续失败 ${model.health.consecutiveFailures} 次，已标记为不可用`,
          'MultiModelLLMProvider'
        );
      }
    }

    model.health.lastCheckTime = Date.now();
  }

  private startHealthCheck(): void {
    this.healthCheckTimer = setInterval(() => {
      void this.checkModelsHealth();
    }, this.config.healthCheckIntervalMs);
  }

  private async checkModelsHealth(): Promise<void> {
    for (const [, model] of this.models) {
      if (!model.enabled) continue;

      try {
        const startTime = Date.now();
        await model.model.generate({
          prompt: '你好',
          maxTokens: 5,
        });
        const latency = Date.now() - startTime;
        this.updateHealthStatus(model, true, latency);
      } catch (error) {
        this.updateHealthStatus(model, false, 0, (error as Error).message);
      }
    }
  }

  private cleanup(): void {
    if (this.healthCheckTimer) {
      clearInterval(this.healthCheckTimer);
      this.healthCheckTimer = undefined;
    }
    this.models.clear();
    this.initialized = false;
  }

  private async testSpeed(model: RegisteredModel): Promise<number> {
    try {
      const startTime = Date.now();
      await model.model.generate({
        prompt: 'Hello',
        maxTokens: 10,
      });
      const latency = Date.now() - startTime;
      return Math.max(0, Math.min(100, 100 - latency / 10));
    } catch {
      return 0;
    }
  }

  private async testCoding(model: RegisteredModel): Promise<number> {
    try {
      const output = await model.model.generate({
        prompt: 'Write a function to calculate factorial in Python',
        maxTokens: 100,
      });
      const hasCode =
        output.text.includes('def ') && output.text.includes('return');
      return hasCode ? 80 + Math.random() * 20 : 40 + Math.random() * 20;
    } catch {
      return 0;
    }
  }

  private async testReasoning(model: RegisteredModel): Promise<number> {
    try {
      const output = await model.model.generate({
        prompt:
          'If it takes 5 machines 5 minutes to make 5 widgets, how long does it take 100 machines to make 100 widgets?',
        maxTokens: 50,
      });
      const correct =
        output.text.includes('5 minutes') || output.text.includes('5分钟');
      return correct ? 90 + Math.random() * 10 : 50 + Math.random() * 20;
    } catch {
      return 0;
    }
  }

  private async testVision(model: RegisteredModel): Promise<number> {
    return model.capabilities.visionScore || 50;
  }
}

/**
 * OpenAI 兼容多模态 LLM 适配器
 * 支持通过 OpenAI API 格式调用本地多模态模型（如 qwen2.5-vl）
 * 支持文本+图像的多模态输入
 * 增强功能：指数退避重试、超时熔断、降级回复
 */

import { Logger } from '../utils/Logger';
import { Model, ModelInput, ModelOutput } from './ModelInterface';

/**
 * OpenAI 兼容模型的配置
 */
export interface OpenAICompatibleConfig {
  baseUrl: string;
  apiKey: string;
  modelName: string;
  timeout: number;
  maxTokens: number;
  temperature: number;
  topP: number;
  maxRetries?: number;
  retryDelayBase?: number;
  circuitBreakerThreshold?: number;
  circuitBreakerRecoveryMs?: number;
  thinkingMode?: 'enabled' | 'disabled';
  reasoningEffort?: 'high' | 'max';
}

/**
 * 多模态消息内容
 */
export interface MultimodalMessageContent {
  type: 'text' | 'image_url';
  text?: string;
  image_url?: {
    url: string;
  };
}

/**
 * OpenAI 格式的聊天消息
 */
export interface ChatMessage {
  role: 'system' | 'user' | 'assistant';
  content: string | MultimodalMessageContent[];
}

/**
 * 多模态输入扩展
 */
export interface MultimodalInput extends ModelInput {
  images?: string[];
}

/**
 * OpenAI 兼容多模态 LLM 实现
 */
/**
 * 降级回复模板
 */
const FALLBACK_RESPONSES = [
  '抱歉，我暂时无法连接到大模型，让我用本地知识来回答你...',
  '服务暂时繁忙，我先给你一个简要的回复...',
  '网络连接有些不稳定，让我尝试用备用方案...',
];

type ResolvedConfig = Omit<Required<OpenAICompatibleConfig>, 'thinkingMode' | 'reasoningEffort'> & Pick<OpenAICompatibleConfig, 'thinkingMode' | 'reasoningEffort'>;

export class OpenAICompatibleModel implements Model {
  private config: ResolvedConfig;
  private initialized: boolean = false;
  /** 连续失败次数 */
  private consecutiveFailures: number = 0;
  /** 连接错误导致的连续失败次数（连接错误不再自动恢复） */
  private consecutiveConnectionFailures: number = 0;
  /** 熔断状态 */
  private circuitOpen: boolean = false;
  /** 熔断恢复时间 */
  private circuitOpenUntil: number = 0;
  /** 最后成功时间 */
  private lastSuccessTime: number = 0;
  /** 连接错误导致的永久熔断 - 不再自动恢复 */
  private permanentlyDisabled: boolean = false;

  constructor(config: Partial<OpenAICompatibleConfig> = {}) {
    this.config = {
      baseUrl:
        config.baseUrl ||
        process.env.OPENAI_API_BASE ||
        'http://127.0.0.1:8000/v1',
      apiKey: config.apiKey || process.env.OPENAI_API_KEY || 'not-needed',
      modelName: config.modelName || process.env.LLM_MODEL || 'qwen2.5-vl',
      timeout: config.timeout || 30000,
      maxTokens: config.maxTokens || 4096,
      temperature: config.temperature || 0.7,
      topP: config.topP || 0.9,
      maxRetries: config.maxRetries ?? 3,
      retryDelayBase: config.retryDelayBase ?? 1000,
      circuitBreakerThreshold: config.circuitBreakerThreshold ?? 5,
      circuitBreakerRecoveryMs: config.circuitBreakerRecoveryMs ?? 60000,
      thinkingMode: config.thinkingMode,
      reasoningEffort: config.reasoningEffort,
    };
  }

  async initialize(): Promise<void> {
    try {
      Logger.info(
        `🔌 正在连接 OpenAI 兼容服务: ${this.config.baseUrl}`,
        'OpenAICompatibleModel'
      );

      const response = await this.fetchWithTimeout(
        `${this.config.baseUrl}/models`,
        {
          headers: {
            Authorization: `Bearer ${this.config.apiKey}`,
          },
        }
      );

      if (response.ok) {
        const responseText = await response.text();
        let data: Record<string, unknown>;
        try {
          data = JSON.parse(responseText);
        } catch {
          throw new Error(`API 响应 JSON 解析失败 (${response.status}): ${responseText.substring(0, 200)}`);
        }
        const models =
          (data.data as Array<Record<string, string>> | undefined) || [];
        const modelNames =
          models.map((m: Record<string, string>) => m.id).join(', ') || '未知';

        this.initialized = true;
        Logger.info(
          `✅ OpenAI 兼容服务已初始化 - 模型: ${this.config.modelName}, 可用模型: ${modelNames}`,
          'OpenAICompatibleModel'
        );
      } else if (response.status === 401) {
        this.initialized = true;
        Logger.warn(
          `⚠️ OpenAI 兼容服务 /models 端点返回 401 (认证失败)，请检查 API_KEY 配置，模型仍会尝试使用`,
          'OpenAICompatibleModel'
        );
      } else {
        this.initialized = true;
        Logger.warn(
          `⚠️ OpenAI 兼容服务 /models 端点返回 ${response.status}，但模型仍可尝试使用`,
          'OpenAICompatibleModel'
        );
      }
    } catch (error) {
      this.initialized = true;
      Logger.warn(
        `⚠️ OpenAI 兼容模型初始化检查失败: ${(error as Error).message}，模型仍将尝试运行`,
        'OpenAICompatibleModel'
      );
    }
  }

  async generate(input: ModelInput | MultimodalInput): Promise<ModelOutput> {
    if (!this.initialized) {
      return {
        text: '',
        error: 'OpenAI 兼容模型未初始化',
      };
    }

    // 永久禁用检查 - 连接错误导致不再重试
    if (this.permanentlyDisabled) {
      Logger.warn(
        '🚫 模型已永久禁用（连接错误），请检查 LLM 服务是否运行',
        'OpenAICompatibleModel'
      );
      throw new Error('模型已永久禁用，请检查 LLM 服务');
    }

    // 检查熔断状态
    if (this.isCircuitOpen()) {
      Logger.warn('⚠️ 熔断器开启，跳过此模型', 'OpenAICompatibleModel');
      throw new Error('熔断器开启，模型暂时不可用');
    }

    let lastError: Error | undefined;

    // 本次尝试是否应跳过重试（连接错误直接失败）
    let skipRetry = false;

    // 指数退避重试
    for (let attempt = 0; attempt <= this.config.maxRetries; attempt++) {
      try {
        const result = await this.executeGenerate(input);
        // 成功：重置失败计数
        this.consecutiveFailures = 0;
        this.consecutiveConnectionFailures = 0;
        this.lastSuccessTime = Date.now();
        return result;
      } catch (error) {
        lastError = error as Error;
        this.consecutiveFailures++;

        const errorMsg = lastError.message.toLowerCase();
        const isConnectionError =
          errorMsg.includes('econnrefused') ||
          errorMsg.includes('econnreset') ||
          errorMsg.includes('enetunreach') ||
          errorMsg.includes('connection refused') ||
          errorMsg.includes('fetch failed') ||
          errorMsg.includes('abort');

        if (isConnectionError) {
          this.consecutiveConnectionFailures++;
          Logger.warn(
            `🚫 连接错误 (第${this.consecutiveConnectionFailures}次)，跳过重试: ${lastError.message}`,
            'OpenAICompatibleModel'
          );
          skipRetry = true;
          // 连接错误快速触发熔断
          if (this.consecutiveConnectionFailures >= 1) {
            this.openCircuit(true);
            Logger.error(
              `🔥 连接错误触发熔断`,
              undefined,
              'OpenAICompatibleModel'
            );
          }
          // 连续连接错误超过3次 → 永久禁用，不再自动恢复
          if (this.consecutiveConnectionFailures >= 3) {
            this.permanentlyDisabled = true;
            this.circuitOpen = false;
            Logger.error(
              `🔴 连续 ${this.consecutiveConnectionFailures} 次连接错误，永久禁用此模型。请确认 LLM 服务已启动后重启应用。`,
              undefined,
              'OpenAICompatibleModel'
            );
          }
          break;
        }

        // 检查是否达到熔断阈值
        if (this.consecutiveFailures >= this.config.circuitBreakerThreshold) {
          this.openCircuit(false);
          Logger.error(
            `🔥 连续失败${this.consecutiveFailures}次，触发熔断`,
            undefined,
            'OpenAICompatibleModel'
          );
          break;
        }

        if (attempt < this.config.maxRetries && !skipRetry) {
          const delay = this.config.retryDelayBase * Math.pow(2, attempt);
          Logger.warn(
            `⚠️ LLM调用失败 (${attempt + 1}/${this.config.maxRetries + 1})，${delay}ms后重试: ${lastError?.message || '未知错误'}`,
            'OpenAICompatibleModel'
          );
          await this.sleep(delay);
        }
      }
    }

    // 所有重试失败，抛出错误让 MultiModelLLMProvider 处理降级
    Logger.error(
      `❌ LLM调用最终失败: ${lastError?.message || '未知错误'}`,
      undefined,
      'OpenAICompatibleModel'
    );
    throw lastError || new Error('LLM调用失败');
  }

  /**
   * 执行实际生成请求
   */
  private async executeGenerate(
    input: ModelInput | MultimodalInput
  ): Promise<ModelOutput> {
    const multimodalInput = input as MultimodalInput;
    // 如果传入了 messages 数组（Function Calling 循环），直接使用
    // 否则从 prompt 构建消息
    const messages =
      input.messages && input.messages.length > 0
        ? input.messages
        : this.buildMessages(input, multimodalInput.images);

    const requestBody: Record<string, unknown> = {
      model: this.config.modelName,
      messages,
      temperature: input.temperature ?? this.config.temperature,
      max_tokens: input.maxTokens ?? this.config.maxTokens,
      top_p: input.topP ?? this.config.topP,
      stream: false,
    };

    if (this.config.thinkingMode === 'enabled') {
      requestBody.thinking = { type: 'enabled' };
      if (this.config.reasoningEffort) {
        requestBody.reasoning_effort = this.config.reasoningEffort;
      }
    }

    // 如果有工具定义，添加到请求中（Function Calling）
    if (input.tools && input.tools.length > 0) {
      requestBody.tools = input.tools;
    }

    const response = await this.fetchWithTimeout(
      `${this.config.baseUrl}/chat/completions`,
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${this.config.apiKey}`,
        },
        body: JSON.stringify(requestBody),
      }
    );

    if (!response.ok) {
      const errorBody = await response.text();
      Logger.error(
        `❌ LLM API请求失败: status=${response.status}, body=${errorBody.substring(0, 200)}`,
        undefined,
        'OpenAICompatibleModel'
      );
      throw new Error(`API 请求失败 (${response.status}): ${errorBody}`);
    }

    const responseText = await response.text();
    Logger.debug(
      `📨 LLM API响应: 长度=${responseText.length}字符`,
      'OpenAICompatibleModel'
    );
    let data: Record<string, unknown>;
    try {
      data = JSON.parse(responseText);
    } catch {
      throw new Error(`API 响应 JSON 解析失败: ${responseText.substring(0, 200)}`);
    }
    const choices = data.choices as
      | Array<Record<string, Record<string, unknown>>>
      | undefined;

    if (!choices || choices.length === 0) {
      throw new Error('模型未返回有效内容');
    }

    const message = choices[0].message as Record<string, unknown> | undefined;
    const generatedText = (message?.content as string) || '';

    const reasoningContent = message?.reasoning_content as string | undefined;

    const result: ModelOutput = {
      text: generatedText,
      finishReason: String(choices[0].finish_reason || 'stop'),
    };

    if (reasoningContent) {
      result.metadata = { reasoningContent };
    }

    // 解析 tool_calls
    const rawToolCalls = message?.tool_calls as
      | Array<Record<string, unknown>>
      | undefined;
    if (rawToolCalls && rawToolCalls.length > 0) {
      result.toolCalls = this.normalizeToolCalls(rawToolCalls);
    }

    const usage = data.usage as Record<string, number> | undefined;
    if (usage) {
      result.tokens = {
        prompt: usage.prompt_tokens || 0,
        completion: usage.completion_tokens || 0,
        total: usage.total_tokens || 0,
      };
    }

    return result;
  }

  /**
   * F0-04: 规范化 tool_calls，确保所有必需字段存在
   * DeepSeek V4 Flash 等模型可能返回缺失 id/type 字段的 tool_calls
   */
  private normalizeToolCalls(rawToolCalls: Array<Record<string, unknown>>): Array<{
    id: string;
    type: string;
    function: { name: string; arguments: string };
  }> {
    return rawToolCalls.map((tc, index) => {
      const fn = tc.function as Record<string, unknown> | undefined;
      let args = '';
      if (fn) {
        if (typeof fn.arguments === 'string') {
          args = fn.arguments;
        } else if (fn.arguments !== undefined && fn.arguments !== null) {
          try {
            args = JSON.stringify(fn.arguments);
          } catch {
            args = '{}';
          }
        }
      }

      return {
        id: (tc.id as string) || `tc_${Date.now()}_${index}`,
        type: (tc.type as string) || 'function',
        function: {
          name: (fn?.name as string) || 'unknown',
          arguments: args,
        },
      };
    });
  }

  /**
   * 生成降级回复
   */
  private generateFallbackResponse(
    input: ModelInput,
    error?: Error
  ): ModelOutput {
    const prompt = input.prompt || '';
    const fallbackIndex = Math.min(
      this.consecutiveFailures,
      FALLBACK_RESPONSES.length - 1
    );
    const fallbackPrefix = FALLBACK_RESPONSES[fallbackIndex];

    // 简单的关键词匹配降级回复
    let fallbackText = fallbackPrefix;

    if (prompt.includes('你好') || prompt.includes('hello')) {
      fallbackText += '\n\n你好！我是jiabaixing，很高兴为你服务。';
    } else if (prompt.includes('谢谢') || prompt.includes('感谢')) {
      fallbackText += '\n\n不客气！有什么需要随时告诉我。';
    } else if (prompt.includes('再见') || prompt.includes('拜拜')) {
      fallbackText += '\n\n再见！期待下次为你服务。';
    } else {
      fallbackText += '\n\n你可以尝试重新发送消息，或者稍后再试。';
    }

    return {
      text: fallbackText,
      error: error?.message || '服务暂时不可用',
      isFallback: true,
    };
  }

  /**
   * 检查熔断器是否开启
   */
  private isCircuitOpen(): boolean {
    if (this.permanentlyDisabled) return true;
    if (!this.circuitOpen) return false;

    // 检查是否已过恢复时间
    if (Date.now() >= this.circuitOpenUntil) {
      this.circuitOpen = false;
      this.consecutiveFailures = 0;
      Logger.info('🔓 熔断器恢复，重新尝试连接', 'OpenAICompatibleModel');
      return false;
    }

    return true;
  }

  /**
   * 开启熔断器
   * @param isConnectionError - 是否为连接错误（连接错误恢复时间更长）
   */
  private openCircuit(isConnectionError: boolean = false): void {
    const recoveryMs = isConnectionError
      ? 300000
      : this.config.circuitBreakerRecoveryMs;
    this.circuitOpen = true;
    this.circuitOpenUntil = Date.now() + recoveryMs;
    Logger.warn(
      `🔒 熔断器已开启，${recoveryMs / 1000}秒后恢复`,
      'OpenAICompatibleModel'
    );
  }

  /**
   * 延迟函数
   */
  private sleep(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  async *stream(input: ModelInput): AsyncGenerator<string> {
    if (!this.initialized) {
      throw new Error('OpenAI 兼容模型未初始化');
    }

    try {
      const messages = this.buildMessages(input);

      const requestBody = {
        model: this.config.modelName,
        messages,
        temperature: input.temperature ?? this.config.temperature,
        max_tokens: input.maxTokens ?? this.config.maxTokens,
        stream: true,
      };

      const response = await this.fetchWithTimeout(
        `${this.config.baseUrl}/chat/completions`,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${this.config.apiKey}`,
          },
          body: JSON.stringify(requestBody),
        }
      );

      if (!response.ok) {
        throw new Error(`API 请求失败: ${response.status}`);
      }

      if (!response.body) {
        throw new Error('响应体为空');
      }

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split('\n');
        buffer = lines.pop() || '';

        for (const line of lines) {
          const trimmed = line.trim();
          if (!trimmed || !trimmed.startsWith('data:')) continue;

          const data = trimmed.slice(5).trim();
          if (data === '[DONE]') return;

          try {
            const parsed = JSON.parse(data) as Record<string, unknown>;
            const choices = parsed.choices as
              | Array<Record<string, Record<string, string>>>
              | undefined;
            if (choices && choices.length > 0) {
              const delta = choices[0].delta as
                | Record<string, string>
                | undefined;
              const content = delta?.content;
              if (content) {
                yield content;
              }
            }
          } catch {
            // 忽略解析错误
          }
        }
      }
    } catch (error) {
      throw new Error(`流式生成失败: ${(error as Error).message}`);
    }
  }

  async getModelInfo(): Promise<Record<string, unknown>> {
    return {
      name: this.config.modelName,
      baseUrl: this.config.baseUrl,
      initialized: this.initialized,
      provider: 'openai_compatible',
    };
  }

  async shutdown(): Promise<void> {
    this.initialized = false;
    Logger.info('🔌 OpenAI 兼容模型已关闭', 'OpenAICompatibleModel');
  }

  getName(): string {
    return this.config.modelName;
  }

  /**
   * 构建 OpenAI 格式的消息列表
   */
  private buildMessages(input: ModelInput, images?: string[]): ChatMessage[] {
    const messages: ChatMessage[] = [];

    if (input.systemPrompt) {
      messages.push({
        role: 'system',
        content: input.systemPrompt,
      });
    }

    const userContent: MultimodalMessageContent[] = [];

    if (images && images.length > 0) {
      for (const image of images) {
        userContent.push({
          type: 'image_url',
          image_url: {
            url:
              image.startsWith('data:') || image.startsWith('http')
                ? image
                : `data:image/jpeg;base64,${image}`,
          },
        });
      }
    }

    userContent.push({
      type: 'text',
      text: input.prompt,
    });

    messages.push({
      role: 'user',
      content: userContent,
    });

    return messages;
  }

  /**
   * 带超时的 fetch 请求
   */
  private async fetchWithTimeout(
    url: string,
    options: RequestInit = {}
  ): Promise<Response> {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), this.config.timeout);

    try {
      const response = await fetch(url, {
        ...options,
        signal: controller.signal,
      } as RequestInit);
      return response;
    } finally {
      clearTimeout(timeoutId);
    }
  }
}

