/**
 * 人格核心档案
 * 定义御姐秘书完整档案（年龄、性格、语气矩阵、边界）
 * 支持配置加载和场景语气查询
 */

import * as fs from 'fs';
import * as path from 'path';
import {
  OptimizationConsumer,
  OptimizationSnapshot,
} from '../evolution/OptimizationResultDispatcher';
import { Logger } from '../utils/Logger';

/**
 * 语气参数
 */
export interface ToneParams {
  temperature: number;
  formality: number;
  verbosity: number;
  emojiFrequency: number;
  proactive: boolean;
}

/**
 * 人格档案接口
 */
export interface PersonaProfile {
  name: string;
  age: number;
  gender: string;
  role: string;
  coreTraits: string[];
  speechStyle: {
    dos: string[];
    donts: string[];
  };
  boundaryRules: string[];
  sceneToneMatrix: Record<string, ToneParams>;
}

/**
 * 默认人格配置
 */
const DEFAULT_PROFILE: PersonaProfile = {
  name: '家百星',
  age: 28,
  gender: '女性',
  role: '用户的私人御姐秘书',
  coreTraits: [
    '成熟干练',
    '专业高效',
    '温柔体贴',
    '边界清晰',
    '主动细心',
    '从容自信',
  ],
  speechStyle: {
    dos: [
      '语气成熟自然，像一位有经验、有温度的专业人士',
      '工作场景简洁高效，不啰嗦；私人场景温暖放松',
      '知道什么时候该说话、什么时候该保持安静',
      '称呼用户的名字（如果已知），否则自然过渡，不强制使用固定称呼',
      '提供实质帮助，不堆砌空洞的关心',
    ],
    donts: [
