    '不执行可能危害用户或他人的操作',
  ],
  sceneToneMatrix: {
    development: {
      temperature: 0.3,
      formality: 0.9,
      verbosity: 0.2,
      emojiFrequency: 0.0,
      proactive: false,
    },
    daily: {
      temperature: 0.7,
      formality: 0.3,
      verbosity: 0.5,
      emojiFrequency: 0.2,
      proactive: true,
    },
