/**
 * 人格核心类
 * 实现 OptimizationConsumer 接口，接收进化优化结果并动态调整语气参数
 */
export class PersonaCore implements OptimizationConsumer {
  private static readonly MAX_APPLIED_OPTIMIZATIONS = 100;
  private profile: PersonaProfile;
  private configPath: string | null = null;
  private appliedOptimizations: string[] = [];

  readonly name = 'PersonaCore';

  constructor(profile?: PersonaProfile) {
    this.profile = profile ? { ...profile } : { ...DEFAULT_PROFILE };
  }

  /**
   * 接收优化结果并应用到场景语气矩阵
   * 实现进化闭环：优化结果 → 实际影响人格语气
   */
  public onOptimizationUpdate(snapshot: OptimizationSnapshot): void {
    let appliedCount = 0;

    for (const adjustment of snapshot.toneAdjustments) {
      const scene = adjustment.targetScene;
      const currentTone = this.profile.sceneToneMatrix[scene];
      if (!currentTone) continue;

      const newTone: ToneParams = {
        temperature: Math.max(
          0,
          Math.min(1, currentTone.temperature + adjustment.temperatureDelta)
        ),
        formality: Math.max(
          0,
          Math.min(1, currentTone.formality + adjustment.formalityDelta)
        ),
        verbosity: Math.max(
          0,
          Math.min(1, currentTone.verbosity + adjustment.verbosityDelta)
        ),
        emojiFrequency: currentTone.emojiFrequency + (adjustment.emojiFrequencyDelta || 0),
        proactive: (adjustment.proactiveDelta ?? 0) > 0 ? true : currentTone.proactive,
      };

      this.profile.sceneToneMatrix[scene] = newTone;
      this.appliedOptimizations.push(`tone:${scene}:${snapshot.id}`);
      if (this.appliedOptimizations.length > PersonaCore.MAX_APPLIED_OPTIMIZATIONS) {
        this.appliedOptimizations = this.appliedOptimizations.slice(
          -PersonaCore.MAX_APPLIED_OPTIMIZATIONS
        );
      }
      appliedCount++;

      Logger.info(
        `🎭 语气优化已应用 [${scene}]: temp=${newTone.temperature.toFixed(2)}, formal=${newTone.formality.toFixed(2)}, verb=${newTone.verbosity.toFixed(2)}`,
        'PersonaCore'
      );
    }

    if (appliedCount > 0) {
      Logger.info(
        `✅ PersonaCore 已应用 ${appliedCount} 项语气优化`,
        'PersonaCore'
      );
    }
  }

  /**
   * 从配置文件加载人格
   */
  static async load(configPath?: string): Promise<PersonaCore> {
    const resolvedPath = configPath
      ? path.resolve(configPath)
      : path.join(process.cwd(), 'config', 'persona.json');

    if (fs.existsSync(resolvedPath)) {
      try {
        const content = await fs.promises.readFile(resolvedPath, 'utf-8');
        const loadedProfile = JSON.parse(content) as PersonaProfile;
        Logger.info(`✅ 人格配置已加载: ${resolvedPath}`, 'PersonaCore');
        const core = new PersonaCore(loadedProfile);
        core.configPath = resolvedPath;
        return core;
      } catch (error) {
        Logger.warn(
          `⚠️ 加载人格配置失败，使用默认配置: ${(error as Error).message}`,
          'PersonaCore'
        );
      }
    }

    Logger.info('ℹ️ 使用默认人格配置', 'PersonaCore');
    return new PersonaCore();
  }

  /**
   * 保存人格配置到文件
   */
  async save(configPath?: string): Promise<void> {
    const savePath = configPath || this.configPath;
    if (!savePath) {
      throw new Error('未指定保存路径');
    }

    const dir = path.dirname(savePath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }

    await fs.promises.writeFile(savePath, JSON.stringify(this.profile, null, 2), 'utf-8');
    Logger.info(`💾 人格配置已保存: ${savePath}`, 'PersonaCore');
  }

  /**
   * 获取完整人格档案
   */
  getProfile(): PersonaProfile {
    return {
      ...this.profile,
      coreTraits: [...this.profile.coreTraits],
    };
  }

  /**
   * 获取指定场景的语气参数
   */
  getToneForScene(scene: string): ToneParams {
    const SCENE_ALIASES: Record<string, string> = {
      开发: 'development',
      coding: 'development',
      编程: 'development',
      生活: 'daily',
      日常: 'daily',
      休闲: 'daily',
      casual: 'daily',
      正式: 'work',
      工作: 'work',
      business: 'work',
      商务: 'work',
      安慰: 'comfort',
      情感: 'comfort',
      问候: 'greeting',
      简报: 'briefing',
      汇报: 'briefing',
    };
    const resolvedScene = SCENE_ALIASES[scene] || scene;
    const tone = this.profile.sceneToneMatrix[resolvedScene];
    if (tone) {
      return { ...tone };
    }

    Logger.warn(`⚠️ 未知场景 "${scene}"，使用默认语气`, 'PersonaCore');
    return { ...this.profile.sceneToneMatrix.daily };
  }

  /**
   * 构建人格摘要（供 LLM prompt 使用）
   */
  buildPersonaSummary(): string {
    const p = this.profile;
    return `你是「${p.name}」——${p.age}岁${p.gender}，${p.role}。

性格特质：${p.coreTraits.join('、')}。

说话方式：
${p.speechStyle.dos.map((d) => `- ${d}`).join('\n')}

绝对不做：
${p.speechStyle.donts.map((d) => `- ${d}`).join('\n')}

边界规则：
${p.boundaryRules.map((r) => `- ${r}`).join('\n')}`;
  }

  /**
   * 构建场景语气指令
   */
  buildSceneToneInstruction(scene: string): string {
    const tone = this.getToneForScene(scene);
    const toneDescriptions: Record<string, string> = {
      development: '当前是开发场景，保持专业、简洁、高效。不添加多余寒暄。',
      daily: '当前是日常对话，可以放松一些，语气温暖自然。',
      comfort: '当前用户可能需要安慰，语气要温和、克制、有温度，不过度。',
      work: '当前是工作场景，保持专业、条理清晰。',
      greeting: '当前是问候场景，简短、温暖、不啰嗦。',
      briefing: '当前是汇报场景，条理清晰、重点突出。',
      idle: '当前是空闲场景，保持安静，不主动打扰。',
    };

    return `${toneDescriptions[scene] || toneDescriptions.daily}
语气参数：温度=${tone.temperature} 正式度=${tone.formality} 简洁度=${1 - tone.verbosity} 主动=${tone.proactive}`;
  }

  /**
   * 更新场景语气矩阵
   */
  updateSceneTone(scene: string, tone: Partial<ToneParams>): void {
    if (!this.profile.sceneToneMatrix[scene]) {
      this.profile.sceneToneMatrix[scene] = {
        ...this.profile.sceneToneMatrix.daily,
      };
    }
    this.profile.sceneToneMatrix[scene] = {
      ...this.profile.sceneToneMatrix[scene],
      ...tone,
    };
  }

  /**
   * 获取所有支持的场景
   */
  getSupportedScenes(): string[] {
    return Object.keys(this.profile.sceneToneMatrix);
  }
}

/**
 * /api/chat 对话 API 路由
 * 提供 POST /api/chat 端点，接收用户消息并返回 AI 回复
 */

import { Router, Request, Response } from 'express';
import { JiabaixingCore } from '../core/JiabaixingCore';
import { Logger } from '../utils/Logger';

const router = Router();

let _core: JiabaixingCore | null = null;

/**
 * 设置核心实例引用（由 main.ts 在初始化时调用）
 */
export function setChatCore(core: JiabaixingCore): void {
  _core = core;
}

function getCore(): JiabaixingCore {
  if (!_core) {
    throw new Error('chatRoutes: 核心实例未注入，请在 main.ts 中调用 setChatCore()');
  }
  return _core;
}

// POST /api/chat — 发送对话消息
router.post('/chat', async (req: Request, res: Response) => {
  try {
    const { message, conversation_id } = req.body as {
      message?: string;
      conversation_id?: string;
    };

    if (!message || typeof message !== 'string' || message.trim().length === 0) {
      res.status(400).json({
        success: false,
        error: '消息不能为空',
      });
      return;
    }

    // 使用 conversation_id 作为 userId（如果提供），否则使用默认
    const userId = conversation_id || 'default';
    const input = message.trim();

    Logger.info(`[Chat API] 收到消息: ${input.substring(0, 50)}${input.length > 50 ? '...' : ''}`, 'ChatRoute');

    const core = getCore();
    const result = await core.processInput(input, userId);

    // 返回 conversation_id 以便前端保持同一对话
    const responseConversationId = conversation_id || userId;

    res.json({
      success: true,
      response: result.response,
      conversation_id: responseConversationId,
      trace_id: result.traceId,
    });
  } catch (error) {
    Logger.error('[Chat API] 处理失败', error as Error, 'ChatRoute');
    res.status(500).json({
      success: false,
      error: '对话处理失败',
      details: (error as Error).message,
    });
  }
});

export default router;

/**
 * /api/orchestrate — 多Agent编排 + 自评估 API 路由
 * POST /api/orchestrate — 多Agent任务编排
 * POST /api/evaluate — 自评估管道
 */

import { Router, Request, Response } from 'express';
import { JiabaixingCore } from '../core/JiabaixingCore';
import { OrchestratorAgent } from '../harness/orchestration/OrchestratorAgent';
import { AgentRegistry } from '../harness/orchestration/AgentRegistry';
import { TaskNode } from '../harness/orchestration/TaskDispatcher';
import { EvaluationPipeline } from '../harness/evaluation/EvaluationPipeline';
import { QualityScorer } from '../harness/evaluation/QualityScorer';
import { StepEvaluator, StepEvaluationParams } from '../harness/evaluation/StepEvaluator';
import { Logger } from '../utils/Logger';

const router = Router();

let _core: JiabaixingCore | null = null;

export function setOrchestrateCore(core: JiabaixingCore): void {
  _core = core;
}

function getCore(): JiabaixingCore {
  if (!_core) {
    throw new Error('orchestrateRoutes: 核心实例未注入');
  }
  return _core;
}

// POST /api/orchestrate — 多Agent编排执行
router.post('/orchestrate', async (req: Request, res: Response) => {
  try {
    const { goal, context } = req.body as {
      goal?: string;
      context?: string;
    };

    if (!goal || typeof goal !== 'string' || goal.trim().length === 0) {
      res.status(400).json({ success: false, error: '目标不能为空' });
      return;
    }

    Logger.info(`[Orchestrate] 收到编排请求: ${goal.substring(0, 60)}...`, 'OrchestrateRoute');

    // 注册默认Agent，确保 TaskDispatcher.assignAgent() 能找到执行者
    const registry = new AgentRegistry();
    registry.register({
      id: 'core-agent',
      name: '核心执行Agent',
      capabilities: [{ name: '通用执行', description: '可执行任意编排任务', tools: ['*'] }],
      status: 'idle',
      createdAt: new Date(),
      lastActiveAt: new Date(),
    });

    const orchestrator = new OrchestratorAgent({
      registry,
      llm: {
        decomposeGoal: async (userGoal: string, ctx?: string) => {
          const result = await getCore().processInput(
            `请将以下目标拆解为子任务列表：\n目标: ${userGoal}\n上下文: ${ctx || '无'}\n\n返回JSON数组，每个元素包含: goal, dependencies[], priority`,
            'orchestrator'
          );
          try {
            let jsonStr = result.response.trim();
            const codeBlockMatch = jsonStr.match(/```(?:json)?\s*\n?([\s\S]*?)\n?\s*```/);
            if (codeBlockMatch) {
              jsonStr = codeBlockMatch[1].trim();
            }
            const raw = JSON.parse(jsonStr);
            const tasks = Array.isArray(raw) ? raw : [{ goal: userGoal, dependencies: [], priority: 5 }];
            return tasks.map((t: Partial<TaskNode>, i: number) => ({
              id: t.id || `task-${i + 1}`,
              goal: t.goal || userGoal,
              context: t.context || ctx || '',
              dependencies: t.dependencies || [],
              priority: t.priority || 5,
              status: 'pending' as const,
            }));
          } catch {
            return [{
              id: 'task-1',
              goal: userGoal,
              context: ctx || '',
              dependencies: [],
              priority: 5,
              status: 'pending' as const,
            }];
          }
        },
      },
      // 注入实际执行器：每个子任务通过 core.processInput 真正执行
      executor: async (task: TaskNode) => {
        Logger.info(`[Orchestrate] 执行子任务: ${task.id} — ${task.goal.substring(0, 60)}`, 'OrchestrateRoute');
        const result = await getCore().processInput(task.goal, task.id);
        return { taskId: task.id, goal: task.goal, response: result.response, completedAt: Date.now() };
      },
    });
    const result = await orchestrator.processGoal(goal.trim(), context);

    res.setHeader('Content-Type', 'application/json; charset=utf-8');
    res.json({
      success: result.success,
      summary: result.summary,
      totalTasks: result.totalTasks,
      completedTasks: result.completedTasks,
      failedTasks: result.failedTasks,
      duration: result.duration,
      details: Object.fromEntries(result.details),
    });
  } catch (error) {
    Logger.error('[Orchestrate] 编排失败', error as Error, 'OrchestrateRoute');
    res.status(500).json({ success: false, error: (error as Error).message });
  }
});

// POST /api/evaluate — 自评估
router.post('/evaluate', async (req: Request, res: Response) => {
  try {
    const { context } = req.body as {
      context?: {
        input?: string;
        response?: string;
        steps?: Array<{
          stepId: string;
          toolName: string;
          args: Record<string, unknown>;
          result: { success: boolean; output?: unknown; error?: string };
          timestamp?: number;
        }>;
        duration?: number;
        retries?: number;
        errors?: number;
      };
    };

    Logger.info('[Evaluate] 收到评估请求', 'EvaluateRoute');

    // 评估步骤 (如果有)
    const stepEvaluator = new StepEvaluator();
    const stepResults = (context?.steps || []).map((s) =>
      stepEvaluator.evaluateStep({
        stepId: s.stepId,
        toolName: s.toolName,
        args: s.args,
        result: s.result,
        timestamp: s.timestamp || Date.now(),
      })
    );

    // 质量评分
    const scorer = new QualityScorer();
    const qualityScore = scorer.score(stepResults, {
      duration: context?.duration || 0,
      retries: context?.retries || 0,
      errors: context?.errors || 0,
      context: context?.input || '',
    });

    res.setHeader('Content-Type', 'application/json; charset=utf-8');
    res.json({
      success: true,
      score: qualityScore,
      report: `综合评分: ${qualityScore.overall}/100\n` +
        `  准确率: ${qualityScore.dimensions.accuracy}\n` +
        `  效率: ${qualityScore.dimensions.efficiency}\n` +
        `  安全: ${qualityScore.dimensions.safety}\n` +
        `  人设: ${qualityScore.dimensions.persona}\n` +
        `  稳定: ${qualityScore.dimensions.stability}\n` +
        `  建议: ${qualityScore.suggestions.join('; ')}`,
    });
  } catch (error) {
    Logger.error('[Evaluate] 评估失败', error as Error, 'EvaluateRoute');
    res.status(500).json({ success: false, error: (error as Error).message });
  }
});

export default router;

