import * as WebSocket from 'ws';

import { JiabaixingCore } from '../core/JiabaixingCore';
import { EVENTBUS_TO_WS_MAP } from '../shared/contracts';
import { EventBus } from '../shared/EventBus';
import { Logger } from '../utils/Logger';

type WSServer = WebSocket.Server;
type BroadcastFn = (data: Record<string, unknown>) => void;

export function setupEventBus(
  wss: WSServer | null,
  core: JiabaixingCore | null
): BroadcastFn {
  const broadcast: BroadcastFn = (data: Record<string, unknown>): void => {
    if (!wss) return;
    const message = JSON.stringify(data);
    wss.clients.forEach((client) => {
      if ((client as WebSocket.WebSocket).readyState === 1) {
        (client as WebSocket.WebSocket).send(message);
      }
    });
  };

  const registeredEvents = new Set<string>();

  const registerOnce = (
    event: string,
    handler: (...args: unknown[]) => void
  ) => {
    if (registeredEvents.has(event)) return;
    registeredEvents.add(event);
    EventBus.on(event as any, handler as any);
  };

  registerOnce('weight_update', (data: unknown) => {
    const payload = data as { weights?: Record<string, number> };
    broadcast({
      type: 'weight_update',
      data: { weights: payload.weights || {} },
    });
  });

  registerOnce('agent_execution_update', (data: unknown) => {
    const payload = data as {
      traceId?: string;
      phase?: string;
      status?: string;
      result?: unknown;
      timestamp?: string;
    };
    broadcast({
      type: 'agent_execution_update',
      data: {
        traceId: payload.traceId || 'unknown',
        phase: payload.phase || 'unknown',
        status: payload.status || 'unknown',
        result: payload.result,
        timestamp: payload.timestamp || new Date().toISOString(),
      },
    });
  });

  registerOnce('proactive_interaction', async (data: unknown) => {
    const payload = data as {
      reason: string;
      context?: string;
      scene?: string;
      isEmotionBased?: boolean;
      priority?: string;
    };

    Logger.info(
      `🔔 收到主动交互信号: 原因=${payload.reason}, 场景=${payload.scene}, 优先级=${payload.priority}`,
      'Main'
    );

    try {
      if (!core) {
        Logger.warn('核心系统未初始化，无法生成主动消息', 'Main');
        return;
      }

      const message = await core.generateProactiveMessage({
        reason: payload.reason || 'scheduled',
        context: payload.context || '',
        scene: payload.scene || '休闲',
        isEmotionBased: payload.isEmotionBased || false,
      });

      if (message) {
        broadcast({
          type: 'proactive_message',
          data: {
            message,
            reason: payload.reason,
            scene: payload.scene,
            timestamp: Date.now(),
          },
        });
        Logger.info(
          `📤 主动消息已推送: "${message.substring(0, 50)}..."`,
          'Main'
        );
      }
    } catch (error) {
      Logger.warn(`⚠️ 生成主动消息失败: ${(error as Error).message}`, 'Main');
    }
  });

  registerOnce('weight_changed', (data: unknown) => {
    const payload = data as {
      toolId?: string;
      oldWeight?: number;
      newWeight?: number;
      reason?: string;
      timestamp?: number;
    };
    broadcast({
      type: 'weight_update',
      data: {
        toolId: payload.toolId || '',
        oldWeight: payload.oldWeight,
        newWeight: payload.newWeight,
        reason: payload.reason || '',
        timestamp: payload.timestamp || Date.now(),
        updateType: 'single',
      },
    });
  });

  registerOnce('user_correction', (data: unknown) => {
    broadcast({ type: 'user_correction', data });
  });

  registerOnce('perception_update', (data: unknown) => {
    const payload = data as {
      traceId?: string;
      modality?: string;
      status?: string;
      progress?: number;
      result?: unknown;
      confidence?: number;
      error?: string;
      timestamp?: string;
    };
    broadcast({
      type: 'perception_update',
      data: {
        traceId: payload.traceId || 'unknown',
        modality: payload.modality || 'text',
        status: payload.status || 'unknown',
        progress: payload.progress,
        result: payload.result,
        confidence: payload.confidence,
        error: payload.error,
        timestamp: payload.timestamp || new Date().toISOString(),
      },
    });
  });

  registerOnce('brain_stage_update', (data: unknown) => {
    const payload = data as {
      traceId?: string;
      stage?: string;
      status?: string;
      duration?: number;
      result?: unknown;
      timestamp?: string;
    };
    broadcast({
      type: 'brain_stage_update',
      data: {
        traceId: payload.traceId || 'unknown',
        stage: payload.stage || 'unknown',
        status: payload.status || 'unknown',
        duration: payload.duration,
        result: payload.result,
        timestamp: payload.timestamp || new Date().toISOString(),
      },
    });
  });

  registerOnce('skill_execution_update', (data: unknown) => {
    const payload = data as {
      traceId?: string;
      skillName?: string;
      step?: string;
      attempt?: number;
      maxRetries?: number;
      duration?: number;
      error?: string;
      timestamp?: string;
    };
    broadcast({
      type: 'skill_execution_update',
      data: {
        traceId: payload.traceId || 'unknown',
        skillName: payload.skillName || 'unknown',
        step: payload.step || 'started',
        attempt: payload.attempt,
        maxRetries: payload.maxRetries,
        duration: payload.duration,
        error: payload.error,
        timestamp: payload.timestamp || new Date().toISOString(),
      },
    });
  });

  registerOnce('evolution_event', (data: unknown) => {
    const payload = data as {
      type?: string;
      traceId?: string;
      score?: number;
      description?: string;
      metrics?: Record<string, number>;
      timestamp?: string;
    };
    broadcast({
      type: 'evolution_event',
      data: {
        type: payload.type || 'quality_assessed',
        traceId: payload.traceId,
        score: payload.score,
        description: payload.description || '',
        metrics: payload.metrics,
        timestamp: payload.timestamp || new Date().toISOString(),
      },
    });
  });

  registerOnce('clarification_request', (data: unknown) => {
    const payload = data as {
      traceId?: string;
      question?: string;
      options?: string[];
      context?: string;
      timestamp?: string;
    };
    broadcast({
      type: 'clarification_request',
      data: {
        traceId: payload.traceId || 'unknown',
        question: payload.question || '',
        options: payload.options || [],
        context: payload.context || '',
        timestamp: payload.timestamp || new Date().toISOString(),
      },
    });
  });

  registerOnce('execution_preview', (data: unknown) => {
    const payload = data as {
      traceId?: string;
      summary?: string;
      changes?: unknown[];
      estimatedTime?: number;
      timestamp?: string;
    };
    broadcast({
      type: 'execution_preview',
      data: {
        traceId: payload.traceId || 'unknown',
        summary: payload.summary || '',
        changes: payload.changes || [],
        estimatedTime: payload.estimatedTime,
        timestamp: payload.timestamp || new Date().toISOString(),
      },
    });
  });

  registerOnce('file_modified', (data: unknown) => {
    const payload = data as {
      traceId?: string;
      filePath?: string;
      changeType?: string;
      edits?: unknown[];
      timestamp?: string;
    };
    broadcast({
      type: 'file_modified',
      data: {
        traceId: payload.traceId || 'unknown',
        filePath: payload.filePath || '',
        changeType: payload.changeType || 'modified',
        edits: payload.edits,
        timestamp: payload.timestamp || new Date().toISOString(),
      },
    });
  });

  registerOnce('file_rollback', (data: unknown) => {
    const payload = data as {
      traceId?: string;
      filePath?: string;
      success?: boolean;
      timestamp?: string;
    };
    broadcast({
      type: 'file_rollback',
      data: {
        traceId: payload.traceId || 'unknown',
        filePath: payload.filePath || '',
        success: payload.success ?? true,
        timestamp: payload.timestamp || new Date().toISOString(),
      },
    });
  });

  registerOnce('multi_file_modified', (data: unknown) => {
    const payload = data as {
      traceId?: string;
      files?: Array<{ path: string; changeType: string }>;
      timestamp?: string;
    };
    broadcast({
      type: 'multi_file_modified',
      data: {
        traceId: payload.traceId || 'unknown',
        files: payload.files || [],
        timestamp: payload.timestamp || new Date().toISOString(),
      },
    });
  });

  registerOnce('tool_trace', (data: unknown) => {
    const payload = data as {
      timestamp?: string;
      traceId?: string;
      toolCallId?: string;
      toolName?: string;
      status?: string;
      duration?: number;
      success?: boolean | null;
      errorMessage?: string | null;
    };
    broadcast({
      type: 'tool_trace',
      data: {
        timestamp: payload.timestamp || new Date().toISOString(),
        traceId: payload.traceId || 'unknown',
        toolCallId: payload.toolCallId || '',
        toolName: payload.toolName || '',
        status: payload.status || 'started',
        duration: payload.duration || 0,
        success: payload.success ?? null,
        errorMessage: payload.errorMessage ?? null,
      },
    });
  });

  registerOnce('response_ready', (data: unknown) => {
    const payload = data as {
      response?: string;
      traceId?: string;
      success?: boolean;
    };
    Logger.info(
      `📡 EventBus广播 response_ready: traceId=${payload.traceId}, success=${payload.success}, 响应长度=${payload.response?.length || 0}`,
      'EventBus'
    );
    broadcast({
      type: 'response_ready',
      data: {
        response: payload.response || '',
        traceId: payload.traceId || '',
      },
    });
  });

  Logger.on('log', (entry) => {
    broadcast({
      type: 'server_log',
      data: entry,
    });
  });

  Logger.info(
    `✅ EventBus 监听器已注册（防重复机制已启用，共 ${registeredEvents.size} 个事件）`,
    'EventBus'
  );

  return broadcast;
}

import { EvolutionOrchestrator } from '../../evolution/EvolutionOrchestrator';
import { EvolutionEngine } from '../../evolution/EvolutionEngine';
import { EvaluationPipeline } from '../../harness/evaluation/EvaluationPipeline';
import { OptimizationFeedbackLoop } from '../../harness/evaluation/OptimizationFeedbackLoop';
import { TRAEOptimizationIntegrator } from '../../integration/TRAEOptimizationIntegrator';
import type { MemoryEngine } from '../../memory/MemoryEngine';
import type { JiabaixingCore } from '../../core/JiabaixingCore';
import { Logger } from '../../utils/Logger';

export interface EvolutionInitResult {}

export async function initEvolution(
  core: JiabaixingCore,
  memoryEngine: MemoryEngine
): Promise<EvolutionInitResult> {
  const { OptimizationResultDispatcher } =
    await import('../../evolution/OptimizationResultDispatcher');
  const dispatcher = OptimizationResultDispatcher.getInstance();

  const ENABLE_AUTO_OPTIMIZE = process.env.ENABLE_AUTO_OPTIMIZE !== 'false';
  let optimizationFeedbackLoop: OptimizationFeedbackLoop | null = null;

  if (ENABLE_AUTO_OPTIMIZE) {
    const evolutionEngine = new EvolutionEngine(memoryEngine);
    evolutionEngine.start();

    core.setEvolutionEngine(evolutionEngine);

    const orchestrator = EvolutionOrchestrator.getInstance();
    orchestrator.registerEngines({
      evolutionEngine,
      llmProvider: core?.getLLM(),
    });
    orchestrator.start();

    const evaluationPipeline = new EvaluationPipeline();
    optimizationFeedbackLoop = new OptimizationFeedbackLoop(
      evaluationPipeline,
      orchestrator,
      { threshold: 60, maxConsecutiveOptimizations: 3, cooldownMs: 60 * 1000, forceOptimization: false }
    );

    const OPTIMIZATION_INTERVAL_MS = 5 * 60 * 1000;
    setInterval(() => {
      if (optimizationFeedbackLoop) {
        const metrics = orchestrator.getUnifiedMetrics();
        const recentScores = metrics.quality.recentScores;
        const avgScore = recentScores.length > 0
          ? recentScores.reduce((a, b) => a + b, 0) / recentScores.length
          : 0;

        if (metrics.summary.totalInteractions > 0 && avgScore < 0.6) {
          Logger.info(
            `🔄 定时优化检查触发 | 平均质量=${(avgScore * 100).toFixed(1)} | 交互次数=${metrics.summary.totalInteractions}`,
            'Bootstrap'
          );

          void optimizationFeedbackLoop.evaluateAndOptimize({
            stepParams: [],
            evalInput: {
              userInput: '定时优化检查',
              conversationHistory: [],
              currentOutput: `平均质量评分: ${(avgScore * 100).toFixed(1)}`,
            },
            scorerMetadata: {
              duration: metrics.performance.averageResponseTime,
              retries: 0,
              errors: Math.floor(metrics.quality.failureRate * metrics.summary.totalInteractions),
              context: '定时优化检查',
            },
          });
        }
      }
    }, OPTIMIZATION_INTERVAL_MS);

    Logger.info(
      '✅ 优化反馈闭环已启动（每5分钟检查一次，阈值=60）',
      'Bootstrap'
    );

    dispatcher.registerConsumer(core.getPersonaCore());
    Logger.info(
      '✅ PersonaCore 已注册为优化消费者（语气调整闭环已连通）',
      'Bootstrap'
    );

    const toolWeightConsumer: import('../../evolution/OptimizationResultDispatcher').OptimizationConsumer = {
      name: 'ToolWeightBridge',
      onOptimizationUpdate(snapshot: import('../../evolution/OptimizationResultDispatcher').OptimizationSnapshot): void {
        const weights = snapshot.skillWeights;
        if (Object.keys(weights).length === 0) return;
        const harness = core.getHarness();
        if (harness) {
          const registry = harness.getToolRegistry();
          const tracker = registry?.getReliabilityTracker();
          if (tracker) {
            tracker.applyEvolutionWeights(weights);
            if (registry) {
              registry.invalidateCache();
            }
            Logger.info(
              `🔧 进化闭环: 技能权重已应用并刷新工具列表 [${Object.entries(weights).map(([k, v]) => `${k}=${v.toFixed(2)}`).join(', ')}]`,
              'Bootstrap'
            );
          }
        }
      },
    };
    dispatcher.registerConsumer(toolWeightConsumer);
  }

  try {
    const traeOptimizationIntegrator = TRAEOptimizationIntegrator.getInstance();
    await traeOptimizationIntegrator.initialize();
    core.setTRAEOptimizationIntegrator(traeOptimizationIntegrator);
  } catch (error) {
    Logger.warn(
      `TRAE 优化系统初始化跳过（非必需）: ${(error as Error).message}`,
      'Bootstrap'
    );
  }

  return {};
}

import { EventBus } from '../../shared/EventBus';
import type { AgentHarness } from '../../harness/AgentHarness';
import type { JiabaixingCore } from '../../core/JiabaixingCore';
import { Logger } from '../../utils/Logger';

export interface GatewayInitResult {}

export async function initGateway(
  core: JiabaixingCore,
  harness: AgentHarness | null
): Promise<GatewayInitResult> {
  const { GatewayBridge } = await import('../../integration/GatewayBridge');
  const gatewayBridge = GatewayBridge.getInstance();

  gatewayBridge.setIncomingMessageHandler(async (message) => {
    Logger.info(`收到平台消息: ${message.platform}`, 'Bootstrap');

    if (harness) {
      const result = await harness.processInput({
        text: message.content,
        userId: message.from,
      });

      if (result.response && message.from && message.platform) {
        await gatewayBridge.sendMessage({
          platform: message.platform,
          message: result.response,
          to: message.from,
        });
      }
    }
  });

  try {
    await gatewayBridge.start();
    console.log('✅ (隔离进程模式)');
    Logger.info('网关启动成功: 隔离进程模式', 'Bootstrap');
  } catch (err) {
    Logger.warn(
      `网关隔离进程启动失败: ${(err as Error).message}，回退到内联模式`,
      'Bootstrap'
    );
    const { IntegrationManager } = await import(
      '../../integration/IntegrationManager'
    );
    const integrationManager = IntegrationManager.getInstance();
    integrationManager.setCore(core);
    console.log('✅ (内联模式)');
    Logger.info('网关启动成功: 内联模式', 'Bootstrap');
  }

  EventBus.on('integration_message', async (data: unknown) => {
    try {
      const payload = data as {
        content: string;
        from?: string;
        platform?: string;
      };
      Logger.info(`收到平台消息: ${payload.platform}`, 'Bootstrap');

      if (harness) {
        const result = await harness.processInput({
          text: payload.content,
          userId: payload.from,
        });

        if (result.response && payload.from && payload.platform) {
          if (gatewayBridge.isWorkerAlive()) {
            await gatewayBridge.sendMessage({
              platform: payload.platform as any,
              message: result.response,
              to: payload.from,
            });
          } else {
            const { IntegrationManager } = await import('../../integration/IntegrationManager');
            const im = IntegrationManager.getInstance();
            await im.sendMessage({
              platform: payload.platform as any,
              message: result.response,
              to: payload.from,
            });
          }
        }
      }
    } catch (error) {
      Logger.error('处理集成消息失败', error as Error, 'Bootstrap');
    }
  });

  return {};
}

