/**
 * 调试路由 - debug weights / recentHistory / simulate_task
 */

import express, { Request, Response } from 'express';

import { JiabaixingCore } from '../../core/JiabaixingCore';
import { EventBus } from '../../shared/EventBus';
import { Logger } from '../../utils/Logger';

type BroadcastFn = (data: Record<string, unknown>) => void;

export function registerDebugRoutes(
  app: express.Application,
  core: JiabaixingCore | null,
  broadcast: BroadcastFn
): void {
  app.get('/api/debug/weights', (_req, res) => {
    try {
      if (!core) {
        res.status(503).json({ success: false, error: '核心系统未初始化' });
        return;
      }

      const snapshot: Array<{ toolName: string; weight: number }> = [];
      const weights: Record<string, number> = {};
      res.json({ weights, snapshot, timestamp: new Date().toISOString() });
    } catch {
      res.json({ error: '无法获取权重信息' });
    }
  });

  app.get('/api/debug/recentHistory', (_req, res) => {
    try {
      if (!core) {
        res.status(503).json({ success: false, error: '核心系统未初始化' });
        return;
      }

      const history: Array<Record<string, unknown>> = [];
      res.json({ history, timestamp: new Date().toISOString() });
    } catch {
      res.json({ history: [], timestamp: new Date().toISOString() });
    }
  });

  app.get('/api/debug/tool-usage', (_req, res) => {
    try {
      if (!core) {
        res.status(503).json({ success: false, error: '核心系统未初始化' });
        return;
      }

      const toolExecutor = (core as unknown as { toolExecutor?: { getExecutionStats?: () => unknown; getToolCallLogs?: () => unknown; getTools?: () => unknown } }).toolExecutor;

      if (!toolExecutor) {
        res.json({ success: false, error: '工具执行器未初始化' });
        return;
      }

      const stats = toolExecutor.getExecutionStats ? toolExecutor.getExecutionStats() : {};
      const logs = toolExecutor.getToolCallLogs ? toolExecutor.getToolCallLogs() : [];
      const tools = toolExecutor.getTools ? toolExecutor.getTools() : [];

      res.json({
        success: true,
        data: {
          totalTools: Array.isArray(tools) ? tools.length : 0,
          tools: Array.isArray(tools) ? tools.map((t: { name: string; description: string }) => ({
            name: t.name,
            description: t.description,
          })) : [],
          stats: stats instanceof Map
            ? Object.fromEntries(stats)
            : stats,
          recentLogs: Array.isArray(logs) ? logs.slice(-20) : [],
          totalLogs: Array.isArray(logs) ? logs.length : 0,
        },
        timestamp: new Date().toISOString(),
      });
    } catch (error) {
      res.json({ success: false, error: (error as Error).message });
    }
  });

  app.post('/api/simulate_task', express.json({ limit: '1mb' }), (req, res) => {
    try {
      const { taskId = 'sim_task', prompt = '' } = req.body || {};
      const traceId = Logger.generateTraceId();

      const emitPhase = (phase: string, status: string, result?: unknown) => {
        const payload = {
          traceId,
          phase,
          status,
          result,
          timestamp: new Date().toISOString(),
          taskId,
        };
        try {
          void EventBus.emit('agent_execution_update', payload);
        } catch {
          broadcast({ type: 'agent_execution_update', data: payload });
        }
      };

      emitPhase('perceive', 'in-progress');
      setTimeout(() => emitPhase('perceive', 'completed'), 200);
      setTimeout(() => emitPhase('plan', 'in-progress'), 400);
      setTimeout(() => emitPhase('plan', 'completed'), 800);
      setTimeout(() => emitPhase('execute', 'in-progress'), 900);
      setTimeout(
        () => emitPhase('execute', 'completed', { message: '执行完成' }),
        1800
      );
      setTimeout(() => emitPhase('verify', 'in-progress'), 1850);
      setTimeout(() => emitPhase('verify', 'completed', { ok: true }), 2100);
      setTimeout(() => emitPhase('output', 'in-progress'), 2150);
      setTimeout(
        () =>
          emitPhase('output', 'completed', {
            response: `模拟结果：${String(prompt).substring(0, 200)}`,
          }),
        2600
      );
      setTimeout(() => emitPhase('learn', 'in-progress'), 2650);
      setTimeout(() => emitPhase('learn', 'completed'), 3000);

      res.json({ success: true, message: '模拟任务已触发', traceId, taskId });
    } catch (error) {
      Logger.error('❌ /api/simulate_task 触发失败', error as Error, 'Main');
      res.status(500).json({ success: false, error: (error as Error).message });
    }
  });
}

/**
 * 进化引擎路由 - evolution metrics / insights / trigger / orchestrator
 */

import express from 'express';

import { JiabaixingCore } from '../../core/JiabaixingCore';
import { EvolutionOrchestrator } from '../../evolution/EvolutionOrchestrator';

export function registerEvolutionRoutes(
  app: express.Application,
  core: JiabaixingCore | null
): void {
  app.get('/api/evolution/metrics', (_req, res) => {
    try {
      const evolutionEngine = (core as unknown as Record<string, unknown>)
        .evolutionEngine as
        | import('../../evolution/EvolutionEngine').EvolutionEngine
        | undefined;
      if (!evolutionEngine) {
        return res
          .status(503)
          .json({ success: false, error: '进化引擎未启动' });
      }
      const metrics = evolutionEngine.getMetrics();
      res.json({ success: true, data: metrics });
    } catch (error) {
      res.status(500).json({ success: false, error: (error as Error).message });
    }
  });

  app.get('/api/evolution/insights', (_req, res) => {
    try {
      const evolutionEngine = (core as unknown as Record<string, unknown>)
        .evolutionEngine as
        | import('../../evolution/EvolutionEngine').EvolutionEngine
        | undefined;
      if (!evolutionEngine) {
        return res
          .status(503)
          .json({ success: false, error: '进化引擎未启动' });
      }
      const insights = evolutionEngine.getInsights();
      res.json({ success: true, data: insights });
    } catch (error) {
      res.status(500).json({ success: false, error: (error as Error).message });
    }
  });

  app.post(
    '/api/evolution/trigger',
    express.json({ limit: '1mb' }),
    async (req, res) => {
      try {
        const evolutionEngine = (core as unknown as Record<string, unknown>)
          .evolutionEngine as
          | import('../../evolution/EvolutionEngine').EvolutionEngine
          | undefined;
        if (!evolutionEngine) {
          return res
            .status(503)
            .json({ success: false, error: '进化引擎未启动' });
        }
        const reason = (req.body as { reason?: string }).reason || '手动触发';
        const log = await evolutionEngine.triggerManualOptimization(reason);
        res.json({ success: true, data: { id: log.id, reason: log.reason } });
      } catch (error) {
        res
          .status(500)
          .json({ success: false, error: (error as Error).message });
      }
    }
  );

  // v3.4: 统一进化编排器 API
  app.get('/api/orchestrator/metrics', (_req, res) => {
    try {
      const orchestrator = EvolutionOrchestrator.getInstance();
      const metrics = orchestrator.getUnifiedMetrics();
      res.json({ success: true, data: metrics });
    } catch (error) {
      res.status(500).json({ success: false, error: (error as Error).message });
    }
  });

  app.post(
    '/api/orchestrator/optimize',
    express.json({ limit: '1mb' }),
    async (req, res) => {
      try {
        const orchestrator = EvolutionOrchestrator.getInstance();
        const reason = (req.body as { reason?: string }).reason || '手动触发';
        const cycle = await orchestrator.triggerOptimizationCycle(reason, true);
        res.json({ success: true, data: { cycleId: cycle?.cycleId, reason } });
      } catch (error) {
        res
          .status(500)
          .json({ success: false, error: (error as Error).message });
      }
    }
  );

  app.post(
    '/api/evolution/cycle',
    express.json({ limit: '1mb' }),
    async (req, res) => {
      try {
        const orchestrator = EvolutionOrchestrator.getInstance();
        const reason = (req.body as { reason?: string }).reason || '手动触发完整进化周期';
        await orchestrator.triggerOptimizationCycle(reason, true);

        res.json({
          success: true,
          message: '进化周期已触发',
          duration: '0ms',
          summary: {
            healingCount: 0,
            refactorSuccess: true,
            enhancementCount: 0,
          },
          timestamp: new Date().toISOString(),
        });
      } catch (error) {
        res
          .status(500)
          .json({ success: false, error: (error as Error).message });
      }
    }
  );

  app.post(
    '/api/evolution/healing',
    express.json({ limit: '1mb' }),
    async (req, res) => {
      try {
        const evolutionEngine = (core as unknown as Record<string, unknown>)
          .evolutionEngine as
          | import('../../evolution/EvolutionEngine').EvolutionEngine
          | undefined;

        if (!evolutionEngine) {
          return res
            .status(503)
            .json({ success: false, error: '进化引擎未启动' });
        }

        const results: unknown[] = [];

        res.json({
          success: true,
          message: '自愈操作已执行',
          results,
          timestamp: new Date().toISOString(),
        });
      } catch (error) {
        res
          .status(500)
          .json({ success: false, error: (error as Error).message });
      }
    }
  );

  app.post(
    '/api/evolution/refactor',
    express.json({ limit: '1mb' }),
    async (req, res) => {
      try {
        const evolutionEngine = (core as unknown as Record<string, unknown>)
          .evolutionEngine as
          | import('../../evolution/EvolutionEngine').EvolutionEngine
          | undefined;

        if (!evolutionEngine) {
          return res
            .status(503)
            .json({ success: false, error: '进化引擎未启动' });
        }

        const _reason = (req.body as { reason?: string }).reason || '手动触发重构';
        void _reason;

        res.json({
          success: true,
          message: '重构操作已执行',
          result: null,
          timestamp: new Date().toISOString(),
        });
      } catch (error) {
        res
          .status(500)
          .json({ success: false, error: (error as Error).message });
      }
    }
  );

  app.post(
    '/api/evolution/enhance',
    express.json({ limit: '1mb' }),
    async (req, res) => {
      try {
        const evolutionEngine = (core as unknown as Record<string, unknown>)
          .evolutionEngine as
          | import('../../evolution/EvolutionEngine').EvolutionEngine
          | undefined;

        if (!evolutionEngine) {
          return res
            .status(503)
            .json({ success: false, error: '进化引擎未启动' });
        }

        const _reason = (req.body as { reason?: string }).reason || '手动触发增强';
        void _reason;
        const opportunities: unknown[] = [];

        res.json({
          success: true,
          message: '增强操作已执行',
          opportunities,
          timestamp: new Date().toISOString(),
        });
      } catch (error) {
        res
          .status(500)
          .json({ success: false, error: (error as Error).message });
      }
    }
  );
}

import express, { Request, Response } from 'express';
import { Logger } from '../../utils/Logger';
import {
  IntegrationPlatform,
  ConnectRequest,
  SendMessageRequest,
  ApiResponse,
  IntegrationStatusResponse,
  PlatformConnectResponse,
  PlatformDisconnectResponse,
  SendMessageResponse,
} from '../../shared/contracts';
import { IntegrationManager } from '../../integration/IntegrationManager';
import { GatewayBridge } from '../../integration/GatewayBridge';

const router = express.Router();

function getGateway(): IntegrationManager | GatewayBridge {
  const bridge = GatewayBridge.getInstance();
  if (bridge.isWorkerAlive()) {
    return bridge;
  }
  return IntegrationManager.getInstance();
}

function isBridge(gateway: IntegrationManager | GatewayBridge): gateway is GatewayBridge {
  return gateway instanceof GatewayBridge;
}

router.get('/wechat/qrcode', async (_req: Request, res: Response) => {
  try {
    const gateway = getGateway();
    const qrState = isBridge(gateway)
      ? gateway.getWeChatQRState()
      : gateway.getWeChatQRState();

    if (!qrState) {
      res.json({
        success: false,
        error: '未开启微信扫码模式，请先连接 (mode: qr)',
      });
      return;
    }
    res.json({
      success: true,
      data: qrState,
    });
  } catch (error) {
    Logger.error('获取微信二维码失败', error as Error, 'IntegrationRoutes');
    res.status(500).json({
      success: false,
      error: '获取微信二维码失败',
    });
  }
});

router.get('/platforms', async (_req: Request, res: Response) => {
  try {
    const gateway = getGateway();
    const platforms = isBridge(gateway)
      ? gateway.getPlatforms()
      : gateway.getPlatforms();

    const response: ApiResponse<IntegrationStatusResponse> = {
      success: true,
      data: { platforms },
    };
    res.json(response);
  } catch (error) {
    Logger.error('获取集成平台失败', error as Error, 'IntegrationRoutes');
    res.status(500).json({
      success: false,
      error: '获取集成平台信息失败',
      message: (error as Error).message,
    });
  }
});

router.get('/:platform/status', async (req: Request, res: Response) => {
  try {
    const platform = req.params.platform as IntegrationPlatform;
    const gateway = getGateway();
    const status = isBridge(gateway)
      ? gateway.getPlatformStatus(platform)
      : gateway.getPlatformStatus(platform);

    res.json({
      success: true,
      data: status,
    });
  } catch (error) {
    Logger.error('获取平台状态失败', error as Error, 'IntegrationRoutes');
    res.status(500).json({
      success: false,
      error: '获取平台状态失败',
    });
  }
});

router.post('/:platform/connect', async (req: Request, res: Response) => {
  try {
    const platform = req.params.platform as IntegrationPlatform;
    const requestBody = req.body as ConnectRequest;

    const gateway = getGateway();
    const success = isBridge(gateway)
      ? await gateway.connectPlatform(platform, requestBody.config)
      : await gateway.connectPlatform(platform, requestBody.config);

    const response: ApiResponse<PlatformConnectResponse> = {
      success,
      data: {
        success,
        platform,
        status: success ? 'connected' : 'failed',
      },
    };

    if (!success) {
      response.error = '连接失败';
    }

    res.status(success ? 200 : 400).json(response);
  } catch (error) {
    Logger.error('连接平台失败', error as Error, 'IntegrationRoutes');
    res.status(500).json({
      success: false,
      error: '连接平台失败',
      message: (error as Error).message,
    });
  }
});

router.post('/:platform/disconnect', async (req: Request, res: Response) => {
  try {
    const platform = req.params.platform as IntegrationPlatform;
    const gateway = getGateway();

    if (isBridge(gateway)) {
      await gateway.disconnectPlatform(platform);
    } else {
      await gateway.disconnectPlatform(platform);
    }

    const response: ApiResponse<PlatformDisconnectResponse> = {
      success: true,
      data: {
        success: true,
        platform,
      },
    };

    res.json(response);
  } catch (error) {
    Logger.error('断开连接失败', error as Error, 'IntegrationRoutes');
    res.status(500).json({
      success: false,
      error: '断开连接失败',
    });
  }
});

router.post('/:platform/webhook', async (req: Request, res: Response) => {
  try {
    const platform = req.params.platform as IntegrationPlatform;
    const gateway = getGateway();

    const result = isBridge(gateway)
      ? await gateway.handleWebhook(platform, req.body)
      : await gateway.handleWebhook(platform, req.body);

    if (result.success) {
      res.status(200).json(result.response || { success: true });
    } else {
      res.status(400).json({ success: false });
    }
  } catch (error) {
    Logger.error('处理 Webhook 失败', error as Error, 'IntegrationRoutes');
    res.status(500).json({ success: false });
  }
});

router.post('/:platform/send', async (req: Request, res: Response) => {
  try {
    const platform = req.params.platform as IntegrationPlatform;
    const requestBody: SendMessageRequest = {
      ...req.body,
      platform,
    };

    const gateway = getGateway();
    const response = isBridge(gateway)
      ? await gateway.sendMessage(requestBody)
      : await gateway.sendMessage(requestBody);

    const apiResponse: ApiResponse<SendMessageResponse> = {
      success: response.success,
      data: response,
    };

    if (!response.success) {
      apiResponse.error = response.error;
    }

    res.status(response.success ? 200 : 400).json(apiResponse);
  } catch (error) {
    Logger.error('发送消息失败', error as Error, 'IntegrationRoutes');
    res.status(500).json({
      success: false,
      error: '发送消息失败',
      message: (error as Error).message,
    });
  }
});

router.get('/system-status', async (_req: Request, res: Response) => {
  try {
    const bridge = GatewayBridge.getInstance();
    const systemStatus = {
      timestamp: Date.now(),
      architecture: 'v5.0-harness-isolated-gateway',
      gateway: {
        mode: bridge.isWorkerAlive() ? 'isolated_worker' : 'inline_fallback',
        workerAlive: bridge.isWorkerAlive(),
      },
      layers: {
        preprocessor: 'active',
        llmCore: 'active',
        postprocessor: 'active',
      },
      overall: {
        status: 'operational',
      },
    };

    res.json({
      success: true,
      data: systemStatus,
    });
  } catch (error) {
    Logger.error(
      '获取系统状态失败',
      error as Error,
      'IntegrationRoutes'
    );
    res.status(500).json({
      success: false,
      error: '获取系统状态失败',
      details: (error as Error).message,
    });
  }
});

export default router;

/**
 * 记忆系统路由 - memory store / search / profile / preferences
 */

import express, { Request, Response } from 'express';
import { UserProfile } from '../../memory/UserProfile';

import { JiabaixingCore } from '../../core/JiabaixingCore';
import { Logger } from '../../utils/Logger';

export function registerMemoryRoutes(
  app: express.Application,
  core: JiabaixingCore | null
): void {
  app.post(
    '/api/memory/store',
    express.json({ limit: '1mb' }),
    async (req, res) => {
      try {
        const { content, userId, importance, tags, emotion, scene } =
          req.body as {
            content?: string;
            userId?: string;
            importance?: string;
            tags?: string[];
            emotion?: unknown;
            scene?: unknown;
          };

        if (!content) {
          return res
            .status(400)
            .json({ success: false, error: '缺少content参数' });
        }

        if (!core) {
          return res
            .status(503)
            .json({ success: false, error: '核心系统未初始化' });
        }

        const memoryEngine = core.getMemoryEngine();
        if (!memoryEngine) {
          return res
            .status(503)
            .json({ success: false, error: '记忆引擎未初始化' });
        }

        if (memoryEngine.storeShortTermMemory) {
          await memoryEngine.storeShortTermMemory(
            content,
            (scene as string) || 'general',
            userId
          );
        }

        res.json({
          success: true,
          data: {
            id: Date.now().toString(),
            content,
            timestamp: new Date().toISOString(),
            importance: importance || 'medium',
          },
        });
      } catch (error) {
        Logger.error('❌ 记忆存储失败', error as Error, 'MemoryAPI');
        res
          .status(500)
          .json({ success: false, error: (error as Error).message });
      }
    }
  );

  app.get('/api/memory/search', async (req, res) => {
    try {
      const {
        query,
        userId,
        limit = 10,
      } = req.query as {
        query?: string;
        userId?: string;
        limit?: string;
      };

      if (!query) {
        return res.status(400).json({ success: false, error: '缺少query参数' });
      }

      if (!core) {
        return res
          .status(503)
          .json({ success: false, error: '核心系统未初始化' });
      }

      const memoryEngine = core.getMemoryEngine();
      if (!memoryEngine) {
        return res
          .status(503)
          .json({ success: false, error: '记忆引擎未初始化' });
      }

      let results: unknown[] = [];
      if (memoryEngine.retrieveContext) {
        const context = await memoryEngine.retrieveContext(query, userId);
        results = context.memories.map((m: unknown, index: number) => {
          const mem = m as any;
          return {
            id: `memory_${index}`,
            content: mem.content,
            importance:
              mem.relevance > 0.7
                ? 'high'
                : mem.relevance > 0.4
                  ? 'medium'
                  : 'low',
            timestamp: new Date().toISOString(),
            similarity: mem.relevance,
          };
        });
      }

      res.json({
        success: true,
        data: {
          query,
          results: results.slice(0, parseInt(limit as string) || 10),
          total: results.length,
        },
      });
    } catch (error) {
      Logger.error('❌ 记忆检索失败', error as Error, 'MemoryAPI');
      res.status(500).json({ success: false, error: (error as Error).message });
    }
  });

  app.get('/api/memory/profile', async (req, res) => {
    try {
      const { userId } = req.query as { userId?: string };

      if (!core) {
        return res
          .status(503)
          .json({ success: false, error: '核心系统未初始化' });
      }

      const memoryEngine = core.getMemoryEngine();
      if (!memoryEngine) {
        return res
          .status(503)
          .json({ success: false, error: '记忆引擎未初始化' });
      }

      const userProfile = memoryEngine.getUserProfile?.() as UserProfile | undefined;

      if (!userProfile) {
        return res
          .status(404)
          .json({ success: false, error: '用户画像不存在' });
      }

      res.json({
        success: true,
        data: {
          basicInfo: userProfile.getBasicInfo(),
          developmentHabits: userProfile.getDevelopmentHabits(),
          lifePreferences: userProfile.getLifePreferences(),
          emotionalPatterns: userProfile.getEmotionalPatterns(),
          taskPreferences: userProfile.getTaskPreferences(),
        },
      });
    } catch (error) {
      Logger.error('❌ 获取用户画像失败', error as Error, 'MemoryAPI');
      res.status(500).json({ success: false, error: (error as Error).message });
    }
  });

  app.post(
    '/api/memory/preferences',
    express.json({ limit: '1mb' }),
    async (req, res) => {
      try {
        const { preferences } = req.body as {
          preferences?: Record<string, unknown>;
        };

        if (!preferences) {
          return res
            .status(400)
            .json({ success: false, error: '缺少preferences参数' });
        }

        if (!core) {
          return res
            .status(503)
            .json({ success: false, error: '核心系统未初始化' });
        }

        const memoryEngine = core.getMemoryEngine();
        if (!memoryEngine) {
          return res
            .status(503)
            .json({ success: false, error: '记忆引擎未初始化' });
        }

        const userProfile = memoryEngine.getUserProfile?.() as UserProfile | undefined;

        if (!userProfile) {
          return res
            .status(404)
            .json({ success: false, error: '用户画像不存在' });
        }

        await userProfile.update({
          ...preferences,
          timestamp: new Date(),
        });

        res.json({
          success: true,
          data: {
            basicInfo: userProfile.getBasicInfo(),
            developmentHabits: userProfile.getDevelopmentHabits(),
            lifePreferences: userProfile.getLifePreferences(),
            emotionalPatterns: userProfile.getEmotionalPatterns(),
            taskPreferences: userProfile.getTaskPreferences(),
          },
        });
      } catch (error) {
        Logger.error('❌ 更新用户偏好失败', error as Error, 'MemoryAPI');
        res
          .status(500)
          .json({ success: false, error: (error as Error).message });
      }
    }
  );
}

/**
 * 性能监控路由 - performance snapshot / metrics / errors / llm performance
 */

import express, { Request, Response } from 'express';

import { JiabaixingCore } from '../../core/JiabaixingCore';
import { Logger } from '../../utils/Logger';

export function registerPerformanceRoutes(
  app: express.Application,
  core: JiabaixingCore | null
): void {
  app.get('/api/performance/snapshot', (_req, res) => {
    try {
      if (!core) {
        res.status(503).json({ success: false, error: '核心系统未初始化' });
        return;
      }

      const snapshot = core.getPerformanceMonitor().getCurrentMetrics();
      res.json({ success: true, data: snapshot });
    } catch (error) {
      res.status(500).json({ success: false, error: (error as Error).message });
    }
  });

  app.get('/api/performance/metrics', (req, res) => {
    try {
      if (!core) {
        res.status(503).json({ success: false, error: '核心系统未初始化' });
        return;
      }
      const limit = parseInt(req.query.limit as string) || 100;
      const metrics = core.getPerformanceMonitor().getMetrics(limit);
      res.json({ success: true, data: metrics });
    } catch (error) {
      res.status(500).json({ success: false, error: (error as Error).message });
    }
  });

  app.get('/api/performance/errors', (req, res) => {
    try {
      if (!core) {
        res.status(503).json({ success: false, error: '核心系统未初始化' });
        return;
      }

      const limit = parseInt(req.query.limit as string) || 50;
      const metrics = core.getPerformanceMonitor().getMetrics(limit);
      const errors = metrics.filter((m) => m.errorRate > 0);
      res.json({ success: true, data: errors });
    } catch (error) {
      res.status(500).json({ success: false, error: (error as Error).message });
    }
  });

  app.get('/api/llm/performance', async (_req, res) => {
    try {
      const { MultiModelLLMProvider } =
        await import('../../models/MultiModelLLMProvider');
      const provider = MultiModelLLMProvider.getInstance();
      await provider.initialize();

      const models = provider.getAvailableModels();
      const healthStatus = (provider as any).modelHealthStatus || new Map();

      const modelStats = models.map((model) => {
        const health = healthStatus.get(model.id) || {
          successCount: 0,
          failureCount: 0,
          avgLatency: 0,
          lastError: null,
        };

        const totalCalls = health.successCount + health.failureCount;
        const successRate =
          totalCalls > 0 ? health.successCount / totalCalls : 0;

        let status: 'healthy' | 'degraded' | 'unhealthy' = 'healthy';
        if (successRate < 0.5 || health.failureCount >= 5) {
          status = 'unhealthy';
        } else if (successRate < 0.8 || health.failureCount >= 3) {
          status = 'degraded';
        }

        return {
          modelId: model.id,
          modelName: model.name,
          provider: model.id.includes('zhipu') ? '智谱AI' : '本地LLM',
          totalCalls,
          successCalls: health.successCount,
          failedCalls: health.failureCount,
          avgLatency: health.avgLatency || 0,
          totalTokens: Math.floor(totalCalls * 500),
          promptTokens: Math.floor(totalCalls * 300),
          completionTokens: Math.floor(totalCalls * 200),
          lastUsed: health.lastSuccess
            ? new Date(health.lastSuccess).toISOString()
            : '-',
          status,
        };
      });

      const totalTokens = modelStats.reduce((sum, m) => sum + m.totalTokens, 0);
      const totalCalls = modelStats.reduce((sum, m) => sum + m.totalCalls, 0);

      const response = {
        models: modelStats,
        tokenUsage: {
          totalTokens,
          promptTokens: modelStats.reduce((sum, m) => sum + m.promptTokens, 0),
          completionTokens: modelStats.reduce(
            (sum, m) => sum + m.completionTokens,
            0
          ),
          avgTokensPerCall:
            totalCalls > 0 ? Math.floor(totalTokens / totalCalls) : 0,
          tokensByModel: modelStats.map((m) => ({
            model: m.modelName,
            tokens: m.totalTokens,
          })),
          tokensByHour: [],
        },
        systemStatus: {
          circuitBreakerOpen: modelStats.some((m) => m.status === 'unhealthy'),
          lastError: null,
          uptime: process.uptime(),
        },
      };

      res.status(200).json(response);
    } catch (error) {
      Logger.error('获取LLM性能数据失败', error as Error, 'Performance');
      res.status(500).json({ error: 'Internal server error' });
    }
  });

  app.post(
    '/api/performance/metrics',
    express.json({ limit: '1mb' }),
    (req, res) => {
      try {
        const metrics = req.body;
        Logger.debug('收到性能指标数据', 'Performance', metrics);

        res.json({
          success: true,
          status: 'received',
          timestamp: new Date().toISOString(),
        });
      } catch (error) {
        res.status(500).json({
          success: false,
          error: (error as Error).message,
        });
      }
    }
  );
}

