/**
 * 安全路由 - security logs / events / report / validate / audit
 */

import express, { Request, Response } from 'express';

import { JiabaixingCore } from '../../core/JiabaixingCore';
import { Logger } from '../../utils/Logger';

interface TRAEIntegrator {
  getSystemHealth?: () => unknown;
  getPerformanceMetrics?: () => unknown;
  getMCPStatus?: () => unknown;
  getSkillStatus?: () => unknown;
  executeOptimizedSkill?: (
    skillName: string,
    params: unknown
  ) => Promise<unknown>;
}

export function registerSecurityRoutes(
  app: express.Application,
  core: JiabaixingCore | null
): void {
  const securityAuditor = {
    queryLogs: (filter: { level?: string; category?: string; limit?: number }) => {
      return { logs: [], total: 0, filter };
    },
    queryEvents: (filter: { eventType?: string; severity?: string; limit?: number }) => {
      return { events: [], total: 0, filter };
    },
    generateReport: (timeWindowHours: number) => {
      return {
        timeWindow: `${timeWindowHours}h`,
        summary: { totalEvents: 0, criticalCount: 0, highCount: 0 },
        recommendations: [],
      };
    },
  };

  app.get('/api/security/logs', (req, res) => {
    try {
      if (!core) {
        res.status(503).json({ success: false, error: '核心系统未初始化' });
        return;
      }
      const level = req.query.level as
        | 'info'
        | 'warning'
        | 'error'
        | 'critical'
        | undefined;
      const category = req.query.category as
        | 'authentication'
        | 'authorization'
        | 'data_access'
        | 'system'
        | 'security_event'
        | 'user_action'
        | undefined;
      const limit = parseInt(req.query.limit as string) || 100;
      const result = securityAuditor.queryLogs({ level, category, limit });
      res.json({ success: true, data: result.logs });
    } catch (error) {
      res.status(500).json({ success: false, error: (error as Error).message });
    }
  });

  app.get('/api/security/events', (req, res) => {
    try {
      if (!core) {
        res.status(503).json({ success: false, error: '核心系统未初始化' });
        return;
      }

      const eventType = req.query.eventType as
        | 'login_failed'
        | 'access_denied'
        | 'suspicious_activity'
        | 'data_breach_attempt'
        | 'rate_limit_exceeded'
        | 'malicious_input'
        | undefined;
      const severity = req.query.severity as
        | 'low'
        | 'medium'
        | 'high'
        | 'critical'
        | undefined;
      const limit = parseInt(req.query.limit as string) || 50;
      const events = securityAuditor.queryEvents({ eventType, severity, limit });
      res.json({ success: true, data: events });
    } catch (error) {
      res.status(500).json({ success: false, error: (error as Error).message });
    }
  });

  app.get('/api/security/report', (req, res) => {
    try {
      if (!core) {
        res.status(503).json({ success: false, error: '核心系统未初始化' });
        return;
      }

      const timeWindowHours =
        parseInt(req.query.timeWindowHours as string) || 24;
      const report = securityAuditor.generateReport(timeWindowHours);
      res.json({ success: true, data: report });
    } catch (error) {
      res.status(500).json({ success: false, error: (error as Error).message });
    }
  });

  app.post(
    '/api/security/validate',
    express.json({ limit: '10mb' }),
    async (req, res) => {
      try {
        const { input } = req.body as { input?: string };

        if (!input) {
          return res
            .status(400)
            .json({ success: false, error: '缺少input参数' });
        }

        const SecurityGuard = (await import('../../security/SecurityGuard'))
          .SecurityGuard;
        const securityGuard = new SecurityGuard();

        const validationResult = securityGuard.validateInput(input);

        res.json({
          success: true,
          data: {
            valid: validationResult.valid,
            errors: validationResult.errors,
            warnings: validationResult.warnings,
            riskLevel: validationResult.valid ? 'low' : 'high',
          },
        });
      } catch (error) {
        Logger.error('❌ 安全验证失败', error as Error, 'SecurityAPI');
        res
          .status(500)
          .json({ success: false, error: (error as Error).message });
      }
    }
  );

  app.get('/api/security/audit', async (req, res) => {
    try {
      const { limit = 20, type } = req.query as {
        limit?: string;
        type?: string;
      };

      if (!core) {
        return res
          .status(503)
          .json({ success: false, error: '核心系统未初始化' });
      }

      const traeIntegrator =
        core.getTRAEOptimizationIntegrator() as TRAEIntegrator;
      if (!traeIntegrator) {
        return res
          .status(503)
          .json({ success: false, error: 'TRAE优化系统未启动' });
      }

      const auditResult = (await traeIntegrator.executeOptimizedSkill?.(
        'SecurityAuditSkill',
        {
          target: 'src',
          auditType: type || 'comprehensive',
          limit: parseInt(limit as string) || 20,
        }
      )) as { success?: boolean; output?: unknown };

      res.json({
        success: auditResult.success,
        data: auditResult.output,
      });
    } catch (error) {
      Logger.error('❌ 获取安全审计日志失败', error as Error, 'SecurityAPI');
      res.status(500).json({ success: false, error: (error as Error).message });
    }
  });
}

/**
 * 技能路由 - skills execute / list
 * 同时导出 registerSkillRoutes（main.ts 使用）和 skillRoutes Router（server/index.ts 兼容）
 */

import express, { Request, Response } from 'express';

import { JiabaixingCore } from '../../core/JiabaixingCore';
import { SkillRegistry } from '../../skills/SkillRegistry';
import { Logger } from '../../utils/Logger';

// 兼容 server/index.ts 的 Router 导出
export const skillRoutes = express.Router();

skillRoutes.post('/execute', express.json({ limit: '10mb' }), async (req, res) => {
  try {
    const { skillName, params } = req.body as {
      skillName?: string;
      params?: Record<string, unknown>;
    };
    if (!skillName) {
      return res
        .status(400)
        .json({ success: false, error: '缺少 skillName' });
    }

    const registry = SkillRegistry.getInstance();
    const skill = registry.getSkill(skillName);

    if (!skill) {
      return res
        .status(404)
        .json({ success: false, error: `技能不存在: ${skillName}` });
    }

    const validation = await skill.validate(params || {});
    if (!validation.valid) {
      return res
        .status(400)
        .json({ success: false, error: validation.errors.join(', ') });
    }

    const context = {
      userId: (req.body as { userId?: string }).userId || 'api_user',
      traceId: Logger.generateTraceId(),
    };

    const startTime = Date.now();
    const result = await skill.execute(params || {}, context);
    const duration = Date.now() - startTime;

    res.json({
      success: result.success,
      output: result.output,
      error: result.error,
      metadata: { ...result.metadata, duration },
    });
  } catch (error) {
    Logger.error('❌ 技能执行失败', error as Error, 'API');
    res
      .status(500)
      .json({ success: false, error: (error as Error).message });
  }
});

skillRoutes.get('/list', (_req, res) => {
  try {
    const registry = SkillRegistry.getInstance();
    const skills = registry.getAllSkillMeta();
    res.json({ success: true, skills, count: skills.length });
  } catch (error) {
    res.status(500).json({ success: false, error: (error as Error).message });
  }
});

// main.ts 使用的注册函数
export function registerSkillRoutes(
  app: express.Application,
  core: JiabaixingCore | null
): void {
  app.post(
    '/api/skills/execute',
    express.json({ limit: '10mb' }),
    async (req, res) => {
      try {
        const { skillName, params } = req.body as {
          skillName?: string;
          params?: Record<string, unknown>;
        };
        if (!skillName) {
          return res
            .status(400)
            .json({ success: false, error: '缺少 skillName' });
        }

        const registry = SkillRegistry.getInstance();
        const skill = registry.getSkill(skillName);

        if (!skill) {
          return res
            .status(404)
            .json({ success: false, error: `技能不存在: ${skillName}` });
        }

        const validation = await skill.validate(params || {});
        if (!validation.valid) {
          return res
            .status(400)
            .json({ success: false, error: validation.errors.join(', ') });
        }

        const context = {
          userId: (req.body as { userId?: string }).userId || 'api_user',
          traceId: Logger.generateTraceId(),
        };

        const startTime = Date.now();
        const result = await skill.execute(params || {}, context);
        const duration = Date.now() - startTime;

        res.json({
          success: result.success,
          output: result.output,
          error: result.error,
          metadata: { ...result.metadata, duration },
        });
      } catch (error) {
        Logger.error('❌ 技能执行失败', error as Error, 'API');
        res
          .status(500)
          .json({ success: false, error: (error as Error).message });
      }
    }
  );

  app.get('/api/skills/list', (_req, res) => {
    try {
      const registry = SkillRegistry.getInstance();
      const skills = registry.getAllSkillMeta();
      res.json({ success: true, skills, count: skills.length });
    } catch (error) {
      res.status(500).json({ success: false, error: (error as Error).message });
    }
  });
}

/**
 * 系统状态暴露路由 - 200任务改进建议实现
 * 提供7个新API端点，暴露系统真实内部状态
 */

import { Router, json } from 'express';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { EvolutionStats, JiabaixingCorePublicAPI } from '../../interfaces';
import { SkillRegistry } from '../../skills/SkillRegistry';
import { Logger } from '../../utils/Logger';

const router = Router();

let _core: JiabaixingCorePublicAPI | null = null;

/**
 * 设置核心实例引用（由 main.ts 在初始化时调用）
 */
export function setSystemStateCore(core: JiabaixingCorePublicAPI): void {
  _core = core;
}

// ── 查询参数辅助函数 ──

function queryAsNumber(value: unknown, fallback: number = 100): number {
  const str = Array.isArray(value) ? String(value[0]) : String(value || '');
  const num = parseInt(str, 10);
  return isNaN(num) ? fallback : num;
}

function getAssistantAPI(): JiabaixingCorePublicAPI {
  if (!_core) {
    throw new Error('systemStateRoutes: 核心实例未注入，请在 main.ts 中调用 setSystemStateCore()');
  }
  return _core;
}

// ── 1. 系统资源 ──

router.get('/api/system/resources', (_req, res) => {
  try {
    const memUsage = process.memoryUsage();
    const cpuUsage = process.cpuUsage();
    const totalMem = os.totalmem();
    const freeMem = os.freemem();
    const loadAvg = os.loadavg();

    // 获取磁盘信息（项目所在目录）
    const projectDir = process.cwd();
    let diskInfo = { free: 0, total: 0, used: 0 };
    try {
      fs.statSync(projectDir);
      // Windows下无法直接获取磁盘大小，使用环境变量或默认值
      diskInfo = {
        free: freeMem,
        total: totalMem,
        used: totalMem - freeMem,
      };
    } catch {
      // ignore
    }

    res.json({
      success: true,
      data: {
        timestamp: new Date().toISOString(),
        process: {
          pid: process.pid,
          uptime: process.uptime(),
          version: process.version,
          platform: process.platform,
          arch: process.arch,
        },
        memory: {
          heapUsed: Math.round(memUsage.heapUsed / 1024 / 1024),
          heapTotal: Math.round(memUsage.heapTotal / 1024 / 1024),
          rss: Math.round(memUsage.rss / 1024 / 1024),
          external: Math.round((memUsage.external || 0) / 1024 / 1024),
          systemTotal: Math.round(totalMem / 1024 / 1024),
          systemFree: Math.round(freeMem / 1024 / 1024),
          usagePercent: Math.round(((totalMem - freeMem) / totalMem) * 100),
        },
        cpu: {
          loadAverage: loadAvg,
          userTime: cpuUsage.user,
          systemTime: cpuUsage.system,
          count: os.cpus().length,
        },
        disk: diskInfo,
      },
    });
  } catch (error) {
    Logger.error('获取系统资源失败', error as Error, 'SystemState');
    res.status(500).json({ success: false, error: '获取系统资源失败' });
  }
});

// ── 2. 记忆统计 ──

router.get('/api/memory/stats', async (_req, res) => {
  try {
    const assistant = getAssistantAPI();
    const memoryEngine = assistant.memoryEngine;

    // 从MemoryDatabase获取统计
    const { MemoryDatabase } = await import('../../memory/Database');
    const db = MemoryDatabase.getInstance();
    const allRecords = db.query(undefined, 10000);

    const typeStats: Record<string, number> = {};
    let totalRecords = 0;

    for (const record of allRecords) {
      totalRecords++;
      const type = record.type || 'unknown';
      typeStats[type] = (typeStats[type] || 0) + 1;
    }

    // 检查数据库文件大小
    const dbPath = path.join(process.cwd(), 'data', 'memory.db');
    let dbSize = 0;
    try {
      const stat = fs.statSync(dbPath);
      dbSize = stat.size;
    } catch {
      // ignore
    }

    res.json({
      success: true,
      data: {
        timestamp: new Date().toISOString(),
        totalRecords,
        typeDistribution: typeStats,
        databaseSize: dbSize,
        databaseSizeMB: Math.round((dbSize / 1024 / 1024) * 100) / 100,
        engineStats: memoryEngine?.getStats?.() || null,
      },
    });
  } catch (error) {
    Logger.error('获取记忆统计失败', error as Error, 'SystemState');
    res.status(500).json({ success: false, error: '获取记忆统计失败' });
  }
});

// ── 3. 性能指标 ──

const apiMetrics: Array<{
  endpoint: string;
  method: string;
  duration: number;
  timestamp: number;
  statusCode: number;
}> = [];

export function recordApiMetric(
  endpoint: string,
  method: string,
  duration: number,
  statusCode: number
): void {
  apiMetrics.push({
    endpoint,
    method,
    duration,
    timestamp: Date.now(),
    statusCode,
  });
  // 保留最近1000条
  if (apiMetrics.length > 1000) {
    apiMetrics.shift();
  }
}

router.get('/api/metrics', (_req, res) => {
  try {
    const now = Date.now();
    const oneHourAgo = now - 3600 * 1000;
    const recentMetrics = apiMetrics.filter((m) => m.timestamp > oneHourAgo);

    // 按端点分组统计
    const endpointStats: Record<
      string,
      {
        count: number;
        totalDuration: number;
        errors: number;
        p50: number;
        p95: number;
      }
    > = {};

    for (const m of recentMetrics) {
      const key = `${m.method} ${m.endpoint}`;
      if (!endpointStats[key]) {
        endpointStats[key] = {
          count: 0,
          totalDuration: 0,
          errors: 0,
          p50: 0,
          p95: 0,
        };
      }
      endpointStats[key].count++;
      endpointStats[key].totalDuration += m.duration;
      if (m.statusCode >= 400) {
        endpointStats[key].errors++;
      }
    }

    // 计算P50/P95
    for (const key of Object.keys(endpointStats)) {
      const durations = recentMetrics
        .filter((m) => `${m.method} ${m.endpoint}` === key)
        .map((m) => m.duration)
        .sort((a, b) => a - b);
      if (durations.length > 0) {
        endpointStats[key].p50 =
          durations[Math.floor(durations.length * 0.5)] || 0;
        endpointStats[key].p95 =
          durations[Math.floor(durations.length * 0.95)] || 0;
      }
    }

    const totalRequests = recentMetrics.length;
    const totalErrors = recentMetrics.filter((m) => m.statusCode >= 400).length;
    const avgDuration =
      totalRequests > 0
        ? recentMetrics.reduce((s, m) => s + m.duration, 0) / totalRequests
        : 0;

    res.json({
      success: true,
      data: {
        timestamp: new Date().toISOString(),
        summary: {
          totalRequests,
          totalErrors,
          errorRate:
            totalRequests > 0
              ? Math.round((totalErrors / totalRequests) * 1000) / 10
              : 0,
          avgDuration: Math.round(avgDuration * 100) / 100,
        },
        endpointStats,
        topSlowest: Object.entries(endpointStats)
          .sort(
            (a, b) =>
              b[1].totalDuration / b[1].count - a[1].totalDuration / a[1].count
          )
          .slice(0, 5)
          .map(([endpoint, stats]) => ({
            endpoint,
            avgDuration:
              Math.round((stats.totalDuration / stats.count) * 100) / 100,
            count: stats.count,
          })),
      },
    });
  } catch (error) {
    Logger.error('获取性能指标失败', error as Error, 'SystemState');
    res.status(500).json({ success: false, error: '获取性能指标失败' });
  }
});

// ── 4. 错误日志 ──

router.get('/api/logs/errors', (req, res) => {
  try {
    const level = req.query.level as string | undefined;
    const hours = queryAsNumber(req.query.hours, 24);
    const limit = queryAsNumber(req.query.limit, 100);

    const logDir = path.join(process.cwd(), 'logs');
    const errors: Array<{
      timestamp: string;
      level: string;
      message: string;
      module?: string;
    }> = [];

    // 读取error.log
    const errorLogPath = path.join(logDir, 'error.log');
    if (fs.existsSync(errorLogPath)) {
      const content = fs.readFileSync(errorLogPath, 'utf-8');
      const lines = content.split('\n').filter((l) => l.trim());
      const cutoff = Date.now() - hours * 3600 * 1000;

      for (const line of lines.reverse()) {
        try {
          const entry = JSON.parse(line);
          const entryTime = new Date(entry.timestamp).getTime();
          if (entryTime < cutoff) continue;
          if (level && entry.level !== level) continue;

          errors.push({
            timestamp: entry.timestamp,
            level: entry.level,
            message: entry._message,
            module: entry._module,
          });

          if (errors.length >= limit) break;
        } catch {
          // ignore invalid lines
        }
      }
    }

    // 统计各级别数量
    const levelCounts: Record<string, number> = {};
    for (const e of errors) {
      levelCounts[e.level] = (levelCounts[e.level] || 0) + 1;
    }

    res.json({
      success: true,
      data: {
        timestamp: new Date().toISOString(),
        total: errors.length,
        levelCounts,
        errors: errors.slice(0, limit),
      },
    });
  } catch (error) {
    Logger.error('获取错误日志失败', error as Error, 'SystemState');
    res.status(500).json({ success: false, error: '获取错误日志失败' });
  }
});

