router.get('/api/system/integrity', async (_req, res) => {
  try {
    const checks: Array<{
      name: string;
      status: 'pass' | 'fail' | 'warn';
      message: string;
    }> = [];

    // 1. 检查数据库文件
    const dbPath = path.join(process.cwd(), 'data', 'memory.db');
    try {
      if (fs.existsSync(dbPath)) {
        const stat = fs.statSync(dbPath);
        checks.push({
          name: '数据库文件',
          status: 'pass',
          message: `存在，大小 ${Math.round(stat.size / 1024)}KB`,
        });
      } else {
        checks.push({ name: '数据库文件', status: 'warn', message: '不存在' });
      }
    } catch (error) {
      checks.push({
        name: '数据库文件',
        status: 'fail',
        message: (error as Error).message,
      });
    }

    // 2. 检查必需目录
    const requiredDirs = ['src', 'data', 'logs', 'config'];
    for (const dir of requiredDirs) {
      const dirPath = path.join(process.cwd(), 'src', '..', dir);
      try {
        if (fs.existsSync(dirPath)) {
          checks.push({
            name: `目录: ${dir}`,
            status: 'pass',
            message: '存在',
          });
        } else {
          checks.push({
            name: `目录: ${dir}`,
            status: 'warn',
            message: '不存在',
          });
        }
      } catch (error) {
        checks.push({
          name: `目录: ${dir}`,
          status: 'fail',
          message: (error as Error).message,
        });
      }
    }

    // 3. 检查关键文件
    const requiredFiles = ['package.json', 'tsconfig.json', '.env'];
    for (const file of requiredFiles) {
      const filePath = path.join(process.cwd(), file);
      try {
        if (fs.existsSync(filePath)) {
          checks.push({
            name: `文件: ${file}`,
            status: 'pass',
            message: '存在',
          });
        } else {
          checks.push({
            name: `文件: ${file}`,
            status: 'warn',
            message: '不存在',
          });
        }
      } catch (error) {
        checks.push({
          name: `文件: ${file}`,
          status: 'fail',
          message: (error as Error).message,
        });
      }
    }

    // 4. 检查数据库可读写
    try {
      const { MemoryDatabase } = await import('../../memory/Database');
      const db = MemoryDatabase.getInstance();
      db.query('short_term', 1);
      checks.push({ name: '数据库读写', status: 'pass', message: '正常' });
    } catch (error) {
      checks.push({
        name: '数据库读写',
        status: 'fail',
        message: (error as Error).message,
      });
    }

    // 5. 检查技能注册表
    try {
      const registry = SkillRegistry.getInstance();
      const skills = registry.getAllSkillMeta();
      checks.push({
        name: '技能注册表',
        status: 'pass',
        message: `${skills.length}个技能已注册`,
      });
    } catch (error) {
      checks.push({
        name: '技能注册表',
        status: 'fail',
        message: (error as Error).message,
      });
    }

    const passCount = checks.filter((c) => c.status === 'pass').length;
    const failCount = checks.filter((c) => c.status === 'fail').length;
    const warnCount = checks.filter((c) => c.status === 'warn').length;

    res.json({
      success: true,
      data: {
        timestamp: new Date().toISOString(),
        summary: {
          pass: passCount,
          fail: failCount,
          warn: warnCount,
          total: checks.length,
        },
        checks,
        overallStatus:
          failCount === 0
            ? warnCount === 0
              ? 'healthy'
              : 'degraded'
            : 'unhealthy',
      },
    });
  } catch (error) {
    Logger.error('完整性检查失败', error as Error, 'SystemState');
    res.status(500).json({ success: false, error: '完整性检查失败' });
  }
});

