// ====================== WebSocket 消息类型 ======================

export type WsClientEventType =
  (typeof WS_EVENTS.CLIENT)[keyof typeof WS_EVENTS.CLIENT];
export type WsServerEventType =
  (typeof WS_EVENTS.SERVER)[keyof typeof WS_EVENTS.SERVER];

export interface WsMessage<T extends WsServerEventType = WsServerEventType> {
  type: T;
  data?: Record<string, unknown>;
  traceId?: string;
  timestamp?: number;
}

// --- 前端→后端 消息 ---

export interface WsUserInputMessage {
  type: 'user_input';
  payload: {
    input: string;
    userId: string;
  };
  traceId?: string;
}

export interface WsClarificationResponseMessage {
  type: 'clarification_response';
  response: string;
  traceId?: string;
}

export interface WsExecutionConfirmMessage {
  type: 'execution_confirm';
  confirmed: boolean;
  traceId?: string;
}

// --- 后端→前端 消息 ---

export interface WsConnectedData {
  message: string;
  model: string;
  status: string;
  timestamp: string;
}

export interface WsResponseReadyData {
  response: string;
  traceId: string;
}

export interface WsErrorData {
  message: string;
  traceId?: string;
}

export interface WsStatusData {
  status: string;
  model: string;
  uptime: number;
  clients: number;
}

export interface WsProactiveMessageData {
  message: string;
  reason: string;
  scene?: string;
  timestamp: number;
}

export interface WsAgentExecutionUpdateData {
  traceId: string;
  phase: string;
  status: string;
  result?: unknown;
  timestamp: string;
}

export interface WsPerceptionUpdateData {
  traceId: string;
  modality: 'voice' | 'image' | 'text' | 'sensor' | 'fusion';
  status: 'started' | 'processing' | 'completed' | 'failed';
  progress?: number;
  result?: unknown;
  confidence?: number;
  error?: string;
  timestamp: string;
}

export interface WsBrainStageUpdateData {
  traceId: string;
  stage:
    | 'intent_recognition'
    | 'task_decomposition'
    | 'scene_recognition'
    | 'memory_retrieval'
    | 'llm_generation'
    | 'persona_adjustment'
    | 'function_calling';
  status: 'started' | 'completed' | 'failed';
  duration?: number;
  result?: unknown;
  timestamp: string;
}

export interface WsSkillExecutionUpdateData {
  traceId: string;
  skillName: string;
  step: 'started' | 'retry' | 'fallback' | 'completed' | 'failed';
  attempt?: number;
  maxRetries?: number;
  duration?: number;
  error?: string;
  timestamp: string;
}

export interface WsEvolutionEventData {
  type:
    | 'quality_assessed'
    | 'micro_optimization'
    | 'deep_optimization'
    | 'strategy_updated'
    | 'threshold_adjusted';
  traceId?: string;
  score?: number;
  description: string;
  metrics?: Record<string, number>;
  timestamp: string;
}

export interface WsClarificationRequestData {
  traceId: string;
  question: string;
  options: string[];
  context: string;
  timestamp: string;
}

export interface WsExecutionPreviewData {
  traceId: string;
  summary: string;
  changes: Array<{
    type: 'file' | 'command' | 'api';
    target: string;
    action: string;
    risk: 'low' | 'medium' | 'high';
    preview?: string;
  }>;
  estimatedTime?: number;
  timestamp: string;
}

export interface WsFileModifiedData {
  traceId: string;
  filePath: string;
  changeType: 'created' | 'modified' | 'deleted';
  edits?: Array<{ description: string; found: boolean }>;
  timestamp: string;
}

export interface WsFileRollbackData {
  traceId: string;
  filePath: string;
  success: boolean;
  timestamp: string;
}

export interface WsMultiFileModifiedData {
  traceId: string;
  files: Array<{
    path: string;
    changeType: 'created' | 'modified' | 'deleted';
  }>;
  timestamp: string;
}

export interface WsToolTraceData {
  timestamp: string;
  traceId: string;
  toolCallId: string;
  toolName: string;
  status: 'started' | 'completed' | 'failed';
  duration: number;
  success: boolean | null;
  errorMessage: string | null;
}

export interface WsWeightUpdateData {
  weights?: Record<string, number>;
  toolId?: string;
  oldWeight?: number;
  newWeight?: number;
  reason?: string;
  timestamp?: number;
