  error?: string;
}

export interface CoreEvents {
  user_input: [payload: { input: string; userId?: string; traceId?: string }];
  task_completed: [payload: { taskId: string; traceId?: string; status: string; result?: unknown }];
  task_started: [payload: { taskId: string; taskName: string }];
  task_failed: [payload: { taskId: string; traceId?: string; error: string }];
  context_update: [key: string, value: unknown];
  response_ready: [payload: { response: string; traceId: string; success?: boolean; duration?: number; error?: string; ws?: unknown }];
  system_status: [status: string, detail?: string];
  command_executed: [command: string, result: unknown];
  context_switch: [fromScene: string, toScene: string];
  active_interaction: [data: { input?: string; userId?: string; text?: string }];
}

export interface SchedulerEvents {
  scheduler_started: [payload: { timestamp: string }];
  scheduler_stopped: [payload: { timestamp: string }];
  proactive_trigger: [payload: { type: string; reason: string; priority: number; suggestedAction?: string; context?: Record<string, unknown> }];
  schedule_check: [scheduleId: string, time: Date];
}

export interface ProactiveEvents {
  proactive_schedule: [payload: { type: string; content: string; priority?: string }];
  proactive_briefing: [payload: { type: string; context: string }];
  proactive_reminder: [payload: { type: string; message: string }];
  proactive_comfort: [payload: { type: string; emotionTypes?: string; intensity?: number; message: string }];
  proactive_checkin: [payload: { type: string; silenceHours?: number; message: string }];
  proactive_behavior: [payload: { pattern: string; confidence: number; message: string }];
  proactive_interaction: [payload: { reason: string; context?: string; scene?: string; priority?: string; isEmotionBased?: boolean }];
}

export interface MemoryEvents {
  memory_stored: [memoryId: string, type: string];
  memory_context_ready: [context: unknown];
  memory_context_request: [query: string];
  memory_update: [memoryId: string, content: unknown];
  memory_consolidation: [payload: { consolidatedCount: number; timestamp: string }];
}

export interface EvolutionEvents {
  evolution_started: [optimizationId: string];
  evolution_update: [data: { version?: string; status?: string; description?: string; metrics?: Record<string, number> }];
  evolution_event: [payload: { type: 'quality_assessed' | 'micro_optimization' | 'deep_optimization' | 'strategy_updated' | 'threshold_adjusted'; traceId?: string; score?: number; description: string; metrics?: Record<string, number>; timestamp: string }];
  evolution_cycle_completed: [payload: { healingSuccess: number; refactorSuccess: boolean; enhancementSuccess: number }];
