}

export interface TraceEvents {
  event_traced: [payload: { eventName: string; traceId: string; duration: number; success: boolean; timestamp: string; metadata?: Record<string, unknown> }];
  trace_started: [payload: { traceId: string; eventName: string; timestamp: string }];
  trace_completed: [payload: { traceId: string; eventName: string; duration: number; success: boolean }];
  trace_error: [payload: { traceId: string; eventName: string; error: string; duration: number }];
