export interface EventMap extends CoreEvents, SchedulerEvents, ProactiveEvents, MemoryEvents, EvolutionEvents, OptimizationEvents, ResourceEvents, UserEvents, WebSocketEvents, AgentExecutionEvents, VibeCodingEvents, AutomationEvents, IntegrationEvents, TraceEvents {}

